import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate member user login behavior with required context metadata.
 *
 * Business intent:
 *
 * - Ensure that a member user can successfully log in when providing valid
 *   credentials along with required session context metadata (href and referrer
 *   as valid URIs).
 * - Ensure that invalid credentials are rejected as business errors even when
 *   context metadata is present, confirming that authentication rules are
 *   enforced.
 *
 * NOTE ON SCENARIO ADAPTATION: The original scenario asked to test behavior
 * when `href`/`referrer` are missing or malformed. However,
 * ITodoAppMemberUserLogin.IRequest defines both fields as required with `string
 * & tags.Format<"uri">`, meaning that any attempt to omit or malform them would
 * violate TypeScript typing and typia validation and is not allowed in E2E test
 * code.
 *
 * Therefore, this test focuses on business-level authentication behavior using
 * only structurally valid ITodoAppMemberUserLogin.IRequest payloads.
 *
 * Steps:
 *
 * 1. Register a new member user via POST /auth/memberUser/join using a random,
 *    unique email and a known password, including valid href and referrer
 *    values.
 * 2. Perform a successful login with the same email/password and valid
 *    href/referrer, asserting that ITodoAppMemberuser.IAuthorized is returned
 *    and typia.assert passes.
 * 3. Attempt a login with the same email but an incorrect password, still
 *    providing valid href/referrer, and assert via TestValidator.error that the
 *    call fails as a business error.
 */
export async function test_api_member_user_login_requires_context_metadata(
  connection: api.IConnection,
) {
  // 1. Register a new member user with valid context metadata
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const password: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // 2. Successful login with valid credentials and context metadata
  const loginBodySuccess = {
    email,
    password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const loggedIn: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBodySuccess,
    });
  typia.assert(loggedIn);

  // 3. Failed login attempt with wrong password but valid context metadata
  const wrongPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const loginBodyFailure = {
    email,
    password: wrongPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  await TestValidator.error(
    "login should fail with wrong password",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: loginBodyFailure,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

export async function test_api_member_user_login_updates_last_login_and_resets_failures(
  connection: api.IConnection,
) {
  // 1. Register a fresh member user to obtain baseline security state
  const joinRequestBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequestBody,
    });
  typia.assert(joined);

  const originalFailedCount: number & tags.Type<"int32"> =
    joined.failed_login_count;
  const originalLastLoginAt:
    | (string & tags.Format<"date-time">)
    | null
    | undefined = joined.last_login_at;

  // 2. Perform multiple failed login attempts with wrong password
  const failedAttempts = 2;
  const wrongPassword = typia.random<string & tags.Format<"password">>();

  await ArrayUtil.asyncRepeat(failedAttempts, async () => {
    const failedLoginBody = {
      email: joinRequestBody.email,
      password: wrongPassword,
      ip: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppMemberUserLogin.IRequest;

    await TestValidator.error(
      "member user login should fail with wrong password",
      async () => {
        await api.functional.auth.memberUser.login(connection, {
          body: failedLoginBody,
        });
      },
    );
  });

  // 3. Perform a successful login using the correct password
  const successfulLoginBody = {
    email: joinRequestBody.email,
    password: joinRequestBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const authorizedAfterSuccess: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: successfulLoginBody,
    });
  typia.assert(authorizedAfterSuccess);

  // 4. Validate last_login_at and failed_login_count behavior
  TestValidator.equals(
    "authorized login response should be for the same member user",
    authorizedAfterSuccess.id,
    joined.id,
  );

  TestValidator.predicate(
    "last_login_at must be set after successful login",
    () =>
      authorizedAfterSuccess.last_login_at !== null &&
      authorizedAfterSuccess.last_login_at !== undefined,
  );

  if (originalLastLoginAt !== null && originalLastLoginAt !== undefined) {
    TestValidator.predicate(
      "last_login_at after success should not equal previous last_login_at when it existed",
      () => authorizedAfterSuccess.last_login_at !== originalLastLoginAt,
    );
  }

  TestValidator.predicate(
    "failed_login_count after successful login should be reduced from what it would be after failed attempts",
    () =>
      typeof authorizedAfterSuccess.failed_login_count === "number" &&
      authorizedAfterSuccess.failed_login_count <=
        originalFailedCount + failedAttempts &&
      authorizedAfterSuccess.failed_login_count <= failedAttempts,
  );

  // Basic sanity checks on status and timestamps to ensure we are looking at an active, updated user
  TestValidator.equals(
    "member user id should remain stable across join and login",
    joined.id,
    authorizedAfterSuccess.id,
  );
  TestValidator.predicate(
    "updated_at should not be earlier than created_at",
    () => joined.created_at <= authorizedAfterSuccess.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that a newly registered member user can create a basic pending todo
 * with minimal required fields.
 *
 * Business workflow:
 *
 * 1. Register a brand-new member user via POST /auth/memberUser/join using
 *    ITodoAppMemberUserJoin.IRequest. This returns
 *    ITodoAppMemberuser.IAuthorized and also configures the Authorization
 *    header for the provided connection.
 * 2. With this authenticated member user context, call POST
 *    /todoApp/memberUser/todos using ITodoAppTodo.ICreate that only specifies a
 *    non-empty, trimmed title (no description field) to validate minimal
 *    creation semantics.
 * 3. Assert that the response is a full ITodoAppTodo object and validate key
 *    business invariants:
 *
 *    - Id is a server-generated UUID.
 *    - MemberUser.id and memberUser.email match the joined member user.
 *    - Status is initialized to "pending".
 *    - Created_at and updated_at are identical on initial creation.
 *    - Completed_at and deleted_at are null/undefined.
 * 4. We skip any follow-up GET by id because such endpoint is not provided in the
 *    current SDK. Instead, we focus on validating the single create operation
 *    and the returned payload.
 */
export async function test_api_todo_creation_by_new_member_user(
  connection: api.IConnection,
) {
  // 1. Register a new member user using realistic random data
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    // ip is optional; omit to let server derive it
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // Basic sanity checks on authorized context
  TestValidator.predicate(
    "authorized member user id is UUID",
    () => typeof authorized.id === "string" && authorized.id.length > 0,
  );

  // 2. Create a todo with minimal required fields (title only)
  const title = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 10,
  }).trim();

  const createBody = {
    title,
    // description intentionally omitted to rely on optional semantics
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(todo);

  // 3. Business validations on the newly created todo

  // Ownership should be derived from the authenticated member user
  TestValidator.equals(
    "todo.memberUser.id should match authorized member id",
    todo.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "todo.memberUser.email should match authorized member email",
    todo.memberUser.email,
    authorized.email,
  );

  // Title should be preserved as provided
  TestValidator.equals(
    "todo.title should equal requested title",
    todo.title,
    title,
  );

  // Description should be null or undefined when omitted on create
  TestValidator.predicate(
    "todo.description should be null or undefined when omitted",
    () => todo.description === null || todo.description === undefined,
  );

  // Status should be initialized to the business default of "pending"
  TestValidator.equals(
    "todo.status should be initialized to 'pending'",
    todo.status,
    "pending",
  );

  // created_at and updated_at should be equal on first creation
  TestValidator.equals(
    "created_at and updated_at should match on initial creation",
    todo.created_at,
    todo.updated_at,
  );

  // completed_at and deleted_at should be null/undefined for a fresh todo
  TestValidator.predicate(
    "todo.completed_at should be null or undefined on creation",
    () => todo.completed_at === null || todo.completed_at === undefined,
  );
  TestValidator.predicate(
    "todo.deleted_at should be null or undefined on creation",
    () => todo.deleted_at === null || todo.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated member user can create a todo with an optional
 * description and that lifecycle defaults are applied correctly.
 *
 * Business goals:
 *
 * - Joining a member user establishes authenticated context through
 *   api.functional.auth.memberUser.join.
 * - Creating a todo via api.functional.todoApp.memberUser.todos.create correctly
 *   associates it with the authenticated member user.
 * - Optional description is accepted and persisted when provided.
 * - Lifecycle fields (status, created_at, updated_at, completed_at, deleted_at)
 *   follow the expected defaults for a new todo.
 *
 * Test workflow:
 *
 * 1. Register a new member user using POST /auth/memberUser/join with
 *    ITodoAppMemberUserJoin.IRequest. The SDK will set the Authorization header
 *    on the provided connection using the returned token.
 * 2. Build a todo creation request body with both title and a non-empty
 *    description and call POST /todoApp/memberUser/todos with
 *    ITodoAppTodo.ICreate.
 * 3. Assert that the response is a valid ITodoAppTodo and that the title and
 *    description exactly match the request body values.
 * 4. Validate lifecycle semantics:
 *
 *    - Status is a non-empty string (treat concrete value as an implementation
 *         detail but do check it is truthy).
 *    - Created_at and updated_at are valid ISO date-time strings and updated_at is
 *         not earlier than created_at.
 *    - Completed_at and deleted_at are null.
 * 5. As an additional variation, create a second todo without supplying
 *    description to confirm that omitting the optional field still results in a
 *    valid todo with lifecycle defaults and a null/undefined description.
 */
export async function test_api_todo_creation_with_optional_description(
  connection: api.IConnection,
) {
  // 1. Register a new member user, which also sets Authorization header
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create a todo with non-empty description
  const titleWithDescription = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 3,
    wordMax: 8,
  });
  const description = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 8,
  });

  const createBodyWithDescription = {
    title: titleWithDescription,
    description,
  } satisfies ITodoAppTodo.ICreate;

  const todoWithDescription: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBodyWithDescription,
    });
  typia.assert(todoWithDescription);

  // 3. Validate basic field echoing for title and description
  TestValidator.equals(
    "todo with description: title should match request body",
    todoWithDescription.title,
    createBodyWithDescription.title,
  );
  TestValidator.equals(
    "todo with description: description should match request body",
    todoWithDescription.description,
    createBodyWithDescription.description,
  );

  // 4. Validate lifecycle fields for first todo
  TestValidator.predicate(
    "todo with description: status must be a non-empty string",
    typeof todoWithDescription.status === "string" &&
      todoWithDescription.status.trim().length > 0,
  );

  // created_at and updated_at are ISO date-time strings; ensure updated_at >= created_at
  const createdAtFirst = new Date(todoWithDescription.created_at).getTime();
  const updatedAtFirst = new Date(todoWithDescription.updated_at).getTime();

  TestValidator.predicate(
    "todo with description: created_at must be a valid date",
    !Number.isNaN(createdAtFirst),
  );
  TestValidator.predicate(
    "todo with description: updated_at must be a valid date",
    !Number.isNaN(updatedAtFirst),
  );
  TestValidator.predicate(
    "todo with description: updated_at should not be earlier than created_at",
    updatedAtFirst >= createdAtFirst,
  );

  TestValidator.equals(
    "todo with description: completed_at should be null when newly created",
    todoWithDescription.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "todo with description: deleted_at should be null when newly created",
    todoWithDescription.deleted_at ?? null,
    null,
  );

  // 5. Create a second todo without description to validate optional handling
  const titleWithoutDescription = RandomGenerator.paragraph({
    sentences: 1,
    wordMin: 3,
    wordMax: 8,
  });

  const createBodyWithoutDescription = {
    title: titleWithoutDescription,
  } satisfies ITodoAppTodo.ICreate;

  const todoWithoutDescription: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBodyWithoutDescription,
    });
  typia.assert(todoWithoutDescription);

  // Validate title echo and that description is null/undefined
  TestValidator.equals(
    "todo without description: title should match request body",
    todoWithoutDescription.title,
    createBodyWithoutDescription.title,
  );
  TestValidator.equals(
    "todo without description: description should be null when omitted in request",
    todoWithoutDescription.description ?? null,
    null,
  );

  // Lifecycle checks for second todo
  TestValidator.predicate(
    "todo without description: status must be a non-empty string",
    typeof todoWithoutDescription.status === "string" &&
      todoWithoutDescription.status.trim().length > 0,
  );

  const createdAtSecond = new Date(todoWithoutDescription.created_at).getTime();
  const updatedAtSecond = new Date(todoWithoutDescription.updated_at).getTime();

  TestValidator.predicate(
    "todo without description: created_at must be a valid date",
    !Number.isNaN(createdAtSecond),
  );
  TestValidator.predicate(
    "todo without description: updated_at must be a valid date",
    !Number.isNaN(updatedAtSecond),
  );
  TestValidator.predicate(
    "todo without description: updated_at should not be earlier than created_at",
    updatedAtSecond >= createdAtSecond,
  );

  TestValidator.equals(
    "todo without description: completed_at should be null when newly created",
    todoWithoutDescription.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "todo without description: deleted_at should be null when newly created",
    todoWithoutDescription.deleted_at ?? null,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate todo creation for an authenticated member user.
 *
 * Original business intent was to ensure that inactive member users cannot
 * create todos. However, with the currently available API surface, there is no
 * endpoint to transition a member user's status to an inactive/disabled state
 * and test that constraint directly, nor is there a safe way for the test
 * itself to manipulate authentication headers.
 *
 * Therefore, this test focuses on the positive path that is implementable with
 * the provided SDK:
 *
 * 1. Register a new member user via POST /auth/memberUser/join.
 * 2. Assert that the join response is a valid ITodoAppMemberuser.IAuthorized
 *    object and that key lifecycle fields look consistent for a fresh account.
 * 3. Using the authenticated connection (token set by the SDK), call POST
 *    /todoApp/memberUser/todos with a valid ITodoAppTodo.ICreate payload to
 *    create a todo for that member user.
 * 4. Assert that the created ITodoAppTodo is well-formed and that its memberUser
 *    summary matches the authenticated member user's identity (id and email)
 *    and exhibits active-like lifecycle state (non-empty status, not deleted).
 *
 * This keeps the test fully type-safe and compilable while still exercising the
 * main endpoint under realistic authenticated conditions.
 */
export async function test_api_todo_creation_rejected_for_inactive_member_user(
  connection: api.IConnection,
) {
  // 1. Register a new member user via /auth/memberUser/join
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // Basic lifecycle sanity checks on the newly created member user
  TestValidator.predicate(
    "member user id is a non-empty UUID string",
    authorized.id.length > 0,
  );
  TestValidator.predicate(
    "member user email matches requested email",
    authorized.email === joinBody.email,
  );
  TestValidator.predicate(
    "member user status is non-empty (represents active-like state)",
    authorized.status.length > 0,
  );
  TestValidator.predicate(
    "member user is not logically deleted on registration",
    authorized.deleted_at === null || authorized.deleted_at === undefined,
  );

  // 2. Create a todo for the authenticated member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(todo);

  // 3. Validate todo ownership and lifecycle basics
  TestValidator.equals(
    "todo owner id matches authenticated member user id",
    todo.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "todo owner email matches authenticated member user email",
    todo.memberUser.email,
    authorized.email,
  );
  TestValidator.predicate(
    "todo title matches the requested title",
    todo.title === createBody.title,
  );
  TestValidator.predicate(
    "todo has a non-empty status string",
    todo.status.length > 0,
  );
  TestValidator.predicate(
    "todo is not logically deleted immediately after creation",
    todo.deleted_at === null || todo.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that the owning member user can update the basic content fields of an
 * existing todo.
 *
 * Business workflow:
 *
 * 1. Register a new member user with POST /auth/memberUser/join to obtain an
 *    authenticated context.
 * 2. Using that context, create an initial todo with POST
 *    /todoApp/memberUser/todos, giving it a title and no description.
 * 3. Call PUT /todoApp/memberUser/todos/{todoId} with an ITodoAppTodo.IUpdate body
 *    that changes the title and adds a description.
 * 4. Assert that the response is a valid ITodoAppTodo.
 * 5. Validate business invariants:
 *
 *    - Id and memberUser are unchanged.
 *    - Title and description match the update payload.
 *    - Updated_at is later than the previous updated_at.
 *    - Status, completed_at, and deleted_at remain equal to their previous values.
 */
export async function test_api_todo_update_basic_fields_by_owner(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) to establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create an initial todo with a title and no description
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: null,
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // Guard that description is currently null and status lifecycle baseline is captured
  TestValidator.equals(
    "initial description should be null",
    created.description ?? null,
    null,
  );

  const previousStatus = created.status;
  const previousCompletedAt = created.completed_at ?? null;
  const previousDeletedAt = created.deleted_at ?? null;
  const previousUpdatedAt = created.updated_at;

  // 3. Update the todo's title and description using PUT /todoApp/memberUser/todos/{todoId}
  const newTitle = RandomGenerator.paragraph({ sentences: 2 });
  const newDescription = RandomGenerator.paragraph({ sentences: 4 });

  const updateBody = {
    title: newTitle,
    description: newDescription,
  } satisfies ITodoAppTodo.IUpdate;

  const updated: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: created.id,
      body: updateBody,
    });
  typia.assert(updated);

  // 4. Validate identity and ownership invariants
  TestValidator.equals(
    "todo id must remain unchanged after update",
    updated.id,
    created.id,
  );

  TestValidator.equals(
    "owning memberUser must remain unchanged after update",
    updated.memberUser,
    created.memberUser,
  );

  // 5. Validate content updates
  TestValidator.equals(
    "title should be updated to the new value",
    updated.title,
    newTitle,
  );

  TestValidator.equals(
    "description should be updated to the new non-null value",
    updated.description ?? null,
    newDescription,
  );

  // 6. Validate updated_at has advanced
  const initialUpdatedAt = new Date(previousUpdatedAt).getTime();
  const updatedUpdatedAt = new Date(updated.updated_at).getTime();

  TestValidator.predicate(
    "updated_at must be later than previous updated_at",
    updatedUpdatedAt > initialUpdatedAt,
  );

  // 7. Lifecycle fields should remain unchanged for this basic content update
  TestValidator.equals(
    "status should remain unchanged when only basic fields are updated",
    updated.status,
    previousStatus,
  );

  TestValidator.equals(
    "completed_at should remain unchanged when only basic fields are updated",
    updated.completed_at ?? null,
    previousCompletedAt,
  );

  TestValidator.equals(
    "deleted_at should remain unchanged when only basic fields are updated",
    updated.deleted_at ?? null,
    previousDeletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate lifecycle transition of a todo from pending to completed via the
 * generic update endpoint.
 *
 * Business goals:
 *
 * - A freshly joined member user can create a todo.
 * - The created todo starts in a non-completed state with completed_at null and
 *   deleted_at null.
 * - Updating the todo's status to a completed value transitions status and sets
 *   completed_at while keeping deleted_at null.
 * - Updated_at advances when the todo is updated and never goes backwards
 *   relative to created_at.
 *
 * High level flow:
 *
 * 1. Join as a member user using /auth/memberUser/join.
 * 2. Create a new todo using /todoApp/memberUser/todos (ITodoAppTodo.ICreate).
 * 3. Update the todo using /todoApp/memberUser/todos/{todoId} with
 *    ITodoAppTodo.IUpdate that sets status to "completed".
 * 4. Assert status, completed_at, updated_at, and deleted_at behave according to
 *    lifecycle expectations.
 */
export async function test_api_todo_update_status_to_completed(
  connection: api.IConnection,
) {
  // 1. Register a member user so that subsequent calls are authenticated as this user.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a new todo for this member user.
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // Basic invariants on freshly created todo.
  TestValidator.equals(
    "created todo has same title as request",
    created.title,
    createBody.title,
  );

  // Lifecycle expectations before completion
  TestValidator.predicate(
    "created_at is not empty",
    created.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is not empty",
    created.updated_at.length > 0,
  );

  if (created.completed_at !== null && created.completed_at !== undefined) {
    TestValidator.predicate(
      "if completed_at is already set, it must be non-empty string",
      created.completed_at.length > 0,
    );
  }

  // For a newly created todo, deleted_at should not be set.
  TestValidator.predicate(
    "deleted_at should not be set for a newly created todo",
    created.deleted_at === null || created.deleted_at === undefined,
  );

  // 3. Update the todo status to completed using the generic update endpoint.
  const completedStatus = "completed";
  const updateBody = {
    status: completedStatus,
  } satisfies ITodoAppTodo.IUpdate;

  const updated: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: created.id,
      body: updateBody,
    });
  typia.assert<ITodoAppTodo>(updated);

  // 4. Business assertions after update

  // Status must reflect the completed state we requested.
  TestValidator.equals(
    "todo status should be updated to completed",
    updated.status,
    completedStatus,
  );

  // completed_at should now be non-null, indicating completion time recorded.
  TestValidator.predicate(
    "completed_at is set after marking todo as completed",
    updated.completed_at !== null && updated.completed_at !== undefined,
  );

  if (updated.completed_at !== null && updated.completed_at !== undefined) {
    TestValidator.predicate(
      "completed_at string is non-empty",
      updated.completed_at.length > 0,
    );
  }

  // deleted_at should remain null for a normal completion.
  TestValidator.predicate(
    "deleted_at remains null after completion",
    updated.deleted_at === null || updated.deleted_at === undefined,
  );

  // updated_at should be >= created_at and should advance between create and update.
  const createdAtMs = Date.parse(created.created_at);
  const createdUpdatedAtMs = Date.parse(created.updated_at);
  const updatedUpdatedAtMs = Date.parse(updated.updated_at);

  TestValidator.predicate(
    "created.updated_at is not earlier than created.created_at",
    !Number.isNaN(createdAtMs) &&
      !Number.isNaN(createdUpdatedAtMs) &&
      createdUpdatedAtMs >= createdAtMs,
  );

  TestValidator.predicate(
    "updated.updated_at is not earlier than created.updated_at",
    !Number.isNaN(createdUpdatedAtMs) &&
      !Number.isNaN(updatedUpdatedAtMs) &&
      updatedUpdatedAtMs >= createdUpdatedAtMs,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that updating a todo with description: null clears the description
 * while preserving other lifecycle fields and the title.
 *
 * Business workflow:
 *
 * 1. Register a member user via /auth/memberUser/join so that the SDK attaches an
 *    Authorization token to the connection.
 * 2. Create a todo for that authenticated member user with a non-null description
 *    using /todoApp/memberUser/todos (ITodoAppTodo.ICreate).
 * 3. Update the todo using /todoApp/memberUser/todos/{todoId} (PUT) with an
 *    ITodoAppTodo.IUpdate body that explicitly sets description to null and
 *    does not include title or status.
 * 4. Verify from the update response that:
 *
 *    - Title is unchanged;
 *    - Description is now null (cleared);
 *    - Updated_at has changed (advanced) compared to the original todo;
 *    - Status, completed_at, and deleted_at remain equal to their original values.
 */
export async function test_api_todo_update_clears_description(
  connection: api.IConnection,
) {
  // 1. Register a member user (join) to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create a todo with non-null description.
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(createdTodo);

  // Ensure preconditions: description is not null and has some content.
  TestValidator.predicate(
    "created todo description must be non-null before clearing",
    createdTodo.description !== null && createdTodo.description !== undefined,
  );

  // Take a snapshot of fields we expect to remain stable or to compare.
  const originalTitle = createdTodo.title;
  const originalStatus = createdTodo.status;
  const originalUpdatedAt = createdTodo.updated_at;
  const originalCompletedAt = createdTodo.completed_at;
  const originalDeletedAt = createdTodo.deleted_at;

  // 3. Update the todo, clearing the description by setting it explicitly to null.
  const updateBody = {
    description: null,
  } satisfies ITodoAppTodo.IUpdate;

  const updatedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: createdTodo.id,
      body: updateBody,
    });
  typia.assert(updatedTodo);

  // 4. Validate business rules.
  // 4-1. Title remains unchanged.
  TestValidator.equals(
    "todo title should remain unchanged after clearing description",
    updatedTodo.title,
    originalTitle,
  );

  // 4-2. Description is now null.
  TestValidator.predicate(
    "todo description should be null after update",
    updatedTodo.description === null,
  );

  // 4-3. updated_at has advanced (is not equal to the previous value).
  TestValidator.notEquals(
    "updated_at should change after description update",
    updatedTodo.updated_at,
    originalUpdatedAt,
  );

  // 4-4. status remains the same.
  TestValidator.equals(
    "todo status should remain unchanged when only description is cleared",
    updatedTodo.status,
    originalStatus,
  );

  // 4-5. completed_at remains the same (both in value and nullability).
  TestValidator.equals(
    "completed_at should remain unchanged when only description is cleared",
    updatedTodo.completed_at,
    originalCompletedAt ?? null,
  );

  // 4-6. deleted_at remains the same (both in value and nullability).
  TestValidator.equals(
    "deleted_at should remain unchanged when only description is cleared",
    updatedTodo.deleted_at,
    originalDeletedAt ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure a member user cannot update another member user's todo.
 *
 * Business goal:
 *
 * - Enforce strict per-user ownership on todo updates.
 * - Validate that an authenticated member user (B) cannot modify a todo owned by
 *   member user (A).
 * - Validation is based on the update operation failing for non-owners.
 *
 * Flow:
 *
 * 1. Register member user A via POST /auth/memberUser/join and obtain an
 *    authenticated context.
 * 2. Under user A's authentication, create a todo via POST
 *    /todoApp/memberUser/todos.
 * 3. Register member user B via POST /auth/memberUser/join; this switches the SDK
 *    connection Authorization to user B.
 * 4. While authenticated as B, attempt to update A's todo via PUT
 *    /todoApp/memberUser/todos/{todoId}.
 * 5. Assert that the update attempt results in an error (authorization
 *    enforcement) via TestValidator.error().
 *
 * Due to current SDK surface, there is no read endpoint for re-fetching the
 * todo, so we validate ownership enforcement solely by ensuring B's update
 * attempt fails.
 */
export async function test_api_todo_update_rejected_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Register member user A (owner of the todo)
  const joinBodyA = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberA: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBodyA,
    });
  typia.assert(memberA);

  // 2. Under user A's context, create a todo
  const createBodyA = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const todoOfA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBodyA,
    });
  typia.assert(todoOfA);

  // 3. Register member user B (non-owner attempting the update)
  const joinBodyB = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberB: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBodyB,
    });
  typia.assert(memberB);

  // 4. While authenticated as B, attempt to update A's todo
  const updateBodyByB = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    status: "completed",
  } satisfies ITodoAppTodo.IUpdate;

  await TestValidator.error(
    "non-owner should not be able to update another user's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.update(connection, {
        todoId: todoOfA.id,
        body: updateBodyByB,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure that soft-deleted todos cannot be updated.
 *
 * Business goal:
 *
 * - Once a todo has been logically deleted (deleted_at set), the update endpoint
 *   must reject any modification attempts, preserving deletion semantics and
 *   preventing accidental resurrection or mutation of deleted records.
 *
 * Scenario steps:
 *
 * 1. Register a member user via /auth/memberUser/join so that we have a valid
 *    authenticated memberUser context (token is auto-bound to the connection by
 *    the SDK).
 * 2. Create a todo for this member via /todoApp/memberUser/todos.
 * 3. Logically delete that todo using /todoApp/memberUser/todos/{todoId} DELETE,
 *    which according to ITodoAppTodo marks deleted_at.
 * 4. Attempt to update the deleted todo via /todoApp/memberUser/todos/{todoId} PUT
 *    with a valid ITodoAppTodo.IUpdate payload that changes
 *    title/description/status.
 * 5. Assert that the update call fails (throws) and that the todo returned from
 *    erase has a non-null deleted_at, confirming the record remains in a
 *    deleted state.
 */
export async function test_api_todo_update_rejected_for_deleted_todo(
  connection: api.IConnection,
) {
  // 1. Register a member user to obtain an authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a todo for this member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  TestValidator.equals(
    "created todo should not be deleted initially",
    created.deleted_at,
    null,
  );

  // 3. Logically delete the todo
  const erased: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.erase(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(erased);

  await TestValidator.predicate(
    "erased todo should have non-null deleted_at",
    async () => erased.deleted_at !== null && erased.deleted_at !== undefined,
  );

  // 4. Attempt to update the logically deleted todo and expect failure
  const updateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
    status: "completed",
  } satisfies ITodoAppTodo.IUpdate;

  await TestValidator.error(
    "cannot update logically deleted todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.update(connection, {
        todoId: created.id,
        body: updateBody,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserRefresh";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify token refresh immediately after member user registration.
 *
 * This E2E test ensures that a freshly registered member user can successfully
 * refresh their authentication tokens using the `/auth/memberUser/refresh`
 * endpoint. It validates that the refresh flow preserves member identity and
 * issues a valid new authorization token structure.
 *
 * Business flow:
 *
 * 1. Register a new member user with POST /auth/memberUser/join using a unique
 *    email, valid password, and realistic href/referrer.
 * 2. Confirm that the join response conforms to `ITodoAppMemberuser.IAuthorized`
 *    and extract the refresh token.
 * 3. Call POST /auth/memberUser/refresh with `ITodoAppMemberUserRefresh.IRequest`
 *    using the extracted refresh token.
 * 4. Validate that the refresh response is also a valid
 *    `ITodoAppMemberuser.IAuthorized` instance.
 * 5. Ensure the member identity fields (id, email, status, etc.) are preserved
 *    between the original and refreshed contexts and that the account remains
 *    in an authenticable state (no unexpected status changes and deleted_at
 *    remains null/undefined).
 * 6. Confirm that token objects from both responses look structurally correct via
 *    `typia.assert`, and that the refresh issues a new access token value
 *    relative to the original one.
 */
export async function test_api_member_user_token_refresh_after_join(
  connection: api.IConnection,
) {
  // 1. Join a new member user with realistic registration data
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(joined);

  // Sanity-check basic identity invariants from the join response
  TestValidator.predicate(
    "joined member id should be a non-empty uuid string",
    () => joined.id.length > 0,
  );
  TestValidator.predicate(
    "joined member email should equal requested email",
    () => joined.email === joinBody.email,
  );

  // 2. Extract the refresh token from the join response
  const originalToken: IAuthorizationToken = joined.token;
  typia.assert<IAuthorizationToken>(originalToken);

  TestValidator.predicate(
    "original access token string should be non-empty",
    () => originalToken.access.length > 0,
  );
  TestValidator.predicate(
    "original refresh token string should be non-empty",
    () => originalToken.refresh.length > 0,
  );

  // 3. Call refresh API using the refresh token
  const refreshBody = {
    refreshToken: originalToken.refresh,
  } satisfies ITodoAppMemberUserRefresh.IRequest;

  const refreshed: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.refresh(connection, {
      body: refreshBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(refreshed);

  const refreshedToken: IAuthorizationToken = refreshed.token;
  typia.assert<IAuthorizationToken>(refreshedToken);

  // 4. Identity must be preserved between join and refresh
  TestValidator.equals(
    "refreshed member id should equal joined member id",
    refreshed.id,
    joined.id,
  );
  TestValidator.equals(
    "refreshed member email should equal joined member email",
    refreshed.email,
    joined.email,
  );

  TestValidator.equals(
    "account status should remain unchanged after refresh",
    refreshed.status,
    joined.status,
  );

  TestValidator.equals(
    "failed_login_count should be stable across refresh",
    refreshed.failed_login_count,
    joined.failed_login_count,
  );

  // last_login_at and deleted_at are nullable/undefinable; we only
  // ensure that logical deletion has not been introduced by refresh.
  TestValidator.equals(
    "deleted_at should not become non-null due to refresh",
    refreshed.deleted_at ?? null,
    joined.deleted_at ?? null,
  );

  // 5. Token structure correctness is already ensured by typia.assert,
  // but we add a simple business check that refresh rotates access token.
  TestValidator.predicate(
    "refreshed access token should differ from original access token",
    () => refreshedToken.access !== originalToken.access,
  );
}

