/**
 * Validate basic paginated listing of guest users for an authenticated
 * guestUser.
 *
 * Business goals
 *
 * - Ensure a guestUser actor (obtained via POST /auth/guestUser/join) can
 *   successfully call PATCH /todoApp/guestUser/guestUsers.
 * - Verify that simple pagination parameters (page and limit) are respected and
 *   correctly reflected in the IPage.IPagination metadata.
 * - Confirm that each returned summary row structurally matches
 *   ITodoAppGuestUser.ISummary and looks reasonable for list rendering.
 *
 * Scenario steps
 *
 * 1. Call api.functional.auth.guestUser.join to obtain
 *    ITodoAppGuestUser.IAuthorized and implicitly configure the connection for
 *    authenticated guestUser requests.
 * 2. Request the first page of guest users with limit = 10 via
 *    api.functional.todoApp.guestUser.guestUsers.index, using an
 *    ITodoAppGuestUser.IRequest body with only page and limit populated.
 * 3. Assert the response type with
 *    typia.assert<IPageITodoAppGuestuser.ISummary>().
 * 4. Validate pagination metadata:
 *
 *    - Pagination.current must equal 1
 *    - Pagination.limit must equal 10
 *    - Pagination.records and pagination.pages must be non-negative integers.
 * 5. Iterate over data, asserting each element with typia.assert and checking
 *    that:
 *
 *    - Id is a non-empty string (UUID format is already guaranteed by typia)
 *    - Created_at and updated_at are non-empty strings (date-time format guaranteed
 *         by typia)
 * 6. Perform a second listing call with a different limit (e.g., 5) and verify:
 *
 *    - Pagination.limit equals the new limit
 *    - Data.length does not exceed the requested limit.
 */
export async function test_api_guest_user_list_basic_pagination(
  connection: api.IConnection,
) {
  // 1. Join as a guest user to establish guestUser authorization context
  const authorized = await api.functional.auth.guestUser.join(connection, {
    body: {
      // display_name is optional; provide a random name for realism
      display_name: RandomGenerator.name(1),
    } satisfies ITodoAppGuestUser.IJoin,
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);

  // 2. Request first page with limit = 10
  const requestPage1 = {
    page: 1 satisfies number,
    limit: 10 satisfies number,
  } satisfies ITodoAppGuestUser.IRequest;

  const page1 = await api.functional.todoApp.guestUser.guestUsers.index(
    connection,
    {
      body: requestPage1,
    },
  );
  typia.assert<IPageITodoAppGuestuser.ISummary>(page1);

  const pagination1 = page1.pagination;

  // 3. Validate pagination metadata for first request
  TestValidator.equals(
    "pagination.current should equal requested page (1)",
    pagination1.current,
    requestPage1.page,
  );
  TestValidator.equals(
    "pagination.limit should equal requested limit (10)",
    pagination1.limit,
    requestPage1.limit,
  );
  TestValidator.predicate(
    "pagination.records should be non-negative",
    pagination1.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages should be non-negative",
    pagination1.pages >= 0,
  );

  // 4. Validate each summary item structure and basic sanity
  for (const summary of page1.data) {
    typia.assert<ITodoAppGuestUser.ISummary>(summary);

    TestValidator.predicate(
      "guest user id should be non-empty string",
      summary.id.length > 0,
    );
    TestValidator.predicate(
      "guest user created_at should be non-empty string",
      summary.created_at.length > 0,
    );
    TestValidator.predicate(
      "guest user updated_at should be non-empty string",
      summary.updated_at.length > 0,
    );
  }

  // 5. Perform a second listing with different limit to confirm limit behavior
  const secondLimit = 5;
  const requestPage1Limit5 = {
    page: 1 satisfies number,
    limit: secondLimit satisfies number,
  } satisfies ITodoAppGuestUser.IRequest;

  const page1Limit5 = await api.functional.todoApp.guestUser.guestUsers.index(
    connection,
    {
      body: requestPage1Limit5,
    },
  );
  typia.assert<IPageITodoAppGuestuser.ISummary>(page1Limit5);

  const paginationLimit5 = page1Limit5.pagination;

  TestValidator.equals(
    "pagination.current should remain 1 for second request",
    paginationLimit5.current,
    requestPage1Limit5.page,
  );
  TestValidator.equals(
    "pagination.limit should reflect new limit (5)",
    paginationLimit5.limit,
    requestPage1Limit5.limit,
  );
  TestValidator.predicate(
    "data length should not exceed requested limit (5)",
    page1Limit5.data.length <= secondLimit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

/**
 * Validate date range filtering when listing guest users.
 *
 * Business goal
 *
 * - Ensure operators can slice guest cohorts by creation time using PATCH
 *   /todoApp/guestUser/guestUsers.
 * - Confirm that both created_from (lower bound) and created_to (upper bound) are
 *   applied inclusively and that results never leak outside the window.
 *
 * Test steps
 *
 * 1. Join as a guest user via POST /auth/guestUser/join to obtain
 *    ITodoAppGuestUser.IAuthorized and let the SDK install the token in the
 *    shared connection.
 * 2. Capture the guest user created_at timestamp from the join response.
 * 3. Construct a [from, to] window around that timestamp:
 *
 *    - From: a bit before created_at (for example, created_at minus 5 minutes).
 *    - To: a bit after created_at (for example, created_at plus 5 minutes). All
 *         values must be ISO 8601 strings as required by
 *         ITodoAppGuestUser.IRequest.created_from/created_to.
 * 4. Call api.functional.todoApp.guestUser.guestUsers.index with an
 *    ITodoAppGuestUser.IRequest body that sets:
 *
 *    - Page: 1
 *    - Limit: a small int32 like 10
 *    - Created_from: from
 *    - Created_to: to
 *    - Order_by/order_direction may be omitted so that server defaults apply.
 * 5. Assert the response type using
 *    typia.assert<IPageITodoAppGuestuser.ISummary>(...).
 * 6. For each ITodoAppGuestUser.ISummary in output.data, assert:
 *
 *    - Created_at >= from
 *    - Created_at <= to using Date comparisons and TestValidator.predicate with
 *         descriptive titles.
 * 7. For stronger validation of the upper bound, perform a second list call with a
 *    non-overlapping window that is strictly before the guest's created_at (for
 *    example, [created_at minus 30 minutes, created_at minus 20 minutes]).
 *    Assert that output.data.length === 0 using TestValidator.equals.
 *
 * Implementation notes
 *
 * - Use only the provided imports, especially typia and RandomGenerator if
 *   needed, but keep the test deterministic by basing the window on the actual
 *   created_at value from ITodoAppGuestUser.IAuthorized.
 * - ITodoAppGuestUser.IRequest is used only as the request body type, while
 *   IPageITodoAppGuestuser.ISummary and ITodoAppGuestUser.ISummary describe the
 *   paginated response.
 * - Be careful to use Date.toISOString() for all derived timestamps so they match
 *   string & tags.Format<"date-time">.
 */
export async function test_api_guest_user_list_with_creation_date_range_filter(
  connection: api.IConnection,
) {
  // 1. Join as a guest user and obtain authorization context
  const authorized = await api.functional.auth.guestUser.join(connection, {
    body: {},
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);

  // 2. Capture created_at and parse into Date
  const createdAt = new Date(authorized.created_at);

  // 3. Build an inclusive [from, to] window around created_at
  const fiveMinutesMs = 5 * 60 * 1000;
  const from = new Date(createdAt.getTime() - fiveMinutesMs).toISOString();
  const to = new Date(createdAt.getTime() + fiveMinutesMs).toISOString();

  // 4. Call the listing endpoint with the window
  const inRangePage = await api.functional.todoApp.guestUser.guestUsers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        created_from: from,
        created_to: to,
      } satisfies ITodoAppGuestUser.IRequest,
    },
  );
  typia.assert<IPageITodoAppGuestuser.ISummary>(inRangePage);

  // 5. Validate every record falls within [from, to] inclusively
  const fromDate = new Date(from);
  const toDate = new Date(to);

  for (const summary of inRangePage.data) {
    const createdAtSummary = new Date(summary.created_at);

    TestValidator.predicate(
      "guest user created_at should be on or after created_from",
      createdAtSummary.getTime() >= fromDate.getTime(),
    );
    TestValidator.predicate(
      "guest user created_at should be on or before created_to",
      createdAtSummary.getTime() <= toDate.getTime(),
    );
  }

  // 6. Build a non-overlapping window entirely before the guest's created_at
  const thirtyMinutesMs = 30 * 60 * 1000;
  const twentyMinutesMs = 20 * 60 * 1000;
  const beforeFrom = new Date(
    createdAt.getTime() - thirtyMinutesMs,
  ).toISOString();
  const beforeTo = new Date(
    createdAt.getTime() - twentyMinutesMs,
  ).toISOString();

  const beforePage = await api.functional.todoApp.guestUser.guestUsers.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        created_from: beforeFrom,
        created_to: beforeTo,
      } satisfies ITodoAppGuestUser.IRequest,
    },
  );
  typia.assert<IPageITodoAppGuestuser.ISummary>(beforePage);

  TestValidator.equals(
    "non-overlapping created_at window should return no guest users",
    beforePage.data.length,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

/**
 * Validate guest user listing sorting by created_at.
 *
 * Business goal:
 *
 * - Ensure that PATCH /todoApp/guestUser/guestUsers honors order_by and
 *   order_direction when listing guest user summaries.
 *
 * Steps:
 *
 * 1. Join as a guest user via POST /auth/guestUser/join to establish guestUser
 *    authorization context.
 * 2. Call guestUsers.index with order_by = "created_at" and order_direction =
 *    "desc" and a fixed page/limit to obtain a descending-sorted page.
 * 3. Assert the response type as IPageITodoAppGuestuser.ISummary and that its data
 *    array is sorted by created_at descending.
 * 4. Call guestUsers.index again with order_direction = "asc" to obtain an
 *    ascending-sorted page.
 * 5. Assert the second response type and that its data array is sorted by
 *    created_at ascending.
 * 6. When both pages contain at least one item, perform a basic cross-check (e.g.,
 *    comparing boundary created_at values) to strengthen confidence that
 *    order_direction is applied correctly.
 */
export async function test_api_guest_user_list_with_sorting(
  connection: api.IConnection,
) {
  // 1. Establish guestUser context by joining as a guest user.
  const joinBody = {
    display_name: RandomGenerator.name(1),
  } satisfies ITodoAppGuestUser.IJoin;

  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Request guest users ordered by created_at DESC.
  const descRequest = {
    page: 1,
    limit: 50,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppGuestUser.IRequest;

  const descPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.guestUser.guestUsers.index(connection, {
      body: descRequest,
    });
  typia.assert(descPage);

  // 3. Validate descending sort on created_at when multiple items exist.
  const descData = descPage.data;
  if (descData.length >= 2) {
    await ArrayUtil.asyncForEach(descData, async (current, index, array) => {
      if (index === 0) return;
      const prev = array[index - 1];
      const prevTime = new Date(prev.created_at).getTime();
      const currTime = new Date(current.created_at).getTime();

      TestValidator.predicate(
        "guest users should be sorted by created_at in descending order",
        prevTime >= currTime,
      );
    });
  }

  // 4. Request guest users ordered by created_at ASC.
  const ascRequest = {
    page: 1,
    limit: 50,
    order_by: "created_at",
    order_direction: "asc",
  } satisfies ITodoAppGuestUser.IRequest;

  const ascPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.guestUser.guestUsers.index(connection, {
      body: ascRequest,
    });
  typia.assert(ascPage);

  const ascData = ascPage.data;
  if (ascData.length >= 2) {
    await ArrayUtil.asyncForEach(ascData, async (current, index, array) => {
      if (index === 0) return;
      const prev = array[index - 1];
      const prevTime = new Date(prev.created_at).getTime();
      const currTime = new Date(current.created_at).getTime();

      TestValidator.predicate(
        "guest users should be sorted by created_at in ascending order",
        prevTime <= currTime,
      );
    });
  }

  // 5. Cross-check boundaries when both results contain at least one item.
  if (descData.length > 0 && ascData.length > 0) {
    const newestFromDesc = descData[0];
    const oldestFromAsc = ascData[0];

    const newestTime = new Date(newestFromDesc.created_at).getTime();
    const oldestTime = new Date(oldestFromAsc.created_at).getTime();

    // Depending on dataset size and filters, these may not be exact
    // inverses, but we can at least assert they are valid date-times.
    TestValidator.predicate(
      "newest created_at from DESC page should be a valid timestamp",
      Number.isFinite(newestTime),
    );
    TestValidator.predicate(
      "oldest created_at from ASC page should be a valid timestamp",
      Number.isFinite(oldestTime),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppGuestuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppGuestuser";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

/**
 * Validate pagination boundary behavior for guest user listing.
 *
 * Business purpose:
 *
 * - Ensure PATCH /todoApp/guestUser/guestUsers behaves robustly when clients
 *   request pages at and beyond the available range.
 * - Confirm that out-of-range page requests do not cause errors and instead
 *   return an empty data set with consistent pagination metadata.
 *
 * Steps:
 *
 * 1. Join as a guest user via POST /auth/guestUser/join to establish a guestUser
 *    authorization context and configure the connection token.
 * 2. Call the listing endpoint with page = 1 and a small limit to obtain a
 *    baseline pagination snapshot.
 * 3. If there are no records, verify internal pagination consistency (records = 0,
 *    pages = 0, data empty) and finish.
 * 4. If there are records and pages >= 1, call the listing endpoint again with
 *    page = pages + 1 (out-of-range) and the same limit.
 * 5. Assert that the out-of-range page response:
 *
 *    - Succeeds without error.
 *    - Has data as an empty array.
 *    - Preserves records, pages, and limit from the baseline snapshot.
 *    - Has a non-negative current page index that is not greater than pages.
 * 6. Optionally, call the endpoint with page = pages (last page) and verify that
 *    the last page is non-empty (when records > 0) and size is within the
 *    configured limit while preserving pagination metadata.
 */
export async function test_api_guest_user_list_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Establish guestUser authorization via join endpoint
  const joinBody = {
    // display_name is optional; we can provide a simple test value.
    display_name: "pagination-boundary-tester",
  } satisfies ITodoAppGuestUser.IJoin;

  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Call listing endpoint with page = 1 and a small limit
  const initialRequest = {
    page: 1,
    limit: 5,
  } satisfies ITodoAppGuestUser.IRequest;

  const firstPage: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.guestUser.guestUsers.index(connection, {
      body: initialRequest,
    });
  typia.assert(firstPage);

  const basePagination: IPage.IPagination = firstPage.pagination;
  const baseRecords = basePagination.records;
  const basePages = basePagination.pages;
  const baseLimit = basePagination.limit;

  // Sanity checks on baseline pagination
  TestValidator.predicate(
    "baseline current page is non-negative",
    () => basePagination.current >= 0,
  );
  TestValidator.predicate(
    "baseline pages is non-negative",
    () => basePages >= 0,
  );
  TestValidator.predicate(
    "baseline limit is non-negative",
    () => baseLimit >= 0,
  );

  if (baseRecords === 0) {
    // 3. No data: verify internal consistency and finish
    TestValidator.equals("no-records case: pages should be zero", basePages, 0);
    TestValidator.equals(
      "no-records case: data should be empty",
      firstPage.data.length,
      0,
    );
    return;
  }

  // When there are records, we expect at least one page
  TestValidator.predicate(
    "records>0 case: pages should be at least 1",
    () => basePages >= 1,
  );

  // 4. Out-of-range page request: page = basePages + 1
  const outOfRangePage = basePages + 1;
  const outOfRangeRequest = {
    page: outOfRangePage,
    limit: baseLimit,
  } satisfies ITodoAppGuestUser.IRequest;

  const outOfRangeResult: IPageITodoAppGuestuser.ISummary =
    await api.functional.todoApp.guestUser.guestUsers.index(connection, {
      body: outOfRangeRequest,
    });
  typia.assert(outOfRangeResult);

  const outPagination: IPage.IPagination = outOfRangeResult.pagination;

  // 4-a. Data must be empty for clearly out-of-range page
  TestValidator.equals(
    "out-of-range page should return empty data",
    outOfRangeResult.data.length,
    0,
  );

  // 4-b. Records and pages must remain consistent
  TestValidator.equals(
    "out-of-range page preserves records",
    outPagination.records,
    baseRecords,
  );
  TestValidator.equals(
    "out-of-range page preserves pages",
    outPagination.pages,
    basePages,
  );
  TestValidator.equals(
    "out-of-range page preserves limit",
    outPagination.limit,
    baseLimit,
  );

  // 4-c. current must be non-negative and not exceed pages (normalized or echoed)
  TestValidator.predicate(
    "out-of-range current page is non-negative",
    () => outPagination.current >= 0,
  );
  TestValidator.predicate(
    "out-of-range current page is not greater than total pages",
    () => outPagination.current <= outPagination.pages,
  );

  // 5. Optionally, validate last page behavior when basePages > 0
  if (basePages > 0) {
    const lastPageRequest = {
      page: basePages,
      limit: baseLimit,
    } satisfies ITodoAppGuestUser.IRequest;

    const lastPage: IPageITodoAppGuestuser.ISummary =
      await api.functional.todoApp.guestUser.guestUsers.index(connection, {
        body: lastPageRequest,
      });
    typia.assert(lastPage);

    const lastPagination = lastPage.pagination;

    // Metadata consistency
    TestValidator.equals(
      "last page preserves records",
      lastPagination.records,
      baseRecords,
    );
    TestValidator.equals(
      "last page preserves pages",
      lastPagination.pages,
      basePages,
    );
    TestValidator.equals(
      "last page preserves limit",
      lastPagination.limit,
      baseLimit,
    );

    // When records>0 and pages>0, we expect last page to be non-empty
    TestValidator.predicate(
      "last page should contain at least one record",
      () => lastPage.data.length > 0,
    );
    TestValidator.predicate(
      "last page size must not exceed limit",
      () => lastPage.data.length <= baseLimit,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
