import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_complete_happy_path_for_owner_member_user(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) and obtain authorized context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // Basic sanity checks on the authorized payload.
  await TestValidator.predicate("member user id is uuid", async () => {
    // typia.assert has already validated the format; this predicate just
    // double-checks that id is a non-empty string.
    return typeof authorized.id === "string" && authorized.id.length > 0;
  });

  // 2. Create a todo for this member user.
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // Capture initial lifecycle fields.
  const initialTodoId = created.id;
  const initialMemberUserId = created.memberUser.id;
  const initialStatus = created.status;
  const initialCompletedAt = created.completed_at ?? null;
  const initialUpdatedAt = created.updated_at;

  // Ownership should match the authorized member user.
  TestValidator.equals(
    "todo owner matches authorized member user",
    initialMemberUserId,
    authorized.id,
  );

  // Initially, completed_at should be null (or undefined interpreted as null).
  TestValidator.predicate(
    "initial completed_at is null or undefined",
    initialCompletedAt === null,
  );

  // 3. Complete the todo using the dedicated completion endpoint.
  const completed: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: initialTodoId,
    });
  typia.assert<ITodoAppTodo>(completed);

  // 4. Validate lifecycle and ownership invariants after completion.

  // Id and owner must remain the same.
  TestValidator.equals(
    "completed todo id matches original",
    completed.id,
    initialTodoId,
  );
  TestValidator.equals(
    "completed todo owner matches original",
    completed.memberUser.id,
    initialMemberUserId,
  );

  // completed_at should now be non-null.
  TestValidator.predicate(
    "completed_at is set after completion",
    completed.completed_at !== null && completed.completed_at !== undefined,
  );

  // updated_at should be greater than or equal to previous updated_at.
  const initialUpdatedAtDate = new Date(initialUpdatedAt).getTime();
  const completedUpdatedAtDate = new Date(completed.updated_at).getTime();
  TestValidator.predicate(
    "updated_at is not earlier after completion",
    completedUpdatedAtDate >= initialUpdatedAtDate,
  );

  // Status should change to something that looks like a completed state if it differed.
  // We do a best-effort check: if status changed, the new status should contain
  // the word "complete" (case-insensitive).
  const statusChanged = completed.status !== initialStatus;
  if (statusChanged) {
    const lower = completed.status.toLowerCase();
    TestValidator.predicate(
      "completed status string indicates completion",
      lower.includes("complete"),
    );
  }

  // 5. Optional idempotency check: calling complete again should keep it completed.
  const completedAgain: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: initialTodoId,
    });
  typia.assert<ITodoAppTodo>(completedAgain);

  TestValidator.equals(
    "idempotent completion keeps same id",
    completedAgain.id,
    completed.id,
  );
  TestValidator.predicate(
    "idempotent completion keeps completed_at non-null",
    completedAgain.completed_at !== null &&
      completedAgain.completed_at !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify idempotent completion of a todo item for a member user.
 *
 * Business purpose:
 *
 * - Ensure that clients can safely retry the `complete` operation for a todo
 *   without risk of errors or inconsistent lifecycle state.
 * - Confirm that once a todo has been completed, additional completion calls do
 *   not change its business status or completion timestamp, while maintaining
 *   coherent audit timestamps.
 *
 * Test steps:
 *
 * 1. Register a new member user via auth.memberUser.join and obtain the authorized
 *    context (token is auto-bound to `connection`).
 * 2. Create a new todo via todoApp.memberUser.todos.create and capture the initial
 *    ITodoAppTodo as `created`.
 * 3. Complete the todo once via todoApp.memberUser.todos.complete using the
 *    created todo's id, capturing `firstCompleted`.
 * 4. Immediately call the same complete endpoint again with the same todo id,
 *    capturing `secondCompleted`.
 * 5. Assert idempotency and lifecycle invariants between `created`,
 *    `firstCompleted`, and `secondCompleted`.
 *
 * Assertions:
 *
 * - All API responses conform to their DTO types (enforced via typia.assert).
 * - `created.id === firstCompleted.id === secondCompleted.id`.
 * - `firstCompleted.status === secondCompleted.status`.
 * - `created.status` differs from `firstCompleted.status` (the initial create
 *   should represent an uncompleted state while completion represents completed
 *   state; we only assert inequality, not concrete values, since allowed status
 *   strings are not enumerated in the schema).
 * - `firstCompleted.completed_at` is non-null.
 * - `secondCompleted.completed_at` is exactly equal to
 *   `firstCompleted.completed_at` (strong idempotency on completion
 *   timestamp).
 * - `created.completed_at` is null or undefined (no completion at initial
 *   creation; we allow null/undefined due to DTO definition).
 * - `firstCompleted.updated_at` is >= `created.updated_at`.
 * - `secondCompleted.updated_at` is >= `firstCompleted.updated_at`.
 * - `firstCompleted.deleted_at === secondCompleted.deleted_at` (no accidental
 *   deletion side effect).
 * - `firstCompleted.memberUser.id === secondCompleted.memberUser.id` and both
 *   match the authorized user id from join.
 */
export async function test_api_todo_complete_idempotent_when_already_completed(
  connection: api.IConnection,
) {
  // 1. Register a new member user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todoapp.example.com/join", // valid URI-like string
    referrer: "https://todoapp.example.com/landing", // valid URI-like string
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a new todo for this member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // Basic sanity: ownership and initial lifecycle
  TestValidator.equals(
    "todo is owned by the joined member user",
    created.memberUser.id,
    authorized.id,
  );

  // Note: DTO does not enumerate status values, so we only ensure basic
  // lifecycle transitions and completed_at behavior, not concrete strings.

  // 3. Complete the todo once
  const firstCompleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(firstCompleted);

  // 4. Immediately complete again (idempotent retry)
  const secondCompleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(secondCompleted);

  // 5. Idempotency and lifecycle assertions

  // Identity invariants
  TestValidator.equals(
    "todo id is stable across lifecycle",
    firstCompleted.id,
    created.id,
  );
  TestValidator.equals(
    "todo id is stable across repeated completion",
    secondCompleted.id,
    created.id,
  );

  // Ownership invariants
  TestValidator.equals(
    "owner id remains the same after first completion",
    firstCompleted.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "owner id remains the same after second completion",
    secondCompleted.memberUser.id,
    authorized.id,
  );

  // Status behavior
  TestValidator.notEquals(
    "status changes between creation and first completion",
    firstCompleted.status,
    created.status,
  );
  TestValidator.equals(
    "status remains stable between first and second completion",
    secondCompleted.status,
    firstCompleted.status,
  );

  // completed_at behavior
  TestValidator.predicate(
    "created todo has not yet been completed",
    created.completed_at === null || created.completed_at === undefined,
  );
  TestValidator.predicate(
    "first completion sets completed_at",
    firstCompleted.completed_at !== null &&
      firstCompleted.completed_at !== undefined,
  );
  TestValidator.equals(
    "completed_at is stable across repeated completion",
    secondCompleted.completed_at ?? null,
    firstCompleted.completed_at ?? null,
  );

  // updated_at monotonicity
  TestValidator.predicate(
    "first completion updated_at is >= created updated_at",
    firstCompleted.updated_at >= created.updated_at,
  );
  TestValidator.predicate(
    "second completion updated_at is >= first completion updated_at",
    secondCompleted.updated_at >= firstCompleted.updated_at,
  );

  // created_at stability
  TestValidator.equals(
    "created_at is stable after first completion",
    firstCompleted.created_at,
    created.created_at,
  );
  TestValidator.equals(
    "created_at is stable after second completion",
    secondCompleted.created_at,
    created.created_at,
  );

  // deleted_at stability
  TestValidator.equals(
    "deleted_at remains unchanged between first and second completion",
    secondCompleted.deleted_at ?? null,
    firstCompleted.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure that completing a todo requires authenticated member user context.
 *
 * This test verifies that the POST /todoApp/memberUser/todos/{todoId}/complete
 * endpoint enforces member user authentication and that anonymous callers
 * cannot complete todos.
 *
 * Workflow:
 *
 * 1. Register a new member user via POST /auth/memberUser/join and obtain an
 *    authorized session (handled automatically by the SDK via
 *    connection.headers.Authorization).
 * 2. Create a todo via POST /todoApp/memberUser/todos under that member account
 *    and capture its id and initial lifecycle state.
 * 3. Build an unauthenticated connection and attempt to complete the todo using
 *    POST /todoApp/memberUser/todos/{todoId}/complete, expecting the call to
 *    fail.
 * 4. Call the same completion endpoint again using the authenticated connection
 *    and verify that completion now succeeds and updates the todo lifecycle
 *    fields appropriately.
 *
 * Business rules validated:
 *
 * - Only authenticated member users may complete todos.
 * - Unauthorized attempts result in an error and do not prevent later authorized
 *   completion from succeeding.
 */
export async function test_api_todo_complete_authorization_enforced_for_member_user(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authenticated context
  const joinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const member: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2. Create a todo under the authenticated member user
  const createBody = typia.random<ITodoAppTodo.ICreate>();
  const todoBefore: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(todoBefore);

  // Verify ownership and initial lifecycle state
  TestValidator.equals(
    "created todo is owned by joined member user",
    todoBefore.memberUser.id,
    member.id,
  );
  TestValidator.equals(
    "newly created todo should not be completed yet",
    todoBefore.completed_at,
    null,
  );

  // 3. Attempt to complete todo without authentication
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated completion must fail",
    async () => {
      await api.functional.todoApp.memberUser.todos.complete(unauthConn, {
        todoId: todoBefore.id,
      });
    },
  );

  // 4. Complete todo with proper authentication
  const todoAfter: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: todoBefore.id,
    });
  typia.assert(todoAfter);

  // Validate lifecycle changes and ownership remain consistent
  TestValidator.equals(
    "todo id should remain the same after completion",
    todoAfter.id,
    todoBefore.id,
  );
  TestValidator.equals(
    "todo owner should remain the same after completion",
