import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure an admin user can invoke the member session deletion endpoint.
 *
 * This test walks through a realistic multi-actor auth flow, then calls the
 * admin-only DELETE
 * /todoApp/adminUser/memberUsers/{memberUserId}/sessions/{sessionId} endpoint
 * using the generated SDK.
 *
 * Steps:
 *
 * 1. Register an admin user via POST /auth/adminUser/join and obtain an
 *    ITodoAppAdminUser.IAuthorized context. The SDK automatically stores the
 *    admin access token into connection.headers.Authorization.
 * 2. Register a member user via POST /auth/memberUser/join, capturing
 *    ITodoAppMemberuser.IAuthorized, including the member id that will be
 *    referenced in the admin session delete call.
 * 3. Log in as that member user via POST /auth/memberUser/login to ensure that at
 *    least one authenticated session exists for this member in the backend
 *    (even though the sessionId is not exposed through the SDK).
 * 4. While authenticated as the member, create a todo through POST
 *    /todoApp/memberUser/todos to exercise the session and confirm that todo
 *    operations work for this account.
 * 5. Switch back to the admin user context by calling POST /auth/adminUser/login
 *    with the same credentials used at join-time. The SDK again updates
 *    connection.headers.Authorization.
 * 6. As the admin user, invoke
 *    api.functional.todoApp.adminUser.memberUsers.sessions.erase with the
 *    member user's id and a well-formed UUID as sessionId. Because there is no
 *    session read API, we cannot bind a concrete session row; the primary
 *    purpose here is to validate that an authenticated admin can reach the
 *    endpoint with correct types and without authorization errors.
 *
 * Within current SDK constraints we cannot assert DB-level deletion or
 * follow-up 404 semantics, but we ensure:
 *
 * - Both admin and member authentication flows are valid
 * - Member todo creation succeeds under member auth
 * - The admin-only session erase endpoint is callable with proper memberUserId
 *   and sessionId arguments and returns without throwing.
 */
export async function test_api_admin_delete_member_session_success(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain authorized context
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Register a member user and capture its id
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.test/member/join",
    referrer: "https://todo-app.test/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  const memberUserId = memberAuthorizedFromJoin.id;

  // 3. Log in as the member user to ensure a session exists
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://todo-app.test/member/login",
    referrer: "https://todo-app.test/signin",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  // 4. Create a todo as the authenticated member user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo belongs to the logged-in member user",
    createdTodo.memberUser.id,
    memberUserId,
  );

  // 5. Switch back to the admin user by logging in again as admin
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.test/admin/login",
    referrer: "https://todo-app.test/admin",
    user_agent: "todo-e2e-test-agent",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 6. As admin, invoke the session erase endpoint with a well-formed UUID
  const sessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  await api.functional.todoApp.adminUser.memberUsers.sessions.erase(
    connection,
    {
      memberUserId,
      sessionId,
    },
  );

  // If we reach here without HttpError, treat as success for contract-level test
  TestValidator.predicate(
    "admin session erase endpoint completed without throwing",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that admin session deletion with mismatched member/session
 * identifiers is safely handled and does not corrupt other users' ability to
 * operate.
 *
 * Business intent:
 *
 * - Admin-only endpoint
 *   `/todoApp/adminUser/memberUsers/{memberUserId}/sessions/{sessionId}` must
 *   strictly bind sessions to their owning member user.
 * - When an admin uses a `memberUserId` that does not match the real owner of a
 *   given `sessionId` (or the session does not exist), the system must respond
 *   in a safe, non-leaky way and must not accidentally invalidate or remove
 *   unrelated sessions.
 *
 * Constraints from the SDK surface:
 *
 * - Session internals (real `sessionId` values or a list of sessions) are not
 *   exposed via any API we can call from tests.
 * - The `erase` API returns `void` and does not surface HTTP status codes or
 *   error envelopes in its TypeScript signature.
 * - SDK functions automatically manage `connection.headers.Authorization` based
 *   on auth calls; tests must not manipulate headers manually.
 *
 * Therefore this E2E test focuses on a type-safe, observable behavior:
 *
 * - Create an admin and two separate member users (A and B).
 * - For each member, create at least one todo so we can confirm ownership and
 *   ensure their accounts and sessions are fully established.
 * - As admin, call the session erase endpoint with a mismatched pair:
 *   `memberUserId` = A.id and `sessionId` = a random UUID that does not
 *   correspond to any known session (and in particular not to A's sessions).
 * - Afterwards, confirm that member B is still able to authenticate and create
 *   new todos, demonstrating that the attempted deletion did not globally
 *   disrupt B’s ability to operate.
 */
export async function test_api_admin_delete_member_session_wrong_member_not_found(
  connection: api.IConnection,
) {
  // 1. Admin user registration (also authenticates admin and seeds Authorization)
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Member user A registration (join also authenticates as member A)
  const memberAEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberAPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberAJoinBody = {
    email: memberAEmail,
    password: memberAPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberAJoinBody,
    });
  typia.assert(memberAAuthorized);

  const memberAId: string & tags.Format<"uuid"> = memberAAuthorized.id;

  // 3. Member A creates a todo, confirming ownership
  const todoACreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const todoA: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoACreateBody,
    });
  typia.assert(todoA);

  TestValidator.equals(
    "todo A should belong to member A",
    todoA.memberUser.id,
    memberAId,
  );

  // 4. Member user B registration (join authenticates as member B)
  const memberBEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberBPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberBJoinBody = {
    email: memberBEmail,
    password: memberBPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberBAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberBJoinBody,
    });
  typia.assert(memberBAuthorized);

  const memberBId: string & tags.Format<"uuid"> = memberBAuthorized.id;

  // 5. Member B creates a todo, confirming independent ownership
  const todoBCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies ITodoAppTodo.ICreate;

  const todoB: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBCreateBody,
    });
  typia.assert(todoB);

  TestValidator.equals(
    "todo B should belong to member B",
    todoB.memberUser.id,
    memberBId,
  );

  TestValidator.notEquals(
    "member A and B must be different users",
    memberAId,
    memberBId,
  );

  // 6. Prepare a random sessionId that is guaranteed not to be tied to member A
  const randomSessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 7. Switch back to admin authentication using login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: null,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoggedIn: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  TestValidator.equals(
    "admin login should return same admin id as join",
    adminLoggedIn.id,
    adminAuthorized.id,
  );

  // 8. As admin, attempt to delete a session using a mismatched memberUserId
  //    and an arbitrary random sessionId. The contract says the backend should
  //    treat mismatches as not-found; on the client side we only ensure that
  //    this call does not break type guarantees or prevent future operations.
  await api.functional.todoApp.adminUser.memberUsers.sessions.erase(
    connection,
    {
      memberUserId: memberAId,
      sessionId: randomSessionId,
    },
  );

  // 9. After the deletion attempt, member B should still be able to log in and
  //    create a new todo, showing that their ability to operate remains intact.
  const memberBLoginBody = {
    email: memberBEmail,
    password: memberBPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberBLoggedIn: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberBLoginBody,
    });
  typia.assert(memberBLoggedIn);

  TestValidator.equals(
    "member B login after erase should still reference the same member id",
    memberBLoggedIn.id,
    memberBId,
  );

  const todoBAfterEraseCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies ITodoAppTodo.ICreate;

  const todoBAfterErase: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBAfterEraseCreateBody,
    });
  typia.assert(todoBAfterErase);

  TestValidator.equals(
    "member B can still create todos after mismatched session erase attempt",
    todoBAfterErase.memberUser.id,
    memberBId,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_delete_member_session_unauthorized_without_admin_auth(
  connection: api.IConnection,
) {
  // 1. Register a member user and obtain authorized context (member token + memberUserId)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://todo-app.example.com/",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Use the member token to create a todo (to ensure the session/account is active)
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Ensure the todo is owned by the created member user
  TestValidator.equals(
    "created todo is owned by the joined member user",
    createdTodo.memberUser.id,
    memberAuthorized.id,
  );

  // 3. Prepare a synthetic sessionId for test purposes (authz is what matters here)
  const fakeSessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4. Build an unauthenticated connection (no Authorization header)
  const unauthConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 4-1. Attempt erase with NO Authorization header -> expect 401 or 403
  await TestValidator.httpError(
    "unauthenticated caller cannot erase member user session",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.sessions.erase(
        unauthConnection,
        {
          memberUserId: memberAuthorized.id,
          sessionId: fakeSessionId,
        },
      );
    },
  );

  // 5. Using the memberUser token (on the original connection), attempt the admin erase
  await TestValidator.httpError(
    "member user token cannot erase member user session via admin endpoint",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.sessions.erase(
        connection,
        {
          memberUserId: memberAuthorized.id,
          sessionId: fakeSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an adminUser can retrieve detailed information for a member
 * user who already owns at least one todo.
 *
 * Business workflow:
 *
 * 1. Register an adminUser account and obtain admin tokens (connection becomes
 *    admin-authenticated).
 * 2. Register a member user account and obtain member tokens (connection becomes
 *    member-authenticated).
 * 3. As the member user, create at least one todo so that the account has
 *    activity.
 * 4. Switch back to the adminUser context via login so the connection is
 *    admin-authenticated again.
 * 5. As the adminUser, call the member user detail endpoint GET
 *    /todoApp/adminUser/memberUsers/{memberUserId} with the target member user
 *    id.
 * 6. Assert that the response is a full ITodoAppMemberuser record, with:
 *
 *    - Id and email matching the registered member user
 *    - Status set and non-empty
 *    - Failed_login_count = 0 for a fresh account
 *    - Deleted_at is null (or undefined) for an active account
 *    - Created_at and updated_at populated as valid date-time strings.
 * 7. Ensure that the existence of todos does not change the shape of the
 *    ITodoAppMemberuser response (no todo fields), which is guaranteed via
 *    typia.assert and DTO typing.
 */
export async function test_api_admin_member_user_detail_with_existing_todo(
  connection: api.IConnection,
) {
  // 1. Register adminUser and obtain admin tokens
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        display_name: RandomGenerator.name(),
      } satisfies ITodoAppAdminUser.IJoin,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminJoinOutput);

  // 2. Register member user and obtain member tokens
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinOutput: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: {
        email: memberEmail,
        password: memberPassword,
        display_name: RandomGenerator.name(),
        ip: null,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies ITodoAppMemberUserJoin.IRequest,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(memberJoinOutput);

  // 3. As the member user, create at least one todo
  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // Ensure the todo is owned by the joined member user
  TestValidator.equals(
    "created todo must belong to the joined member user",
    createdTodo.memberUser.id,
    memberJoinOutput.id,
  );

  // 4. Switch back to adminUser context via login
  const adminLoginOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        ip: null,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        user_agent: null,
      } satisfies ITodoAppAdminUser.ILogin,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminLoginOutput);

  // 5. As adminUser, retrieve member user detail
  const memberDetail: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.at(connection, {
      memberUserId: memberJoinOutput.id,
    });
  typia.assert<ITodoAppMemberuser>(memberDetail);

  // 6. Business assertions on the member detail
  TestValidator.equals(
    "member detail id matches joined member user id",
    memberDetail.id,
    memberJoinOutput.id,
  );
  TestValidator.equals(
    "member detail email matches joined member user email",
    memberDetail.email,
    memberJoinOutput.email,
  );

  // status should be non-empty string (typia.assert ensures string type)
  TestValidator.predicate(
    "member status should be non-empty string",
    memberDetail.status.length > 0,
  );

  // failed_login_count should be 0 right after join and before any bad logins
  TestValidator.equals(
    "failed_login_count should be 0 for a fresh member user",
    memberDetail.failed_login_count,
    0,
  );

  // deleted_at should be null or undefined for active member
  TestValidator.predicate(
    "deleted_at should be null or undefined for an active member user",
    memberDetail.deleted_at === null || memberDetail.deleted_at === undefined,
  );

  // created_at and updated_at presence is already validated by typia.assert,
  // but we can still assert they are non-empty strings logically.
  TestValidator.predicate(
    "created_at should be a non-empty string",
    memberDetail.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at should be a non-empty string",
    memberDetail.updated_at.length > 0,
  );

  // 7. Indirectly confirm that todos do not affect member detail shape.
  // If the response had unexpected fields or wrong structure, typia.assert
  // above would have thrown. Therefore, no additional structural assertion
  // is required here beyond this business comment.
}

