import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Ensure admin-only member user detail endpoint rejects non-admin or anonymous
 * callers.
 *
 * Business intent
 *
 * - The GET /todoApp/adminUser/memberUsers/{memberUserId} endpoint is restricted
 *   to adminUser actors.
 * - A regular memberUser token must not be able to access member user details
 *   through this admin surface.
 * - Anonymous (no token) callers must also be rejected.
 *
 * Steps
 *
 * 1. Register a member user using POST /auth/memberUser/join and obtain their id
 *    and token.
 * 2. With the memberUser-authenticated connection, attempt to call the adminUser
 *    memberUsers.at endpoint.
 * 3. Assert that the call fails with an HTTP authorization error (4xx, typically
 *    401/403) and does not return ITodoAppMemberuser.
 * 4. Derive an unauthenticated connection with empty headers.
 * 5. With this unauthenticated connection, call the same adminUser memberUsers.at
 *    endpoint.
 * 6. Assert that this call also fails with an HTTP authorization error.
 */
export async function test_api_admin_member_user_detail_unauthorized_without_admin_token(
  connection: api.IConnection,
) {
  // 1. Register a regular member user (guest -> memberUser)
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized = await api.functional.auth.memberUser.join(
    connection,
    {
      body: memberJoinBody,
    },
  );
  typia.assert(memberAuthorized);

  const targetMemberUserId = memberAuthorized.id;

  // 2. Call adminUser-only endpoint with memberUser token (should be unauthorized)
  await TestValidator.httpError(
    "memberUser token cannot access adminUser member user detail endpoint",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.at(connection, {
        memberUserId: targetMemberUserId,
      });
    },
  );

  // 3. Prepare an unauthenticated connection (no Authorization header)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 4. Call adminUser-only endpoint without any token (should also be unauthorized)
  await TestValidator.httpError(
    "anonymous caller cannot access adminUser member user detail endpoint",
    [401, 403],
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.at(
        unauthenticatedConnection,
        {
          memberUserId: targetMemberUserId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify that the admin user’s member user detail view reflects login activity
 * and does not expose credential hashes.
 *
 * This test wires together the todoApp authentication flows for both adminUser
 * and memberUser with the administrative detail endpoint for member users:
 *
 * 1. Create an initial adminUser via POST /auth/adminUser/join so we have an
 *    administrative actor capable of calling GET
 *    /todoApp/adminUser/memberUsers/{memberUserId}. The SDK automatically
 *    stores the issued access token into `connection.headers.Authorization`.
 * 2. Register a new member user via POST /auth/memberUser/join using a random
 *    email, secure-looking password, and realistic href/referrer URIs. The
 *    response ITodoAppMemberuser.IAuthorized gives us the member user’s UUID
 *    and initial lifecycle fields.
 * 3. Perform a successful login for that same member user via POST
 *    /auth/memberUser/login, again providing correct email/password and session
 *    context metadata. This call is expected to update
 *    todo_app_memberusers.last_login_at to a non-null value and to adjust
 *    failed_login_count according to the authentication rules (for a clean
 *    scenario with only successful logins, failed_login_count should remain
 *    zero).
 * 4. Re-establish an adminUser authentication context by calling POST
 *    /auth/adminUser/join a second time with a different random email. This
 *    overwrites the connection’s Authorization header with an admin token so
 *    that subsequent calls are performed as adminUser.
 * 5. Invoke GET /todoApp/adminUser/memberUsers/{memberUserId} via
 *    api.functional.todoApp.adminUser.memberUsers.at, passing the member user
 *    id captured in step 2.
 * 6. Use typia.assert to validate that the response conforms to
 *    ITodoAppMemberuser, which implicitly guarantees that no password_hash
 *    field is exposed and that all documented lifecycle/login fields are
 *    well-typed.
 * 7. With TestValidator, assert business-level expectations:
 *
 *    - The admin detail view’s id and email match those from the
 *         ITodoAppMemberuser.IAuthorized join/login responses.
 *    - Status, created_at, and deleted_at are consistent between the authenticated
 *         member view and the admin detail view.
 *    - Last_login_at in the admin detail view is non-null after a successful login
 *         and matches the last_login_at from the login response.
 *    - Failed_login_count in the admin detail view is greater than or equal to the
 *         value observed from the login response (and typically zero in this
 *         happy-path scenario).
 */
export async function test_api_admin_member_user_detail_reflects_login_activity(
  connection: api.IConnection,
) {
  // 1. Bootstrap an initial adminUser to satisfy any admin-only access
  //    preconditions, even though we will overwrite the token later.
  const initialAdminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const initialAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: initialAdminJoinBody,
    });
  typia.assert(initialAdmin);

  // 2. Register a new member user
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joinedMember: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(joinedMember);

  // Capture initial lifecycle/login fields from the join response
  const joinedMemberId = joinedMember.id;
  const joinedMemberEmail = joinedMember.email;
  const joinedStatus = joinedMember.status;
  const joinedCreatedAt = joinedMember.created_at;
  const joinedDeletedAt = joinedMember.deleted_at ?? null;
  const joinedLastLoginAt = joinedMember.last_login_at ?? null;
  const joinedFailedLoginCount = joinedMember.failed_login_count;

  // 3. Perform a successful login for the same member user
  const memberLoginBody = {
    email: joinedMemberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const loggedInMember: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(loggedInMember);

  const loginLastLoginAt = loggedInMember.last_login_at ?? null;
  const loginFailedLoginCount = loggedInMember.failed_login_count;
  const loginStatus = loggedInMember.status;
  const loginCreatedAt = loggedInMember.created_at;
  const loginDeletedAt = loggedInMember.deleted_at ?? null;

  // 4. Re-establish an adminUser authentication context so that the
  //    admin-only memberUsers.at endpoint can be called.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 5. Call the admin detail endpoint for the member user
  const detail: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.at(connection, {
      memberUserId: joinedMemberId,
    });
  typia.assert(detail);

  // 6. Assert identity and lifecycle consistency between member auth views
  //    and the admin detail view.
  TestValidator.equals(
    "admin detail id matches member user id",
    detail.id,
    joinedMemberId,
  );

  TestValidator.equals(
    "admin detail email matches member user email",
    detail.email,
    joinedMemberEmail,
  );

  TestValidator.equals(
    "admin detail status matches latest member status",
    detail.status,
    loginStatus,
  );

  TestValidator.equals(
    "admin detail created_at matches member created_at",
    detail.created_at,
    loginCreatedAt,
  );

  TestValidator.equals(
    "admin detail deleted_at matches member deleted_at",
    detail.deleted_at ?? null,
    loginDeletedAt,
  );

  // 7. Validate that last_login_at reflects successful login activity.
  TestValidator.predicate(
    "last_login_at should be non-null after successful login",
    detail.last_login_at !== null && detail.last_login_at !== undefined,
  );

  if (loginLastLoginAt !== null && loginLastLoginAt !== undefined) {
    TestValidator.equals(
      "admin detail last_login_at matches member last_login_at",
      detail.last_login_at ?? null,
      loginLastLoginAt,
    );
  }

  // 8. Validate failed_login_count behavior: it should not decrease and
  //    should remain a sane non-negative int32.
  TestValidator.predicate(
    "failed_login_count is non-negative in admin detail view",
    detail.failed_login_count >= 0,
  );

  TestValidator.predicate(
    "failed_login_count in admin detail is not less than value from login response",
    detail.failed_login_count >= loginFailedLoginCount,
  );

  TestValidator.predicate(
    "failed_login_count in admin detail is not less than value from join response",
    detail.failed_login_count >= joinedFailedLoginCount,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated admin user can update basic editable profile
 * and status fields of a member user account.
 *
 * Business goals:
 *
 * - Ensure that /todoApp/adminUser/memberUsers/{memberUserId} accepts a
 *   well-formed ITodoAppMemberuser.IUpdate payload when invoked by an
 *   authenticated adminUser.
 * - Confirm that mutable fields like display_name, status, and failed_login_count
 *   are updated while immutable identity fields (id, created_at) remain
 *   unchanged.
 * - Verify that updated_at is touched as part of the update operation.
 * - Exercise realistic preconditions: the member user exists, can log in, and
 *   owns at least one todo.
 */
export async function test_api_admin_member_user_update_basic_profile_fields(
  connection: api.IConnection,
) {
  // 1. Prepare an admin user (join implies authentication with token set).
  const adminJoinInput = typia.random<ITodoAppAdminUser.IJoin>();
  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinInput,
    });
  typia.assert(admin);

  // 2. Create a member user via join.
  const memberJoinRequest: ITodoAppMemberUserJoin.IRequest =
    typia.random<ITodoAppMemberUserJoin.IRequest>();
  const memberAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuth);

  const memberUserId = memberAuth.id;

  // Capture a pre-update snapshot-like view (using authorized payload fields).
  const beforeDisplayName = memberAuth.display_name ?? null;
  const beforeStatus = memberAuth.status;
  const beforeFailedLoginCount = memberAuth.failed_login_count;
  const beforeCreatedAt = memberAuth.created_at;
  const beforeUpdatedAt = memberAuth.updated_at;
  const beforeDeletedAt = memberAuth.deleted_at ?? null;

  // 3. Log in explicitly as the member user to simulate normal usage.
  const memberLoginRequest: ITodoAppMemberUserLogin.IRequest = {
    email: memberJoinRequest.email,
    password: memberJoinRequest.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  };
  const memberLoggedIn: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginRequest,
    });
  typia.assert(memberLoggedIn);

  TestValidator.equals(
    "member login should reference same user id as join",
    memberLoggedIn.id,
    memberUserId,
  );

  // 4. Create a todo as this member user to simulate real activity.
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "todo owner id should match member user id",
    createdTodo.memberUser.id,
    memberUserId,
  );

  // 5. Switch context back to the admin user.
  const adminLoginBody: ITodoAppAdminUser.ILogin = {
    email: adminJoinInput.email,
    password: adminJoinInput.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: RandomGenerator.name(),
  };
  const adminLoggedIn: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  TestValidator.equals(
    "admin login id should match admin join id",
    adminLoggedIn.id,
    admin.id,
  );

  // 6. Build an update payload for the member user.
  const newDisplayName = RandomGenerator.name();
  const newStatus = "inactive";
  const newFailedLoginCount = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<0>
  >();

  const updateBody = {
    display_name: newDisplayName,
    status: newStatus,
    failed_login_count: newFailedLoginCount,
  } satisfies ITodoAppMemberuser.IUpdate;

  const updatedMember: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.update(connection, {
      memberUserId,
      body: updateBody,
    });
  typia.assert(updatedMember);

  // 7. Validate response invariants and updates.
  TestValidator.equals(
    "member id should remain unchanged after update",
    updatedMember.id,
    memberUserId,
  );

  TestValidator.equals(
    "created_at should remain unchanged after update",
    updatedMember.created_at,
    beforeCreatedAt,
  );

  TestValidator.equals(
    "display_name should be updated to the new value",
    updatedMember.display_name ?? null,
    newDisplayName,
  );

  TestValidator.equals(
    "status should be updated to the new value",
    updatedMember.status,
    newStatus,
  );

  TestValidator.equals(
    "failed_login_count should be updated to the new value",
    updatedMember.failed_login_count,
    newFailedLoginCount,
  );

  TestValidator.notEquals(
    "updated_at should differ from pre-update updated_at",
    updatedMember.updated_at,
    beforeUpdatedAt,
  );

  TestValidator.equals(
    "deleted_at should remain unchanged by profile update",
    updatedMember.deleted_at ?? null,
    beforeDeletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that disabling a member user via admin update blocks future logins.
 *
 * Business goal:
 *
 * - Ensure that when an admin changes a member user's status to a disabled-like
 *   state using the admin-only update endpoint, the authentication flow
 *   respects this status and rejects subsequent login attempts for that
 *   account.
 *
 * High-level steps:
 *
 * 1. Create an adminUser using POST /auth/adminUser/join, which also seeds the
 *    Authorization header for admin-only operations.
 * 2. Register a member user with POST /auth/memberUser/join, capturing their id,
 *    email, and password.
 * 3. As the member user, perform a successful login via POST
 *    /auth/memberUser/login to establish the baseline that the account can
 *    currently authenticate.
 * 4. Switch the connection context back to an adminUser by calling
 *    /auth/adminUser/join again with a distinct admin email so that the
 *    Authorization header carries admin credentials.
 * 5. Call PUT /todoApp/adminUser/memberUsers/{memberUserId} with an
 *    ITodoAppMemberuser.IUpdate payload that sets status to a disabled-like
 *    string value (for example, "disabled"). Validate that the response is a
 *    full ITodoAppMemberuser object whose id matches the target member user and
 *    whose status property equals the disabled value.
 * 6. Optionally call GET /todoApp/adminUser/memberUsers/{memberUserId} to re-read
 *    the member user and confirm that the persisted status remains disabled.
 * 7. Attempt to log in again as the member user using the same email/password
 *    combination via POST /auth/memberUser/login. This time the login must fail
 *    because the account has been disabled. Wrap this call in
 *    TestValidator.error to ensure an error is thrown, but do not assert on
 *    specific HTTP status codes or error payloads.
 *
 * Assertions:
 *
 * - All created and fetched DTOs pass typia.assert for structural and type
 *   validation.
 * - The member user can log in successfully before the status change.
 * - After the admin updates the member user's status to disabled, the
 *   ITodoAppMemberuser (and optional GET re-read) shows the disabled status.
 * - A subsequent login attempt for the disabled member user fails and is captured
 *   by TestValidator.error with a descriptive title.
 */
export async function test_api_admin_member_user_update_disable_account_blocks_future_login(
  connection: api.IConnection,
) {
  // 1. Create an admin user who can manage member users
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;
  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register a new member user whose account will later be disabled
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorizedOnJoin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedOnJoin);

  const memberUserId: string & tags.Format<"uuid"> = memberAuthorizedOnJoin.id;

  // 3. Verify that the member user can log in successfully before disabling
  const preDisableLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAuthorizedOnLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: preDisableLoginBody,
    });
  typia.assert(memberAuthorizedOnLogin);

  TestValidator.equals(
    "member login succeeds before disabling",
    memberAuthorizedOnLogin.id,
    memberUserId,
  );

  // 4. Switch back to an admin context by joining another admin user
  const secondAdminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;
  const secondAdminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: secondAdminJoinBody,
    });
  typia.assert(secondAdminAuthorized);

  // 5. Admin updates the member user's status to a disabled-like value
  const disabledStatus = "disabled";
  const updateBody = {
    status: disabledStatus,
  } satisfies ITodoAppMemberuser.IUpdate;

  const updatedMember: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.update(connection, {
      memberUserId,
      body: updateBody,
    });
  typia.assert(updatedMember);

  TestValidator.equals(
    "updated member id remains unchanged",
    updatedMember.id,
    memberUserId,
  );
  TestValidator.equals(
    "member status updated to disabled",
    updatedMember.status,
    disabledStatus,
  );

  // 6. Re-read the member user via admin detail endpoint to confirm status
  const reloadedMember: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.at(connection, {
      memberUserId,
    });
  typia.assert(reloadedMember);

  TestValidator.equals(
    "reloaded member reflects disabled status",
    reloadedMember.status,
    disabledStatus,
  );

  // 7. Attempt to log in again as the now-disabled member user; this must fail
  const postDisableLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  await TestValidator.error("disabled member cannot log in", async () => {
    await api.functional.auth.memberUser.login(connection, {
      body: postDisableLoginBody,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

export async function test_api_admin_member_user_update_reset_failed_login_count(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain admin authorization token
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register a member user with known credentials
  const memberPassword: string = typia.random<
    string & tags.Format<"password">
  >();
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberUserId = memberAuthorized.id;

  // 3. Perform several failed login attempts with wrong password
  const wrongPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const failedLoginBodyBase = {
    email: memberJoinBody.email,
    password: wrongPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const failedAttempts = 3;
  for (let i = 0; i < failedAttempts; i += 1) {
    await TestValidator.error(
      `memberUser wrong password login attempt ${i + 1} should fail`,
      async () => {
        await api.functional.auth.memberUser.login(connection, {
          body: failedLoginBodyBase,
        });
      },
    );
  }

  // After failed logins, Authorization header likely points to member context.
  // Re-acquire admin authorization to call admin-only memberUser endpoints.
  const adminAuthorizedAgain: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedAgain);

  // 4. As admin, read member user and ensure failed_login_count > 0
  const beforeUpdate: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.at(connection, {
      memberUserId,
    });
  typia.assert(beforeUpdate);

  TestValidator.predicate(
    "failed_login_count should be greater than or equal to 1 after repeated failed logins",
    beforeUpdate.failed_login_count > 0,
  );

  // 5. Admin resets failed_login_count to 0 using update endpoint
  const updateBody = {
    failed_login_count: 0,
  } satisfies ITodoAppMemberuser.IUpdate;

  const afterUpdate: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.update(connection, {
      memberUserId,
      body: updateBody,
    });
  typia.assert(afterUpdate);

  // 6. Validate that identity fields are preserved and failed_login_count reset
  TestValidator.equals(
    "memberUser id should remain unchanged after update",
    afterUpdate.id,
    beforeUpdate.id,
  );
  TestValidator.equals(
    "memberUser email should remain unchanged after update",
    afterUpdate.email,
    beforeUpdate.email,
  );
  TestValidator.equals(
    "failed_login_count should be reset to 0 by admin update",
    afterUpdate.failed_login_count,
    0,
  );

  // 7. Optionally: perform a successful login with correct password.
  // This will switch Authorization to the member user again.
  const successLoginBody = {
    email: memberJoinBody.email,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAuthorizedAfterSuccess: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: successLoginBody,
    });
  typia.assert(memberAuthorizedAfterSuccess);

  // Re-acquire admin authorization one more time to confirm failed_login_count
  const adminAuthorizedFinal: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFinal);

  const finalState: ITodoAppMemberuser =
    await api.functional.todoApp.adminUser.memberUsers.at(connection, {
      memberUserId,
    });
  typia.assert(finalState);

  TestValidator.equals(
    "failed_login_count should remain 0 after successful login following admin reset",
    finalState.failed_login_count,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that updating a member user via the admin-only endpoint is rejected
 * when the caller is either unauthenticated or authenticated only as a member
 * user (not an admin user).
 *
 * Business intent
 *
 * - The PUT /todoApp/adminUser/memberUsers/{memberUserId} endpoint is reserved
 *   for adminUser actors. Regular member users or guests must not be able to
 *   update member accounts through this route.
 * - This test demonstrates that:
 *
 *   1. A completely unauthenticated call fails.
 *   2. A call authenticated as a memberUser (not adminUser) also fails.
 *
 * High-level steps
 *
 * 1. Create a base unauthenticated connection (guest) from the provided connection
 *    argument by stripping its headers. This will simulate a request with no
 *    Authorization header.
 * 2. Using a cloned connection dedicated to the memberUser actor, call POST
 *    /auth/memberUser/join to create a member user. The join call will set the
 *    memberUser token on that cloned connection.
 * 3. Prepare a deterministic ITodoAppMemberuser.IUpdate payload that attempts to
 *    change editable fields like display_name, status, and failed_login_count.
 * 4. Negative case A (guest): Using the unauthenticated connection, call
 *    api.functional.todoApp.adminUser.memberUsers.update with the target
 *    memberUserId and update payload wrapped in TestValidator.error, asserting
 *    that an error is thrown (without asserting specific status codes).
 * 5. Negative case B (memberUser token): Using the memberUser-authenticated
 *    connection, call the same update function again, also expecting an error.
 *    This validates that memberUser tokens are not sufficient to access
 *    admin-only member management APIs.
 * 6. Because we lack an exposed GET adminUser/memberUsers API in the provided SDK,
 *    we do not attempt to re-read the member user record to check persistence.
 *    The absence of a successful update response plus the thrown errors in both
 *    scenarios is sufficient to validate the access control behavior within the
 *    constraints of available APIs.
 */
export async function test_api_admin_member_user_update_unauthorized_without_admin_token(
  connection: api.IConnection,
) {
  // 1. Prepare an unauthenticated base connection (guest).
  //    This connection should not have any Authorization header set and will
  //    be used to simulate calls without any auth token.
  const guestConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 2. Prepare a separate connection object for memberUser operations so that
  //    its Authorization header can be mutated by join() without affecting the
  //    guest connection.
  const memberConnection: api.IConnection = { ...connection };

  // 3. Register a new member user via POST /auth/memberUser/join.
  //    This call both creates the member record and sets the memberUser token
  //    on memberConnection.headers.Authorization.
  const memberJoinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(memberConnection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const targetMemberUserId: string & tags.Format<"uuid"> = memberAuthorized.id;

  // 4. Prepare an ITodoAppMemberuser.IUpdate payload that attempts to change
  //    editable fields on the member account.
  const updateBody = {
    display_name: RandomGenerator.name(),
    status: "suspended",
    failed_login_count: typia.random<number & tags.Type<"int32">>(),
  } satisfies ITodoAppMemberuser.IUpdate;

  // 5. Negative case A: Unauthenticated (guest) call must be rejected.
  await TestValidator.error(
    "unauthenticated caller cannot update member user via admin endpoint",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.update(
        guestConnection,
        {
          memberUserId: targetMemberUserId,
          body: updateBody,
        },
      );
    },
  );

  // 6. Negative case B: memberUser-authenticated call must also be rejected
  //    because the endpoint is restricted to adminUser actors.
  await TestValidator.error(
    "memberUser-authenticated caller cannot use admin member update endpoint",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.update(
        memberConnection,
        {
          memberUserId: targetMemberUserId,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that a newly registered member user can perform a global logout
 * immediately after registration, and that the logout-all response follows the
 * expected semantics.
 *
 * Business context:
 *
 * - POST /auth/memberUser/join both creates the member account and issues initial
 *   access/refresh tokens, returning ITodoAppMemberuser.IAuthorized.
 * - POST /auth/memberUser/logoutAll uses the current authenticated context
 *   (Authorization header managed by the SDK) to expire all active sessions for
 *   that member user and invalidate their tokens.
 *
 * Steps:
 *
 * 1. Build a valid ITodoAppMemberUserJoin.IRequest payload using typia tags for
 *    email, password, href, and referrer. Optionally include display_name and
 *    leave ip as null to exercise server-side IP derivation.
 * 2. Call api.functional.auth.memberUser.join(connection, { body }) and validate
 *    the response with typia.assert<ITodoAppMemberuser.IAuthorized>().
 *    Additionally, check via TestValidator that:
 *
 *    - Token.access is a non-empty string
 *    - Token.refresh is a non-empty string
 * 3. Immediately call api.functional.auth.memberUser.logoutAll(connection).
 *    Validate the response shape using
 *    typia.assert<ITodoAppMemberUserLogoutAll.IResponse>().
 * 4. Add business-level assertions on the logoutAll response:
 *
 *    - Success is true
 *    - AffectedSessionCount >= 1
 *    - If message is not null/undefined, it must be a non-empty string
 *
 * Notes:
 *
 * - We do not attempt to call any additional memberUser-only business endpoints
 *   with the old token because such endpoints are not present in the provided
 *   SDK surface. Instead, we focus on validating the join and logoutAll
 *   behaviors themselves and the semantics of the logoutAll response.
 */
export async function test_api_member_user_logout_all_after_registration(
  connection: api.IConnection,
) {
  // 1. Prepare registration payload for member user join
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  // 2. Register new member user and obtain authorized context + tokens
  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // Basic sanity checks on issued tokens
  const token: IAuthorizationToken = authorized.token;
  TestValidator.predicate(
    "access token should be a non-empty string",
    token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be a non-empty string",
    token.refresh.length > 0,
  );

  // 3. Invoke global logout for the authenticated member user
  const logoutResult: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert<ITodoAppMemberUserLogoutAll.IResponse>(logoutResult);

  // 4. Business-level assertions on logoutAll response
  TestValidator.predicate(
    "logoutAll.success must be true",
    logoutResult.success === true,
  );

  TestValidator.predicate(
    "logoutAll.affectedSessionCount must be at least 1",
    logoutResult.affectedSessionCount >= 1,
  );

  if (logoutResult.message !== null && logoutResult.message !== undefined) {
    TestValidator.predicate(
      "logoutAll.message, when present, must be non-empty",
      logoutResult.message.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

export async function test_api_member_user_logout_all_with_multiple_sessions(
  connection: api.IConnection,
) {
  // 1. Register a new member user to create the first authenticated session (Session A)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://app.example.com/signup",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const sessionA: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(sessionA);

  const email = sessionA.email;
  const password = joinBody.password;

  // 2. Perform additional logins on the same account to simulate multiple sessions
  const loginBodyBase = {
    email,
    password,
    ip: null,
    href: "https://app.example.com/login",
    referrer: "https://app.example.com/landing",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const sessionB: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBodyBase,
    });
  typia.assert(sessionB);

  const sessionC: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBodyBase,
    });
  typia.assert(sessionC);

  // 3. Using the currently authenticated session (latest login), call logoutAll
  const logoutAllResponse: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert(logoutAllResponse);

  TestValidator.predicate(
    "logoutAll success flag should be true",
    logoutAllResponse.success === true,
  );

  TestValidator.predicate(
    "logoutAll affectedSessionCount should be >= 1",
    logoutAllResponse.affectedSessionCount >= 1,
  );

  // 4. Immediately calling logoutAll again with the same token should fail
  await TestValidator.error(
    "calling logoutAll again with an already invalidated session must fail",
    async () => {
      await api.functional.auth.memberUser.logoutAll(connection);
    },
  );

  // 5. Perform a fresh login to confirm that new tokens work after global logout
  const freshLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginBodyBase,
    });
  typia.assert(freshLogin);

  TestValidator.equals(
    "fresh login should be for the same member user id",
    freshLogin.id,
    sessionA.id,
  );

  // 6. Call logoutAll again with the fresh session to ensure it still functions
  const secondLogoutAll: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert(secondLogoutAll);

  TestValidator.predicate(
    "second logoutAll success flag should be true",
    secondLogoutAll.success === true,
  );

  TestValidator.predicate(
    "second logoutAll affectedSessionCount should be >= 1",
    secondLogoutAll.affectedSessionCount >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserLogout } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogout";
import type { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

export async function test_api_member_user_logout_all_idempotent_when_no_active_sessions(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain initial authorized session
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    // provide realistic but simple optional metadata
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://example.com/signup",
    referrer: "https://example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(joined);

  // 2. Perform an initial global logout to ensure all existing sessions are expired.
  //    This also gives us a baseline behavior when at least one active session exists.
  const firstLogoutAll: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert(firstLogoutAll);

  // 3. Log in again to create a fresh session
  const loginRequest = {
    email: joinRequest.email,
    password: joinRequest.password,
    ip: null,
    href: "https://example.com/login",
    referrer: "https://example.com/landing",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const loggedIn: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: loginRequest,
    });
  typia.assert(loggedIn);

  // 4. Log out the current session so that there are no active sessions left
  const singleLogout: ITodoAppMemberUserLogout.IResponse =
    await api.functional.auth.memberUser.logout(connection);
  typia.assert(singleLogout);

  // 5. Call logoutAll again when there should be zero active sessions
  const secondLogoutAll: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert(secondLogoutAll);

  // 6. Business assertions about idempotent behavior when no active sessions exist
  TestValidator.equals(
    "logoutAll without active sessions should succeed",
    secondLogoutAll.success,
    true,
  );

  TestValidator.equals(
    "logoutAll without active sessions should affect zero sessions",
    secondLogoutAll.affectedSessionCount,
    0,
  );

  // message is optional and may be null/undefined; only assert it has a valid type shape
  TestValidator.predicate(
    "logoutAll message is either null/undefined or a string",
    () => {
      const msg = secondLogoutAll.message;
      if (msg === null || msg === undefined) return true;
      return typeof msg === "string";
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that global member user logout does not delete or mutate the
 * underlying todo_app_memberusers account record.
 *
 * Business purpose:
 *
 * - LogoutAll is a session-management operation that should operate only on
 *   todo_app_memberuser_sessions and token revocation, not on the
 *   todo_app_memberusers row itself.
 * - Member users must remain able to log in after a global logout, and admins
 *   must still see the account unchanged via admin search.
 *
 * Scenario steps:
 *
 * 1. Create an admin user so we can later inspect member accounts through the
 *    admin memberUsers index endpoint.
 * 2. Register a new member user via /auth/memberUser/join and capture the returned
 *    ITodoAppMemberuser.IAuthorized as the initial account snapshot.
 * 3. Log in as the same member user via /auth/memberUser/login at least once to
 *    exercise the normal login flow and capture a second snapshot.
 * 4. While authenticated as that member user, call /auth/memberUser/logoutAll and
 *    assert that the response indicates success and provides a non-negative
 *    affectedSessionCount.
 * 5. Log in again as the same member user to prove the account is still active and
 *    obtain a third ITodoAppMemberuser.IAuthorized snapshot.
 * 6. Switch to the admin user context and call PATCH
 *    /todoApp/adminUser/memberUsers with a filter by the member email,
 *    retrieving an IPageITodoAppMemberuser.ISummary page. Locate the member's
 *    summary record by id.
 * 7. Cross-check invariants across all snapshots and the admin summary:
 *
 *    - Id must be identical everywhere.
 *    - Email must be identical everywhere.
 *    - Display_name (if set) must be stable between join snapshot and admin summary;
 *         nullable semantics are respected.
 *    - Status must match between snapshots and summary and must not indicate
 *         deletion or other lifecycle change caused by logoutAll.
 *    - Deleted_at must remain the same across member snapshots (typically null),
 *         proving logoutAll did not soft-delete the account.
 *    - Created_at must be identical across all member snapshots, confirming that the
 *         same DB row is reused, not recreated.
 *    - Updated_at and last_login_at may advance forward with each successful login
 *         but must never regress or reset unexpectedly.
 *    - The account must still appear in the admin search results filtered by email.
 */
export async function test_api_member_user_logout_all_does_not_delete_account(
  connection: api.IConnection,
) {
  // 1. Admin user setup: join as an admin to get tokens for later admin calls.
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = RandomGenerator.alphaNumeric(12) + "!A";

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminJoin);

  // 2. Member user setup: join as a new member user and capture initial snapshot.
  const memberEmail: string = typia.random<string & tags.Format<"email">>();
  const memberPassword: string = RandomGenerator.alphaNumeric(12) + "!a";
  const href: string = "https://todo-app.example.com/join";
  const referrer: string = "https://landing.example.com";

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberJoinAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(memberJoinAuth);

  // Snapshot 1: initial account state right after join.
  const initialSnapshot: ITodoAppMemberuser.IAuthorized = memberJoinAuth;

  // 3. First login as the member user and capture snapshot 2.
  const loginHref: string = "https://todo-app.example.com/login";
  const loginReferrer: string = "https://todo-app.example.com";

  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: loginHref,
    referrer: loginReferrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const firstLoginAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(firstLoginAuth);

  const postLoginSnapshot: ITodoAppMemberuser.IAuthorized = firstLoginAuth;

  // Ensure basic invariants between join and first login.
  TestValidator.equals(
    "member id remains the same between join and first login",
    postLoginSnapshot.id,
    initialSnapshot.id,
  );
  TestValidator.equals(
    "member email remains the same between join and first login",
    postLoginSnapshot.email,
    initialSnapshot.email,
  );

  // 4. While authenticated as member, perform global logout.
  const logoutAllResult: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert<ITodoAppMemberUserLogoutAll.IResponse>(logoutAllResult);

  TestValidator.predicate(
    "logoutAll result reports success",
    logoutAllResult.success === true,
  );
  TestValidator.predicate(
    "logoutAll affectedSessionCount is non-negative",
    logoutAllResult.affectedSessionCount >= 0,
  );

  // 5. Log in again as the same member user after global logout.
  const secondLoginAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(secondLoginAuth);

  const postLogoutAllSnapshot: ITodoAppMemberuser.IAuthorized = secondLoginAuth;

  // Core identity invariants across all three member snapshots.
  TestValidator.equals(
    "member id remains stable across join, first login, and post-logoutAll login",
    postLogoutAllSnapshot.id,
    initialSnapshot.id,
  );
  TestValidator.equals(
    "member email remains stable across all member snapshots",
    postLogoutAllSnapshot.email,
    initialSnapshot.email,
  );

  // Display name invariants (respect nullable semantics).
  TestValidator.equals(
    "display_name is consistent between join and post-logoutAll login",
    postLogoutAllSnapshot.display_name ?? null,
    initialSnapshot.display_name ?? null,
  );

  // Status must remain the same logical account status across snapshots.
  TestValidator.equals(
    "status remains the same across join and post-logoutAll login",
    postLogoutAllSnapshot.status,
    initialSnapshot.status,
  );

  // deleted_at must not change due to logoutAll.
  TestValidator.equals(
    "deleted_at is unchanged by logoutAll",
    postLogoutAllSnapshot.deleted_at ?? null,
    postLoginSnapshot.deleted_at ?? null,
  );

  // created_at must remain constant (same DB row).
  TestValidator.equals(
    "created_at is identical across all member snapshots",
    postLogoutAllSnapshot.created_at,
    initialSnapshot.created_at,
  );

  // updated_at and last_login_at should only move forward (or stay equal), never backwards.
  TestValidator.predicate(
    "updated_at after logoutAll login is not earlier than initial created_at",
    postLogoutAllSnapshot.updated_at >= initialSnapshot.created_at,
  );
  if (
    postLoginSnapshot.last_login_at !== undefined &&
    postLoginSnapshot.last_login_at !== null &&
    postLogoutAllSnapshot.last_login_at !== undefined &&
    postLogoutAllSnapshot.last_login_at !== null
  ) {
    TestValidator.predicate(
      "last_login_at after logoutAll login is not earlier than first login last_login_at",
      postLogoutAllSnapshot.last_login_at >= postLoginSnapshot.last_login_at,
    );
  }

  // 6. Switch to admin user context by logging in as the admin again
  //    (SDK will update connection headers with admin token).
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "e2e-test-suite",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminLogin);

  // 7. As admin, search for the member user in memberUsers.index.
  const memberSearchBody = {
    page: 1,
    limit: 10,
    email: memberEmail,
    status: undefined,
    createdFrom: undefined,
    createdTo: undefined,
    deleted: undefined,
    orderBy: undefined,
    orderDirection: undefined,
  } satisfies ITodoAppMemberuser.IRequest;

  const searchResult: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: memberSearchBody,
    });
  typia.assert<IPageITodoAppMemberuser.ISummary>(searchResult);

  TestValidator.predicate(
    "admin search returns at least one member user for the email",
    searchResult.pagination.records >= 1 && searchResult.data.length >= 1,
  );

  const foundMemberSummary = searchResult.data.find(
    (summary) => summary.id === postLogoutAllSnapshot.id,
  );

  TestValidator.predicate(
    "member appears in admin memberUsers search results",
    !!foundMemberSummary,
  );

  if (foundMemberSummary) {
    // Identity and profile consistency between admin summary and member snapshot.
    TestValidator.equals(
      "admin summary id matches member snapshot id",
      foundMemberSummary.id,
      postLogoutAllSnapshot.id,
    );
    TestValidator.equals(
      "admin summary email matches member snapshot email",
      foundMemberSummary.email,
      postLogoutAllSnapshot.email,
    );
    TestValidator.equals(
      "admin summary display_name matches member snapshot display_name",
      foundMemberSummary.display_name ?? null,
      postLogoutAllSnapshot.display_name ?? null,
    );
    TestValidator.equals(
      "admin summary status matches member snapshot status",
      foundMemberSummary.status,
      postLogoutAllSnapshot.status,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate successful password change flow for an authenticated member user.
 *
 * Business workflow:
 *
 * 1. Register a new member user with a known email and initial password using join
 *    API.
 * 2. While authenticated as this member user, invoke changePassword with correct
 *    currentPassword and a strong newPassword.
 * 3. Verify the changePassword response indicates success.
 * 4. Confirm that logging in with the old password now fails.
 * 5. Confirm that logging in with the new password succeeds and returns a valid
 *    authorized payload whose id/email match the original user.
 */
export async function test_api_member_user_change_password_success_flow(
  connection: api.IConnection,
) {
  // 1. Register a new member user with known credentials
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const initialPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password: initialPassword,
    href: "https://example.com/signup",
    referrer: "https://example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // 2. Change password using correct current password
  const newPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const changePasswordBody = {
    currentPassword: initialPassword,
    newPassword,
  } satisfies ITodoAppMemberUserChangePassword.IRequest;

  const changeResult: ITodoAppMemberUserChangePassword.IResponse =
    await api.functional.auth.memberUser.password.changePassword(connection, {
      body: changePasswordBody,
    });
  typia.assert(changeResult);
  TestValidator.predicate(
    "password change success flag should be true",
    changeResult.success === true,
  );

  // 3. Attempt login with old password - must fail
  const oldLoginBody = {
    email,
    password: initialPassword,
    href: "https://example.com/login",
    referrer: "https://example.com/profile",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  await TestValidator.error("login with old password must fail", async () => {
    await api.functional.auth.memberUser.login(connection, {
      body: oldLoginBody,
    });
  });

  // 4. Login with new password - must succeed
  const newLoginBody = {
    email,
    password: newPassword,
    href: "https://example.com/login",
    referrer: "https://example.com/profile",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const reAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: newLoginBody,
    });
  typia.assert(reAuthorized);

  // Validate identity continuity
  TestValidator.equals(
    "re-authorized user id must match original",
    reAuthorized.id,
    joined.id,
  );
  TestValidator.equals(
    "re-authorized user email must match original",
    reAuthorized.email,
    joined.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that member user password change fails when the current password is
 * incorrect.
 *
 * Business intent
 *
 * - Ensure PUT /auth/memberUser/password requires the correct currentPassword
 *   before updating password_hash for an authenticated member user.
 * - Verify that a failed password change attempt does not alter the stored
 *   password and that the original password remains usable for login.
 * - Optionally, confirm via admin search that the member user still exists with
 *   consistent metadata after the failed change.
 *
 * End-to-end workflow
 *
 * 1. Register a new member user via POST /auth/memberUser/join with a known email
 *    and password (captured in local variables for later reuse).
 * 2. While authenticated as this member user (join sets Authorization header),
 *    call PUT /auth/memberUser/password with
 *    ITodoAppMemberUserChangePassword.IRequest providing:
 *
 *    - CurrentPassword: an intentionally incorrect value (e.g., original +
 *         "!wrong").
 *    - NewPassword: a syntactically valid password string.
 * 3. Assert that the password change response
 *    (ITodoAppMemberUserChangePassword.IResponse) indicates failure (success
 *    === false). Do not assert on the exact message text, only that the DTO is
 *    structurally valid.
 * 4. Call POST /auth/memberUser/login with the original email and original
 *    password, and assert that login still succeeds (typia.assert on
 *    ITodoAppMemberuser.IAuthorized), confirming that the failed password
 *    change did not change credentials.
 * 5. As an admin user, join/login via /auth/adminUser/join and optionally
 *    /auth/adminUser/login, then call PATCH
 *    /todoApp/adminUser/memberUsers.index filtering by the member email.
 *    Confirm that at least one member user summary exists with that email and
 *    that its status field is present, demonstrating that the account remains
 *    intact and active.
 */
export async function test_api_member_user_change_password_invalid_current_password(
  connection: api.IConnection,
) {
  // 1. Register a new member user with explicit credentials we can reuse.
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joinedMember = await api.functional.auth.memberUser.join(connection, {
    body: joinBody,
  });
  typia.assert(joinedMember);

  // 2. Attempt to change password with an incorrect currentPassword.
  const wrongCurrentPassword = `${memberPassword}__wrong`;
  const newPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const changePasswordBody = {
    currentPassword: wrongCurrentPassword,
    newPassword,
  } satisfies ITodoAppMemberUserChangePassword.IRequest;

  const changeResult: ITodoAppMemberUserChangePassword.IResponse =
    await api.functional.auth.memberUser.password.changePassword(connection, {
      body: changePasswordBody,
    });
  typia.assert(changeResult);

  TestValidator.predicate(
    "password change with invalid current password must fail",
    changeResult.success === false,
  );

  // 3. Verify that original password still works via login.
  const loginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const loginResult = await api.functional.auth.memberUser.login(connection, {
    body: loginBody,
  });
  typia.assert(loginResult);

  TestValidator.equals(
    "member email after login should match original email",
    loginResult.email,
    memberEmail,
  );

  // 4. As admin, search memberUsers list to ensure the account is present.
  const adminJoinBody =
    typia.random<ITodoAppAdminUser.IJoin>() satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized = await api.functional.auth.adminUser.join(connection, {
    body: adminJoinBody,
  });
  typia.assert(adminAuthorized);

  const indexBody = {
    page: 1,
    limit: 10,
    email: memberEmail,
    status: undefined,
    createdFrom: undefined,
    createdTo: undefined,
    deleted: undefined,
    orderBy: undefined,
    orderDirection: undefined,
  } satisfies ITodoAppMemberuser.IRequest;

  const pageResult = await api.functional.todoApp.adminUser.memberUsers.index(
    connection,
    {
      body: indexBody,
    },
  );
  typia.assert(pageResult);

  TestValidator.predicate(
    "admin memberUsers index should return at least one record for member email",
    pageResult.data.some((m) => m.email === memberEmail),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify that member user password change enforces complexity and updates
 * authentication behavior.
 *
 * Business workflow under test:
 *
 * 1. Register a new member user via POST /auth/memberUser/join and obtain
 *    ITodoAppMemberuser.IAuthorized, letting the SDK attach the access token to
 *    the connection.
 * 2. While authenticated as this member user, attempt to change the password via
 *    PUT /auth/memberUser/password using the correct currentPassword but a
 *    conceptually weak newPassword. The test expects this call to fail as a
 *    business error (rejected by server-side complexity rules) and uses
 *    TestValidator.error to assert that an error is thrown.
 * 3. Perform a second password change with a stronger newPassword that should
 *    comply with policy. This time the call must succeed and return
 *    ITodoAppMemberUserChangePassword.IResponse with success === true.
 * 4. Attempt login via POST /auth/memberUser/login with the old password and
 *    assert that it now fails (TestValidator.error), confirming that the
 *    original password_hash is no longer valid.
 * 5. Attempt login again with the new password and assert that it succeeds and
 *    returns ITodoAppMemberuser.IAuthorized whose email matches the original
 *    registration, proving that the new password is the only valid credential.
 */
export async function test_api_member_user_change_password_enforces_complexity_rules(
  connection: api.IConnection,
) {
  // 1. Register a new member user and get authorized context
  const email: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const initialPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email,
    password: initialPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // 2. Attempt password change with a conceptually weak new password
  const weakNewPassword: string = "123456";

  await TestValidator.error(
    "password change fails for weak password candidate",
    async () => {
      const weakChangeBody = {
        currentPassword: initialPassword,
        newPassword: weakNewPassword,
      } satisfies ITodoAppMemberUserChangePassword.IRequest;

      const weakResponse: ITodoAppMemberUserChangePassword.IResponse =
        await api.functional.auth.memberUser.password.changePassword(
          connection,
          {
            body: weakChangeBody,
          },
        );
      typia.assert(weakResponse);
    },
  );

  // 3. Attempt password change with a strong password that should be accepted
  const strongNewPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const strongChangeBody = {
    currentPassword: initialPassword,
    newPassword: strongNewPassword,
  } satisfies ITodoAppMemberUserChangePassword.IRequest;

  const strongChangeResponse: ITodoAppMemberUserChangePassword.IResponse =
    await api.functional.auth.memberUser.password.changePassword(connection, {
      body: strongChangeBody,
    });
  typia.assert(strongChangeResponse);

  TestValidator.equals(
    "password change success flag should be true for strong password",
    strongChangeResponse.success,
    true,
  );

  // 4. Verify old password no longer works for login
  await TestValidator.error(
    "login with old password must fail after successful password change",
    async () => {
      const oldLoginBody = {
        email,
        password: initialPassword,
        ip: null,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies ITodoAppMemberUserLogin.IRequest;

      const oldLogin: ITodoAppMemberuser.IAuthorized =
        await api.functional.auth.memberUser.login(connection, {
          body: oldLoginBody,
        });
      typia.assert(oldLogin);
    },
  );

  // 5. Verify new password works for login
  const newLoginBody = {
    email,
    password: strongNewPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const newLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: newLoginBody,
    });
  typia.assert(newLogin);

  TestValidator.equals(
    "login with new password should return same email as registered",
    newLogin.email,
    email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Ensure that changing a member user password invalidates old credentials and
 * requires re-authentication using the new password.
 *
 * Business narrative (rewritten to use only available APIs):
 *
 * - A guest registers as a new member user using /auth/memberUser/join.
 * - The member user then logs in a couple of times using /auth/memberUser/login,
 *   conceptually creating multiple sessions (although SDK only exposes the
 *   latest access token via connection.headers).
 * - While authenticated, the member user calls /auth/memberUser/password to
 *   change their password by providing the currentPassword and newPassword.
 * - After the password change, attempting to login again with the OLD password
 *   must fail (runtime error from the login API).
 * - Logging in with the NEW password must succeed and return an authorized
 *   context with the same user id and email as before.
 *
 * What this test validates:
 *
 * 1. The changePassword endpoint accepts a correct currentPassword/newPassword
 *    pair and returns ITodoAppMemberUserChangePassword.IResponse with success
 *    === true.
 * 2. After a successful password change, the old password can no longer be used
 *    for login via /auth/memberUser/login.
 * 3. The new password can be used for login and yields a valid
 *    ITodoAppMemberuser.IAuthorized context for the same account.
 *
 * Notes:
 *
 * - We do not (and must not) manipulate connection.headers directly; token
 *   handling is fully managed by the SDK join/login functions.
 * - We also do not call any non-provided memberUser-only resource APIs, so the
 *   “session invalidation” rule is approximated through the credential behavior
 *   of the login endpoint.
 */
export async function test_api_member_user_change_password_expires_all_existing_sessions(
  connection: api.IConnection,
) {
  // 1. Register a new member user
  const originalPassword: string = RandomGenerator.alphaNumeric(16);
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: originalPassword as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const joined: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joined);

  // Keep core identity for later comparison
  const userId = joined.id;
  const userEmail = joined.email;

  // 2. Perform additional logins with the same credentials to conceptually
  // create multiple sessions (B, C). The SDK will update connection.headers
  // automatically; we just validate responses.
  const firstReloginBody = {
    email: userEmail,
    password: originalPassword as string & tags.Format<"password">,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const firstRelogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: firstReloginBody,
    });
  typia.assert(firstRelogin);
  TestValidator.equals(
    "first relogin preserves same user id",
    firstRelogin.id,
    userId,
  );

  const secondReloginBody = {
    email: userEmail,
    password: originalPassword as string & tags.Format<"password">,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const secondRelogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: secondReloginBody,
    });
  typia.assert(secondRelogin);
  TestValidator.equals(
    "second relogin preserves same user id",
    secondRelogin.id,
    userId,
  );

  // 3. Change password while authenticated.
  const newPassword: string = RandomGenerator.alphaNumeric(18);
  const changeBody = {
    currentPassword: originalPassword,
    newPassword,
  } satisfies ITodoAppMemberUserChangePassword.IRequest;

  const changeResult: ITodoAppMemberUserChangePassword.IResponse =
    await api.functional.auth.memberUser.password.changePassword(connection, {
      body: changeBody,
    });
  typia.assert(changeResult);
  TestValidator.equals(
    "password change operation reports success",
    changeResult.success,
    true,
  );

  // 4. Ensure that the OLD password can no longer be used for login.
  const oldPasswordLoginBody = {
    email: userEmail,
    password: originalPassword as string & tags.Format<"password">,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  await TestValidator.error(
    "login with old password should fail after password change",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: oldPasswordLoginBody,
      });
    },
  );

  // 5. Verify that login with the NEW password succeeds and references the
  // same member user.
  const newPasswordLoginBody = {
    email: userEmail,
    password: newPassword as string & tags.Format<"password">,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const newLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: newPasswordLoginBody,
    });
  typia.assert(newLogin);

  TestValidator.equals(
    "new password login preserves user id",
    newLogin.id,
    userId,
  );
  TestValidator.equals(
    "new password login preserves email",
    newLogin.email,
    userEmail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify that changing a member user's password does not modify account status
 * or profile fields.
 *
 * Business goal:
 *
 * - Password change is a security-only operation. It must not alter lifecycle
 *   fields such as `status` or `deleted_at`, nor profile fields like
 *   `display_name`, when observed from the admin memberUsers listing endpoint.
 *
 * Flow:
 *
 * 1. Create an admin user (POST /auth/adminUser/join) and rely on automatic login.
 * 2. Create a member user (POST /auth/memberUser/join) with a known
 *    `display_name`.
 * 3. As admin, query member users (PATCH /todoApp/adminUser/memberUsers) filtered
 *    by email, capture the summary for the created member (id, email, status,
 *    display_name, last_login_at).
 * 4. Switch to the member user (POST /auth/memberUser/login) using their
 *    email/password.
 * 5. Change password (PUT /auth/memberUser/password) with correct currentPassword
 *    and a newPassword; assert success in the response.
 * 6. Optionally, login again with the new password to prove it works (not strictly
 *    required for the invariants but gives additional confidence that the
 *    change took effect).
 * 7. Switch back to admin (POST /auth/adminUser/login).
 * 8. Query member users again with the same filter.
 * 9. Assert that the member is still present and that `status` and `display_name`
 *    are unchanged compared to before the password change. Do not assert on
 *    last_login_at because it may change as part of login flows.
 */
export async function test_api_member_user_change_password_does_not_change_account_status_or_profile(
  connection: api.IConnection,
) {
  // 1. Register an admin user and rely on automatic login via token header.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const adminDisplayName: string = RandomGenerator.name();

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        display_name: adminDisplayName,
      } satisfies ITodoAppAdminUser.IJoin,
    });
  typia.assert(adminAuthorized);

  // 2. Register a member user; join also authenticates that member user, but we only
  //    need the identity and email/password for later.
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();
  const memberDisplayName: string = RandomGenerator.name();

  const memberAuthorizedOnJoin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: {
        email: memberEmail,
        password: memberPassword,
        display_name: memberDisplayName,
        href: "https://example.com/join",
        referrer: "https://example.com/landing",
        ip: null,
      } satisfies ITodoAppMemberUserJoin.IRequest,
    });
  typia.assert(memberAuthorizedOnJoin);

  // 3. Switch back to admin explicitly to ensure admin context for listing.
  const adminAfterJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        href: "https://example.com/admin/login",
        referrer: "https://example.com/admin",
        ip: null,
        user_agent: null,
      } satisfies ITodoAppAdminUser.ILogin,
    });
  typia.assert(adminAfterJoin);

  // 4. Admin queries member users list filtered by email to capture baseline summary.
  const firstPage: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 10,
        email: memberEmail,
        status: undefined,
        createdFrom: undefined,
        createdTo: undefined,
        deleted: undefined,
        orderBy: undefined,
        orderDirection: undefined,
      } satisfies ITodoAppMemberuser.IRequest,
    });
  typia.assert(firstPage);

  TestValidator.predicate(
    "admin listing should return at least one member for the given email",
    firstPage.data.length > 0,
  );

  const baseline = firstPage.data.find((u) => u.email === memberEmail);
  TestValidator.predicate(
    "baseline member summary for email must be found",
    !!baseline,
  );

  if (!baseline) return; // Safeguard for TypeScript; logically unreachable after predicate.

  const baselineId = baseline.id;
  const baselineStatus = baseline.status;
  const baselineDisplayName = baseline.display_name;

  // 5. Switch to the member user by logging in with their original password.
  const memberAuthorizedOnLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: {
        email: memberEmail,
        password: memberPassword,
        href: "https://example.com/member/login",
        referrer: "https://example.com",
        ip: null,
      } satisfies ITodoAppMemberUserLogin.IRequest,
    });
  typia.assert(memberAuthorizedOnLogin);

  // 6. Change the password for the authenticated member user.
  const newPassword: string = RandomGenerator.alphaNumeric(16);

  const changeResult: ITodoAppMemberUserChangePassword.IResponse =
    await api.functional.auth.memberUser.password.changePassword(connection, {
      body: {
        currentPassword: memberPassword,
        newPassword,
      } satisfies ITodoAppMemberUserChangePassword.IRequest,
    });
  typia.assert(changeResult);

  TestValidator.predicate(
    "password change operation should report success",
    changeResult.success === true,
  );

  // 7. Optionally, verify new password works by logging in again.
  const memberAuthorizedWithNewPassword: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: {
        email: memberEmail,
        password: newPassword,
        href: "https://example.com/member/login",
        referrer: "https://example.com/after-change",
        ip: null,
      } satisfies ITodoAppMemberUserLogin.IRequest,
    });
  typia.assert(memberAuthorizedWithNewPassword);

  TestValidator.equals(
    "member id should remain the same after password change and re-login",
    memberAuthorizedWithNewPassword.id,
    baselineId,
  );

  // 8. Switch back to admin context.
  const adminAfterPasswordChange: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        href: "https://example.com/admin/login",
        referrer: "https://example.com/admin/after-change",
        ip: null,
        user_agent: null,
      } satisfies ITodoAppAdminUser.ILogin,
    });
  typia.assert(adminAfterPasswordChange);

  // 9. Admin lists member users again to check that lifecycle/profile fields are unchanged.
  const secondPage: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 10,
        email: memberEmail,
        status: undefined,
        createdFrom: undefined,
        createdTo: undefined,
        deleted: undefined,
        orderBy: undefined,
        orderDirection: undefined,
      } satisfies ITodoAppMemberuser.IRequest,
    });
  typia.assert(secondPage);

  const afterChange = secondPage.data.find((u) => u.id === baselineId);
  TestValidator.predicate(
    "member summary with matching id should still be present after password change",
    !!afterChange,
  );

  if (!afterChange) return;

  // Assert that email and id remain identical.
  TestValidator.equals(
    "member id should be unchanged after password change",
    afterChange.id,
    baselineId,
  );
  TestValidator.equals(
    "member email should be unchanged after password change",
    afterChange.email,
    memberEmail,
  );

  // Assert that lifecycle/profile fields visible to admin are unchanged.
  TestValidator.equals(
    "member status should remain unchanged after password change",
    afterChange.status,
    baselineStatus,
  );

  // Handle nullable/optional display_name correctly: normalize to null when absent.
  TestValidator.equals(
    "member display_name should remain unchanged after password change",
    afterChange.display_name ?? null,
    baselineDisplayName ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate updating email and display_name of an existing administrative user
 * via the adminUser update endpoint.
 *
 * Business scenario:
 *
 * - An admin joins the system, obtaining an authorized adminUser context and
 *   token via POST /auth/adminUser/join.
 * - The same admin then updates their own profile fields (email and display_name)
 *   using PUT /todoApp/adminUser/adminUsers/{adminUserId}.
 * - The update must change only the specified fields while preserving other
 *   properties such as id, created_at, status, failed_login_count,
 *   last_login_at, and deleted_at.
 *
 * Steps:
 *
 * 1. Join as a new adminUser (this both creates the admin record and sets
 *    Authorization header on the connection).
 * 2. Record baseline fields from the authorized payload.
 * 3. Prepare an ITodoAppAdminUser.IUpdate body that changes email and display_name
 *    only.
 * 4. Call the update endpoint with the adminUserId from the authorized user.
 * 5. Validate that the returned ITodoAppAdminUser reflects the updated email and
 *    display_name while preserving id, created_at, status, failed_login_count,
 *    last_login_at, and deleted_at.
 * 6. Validate that updated_at is not earlier than the previous updated_at and is
 *    at or after created_at.
 */
export async function test_api_admin_user_update_profile_fields(
  connection: api.IConnection,
) {
  // 1. Join as a new admin user to obtain an authorized context
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinInput,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  // 2. Capture baseline fields from the authorized admin user
  const originalId = authorized.id;
  const originalEmail = authorized.email;
  const originalDisplayName = authorized.display_name ?? null;
  const originalStatus = authorized.status;
  const originalFailedLoginCount = authorized.failed_login_count;
  const originalLastLoginAt = authorized.last_login_at ?? null;
  const originalCreatedAt = authorized.created_at;
  const originalUpdatedAt = authorized.updated_at;
  const originalDeletedAt = authorized.deleted_at ?? null;

  // 3. Prepare update body changing only email and display_name
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newDisplayName = RandomGenerator.name();

  // Ensure the new email is different from the original to make assertion meaningful
  const finalEmail =
    newEmail === originalEmail
      ? typia.random<string & tags.Format<"email">>()
      : newEmail;

  const updateBody = {
    email: finalEmail,
    display_name: newDisplayName,
  } satisfies ITodoAppAdminUser.IUpdate;

  // 4. Perform the update call as the same authenticated admin
  const updated: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: originalId,
      body: updateBody,
    });
  typia.assert<ITodoAppAdminUser>(updated);

  // 5. Validate updated fields and preserved fields
  TestValidator.equals(
    "admin id should remain unchanged",
    updated.id,
    originalId,
  );

  TestValidator.equals(
    "email should be updated to new value",
    updated.email,
    finalEmail,
  );

  TestValidator.equals(
    "display_name should be updated to new non-null value",
    updated.display_name ?? null,
    newDisplayName,
  );

  TestValidator.equals(
    "status should remain unchanged when not provided in update",
    updated.status,
    originalStatus,
  );

  TestValidator.equals(
    "failed_login_count should remain unchanged when not provided in update",
    updated.failed_login_count,
    originalFailedLoginCount,
  );

  TestValidator.equals(
    "last_login_at should remain unchanged when not provided in update",
    updated.last_login_at ?? null,
    originalLastLoginAt,
  );

  TestValidator.equals(
    "deleted_at should remain unchanged when not provided in update",
    updated.deleted_at ?? null,
    originalDeletedAt,
  );

  TestValidator.equals(
    "created_at should remain unchanged",
    updated.created_at,
    originalCreatedAt,
  );

  // 6. Validate updated_at time ordering
  // Compare ISO strings lexicographically as they are in date-time format.
  TestValidator.predicate(
    "updated_at should be at or after original updated_at",
    updated.updated_at >= originalUpdatedAt,
  );

  TestValidator.predicate(
    "updated_at should be at or after created_at",
    updated.updated_at >= updated.created_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate lifecycle status and logical deletion/reactivation updates for an
 * administrative user account.
 *
 * This test covers a realistic admin-user lifecycle scenario:
 *
 * 1. Register a new adminUser via POST /auth/adminUser/join, which both creates
 *    the todo_app_adminusers row and authenticates the actor, returning
 *    ITodoAppAdminUser.IAuthorized plus setting the connection Authorization
 *    header.
 * 2. As that authenticated admin, update the same adminUser record via PUT
 *    /todoApp/adminUser/adminUsers/{adminUserId}, using an
 *    ITodoAppAdminUser.IUpdate body to set a non-active status and populate
 *    deleted_at with a timestamp string, simulating logical deactivation.
 * 3. Assert that the response ITodoAppAdminUser preserves immutable identity
 *    fields (id, created_at) and email, while reflecting the updated status,
 *    deleted_at, and a refreshed updated_at.
 * 4. Then perform a follow-up update that sets status back to an active-like value
 *    and explicitly nulls deleted_at, simulating reactivation of a logically
 *    deleted account. Assert that this transition succeeds and fields match
 *    expectations.
 * 5. Confirm that unrelated fields not included in the update bodies, such as
 *    email and possibly display_name when omitted, remain unchanged across the
 *    lifecycle transitions.
 */
export async function test_api_admin_user_status_and_deactivation_update(
  connection: api.IConnection,
) {
  // 1. Join/register an adminUser and obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized = await api.functional.auth.adminUser.join(connection, {
    body: joinBody,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  // Capture original immutable and baseline fields for later comparison
  const originalId = authorized.id;
  const originalEmail = authorized.email;
  const originalCreatedAt = authorized.created_at;
  const originalUpdatedAt = authorized.updated_at;
  const originalDeletedAt = authorized.deleted_at ?? null;
  const originalStatus = authorized.status;

  // 2. Deactivate: set status to a non-active value and set deleted_at
  const deactivatedStatus = "disabled";
  const deletedAtTimestamp = new Date().toISOString();

  const deactivateBody = {
    status: deactivatedStatus,
    deleted_at: deletedAtTimestamp,
  } satisfies ITodoAppAdminUser.IUpdate;

  const deactivated = await api.functional.todoApp.adminUser.adminUsers.update(
    connection,
    {
      adminUserId: originalId,
      body: deactivateBody,
    },
  );
  typia.assert<ITodoAppAdminUser>(deactivated);

  // Business assertions after deactivation
  TestValidator.equals(
    "id must remain the same after deactivation",
    deactivated.id,
    originalId,
  );
  TestValidator.equals(
    "created_at must remain unchanged after deactivation",
    deactivated.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "email must remain unchanged after deactivation",
    deactivated.email,
    originalEmail,
  );
  TestValidator.equals(
    "status must be updated to deactivated value",
    deactivated.status,
    deactivatedStatus,
  );
  TestValidator.equals(
    "deleted_at must be set to requested timestamp",
    deactivated.deleted_at ?? null,
    deletedAtTimestamp,
  );
  TestValidator.predicate(
    "updated_at must change when deactivating",
    deactivated.updated_at !== originalUpdatedAt,
  );

  // 3. Reactivate: set status back to an active-like value and clear deleted_at
  const reactivatedStatus = "active";

  const reactivateBody = {
    status: reactivatedStatus,
    deleted_at: null,
  } satisfies ITodoAppAdminUser.IUpdate;

  const reactivated = await api.functional.todoApp.adminUser.adminUsers.update(
    connection,
    {
      adminUserId: originalId,
      body: reactivateBody,
    },
  );
  typia.assert<ITodoAppAdminUser>(reactivated);

  // Business assertions after reactivation
  TestValidator.equals(
    "id must remain the same after reactivation",
    reactivated.id,
    originalId,
  );
  TestValidator.equals(
    "created_at must remain unchanged after reactivation",
    reactivated.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "email must remain unchanged after reactivation",
    reactivated.email,
    originalEmail,
  );
  TestValidator.equals(
    "status must be updated to active value",
    reactivated.status,
    reactivatedStatus,
  );
  TestValidator.equals(
    "deleted_at must be cleared (null) after reactivation",
    reactivated.deleted_at ?? null,
    null,
  );
  TestValidator.predicate(
    "updated_at must change again when reactivating",
    reactivated.updated_at !== deactivated.updated_at,
  );

  // Sanity check: original deleted_at should have been null or unchanged prior to our first update
  TestValidator.equals(
    "original deleted_at should be null before lifecycle updates",
    originalDeletedAt,
    null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that an authenticated admin user can reset and adjust
 * failed_login_count on an admin account using the adminUsers.update API.
 *
 * Business flow:
 *
 * 1. Register a new admin user via POST /auth/adminUser/join. The response
 *    ITodoAppAdminUser.IAuthorized includes the admin's id and current
 *    failed_login_count plus created_at/updated_at. The SDK also stores the
 *    access token into connection.headers automatically.
 * 2. Use that same admin as the operator and call PUT
 *    /todoApp/adminUser/adminUsers/{adminUserId} with ITodoAppAdminUser.IUpdate
 *    to change failed_login_count to a positive integer (e.g. 5). Verify the
 *    returned ITodoAppAdminUser has failed_login_count === 5 and that
 *    updated_at has moved forward.
 * 3. Call the update endpoint again to reset failed_login_count back to 0,
 *    confirming that the counter can be cleared after security review and that
 *    updated_at changes again.
 * 4. Throughout, verify that invariant/system-controlled fields such as id,
 *    created_at, and email remain stable, and that deleted_at stays null in
 *    this happy-path scenario.
 */
export async function test_api_admin_user_failed_login_counter_reset(
  connection: api.IConnection,
) {
  // 1. Register a new admin user (acts as both subject and operator)
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  // Basic invariants from join response
  TestValidator.predicate(
    "initial failed_login_count is zero or non-negative",
    authorized.failed_login_count >= 0,
  );
  TestValidator.predicate(
    "created_at and updated_at are defined on authorized payload",
    !!authorized.created_at && !!authorized.updated_at,
  );

  const adminId = authorized.id;
  const originalEmail = authorized.email;
  const originalCreatedAt = authorized.created_at;
  const originalUpdatedAt = authorized.updated_at;
  const originalDeletedAt = authorized.deleted_at ?? null;

  // 2. First update: set failed_login_count to a positive integer
  const firstTargetCount = 5;

  const firstUpdateBody = {
    failed_login_count: firstTargetCount,
  } satisfies ITodoAppAdminUser.IUpdate;

  const afterFirstUpdate: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: adminId,
      body: firstUpdateBody,
    });
  typia.assert<ITodoAppAdminUser>(afterFirstUpdate);

  TestValidator.equals(
    "failed_login_count should be updated to positive integer (5)",
    firstTargetCount,
    afterFirstUpdate.failed_login_count,
  );
  TestValidator.equals(
    "id must remain unchanged after first update",
    afterFirstUpdate.id,
    adminId,
  );
  TestValidator.equals(
    "email must remain unchanged after first update",
    afterFirstUpdate.email,
    originalEmail,
  );
  TestValidator.equals(
    "created_at must remain unchanged after first update",
    afterFirstUpdate.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "deleted_at remains unchanged (null baseline) after first update",
    afterFirstUpdate.deleted_at ?? null,
    originalDeletedAt,
  );

  TestValidator.predicate(
    "updated_at should be same or later than original after first update",
    afterFirstUpdate.updated_at >= originalUpdatedAt,
  );

  const firstUpdatedAt = afterFirstUpdate.updated_at;

  // 3. Second update: reset failed_login_count back to 0
  const secondTargetCount = 0;

  const secondUpdateBody = {
    failed_login_count: secondTargetCount,
  } satisfies ITodoAppAdminUser.IUpdate;

  const afterSecondUpdate: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: adminId,
      body: secondUpdateBody,
    });
  typia.assert<ITodoAppAdminUser>(afterSecondUpdate);

  TestValidator.equals(
    "failed_login_count should be reset to zero",
    secondTargetCount,
    afterSecondUpdate.failed_login_count,
  );
  TestValidator.equals(
    "id remains stable after second update",
    afterSecondUpdate.id,
    adminId,
  );
  TestValidator.equals(
    "email remains stable after second update",
    afterSecondUpdate.email,
    originalEmail,
  );
  TestValidator.equals(
    "created_at remains stable after second update",
    afterSecondUpdate.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "deleted_at remains unchanged (null baseline) after second update",
    afterSecondUpdate.deleted_at ?? null,
    originalDeletedAt,
  );

  TestValidator.predicate(
    "updated_at should be same or later than afterFirstUpdate",
    afterSecondUpdate.updated_at >= firstUpdatedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that privileged admin tooling can override and clear the
 * `last_login_at` audit timestamp for an administrative user.
 *
 * Business workflow:
 *
 * 1. Register an admin user via POST /auth/adminUser/join and obtain an
 *    ITodoAppAdminUser.IAuthorized payload. This also configures the
 *    Authorization header on the shared connection.
 * 2. Use the returned admin id as adminUserId and call PUT
 *    /todoApp/adminUser/adminUsers/{adminUserId} with an
 *    ITodoAppAdminUser.IUpdate body that sets `last_login_at` to a specific
 *    past ISO-8601 date-time string.
 * 3. Assert that the response ITodoAppAdminUser reflects the overridden
 *    `last_login_at` value, while preserving core fields like `email` and
 *    `status`.
 * 4. Call the same update endpoint again, this time explicitly setting
 *    `last_login_at` to null to clear the audit field.
 * 5. Assert that `last_login_at` becomes null, other key fields remain unchanged,
 *    and `updated_at` has advanced to reflect the last modification time.
 */
export async function test_api_admin_user_last_login_timestamp_override(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  const originalId = authorized.id;
  const originalEmail = authorized.email;
  const originalStatus = authorized.status;
  const originalFailedLoginCount = authorized.failed_login_count;
  const originalDeletedAt = authorized.deleted_at ?? null;

  // 2. Prepare a specific past last_login_at timestamp
  const pastDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const overriddenLastLoginAt: string & tags.Format<"date-time"> =
    pastDate.toISOString() as string & tags.Format<"date-time">;

  const firstUpdateBody = {
    last_login_at: overriddenLastLoginAt,
  } satisfies ITodoAppAdminUser.IUpdate;

  const firstUpdated: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: originalId,
      body: firstUpdateBody,
    });
  typia.assert<ITodoAppAdminUser>(firstUpdated);

  // Validate that id/email/status remain consistent and last_login_at updated
  TestValidator.equals(
    "admin id should remain unchanged after first last_login_at override",
    firstUpdated.id,
    originalId,
  );
  TestValidator.equals(
    "admin email should remain unchanged after first last_login_at override",
    firstUpdated.email,
    originalEmail,
  );
  TestValidator.equals(
    "admin status should remain unchanged after first last_login_at override",
    firstUpdated.status,
    originalStatus,
  );
  TestValidator.equals(
    "failed_login_count should remain unchanged after first last_login_at override",
    firstUpdated.failed_login_count,
    originalFailedLoginCount,
  );
  TestValidator.equals(
    "deleted_at should remain unchanged after first last_login_at override",
    firstUpdated.deleted_at ?? null,
    originalDeletedAt,
  );
  TestValidator.equals(
    "last_login_at should be overridden to the specified past timestamp",
    firstUpdated.last_login_at ?? null,
    overriddenLastLoginAt,
  );

  const firstUpdatedAt = firstUpdated.updated_at;

  // 3. Second update: explicitly clear last_login_at by setting it to null
  const secondUpdateBody = {
    last_login_at: null,
  } satisfies ITodoAppAdminUser.IUpdate;

  const secondUpdated: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: originalId,
      body: secondUpdateBody,
    });
  typia.assert<ITodoAppAdminUser>(secondUpdated);

  // Validate invariants and clearing behavior
  TestValidator.equals(
    "admin id should remain unchanged after clearing last_login_at",
    secondUpdated.id,
    originalId,
  );
  TestValidator.equals(
    "admin email should remain unchanged after clearing last_login_at",
    secondUpdated.email,
    originalEmail,
  );
  TestValidator.equals(
    "admin status should remain unchanged after clearing last_login_at",
    secondUpdated.status,
    originalStatus,
  );
  TestValidator.equals(
    "failed_login_count should remain unchanged after clearing last_login_at",
    secondUpdated.failed_login_count,
    originalFailedLoginCount,
  );
  TestValidator.equals(
    "deleted_at should remain unchanged after clearing last_login_at",
    secondUpdated.deleted_at ?? null,
    originalDeletedAt,
  );
  TestValidator.equals(
    "last_login_at should be cleared to null after explicit null update",
    secondUpdated.last_login_at ?? null,
    null,
  );

  // Ensure updated_at reflects the latest modification (second update should be newer or equal)
  TestValidator.predicate(
    "updated_at after second update should be greater than or equal to first updated_at",
    new Date(secondUpdated.updated_at).getTime() >=
      new Date(firstUpdatedAt).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that updating an admin user's email to an email already used by
 * another admin user fails due to the unique email constraint on
 * todo_app_adminusers.
 *
 * Business context:
 *
 * - ITodoAppAdminUser.email is defined as a unique login identifier for admin
 *   accounts, enforced by a unique index in the todo_app_adminusers table.
 * - The PUT /todoApp/adminUser/adminUsers/{adminUserId} endpoint must respect
 *   this uniqueness and reject updates that would cause duplicate emails.
 *
 * Test workflow:
 *
 * 1. Create first admin user A via POST /auth/adminUser/join with a random email.
 * 2. Create second admin user B via POST /auth/adminUser/join with a different
 *    random email.
 * 3. Attempt to update admin B's email to admin A's email via PUT
 *    /todoApp/adminUser/adminUsers/{adminUserId}.
 * 4. Confirm that the update operation fails (throws) due to the email uniqueness
 *    constraint, using TestValidator.error.
 * 5. Ensure both join responses are valid ITodoAppAdminUser.IAuthorized objects
 *    using typia.assert for strong type safety.
 *
 * Note:
 *
 * - We do not validate specific HTTP status codes or error payload contents to
 *   avoid coupling to transport-level details; we only ensure that an error is
 *   raised when attempting a conflicting update.
 */
export async function test_api_admin_user_update_email_uniqueness_violation(
  connection: api.IConnection,
) {
  // 1. Create admin A with a random unique email
  const adminAEmail = typia.random<string & tags.Format<"email">>();
  const adminAJoinBody = {
    email: adminAEmail,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminA);

  // 2. Create admin B with a different random unique email
  const adminBEmail = typia.random<string & tags.Format<"email">>();
  const adminBJoinBody = {
    email: adminBEmail,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminB);

  // Sanity check: ensure emails are indeed different before attempting conflict
  TestValidator.notEquals(
    "admin A and admin B must have different emails before conflict test",
    adminA.email,
    adminB.email,
  );

  // 3. Attempt to update admin B's email to admin A's email, which should
  //    violate the unique index on email in todo_app_adminusers and result in
  //    an error.
  await TestValidator.error(
    "updating admin B's email to admin A's email must fail due to uniqueness constraint",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.update(connection, {
        adminUserId: adminB.id,
        body: {
          email: adminA.email,
        } satisfies ITodoAppAdminUser.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that an authenticated admin user can successfully delete another
 * admin account by UUID using the todo_app_adminusers erase endpoint.
 *
 * Business goals:
 *
 * - Ensure that an admin created through the join flow can call the DELETE
 *   /todoApp/adminUser/adminUsers/{adminUserId} endpoint.
 * - Confirm that it is possible to delete a _different_ admin account (not the
 *   currently authenticated one) using that endpoint.
 * - Exercise the happy path of the erase operation, verifying that it completes
 *   without error when called with a valid adminUserId and proper
 *   authentication.
 *
 * Scenario steps:
 *
 * 1. Create the target admin via POST /auth/adminUser/join. This inserts a row
 *    into todo_app_adminusers and configures the connection with that adminUser
 *    token (Authorization header) via the SDK.
 * 2. Create a second admin (the acting admin) using another join call. After this
 *    call, the connection’s Authorization header corresponds to the acting
 *    admin, while we still retain the target admin’s id from step 1.
 * 3. Assert that the two admin IDs differ to guarantee we are not about to delete
 *    the logged-in admin account.
 * 4. Invoke api.functional.todoApp.adminUser.adminUsers.erase with adminUserId set
 *    to the target admin’s id. Because erase returns void, success is defined
 *    as the call completing without throwing an HttpError.
 * 5. Since the provided SDK subset does not include GET or listing endpoints for
 *    admin users, skip post-deletion read/list validation. The test focuses on
 *    correct authentication, proper parameter wiring, and absence of errors
 *    from the erase call.
 */
export async function test_api_admin_user_delete_success(
  connection: api.IConnection,
) {
  // 1. Create the target admin via join
  const targetAdmin = await api.functional.auth.adminUser.join(connection, {
    body: typia.random<ITodoAppAdminUser.IJoin>(),
  });
  typia.assert(targetAdmin);

  // 2. Create the acting admin via a second join (this updates Authorization)
  const actingAdmin = await api.functional.auth.adminUser.join(connection, {
    body: typia.random<ITodoAppAdminUser.IJoin>(),
  });
  typia.assert(actingAdmin);

  // 3. Ensure we are deleting a different admin than the acting one
  TestValidator.notEquals(
    "acting admin and target admin must have different ids",
    actingAdmin.id,
    targetAdmin.id,
  );

  // 4. Call erase to delete the target admin by UUID while authenticated
  //    as the acting admin
  await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
    adminUserId: targetAdmin.id,
  });

  // 5. No further assertions are possible without read/list APIs for
  //    admin users; successful completion of erase without thrown error
  //    is treated as a successful deletion.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate behavior when deleting a non-existent admin user.
 *
 * Business intent:
 *
 * - Ensure that DELETE /todoApp/adminUser/adminUsers/{adminUserId} reports an
 *   error when the target admin user id does not exist.
 * - Confirm that such a failing deletion does not break the admin authentication
 *   / account system (no unintended side effects).
 *
 * Test flow:
 *
 * 1. Bootstrap an admin context by calling POST /auth/adminUser/join with a
 *    randomized email/password payload. This also sets the Authorization header
 *    on the shared connection via the SDK.
 * 2. Generate a random UUID string to use as a fake adminUserId, which we assume
 *    does not correspond to any real todo_app_adminusers record.
 * 3. Call api.functional.todoApp.adminUser.adminUsers.erase with that random
 *    adminUserId while authenticated as the created admin.
 * 4. Assert that an error is thrown using TestValidator.error. To comply with
 *    global rules, we do not assert on the concrete HTTP status code or error
 *    payload; we only require that the operation fails.
 * 5. As a lightweight regression check for "no side effects", call
 *    api.functional.auth.adminUser.join again with a new random email while
 *    still using the same connection and assert that it returns a valid
 *    ITodoAppAdminUser.IAuthorized via typia.assert(). If this second join
 *    succeeds, it strongly suggests that the failed deletion attempt did not
 *    corrupt global admin state.
 */
export async function test_api_admin_user_delete_not_found(
  connection: api.IConnection,
) {
  // 1. Create an initial admin user to obtain admin authentication context
  const firstAdminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const firstAdmin = await api.functional.auth.adminUser.join(connection, {
    body: firstAdminJoinBody,
  });
  typia.assert(firstAdmin);

  // 2. Generate a random UUID for a non-existent admin user id
  const nonExistentAdminUserId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt to delete the non-existent admin user and assert that it fails
  await TestValidator.error(
    "delete non-existent admin user should fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
        adminUserId: nonExistentAdminUserId,
      });
    },
  );

  // 4. Verify no side effects by performing another successful admin join
  const secondAdminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const secondAdmin = await api.functional.auth.adminUser.join(connection, {
    body: secondAdminJoinBody,
  });
  typia.assert(secondAdmin);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate self-deletion protection for administrative users.
 *
 * This test verifies that an adminUser cannot delete their own account via
 * DELETE /todoApp/adminUser/adminUsers/{adminUserId}, while a different admin
 * can delete that same account, reflecting typical self-protection rules for
 * privileged accounts.
 *
 * Flow:
 *
 * 1. Register adminA with POST /auth/adminUser/join; the SDK automatically
 *    authenticates the connection as adminA and returns
 *    ITodoAppAdminUser.IAuthorized.
 * 2. While still authenticated as adminA, attempt to delete adminA by calling
 *    api.functional.todoApp.adminUser.adminUsers.erase with adminUserId =
 *    adminA.id and assert that the call fails (business rule: self-deletion is
 *    forbidden).
 * 3. Register adminB with POST /auth/adminUser/join; this re-authenticates the
 *    connection as adminB.
 * 4. As adminB, call api.functional.todoApp.adminUser.adminUsers.erase targeting
 *    adminUserId = adminA.id and assert that it succeeds (no error thrown).
 * 5. Optionally, call erase again with the same adminUserId and assert that it now
 *    fails (either not-found or authorization), proving that the first deletion
 *    took effect.
 */
export async function test_api_admin_user_delete_self_protection_rule(
  connection: api.IConnection,
) {
  // 1. Register adminA and authenticate as that admin
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminA);

  // 2. Attempt self-deletion as adminA and expect failure
  await TestValidator.error("adminA cannot delete itself", async () => {
    await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
      adminUserId: adminA.id,
    });
  });

  // 3. Register adminB and authenticate as that admin
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminB);

  // 4. As adminB, delete adminA successfully
  await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
    adminUserId: adminA.id,
  });

  // 5. Subsequent deletion attempts on the same id should fail
  await TestValidator.error(
    "cannot delete already deleted adminA",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
        adminUserId: adminA.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate deletion behavior and potential "last admin" protection for todoApp
 * administrative users.
 *
 * Business intent:
 *
 * - Ensure that basic admin lifecycle operations work via the provided SDK:
 *   creating administrative users with POST /auth/adminUser/join and deleting
 *   them with DELETE /todoApp/adminUser/adminUsers/{adminUserId}.
 * - Probe whether the backend enforces a rule preventing deletion of the last
 *   remaining admin account (self-delete scenario) without breaking the test
 *   when such a rule is absent.
 * - Confirm that, when multiple admins exist, at least one admin record can be
 *   deleted successfully.
 *
 * Constraints from available APIs:
 *
 * - We only have two operations: admin join (create + issue token) and erase
 *   (delete by UUID). There are no list/count/search endpoints for admins and
 *   no audit log APIs, so we cannot assert exact admin counts or inspect logs.
 * - Join automatically sets connection.headers.Authorization using the issued
 *   access token; tests must not touch headers directly.
 * - Erase returns void on success and throws HttpError on failure.
 *
 * Scenario steps:
 *
 * 1. Single-admin self-delete attempt (potential last-admin protection) 1.1. Call
 *    api.functional.auth.adminUser.join to create adminA using
 *    typia.random<ITodoAppAdminUser.IJoin>() as the request payload. 1.2.
 *    Assert the join response with typia.assert and capture adminA.id and email
 *    for sanity checks. 1.3. While authenticated as adminA (connection mutated
 *    by join), call api.functional.todoApp.adminUser.adminUsers.erase with
 *    adminUserId = adminA.id. 1.4. Accept both behaviors as valid: - If erase
 *    succeeds, the environment does not enforce last-admin protection. - If
 *    erase throws an HttpError, we interpret it as a protection rule (e.g.,
 *    last-admin cannot be deleted) and still treat the test as successful.
 * 2. Multi-admin deletion (successful delete when multiple admins exist) 2.1. Call
 *    join again to create adminB; typia.assert the response and record its id.
 *    2.2. Call join a third time to create adminC; typia.assert the response
 *    and record its id. After this call, the connection is authenticated as
 *    adminC. 2.3. Attempt to delete one of the admins (e.g., adminB) using
 *    erase, passing adminUserId = adminB.id. 2.4. Assert that erase does not
 *    throw (a straightforward successful path where the system is not left
 *    without any admin user at all).
 * 3. Basic sanity validations:
 *
 *    - Use TestValidator.equals to ensure that emails returned from join are stable
 *         values we pass into erase.
 *    - Avoid extra type validations beyond typia.assert, focusing instead on
 *         business-level expectations.
 */
export async function test_api_admin_user_delete_last_admin_protection(
  connection: api.IConnection,
) {
  // 1. Single-admin self-delete attempt
  const adminAJoinInput = typia.random<ITodoAppAdminUser.IJoin>();

  const adminA = await api.functional.auth.adminUser.join(connection, {
    body: adminAJoinInput,
  });
  typia.assert(adminA);

  TestValidator.equals(
    "adminA email matches join input",
    adminA.email,
    adminAJoinInput.email,
  );

  // Try to delete adminA as the only admin. This may or may not be allowed
  // depending on backend configuration. We accept both outcomes:
  // - Success: environment does not enforce last-admin protection.
  // - HttpError: environment enforces a protection rule.
  try {
    await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
      adminUserId: adminA.id,
    });
  } catch {
    // Intentionally swallow the error: its mere presence indicates that the
    // backend rejected self-delete, which is an acceptable behavior for this
    // test. We do not inspect status codes or messages.
  }

  // 2. Multi-admin deletion scenario
  const adminBJoinInput = typia.random<ITodoAppAdminUser.IJoin>();
  const adminB = await api.functional.auth.adminUser.join(connection, {
    body: adminBJoinInput,
  });
  typia.assert(adminB);

  const adminCJoinInput = typia.random<ITodoAppAdminUser.IJoin>();
  const adminC = await api.functional.auth.adminUser.join(connection, {
    body: adminCJoinInput,
  });
  typia.assert(adminC);

  TestValidator.equals(
    "adminB email matches join input",
    adminB.email,
    adminBJoinInput.email,
  );
  TestValidator.equals(
    "adminC email matches join input",
    adminC.email,
    adminCJoinInput.email,
  );

  // Attempt to delete adminB while at least adminC remains.
  await api.functional.todoApp.adminUser.adminUsers.erase(connection, {
    adminUserId: adminB.id,
  });
}

