          body,
        },
      );
    typia.assert<IPageITodoAppAdminuserSession.ISummary>(page);
    return page;
  };

  // 2. Initial wide-open query (no from/to filters) to fetch existing sessions for this admin
  const initialRequest = {
    page: 1,
    limit: 50,
    from_created_at: null,
    to_created_at: null,
    only_active: null,
    sort_created_at_desc: null,
  } satisfies ITodoAppAdminuserSession.IRequest;

  const initialPage = await listSessions(initialRequest);

  // Ensure the pagination object is structurally correct
  typia.assert<IPage.IPagination>(initialPage.pagination);

  // If there are no sessions, the test can only assert that filters return empty sets consistently
  if (initialPage.data.length === 0) {
    // With no sessions, any non-null date range should return empty data
    const from = new Date().toISOString();
    const to = new Date(Date.now() + 60_000).toISOString();

    const filteredPage = await listSessions({
      page: 1,
      limit: 50,
      from_created_at: from,
      to_created_at: to,
      only_active: null,
      sort_created_at_desc: null,
    });

    TestValidator.equals(
      "no sessions => filtered result should also be empty",
      filteredPage.data,
      [],
    );
    return;
  }

  // 3. Pick a representative session S from the existing list
  const session: ITodoAppAdminuserSession.ISummary = initialPage.data[0];
  typia.assert<ITodoAppAdminuserSession.ISummary>(session);

  const sessionCreatedAt = session.created_at;

  // 4. Construct an inclusive window [S.created_at, S.created_at]
  const inclusiveRequest = {
    page: 1,
    limit: 50,
    from_created_at: sessionCreatedAt,
    to_created_at: sessionCreatedAt,
    only_active: null,
    sort_created_at_desc: null,
  } satisfies ITodoAppAdminuserSession.IRequest;

  const inclusivePage = await listSessions(inclusiveRequest);

  // Validate that all sessions are within the inclusive window
  for (const s of inclusivePage.data) {
    TestValidator.predicate(
      "inclusive window: session.created_at >= from_created_at",
      s.created_at >= inclusiveRequest.from_created_at!,
    );
    TestValidator.predicate(
      "inclusive window: session.created_at <= to_created_at",
      s.created_at <= inclusiveRequest.to_created_at!,
    );
  }

  // At least one session in the inclusive window should have the same id as our reference session
  const inclusiveContainsReference = inclusivePage.data.some(
    (s) => s.id === session.id,
  );
  TestValidator.predicate(
    "inclusive window should contain the reference session",
    inclusiveContainsReference,
  );

  // 5. Construct a window that starts strictly after S.created_at to exclude S
  // Since we only have ISO-8601 strings, we use Date arithmetic and convert back to ISO string.
  const baseDate = new Date(sessionCreatedAt);
  const afterDate = new Date(baseDate.getTime() + 1_000); // +1 second
  const farFuture = new Date(baseDate.getTime() + 60 * 60 * 1000); // +1 hour

  const exclusiveRequest = {
    page: 1,
    limit: 50,
    from_created_at: afterDate.toISOString(),
    to_created_at: farFuture.toISOString(),
    only_active: null,
    sort_created_at_desc: null,
  } satisfies ITodoAppAdminuserSession.IRequest;

  const exclusivePage = await listSessions(exclusiveRequest);

  for (const s of exclusivePage.data) {
    TestValidator.predicate(
      "exclusive window: session.created_at >= from_created_at (after reference)",
      s.created_at >= exclusiveRequest.from_created_at!,
    );
    TestValidator.predicate(
      "exclusive window: session.created_at <= to_created_at",
      s.created_at <= exclusiveRequest.to_created_at!,
    );
  }

  // Confirm that the reference session is not included in this later window
  const exclusiveContainsReference = exclusivePage.data.some(
    (s) => s.id === session.id,
  );
  TestValidator.predicate(
    "exclusive window should not contain the reference session",
    exclusiveContainsReference === false,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminuserSession";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an authenticated admin user can successfully call the admin
 * session detail endpoint and receive a well-typed session object.
 *
 * Original business scenario:
 *
 * - Admin joins/logs in, generating an authentication session
 * - Admin drills down into a specific session record using GET
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId}
 * - Response contains detailed connection metadata (ip, href, referrer,
 *   created_at, expired_at)
 *
 * Practical constraint with provided SDK:
 *
 * - There is no sessions listing endpoint, so we cannot obtain a real sessionId
 *   belonging to the admin from prior calls.
 * - In simulate mode, the sessions.at call ignores real persistence and returns
 *   typia.random<ITodoAppAdminuserSession>(), so any valid UUID values for
 *   adminUserId and sessionId are acceptable.
 * - In real mode, we can at least use a real adminUserId for the admin, but
 *   sessionId must still be synthetically generated because we lack a discovery
 *   API; we rely on the backend to enforce foreign-key constraints.
 *
 * Therefore this E2E test focuses on:
 *
 * 1. Creating realistic authentication context and app activity
 *
 *    - Create an adminUser with /auth/adminUser/join
 *    - Create a memberUser and log them in
 *    - As the memberUser, create a todo via /todoApp/memberUser/todos
 *    - Log back in as the adminUser so the connection headers contain the admin
 *         token when we call the session detail endpoint
 * 2. Calling the admin session detail API
 *
 *    - Use the real admin.id as adminUserId
 *    - Use a randomly generated UUID as sessionId (since we cannot discover a
 *         concrete one through the public SDK)
 *    - Call api.functional.todoApp.adminUser.adminUsers.sessions.at(connection, {
 *         adminUserId, sessionId })
 * 3. Validating the result
 *
 *    - Use typia.assert to guarantee the response matches ITodoAppAdminuserSession
 *         at runtime
 *    - Use TestValidator.equals to ensure that the returned id is a non-empty string
 *         and matches its own value (sanity check)
 *    - Use TestValidator.predicate to document expectations about created_at and
 *         expired_at, acknowledging that expired_at may be null for active
 *         sessions
 *
 * The test deliberately avoids any type error scenarios or validation of
 * internal foreign-key relationships, which are beyond the capabilities of the
 * exposed SDK.
 */
export async function test_api_adminuser_session_detail_basic_retrieval(
  connection: api.IConnection,
) {
  // 1. Register an admin user (this also authenticates the connection as that admin)
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  // 2. Create a member user and associated activity (todo) to reflect real usage context
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://landing.example.com/ads/todo-app",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const member: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(member);

  // Explicitly log in as the member to simulate ongoing usage
  const memberLoginBody = {
    email: member.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/login",
    referrer: "https://todo-app.example.com/signup-complete",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAfterLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAfterLogin);

  // As the authenticated member, create a todo item
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(todo);

  // 3. Switch authentication context back to the admin user
  const adminLoginBody = {
    email: admin.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "E2E-Test-Agent/1.0",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAfterLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAfterLogin);

  // 4. Call the admin session detail endpoint with a valid UUID pair
  const adminUserId = adminAfterLogin.id;
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  const session: ITodoAppAdminuserSession =
    await api.functional.todoApp.adminUser.adminUsers.sessions.at(connection, {
      adminUserId,
      sessionId,
    });
  typia.assert(session);

  // 5. Business-level sanity checks
  TestValidator.predicate(
    "session id should be non-empty string",
    session.id.length > 0,
  );

  TestValidator.predicate(
    "session created_at should be a non-empty date-time string",
    session.created_at.length > 0,
  );

  // expired_at is allowed to be null or a date-time string; we only assert
  // that, when non-null, it is non-empty.
  if (session.expired_at !== null && session.expired_at !== undefined) {
    TestValidator.predicate(
      "expired_at, when present, should be non-empty",
      session.expired_at.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminuserSession";

/**
 * Verify that an authenticated admin user cannot retrieve arbitrary admin
 * session details using a guessed or foreign session identifier.
 *
 * Business intent:
 *
 * - Ensure that GET
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} does not
 *   leak session information when the requested session id does not belong to
 *   the specified admin user, or does not exist at all.
 * - Demonstrate that an authenticated admin (Admin A) cannot use the endpoint to
 *   probe or enumerate sessions that are not legitimately associated with
 *   them.
 *
 * Due to API and DTO limitations (no way to list or directly access concrete
 * session ids from the join/login flow), we approximate a "foreign" or
 * non-owned session id by using a random UUID that is not issued by the system.
 * The expectation is that any such lookup fails rather than returning a valid
 * ITodoAppAdminuserSession.
 *
 * Test flow:
 *
 * 1. Register and authenticate an admin user (Admin A) using POST
 *    /auth/adminUser/join on the provided connection.
 *
 *    - Build ITodoAppAdminUser.IJoin with random but valid email and password.
 *    - Verify the returned ITodoAppAdminUser.IAuthorized object via typia.assert().
 *         This also configures the connection to carry Admin A's Authorization
 *         header for subsequent calls.
 * 2. Generate a random UUID value to serve as a candidate foreign session
 *    identifier.
 * 3. Call GET /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId}
 *    through api.functional.todoApp.adminUser.adminUsers.sessions.at using:
 *
 *    - AdminUserId = Admin A.id
 *    - SessionId = the generated random UUID Wrap this call in
 *         TestValidator.error(), expecting it to throw rather than return an
 *         ITodoAppAdminuserSession.
 * 4. Do not inspect HttpError status or message; only assert that an error occurs,
 *    thereby ensuring that no session details are exposed for this arbitrary
 *    id.
 */
export async function test_api_adminuser_session_detail_not_found_for_other_admin(
  connection: api.IConnection,
) {
  // 1. Register and authenticate Admin A via join()
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA = await api.functional.auth.adminUser.join(connection, {
    body: joinBody,
  });
  typia.assert(adminA);

  // 2. Generate a random UUID to act as a foreign/invalid session id
  const foreignSessionId = typia.random<string & tags.Format<"uuid">>();

  // 3. Attempt to fetch a session for Admin A using the foreign session id
  //    Expectation: the call must fail (no ITodoAppAdminuserSession is
  //    returned), so we wrap it in TestValidator.error(). We do not check
  //    specific status codes or error messages, only that an error occurs.
  await TestValidator.error(
    "admin user cannot read arbitrary session details",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.at(
        connection,
        {
          adminUserId: adminA.id,
          sessionId: foreignSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminuserSession";

/**
 * Validate that admin session detail endpoint rejects requests with invalid
 * identifiers.
 *
 * Business goal:
 *
 * - Ensure that even an authenticated adminUser cannot retrieve session details
 *   for non-existent admin users or sessions, and that the server responds with
 *   an error instead of a successful ITodoAppAdminuserSession payload.
 * - This strengthens security by avoiding information leakage about which
 *   adminUser/session IDs exist while maintaining consistent not-found
 *   semantics.
 *
 * Test flow:
 *
 * 1. Register a new adminUser via POST /auth/adminUser/join using
 *    ITodoAppAdminUser.IJoin. This both creates the admin user in
 *    todo_app_adminusers and configures the connection with a valid
 *    Authorization header via the SDK.
 * 2. Generate a pair of random UUIDs for adminUserId and sessionId that are
 *    extremely unlikely to match any real records.
 * 3. Call GET /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId}
 *    through api.functional.todoApp.adminUser.adminUsers.sessions.at using
 *    those random IDs.
 * 4. Use TestValidator.error with an async callback to assert that the call fails
 *    (i.e., the backend responds with an HTTP error such as 404 Not Found). Do
 *    not inspect the HttpError.status or message; only the existence of an
 *    error matters.
 * 5. Optionally, generate another random UUID for sessionId while using the real
 *    adminUserId from the join result and perform the same call, again
 *    asserting that an error occurs because the sessionId does not exist for
 *    that admin user.
 *
 * Notes and constraints:
 *
 * - Do not attempt to manually manipulate connection.headers; token management is
 *   handled automatically by the SDK after join.
 * - All UUID values must be produced using typia.random with string &
 *   tags.Format<"uuid">.
 * - Do not attempt to create sessions explicitly or rely on any side effects
 *   beyond what is guaranteed by the provided APIs.
 * - Avoid any type-unsafe patterns such as `as any` and do not test with
 *   deliberately invalid types; focus purely on business-level not-found
 *   behavior using correctly typed identifiers.
 */
export async function test_api_adminuser_session_detail_invalid_ids(
  connection: api.IConnection,
) {
  // 1. Register a new admin user to establish authenticated admin context.
  const joinInput = typia.random<ITodoAppAdminUser.IJoin>();
  const adminUser = await api.functional.auth.adminUser.join(connection, {
    body: joinInput,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminUser);

  // 2. First scenario: both adminUserId and sessionId are random UUIDs
  //    that should not correspond to any real records.
  const nonexistentAdminUserId = typia.random<string & tags.Format<"uuid">>();
  const nonexistentSessionId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "requesting session detail with completely invalid adminUserId and sessionId must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.at(
        connection,
        {
          adminUserId: nonexistentAdminUserId,
          sessionId: nonexistentSessionId,
        },
      );
    },
  );

  // 3. Second scenario: valid adminUserId from the joined admin, but a
  //    random non-existent sessionId should still result in an error.
  const anotherNonexistentSessionId = typia.random<
    string & tags.Format<"uuid">
  >();

  await TestValidator.error(
    "requesting session detail with valid adminUserId but invalid sessionId must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.at(
        connection,
        {
          adminUserId: adminUser.id,
          sessionId: anotherNonexistentSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppAdminuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminuserSession";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify that admin session detail endpoint is protected by admin
 * authentication.
 *
 * Business purpose:
 *
 * - Ensure that detailed administrative session metadata, represented by
 *   ITodoAppAdminuserSession, cannot be fetched without a valid adminUser
 *   authentication context.
 * - Demonstrate that the endpoint rejects unauthenticated access attempts.
 * - Ground the test in realistic usage by creating both a memberUser with todo
 *   activity and an adminUser with an active session, even though the concrete
 *   sessionId cannot be discovered from the provided APIs.
 *
 * Scenario steps:
 *
 * 1. Register a new member user via POST /auth/memberUser/join.
 *
 *    - Use ITodoAppMemberUserJoin.IRequest to provide email, password, href, and
 *         referrer, plus optional display_name and ip.
 *    - Assert the returned ITodoAppMemberuser.IAuthorized using typia.assert.
 * 2. As the authenticated memberUser, create at least one todo via POST
 *    /todoApp/memberUser/todos.
 *
 *    - Use ITodoAppTodo.ICreate with realistic title and optional description.
 *    - Assert the returned ITodoAppTodo structure.
 *    - This step ensures the system has real todo activity, aligning with the
 *         business requirement that admin sessions are inspected in a live
 *         system.
 * 3. Register a new adminUser via POST /auth/adminUser/join.
 *
 *    - Use ITodoAppAdminUser.IJoin to provide email, password, and optional
 *         display_name.
 *    - The SDK automatically stores the admin token in connection.headers.
 *    - Assert returned ITodoAppAdminUser.IAuthorized with typia.assert and capture
 *         the adminUserId from the response.
 * 4. Attempt to read an admin session detail without authentication.
 *
 *    - Construct an unauthenticated connection by shallow-cloning the original
 *         connection and overriding headers with an empty object, without any
 *         further header mutation.
 *    - Choose a concrete adminUserId from the admin join response and a UUID for
 *         sessionId via typia.random<string & tags.Format<"uuid">>().
 *    - Call api.functional.todoApp.adminUser.adminUsers.sessions.at with the
 *         unauthenticated connection and the (adminUserId, sessionId) pair
 *         inside TestValidator.error, asserting that an error is thrown. We do
 *         not check status codes or error body; we only require that the call
 *         fails, proving that unauthenticated actors cannot read admin session
 *         details.
 *
 * Note:
 *
 * - Due to the lack of a session listing API in the provided SDK, there is no
 *   type-safe way to discover a real sessionId. Therefore this test is
 *   intentionally focused on the negative path (unauthenticated access
 *   failure), which still validates the core security boundary that the
 *   endpoint requires admin authentication.
 *
 * Constraints and caveats:
 *
 * - No deliberate type errors: all request bodies use the exact DTO types and
 *   required fields.
 * - No HTTP status code assertions: we only validate that an error occurs.
 * - No direct mutation of connection.headers beyond creating an independent
 *   unauthenticated connection object with headers: {}.
 */
export async function test_api_adminuser_session_detail_requires_admin_auth(
  connection: api.IConnection,
) {
  // 1. Register a new member user
  const memberJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  // 2. Create a todo as the authenticated member user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 3. Register a new admin user and obtain authorized context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(1),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const adminUserId = adminAuthorized.id;

  // 4. Attempt to read session detail without authentication
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  const randomSessionId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "unauthenticated access to admin session should fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.at(
        unauthConn,
        {
          adminUserId,
          sessionId: randomSessionId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate deletion of an admin session after admin join/login flow.
 *
 * Business intent:
 *
 * - Ensure that once an admin user has been registered (and implicitly logged-in)
 *   via POST /auth/adminUser/join, the same authenticated actor can invoke the
 *   admin-only session deletion endpoint DELETE
 *   /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} using a
 *   valid adminUserId and sessionId pair.
 * - Because no session listing/detail SDK functions are available, we treat the
 *   sessionId as a plausible UUID and focus on the contract and authorization
 *   behavior of the erase endpoint, not on actual persistence verification.
 *
 * Flow covered by this test:
 *
 * 1. Register a fresh admin account via api.functional.auth.adminUser.join,
 *    supplying a random but valid ITodoAppAdminUser.IJoin payload. This returns
 *    ITodoAppAdminUser.IAuthorized and also installs the admin access token
 *    into the shared connection headers.
 * 2. Extract the adminUserId from the authorized payload (authorized.id) to use as
 *    the {adminUserId} path parameter for the session deletion endpoint.
 * 3. Generate a random UUID value for {sessionId} to act as the target session
 *    identifier. The backend will determine whether such a session exists; our
 *    goal is to ensure that, when called from an authenticated admin context,
 *    the request is well-formed and reaches the endpoint without client-side
 *    contract issues.
 * 4. Call api.functional.todoApp.adminUser.adminUsers.sessions.erase using the
 *    authenticated connection and the derived adminUserId and sessionId
 *    parameters, and assert that no client-side errors are thrown (successful
 *    completion of the Promise). Because the response type is void, there is no
 *    response body to assert; successful resolution is sufficient.
 * 5. Exercise a basic negative path: create an unauthenticated connection clone
 *    with empty headers and attempt to call the same erase endpoint. Verify via
 *    TestValidator.error that this unauthenticated call fails with some error
 *    (without asserting on concrete HTTP status codes), confirming that
 *    authorization is required for this operation.
 */
export async function test_api_admin_session_delete_after_login_flow(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new admin user via join
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Extract adminUserId from the authorized payload
  const adminUserId: string & tags.Format<"uuid"> = authorized.id;

  // 3. Generate a plausible sessionId for the target session
  const sessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4. Call erase as authenticated admin and ensure it completes without error
  await api.functional.todoApp.adminUser.adminUsers.sessions.erase(connection, {
    adminUserId,
    sessionId,
  });

  // 5. Negative path: unauthenticated connection should not be able to erase
  const unauthenticated: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error("unauthenticated erase must fail", async () => {
    await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
      unauthenticated,
      {
        adminUserId,
        sessionId,
      },
    );
