  const sessionIdForAdminBOwn = typia.random<string & tags.Format<"uuid">>();

  await api.functional.todoApp.adminUser.adminUsers.sessions.erase(connB, {
    adminUserId: adminB.id,
    sessionId: sessionIdForAdminBOwn,
  });
}

