/**
 * Validate that deleting a non-existent admin session fails without affecting
 * existing sessions.
 *
 * Business context:
 *
 * - Admin users authenticate via adminUser flows that create rows in
 *   todo_app_adminusers and todo_app_adminuser_sessions.
 * - Security tooling or admin consoles may attempt to terminate specific sessions
 *   by id.
 * - When a client targets a sessionId that does not exist for the given
 *   adminUserId, the backend must respond with a clear error and must not
 *   accidentally delete other sessions.
 *
 * What this test validates:
 *
 * 1. An admin user can be registered via POST /auth/adminUser/join and receives an
 *    ITodoAppAdminUser.IAuthorized payload with a valid id and token.
 * 2. Calling DELETE
 *    /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} with a
 *    fabricated non-existent sessionId for that admin results in an error
 *    instead of a silent success.
 * 3. Repeated attempts using other non-existent sessionIds also fail,
 *    demonstrating consistent behavior.
 *
 * Due to API surface limitations, this test cannot directly inspect the
 * todo_app_adminuser_sessions table. Instead, it focuses on HTTP-level
 * behavior: ensuring that erase() does not succeed when the targeted session
 * row does not exist.
 */
export async function test_api_admin_session_delete_for_nonexistent_session(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain authorized context (includes token and id).
  const joinInput = typia.random<ITodoAppAdminUser.IJoin>();

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinInput,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  const adminUserId = authorized.id;

  // 2. Generate fabricated non-existent session IDs.
  const fakeSessionId1 = typia.random<string & tags.Format<"uuid">>();
  const fakeSessionId2 = typia.random<string & tags.Format<"uuid">>();

  // 3. First deletion attempt with a non-existent session ID should fail.
  await TestValidator.error(
    "deleting non-existent admin session should fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        connection,
        {
          adminUserId,
          sessionId: fakeSessionId1,
        },
      );
    },
  );

  // 4. Second deletion attempt with another non-existent session ID should also fail.
  await TestValidator.error(
    "repeated deletion attempts of non-existent session should consistently fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        connection,
        {
          adminUserId,
          sessionId: fakeSessionId2,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Verify that deleting an admin session requires proper adminUser
 * authentication.
 *
 * This test exercises the following authorization behaviors on the admin
 * session deletion endpoint:
 *
 * 1. An unauthenticated caller (no Authorization header) must not be allowed to
 *    delete an admin session.
 * 2. A caller using a connection that does not have adminUser credentials set
 *    (simulating a non-admin context in the absence of other actor types) must
 *    also be rejected.
 * 3. A properly authenticated adminUser, obtained via POST /auth/adminUser/join,
 *    must be able to invoke DELETE
 *    /todoApp/adminUser/adminUsers/{adminUserId}/sessions/{sessionId} without
 *    authorization errors.
 *
 * Because the SDK only exposes the adminUser join endpoint and the
 * todoApp.adminUser.adminUsers.sessions.erase endpoint, this test focuses on
 * authorization rather than verifying actual persistence of session rows. The
 * {adminUserId, sessionId} pair used for deletion is generated as random UUIDs
 * to satisfy the type contracts. The key contract under test is that the server
 * enforces the `authorizationActors: ["adminUser"]` requirement for the
 * sessions.erase endpoint.
 */
export async function test_api_admin_session_delete_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Register an admin user to obtain adminUser credentials and
  // Authorization header on the primary connection.
  const adminJoinInput = typia.random<ITodoAppAdminUser.IJoin>();
  const authorizedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinInput,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorizedAdmin);

  // At this point, the SDK's join() implementation has set
  // connection.headers.Authorization = output.token.access.
  // We'll treat this connection as an authenticated adminUser context.

  // Prepare a target adminUserId/sessionId pair. In a full system we'd derive
  // this from a real session, but for this test we only need well-typed
  // identifiers for authorization behavior.
  const adminUserId: string & tags.Format<"uuid"> = authorizedAdmin.id;
  const sessionId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Unauthenticated call: create a separate connection object with no
  // headers to simulate a completely unauthenticated context.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated caller cannot delete admin session",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        unauthenticatedConnection,
        {
          adminUserId,
          sessionId,
        },
      );
    },
  );

  // 3. Simulated non-admin context. Since we have no explicit memberUser or
  // other non-admin role in the available SDK, we simulate this by using
  // another fresh connection without any Authorization header as a distinct
  // logical actor.
  const nonAdminConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "non-admin context cannot delete admin session",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.sessions.erase(
        nonAdminConnection,
        {
          adminUserId,
          sessionId,
        },
      );
    },
  );

  // 4. Positive path: authenticated adminUser should be able to call the
  // deletion endpoint without authorization errors using the main connection.
  await api.functional.todoApp.adminUser.adminUsers.sessions.erase(connection, {
    adminUserId,
    sessionId,
  });

  // No further assertions are made on the response body since erase() returns
  // void and its primary contract is successful completion under valid admin
  // authentication.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEOrderDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEOrderDirection";
import type { IETodoAppActorSearchOrderBy } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorSearchOrderBy";
import type { IETodoAppActorType } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppActorSearch";
import type { ITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSearch";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate admin actor search by type and email.
 *
 * Business goal: Ensure that an authenticated adminUser can search actors
 * filtered by actor type `memberUser` and an exact email address, and receives
 * a paginated result set whose contents and pagination metadata are coherent
 * with the request.
 *
 * Steps:
 *
 * 1. Register an admin user (POST /auth/adminUser/join) to obtain admin
 *    authorization context.
 * 2. Register a member user (POST /auth/memberUser/join) with a uniquely generated
 *    email address.
 * 3. Authenticate as the member user (POST /auth/memberUser/login) and create at
 *    least one todo (POST /todoApp/memberUser/todos) to represent activity by
 *    that actor.
 * 4. Authenticate as the admin user (POST /auth/adminUser/login) to ensure the
 *    current token context is adminUser.
 * 5. Call PATCH /todoApp/adminUser/actors/search via
 *    api.functional.todoApp.adminUser.actors.search.index with
 *    ITodoAppActorSearch.IRequest where:
 *
 *    - ActorTypes = ["memberUser"],
 *    - Email = memberUser.email,
 *    - Page = 1,
 *    - Limit = 10,
 *    - OrderBy = "createdAt",
 *    - OrderDirection = "desc".
 * 6. Assert that the response payload is a valid IPageITodoAppActorSearch.ISummary
 *    object using typia.assert.
 * 7. Validate business rules:
 *
 *    - Pagination.current === 1 and pagination.limit === 10.
 *    - Pagination.records >= data.length.
 *    - If records > 0 then pagination.pages >= 1.
 *    - Data.length may be 0 or more, but if > 0 then:
 *
 *         - Every summary.actorType === "memberUser".
 *         - Every summary.email (when defined) equals the memberUser email used in the
 *                   search filter.
 *         - At least one summary in data has email exactly equal to the memberUser email.
 *         - No summary has actorType "guestUser" or "adminUser".
 */
export async function test_api_actor_search_by_type_and_email(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain authorization
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminJoinBody = {
    email: adminEmail,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. Register a member user with a unique email
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 3. Authenticate as the member user and create at least one todo
  const memberLoginBody = {
    email: memberEmail,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/login",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLoginAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo belongs to the logged-in member user",
    createdTodo.memberUser.email,
    memberEmail,
  );

  // 4. Authenticate back as the admin user
  const adminLoginBody = {
    email: adminEmail,
    password: adminJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "e2e-test-agent",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 5. Call actor search filtered by type and email
  const page = 1;
  const limit = 10;

  const searchRequestBody = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    email: memberEmail,
    page,
    limit,
    orderBy: "createdAt" as IETodoAppActorSearchOrderBy,
    orderDirection: "desc" as IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const searchResult: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: searchRequestBody,
    });
  typia.assert(searchResult);

  const { pagination, data } = searchResult;

  // 6. Validate pagination metadata coherence
  TestValidator.equals(
    "pagination current page should match request page",
    pagination.current,
    page,
  );
  TestValidator.equals(
    "pagination limit should match request limit",
    pagination.limit,
    limit,
  );

  TestValidator.predicate(
    "records must be non-negative and at least data.length",
    pagination.records >= 0 && pagination.records >= data.length,
  );

  if (pagination.records > 0) {
    TestValidator.predicate(
      "pages must be at least 1 when records > 0",
      pagination.pages >= 1,
    );
  }

  // 7. Validate actor filtering and email matching in result data
  for (const actor of data) {
    TestValidator.equals(
      "each actor in result must be of type memberUser",
      actor.actorType,
      "memberUser",
    );

    if (actor.email !== undefined) {
      TestValidator.equals(
        "actor email, when present, must match searched member email",
        actor.email,
        memberEmail,
      );
    }

    TestValidator.predicate(
      "no guestUser or adminUser actors are present in results",
      actor.actorType === "memberUser",
    );
  }

  if (data.length > 0) {
    const hasTargetEmail = data.some(
      (actor) => actor.email !== undefined && actor.email === memberEmail,
    );

    TestValidator.predicate(
      "search results must contain at least one actor with the target member email",
      hasTargetEmail,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEOrderDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEOrderDirection";
import type { IETodoAppActorSearchOrderBy } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorSearchOrderBy";
import type { IETodoAppActorType } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppActorSearch";
import type { ITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSearch";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate pagination behavior of admin actor search for member users.
 *
 * Business context:
 *
 * - Admins need to search and browse actors (users) with stable pagination.
 * - When multiple member users exist, paging through search results must return
 *   consistent metadata, non-overlapping result sets between pages, and
 *   predictable behavior when the page size (limit) changes.
 *
 * Steps:
 *
 * 1. Register an admin user and authenticate as that admin.
 * 2. Register multiple member users with distinct emails and optional display
 *    names.
 * 3. For one dedicated member, log in and create a todo to simulate realistic
 *    activity.
 * 4. Switch back to the admin account.
 * 5. Call actors.search for page=1, limit=2, ordered by createdAt asc for
 *    memberUser actors.
 * 6. Call actors.search again for page=2 with same filters and limit.
 * 7. Compare metadata and actor ID sets across page 1 and 2.
 * 8. Optionally, repeat search with a different limit (e.g., 3) and verify that
 *    first-page results with smaller limit are contained in first-page results
 *    with larger limit.
 */
export async function test_api_actor_search_pagination_behavior(
  connection: api.IConnection,
) {
  // 1. Register an admin user and authenticate as that admin.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedFromJoin);

  // 2. Register multiple member users with distinct emails and display names.
  const MEMBER_COUNT = 5;
  const memberAuthorizedList: ITodoAppMemberuser.IAuthorized[] = [];

  for (let i = 0; i < MEMBER_COUNT; i++) {
    const memberEmail: string & tags.Format<"email"> = typia.random<
      string & tags.Format<"email">
    >();
    const memberPassword: string & tags.Format<"password"> = typia.random<
      string & tags.Format<"password">
    >();

    const memberJoinBody = {
      email: memberEmail,
      password: memberPassword,
      display_name: RandomGenerator.name(),
      ip: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppMemberUserJoin.IRequest;

    const memberAuthorized: ITodoAppMemberuser.IAuthorized =
      await api.functional.auth.memberUser.join(connection, {
        body: memberJoinBody,
      });
    typia.assert<ITodoAppMemberuser.IAuthorized>(memberAuthorized);
    memberAuthorizedList.push(memberAuthorized);
  }

  // 3. Create a dedicated member for todo creation to simulate activity.
  const todoMemberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const todoMemberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const todoMemberJoinBody = {
    email: todoMemberEmail,
    password: todoMemberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const todoMemberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: todoMemberJoinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(todoMemberAuthorized);

  const todoMemberLoginBody = {
    email: todoMemberEmail,
    password: todoMemberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const todoMemberAuthorizedFromLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: todoMemberLoginBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(todoMemberAuthorizedFromLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(todo);

  // 4. Switch back to the admin account via login to ensure admin token.
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: null,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorizedFromLogin);

  // 5. First page search: page=1, limit=2 for memberUser actors.
  const PAGE_LIMIT_SMALL = 2 as const;
  const firstSearchBody = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    page: 1,
    limit: PAGE_LIMIT_SMALL,
    orderBy: "createdAt" as IETodoAppActorSearchOrderBy,
    orderDirection: "asc" as IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const firstPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: firstSearchBody,
    });
  typia.assert<IPageITodoAppActorSearch.ISummary>(firstPage);

  const firstPagination = firstPage.pagination;
  const firstIds = firstPage.data.map((actor) => actor.id);

  TestValidator.equals(
    "first page current should be 1",
    firstPagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit should equal requested limit",
    firstPagination.limit,
    PAGE_LIMIT_SMALL,
  );
  TestValidator.predicate(
    "first page records should be >= number of actors returned",
    firstPagination.records >= firstPage.data.length,
  );
  TestValidator.predicate(
    "first page pages should be at least 1 when records exist",
    firstPagination.records === 0 || firstPagination.pages >= 1,
  );
  TestValidator.predicate(
    "first page should not return more actors than limit",
    firstPage.data.length <= firstPagination.limit,
  );

  // 6. Second page search: page=2 with same limit and filters.
  const secondSearchBody = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    page: 2,
    limit: PAGE_LIMIT_SMALL,
    orderBy: "createdAt" as IETodoAppActorSearchOrderBy,
    orderDirection: "asc" as IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const secondPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: secondSearchBody,
    });
  typia.assert<IPageITodoAppActorSearch.ISummary>(secondPage);

  const secondPagination = secondPage.pagination;
  const secondIds = secondPage.data.map((actor) => actor.id);

  TestValidator.equals(
    "second page current should be 2",
    secondPagination.current,
    2,
  );
  TestValidator.equals(
    "second page limit should equal requested limit",
    secondPagination.limit,
    PAGE_LIMIT_SMALL,
  );
  TestValidator.equals(
    "second page records should equal first page records",
    secondPagination.records,
    firstPagination.records,
  );
  TestValidator.equals(
    "second page pages should equal first page pages",
    secondPagination.pages,
    firstPagination.pages,
  );
  TestValidator.predicate(
    "second page should not return more actors than limit",
    secondPage.data.length <= secondPagination.limit,
  );

  // 7. Cross-page consistency checks.
  const combinedIds = [...firstIds, ...secondIds];

  TestValidator.predicate(
    "combined size should equal sum of individual page sizes",
    combinedIds.length === firstIds.length + secondIds.length,
  );

  const firstIdSet = new Set(firstIds);
  const hasOverlap = secondIds.some((id) => firstIdSet.has(id));
  TestValidator.predicate(
    "page 1 and page 2 actor ID sets should be non-overlapping for same query",
    !hasOverlap,
  );

  const computedPages =
    firstPagination.limit === 0
      ? 0
      : Math.ceil(firstPagination.records / firstPagination.limit);

  TestValidator.predicate(
    "records should be <= pages * limit",
    firstPagination.records <= firstPagination.pages * firstPagination.limit,
  );
  TestValidator.equals(
    "pages should equal ceil(records / limit)",
    firstPagination.pages,
    computedPages,
  );

  // 8. Optional scenario with different limit when there are enough records.
  if (firstPagination.records >= 3) {
    const NEW_LIMIT = 3 as const;
    const altSearchBody = {
      actorTypes: ["memberUser" as IETodoAppActorType],
      page: 1,
      limit: NEW_LIMIT,
      orderBy: "createdAt" as IETodoAppActorSearchOrderBy,
      orderDirection: "asc" as IEOrderDirection,
    } satisfies ITodoAppActorSearch.IRequest;

    const altPage: IPageITodoAppActorSearch.ISummary =
      await api.functional.todoApp.adminUser.actors.search.index(connection, {
        body: altSearchBody,
      });
    typia.assert<IPageITodoAppActorSearch.ISummary>(altPage);

    const altPagination = altPage.pagination;
    const altIds = altPage.data.map((actor) => actor.id);

    TestValidator.equals(
      "alt page current should be 1",
      altPagination.current,
      1,
    );
    TestValidator.equals(
      "alt limit should equal requested NEW_LIMIT",
      altPagination.limit,
      NEW_LIMIT,
    );
    TestValidator.equals(
      "alt records should equal previous records",
      altPagination.records,
      firstPagination.records,
    );
    TestValidator.predicate(
      "alt page should not return more actors than NEW_LIMIT",
      altPage.data.length <= altPagination.limit,
    );

    // When using the same ordering, page=1 with a smaller limit should yield
    // a subset of the actors from page=1 with a larger limit.
    const altIdSet = new Set(altIds);
    const allFirstPageIdsAreInAlt = firstIds.every((id) => altIdSet.has(id));
    TestValidator.predicate(
      "first-page IDs with smaller limit should be contained in first-page IDs with larger limit",
      allFirstPageIdsAreInAlt,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEOrderDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEOrderDirection";
import type { IETodoAppActorSearchOrderBy } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorSearchOrderBy";
import type { IETodoAppActorType } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppActorSearch";
import type { ITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSearch";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_actor_search_filters_by_creation_date_range(
  connection: api.IConnection,
) {
  // 1. Register an admin user (adminUser.join) and keep its email/password
  const adminEmail: string = `${RandomGenerator.alphabets(8)}@example.com`;
  const adminPassword: string = "Admin1234!";

  const adminJoin = await api.functional.auth.adminUser.join(connection, {
    body: {
      email: adminEmail as string & tags.Format<"email">,
      password: adminPassword as string & tags.Format<"password">,
      display_name: RandomGenerator.name(),
    } satisfies ITodoAppAdminUser.IJoin,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminJoin);

  // Capture a baseline time before creating members
  const baselineBeforeMembers: string = new Date().toISOString();

  // 2. Create early batch of member users
  const earlyMembers: ITodoAppMemberuser.IAuthorized[] = [];
  const earlyCount = 2;
  for (let i = 0; i < earlyCount; i++) {
    const email: string & tags.Format<"email"> =
      `${RandomGenerator.alphabets(8)}@early.test` as string &
        tags.Format<"email">;
    const password: string & tags.Format<"password"> = "Member1234!" as string &
      tags.Format<"password">;
    const href: string & tags.Format<"uri"> =
      "https://todoapp.local/join" as string & tags.Format<"uri">;
    const referrer: string & tags.Format<"uri"> =
      "https://todoapp.local/landing" as string & tags.Format<"uri">;

    const member = await api.functional.auth.memberUser.join(connection, {
      body: {
        email,
        password,
        display_name: RandomGenerator.name(),
        ip: null,
        href,
        referrer,
      } satisfies ITodoAppMemberUserJoin.IRequest,
    });
    typia.assert<ITodoAppMemberuser.IAuthorized>(member);
    earlyMembers.push(member);
  }

  // Record a mid timestamp between early and late batches
  const betweenBatches: string = new Date().toISOString();

  // 3. Create late batch of member users
  const lateMembers: ITodoAppMemberuser.IAuthorized[] = [];
  const lateCount = 3;
  for (let i = 0; i < lateCount; i++) {
    const email: string & tags.Format<"email"> =
      `${RandomGenerator.alphabets(8)}@late.test` as string &
        tags.Format<"email">;
    const password: string & tags.Format<"password"> = "Member1234!" as string &
      tags.Format<"password">;
    const href: string & tags.Format<"uri"> =
      "https://todoapp.local/join" as string & tags.Format<"uri">;
    const referrer: string & tags.Format<"uri"> =
      "https://todoapp.local/landing" as string & tags.Format<"uri">;

    const member = await api.functional.auth.memberUser.join(connection, {
      body: {
        email,
        password,
        display_name: RandomGenerator.name(),
        ip: null,
        href,
        referrer,
      } satisfies ITodoAppMemberUserJoin.IRequest,
    });
    typia.assert<ITodoAppMemberuser.IAuthorized>(member);
    lateMembers.push(member);
  }

  const afterLateBatch: string = new Date().toISOString();

  // 3b. Optionally, create a todo as one of the late member users for realism
  const sampleLateMember = lateMembers[0];
  // login as that member (this will switch auth context but join already did too)
  await api.functional.auth.memberUser.login(connection, {
    body: {
      email: sampleLateMember.email,
      password: "Member1234!" as string & tags.Format<"password">,
      ip: null,
      href: "https://todoapp.local/login" as string & tags.Format<"uri">,
      referrer: "https://todoapp.local/landing" as string & tags.Format<"uri">,
    } satisfies ITodoAppMemberUserLogin.IRequest,
  });

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 6 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert<ITodoAppTodo>(createdTodo);
  TestValidator.equals(
    "created todo belongs to sample late member",
    createdTodo.memberUser.id,
    sampleLateMember.id,
  );

  // 4. Switch back to admin user via login
  await api.functional.auth.adminUser.login(connection, {
    body: {
      email: adminEmail as string & tags.Format<"email">,
      password: adminPassword as string & tags.Format<"password">,
      ip: null,
      href: "https://todoapp.local/admin/login" as string & tags.Format<"uri">,
      referrer: "https://todoapp.local/admin" as string & tags.Format<"uri">,
      user_agent: "e2e-test-agent" as string,
    } satisfies ITodoAppAdminUser.ILogin,
  });

  // Helper: compute createdFrom/createdTo based on recorded timestamps.
  const createdFromForLate: string & tags.Format<"date-time"> =
    betweenBatches as string & tags.Format<"date-time">;
  const createdToForLate: string & tags.Format<"date-time"> =
    afterLateBatch as string & tags.Format<"date-time">;

  const memberActorType: IETodoAppActorType = "memberUser";
  const orderBy: IETodoAppActorSearchOrderBy = "createdAt";
  const orderDirection: IEOrderDirection = "asc";

  // 5. Call search endpoint to fetch only late-batch members by creation range
  const lateSearchRequest: ITodoAppActorSearch.IRequest = {
    actorTypes: [memberActorType],
    createdFrom: createdFromForLate,
    createdTo: createdToForLate,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy,
    orderDirection,
  };

  const lateSearchPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: lateSearchRequest,
    });
  typia.assert<IPageITodoAppActorSearch.ISummary>(lateSearchPage);

  const lateSearchActors = lateSearchPage.data;

  // 6. Assert that all results are memberUser actors
  for (const actor of lateSearchActors) {
    TestValidator.equals(
      "actor type is memberUser in late window",
      actor.actorType,
      memberActorType,
    );
  }

  // Map ids for quick membership checks
  const earlyIds = new Set(earlyMembers.map((m) => m.id));
  const lateIds = new Set(lateMembers.map((m) => m.id));

  // Assert that no early member IDs are present
  for (const actor of lateSearchActors) {
    TestValidator.predicate(
      "late window search should not contain early member ids",
      earlyIds.has(actor.id) === false,
    );
  }

  // Assert that at least some late members are present (could be subset if other preexisting data also matches)
  const matchedLateIds = lateSearchActors
    .map((a) => a.id)
    .filter((id) => lateIds.has(id));
  TestValidator.predicate(
    "late window search should contain at least one late member",
    matchedLateIds.length > 0,
  );

  // Pagination sanity checks
  const pagination = lateSearchPage.pagination;
  TestValidator.predicate(
    "pagination.current is 1 for first page in late window search",
    pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination.limit is respected in late window search",
    lateSearchActors.length <= pagination.limit,
  );

  // 7. Second search: window targeting early batch only
  const createdFromForEarly: string & tags.Format<"date-time"> =
    baselineBeforeMembers as string & tags.Format<"date-time">;
  const createdToForEarly: string & tags.Format<"date-time"> =
    betweenBatches as string & tags.Format<"date-time">;

  const earlySearchRequest: ITodoAppActorSearch.IRequest = {
    actorTypes: [memberActorType],
    createdFrom: createdFromForEarly,
    createdTo: createdToForEarly,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy,
    orderDirection,
  };

  const earlySearchPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: earlySearchRequest,
    });
  typia.assert<IPageITodoAppActorSearch.ISummary>(earlySearchPage);

  const earlySearchActors = earlySearchPage.data;

  for (const actor of earlySearchActors) {
    TestValidator.equals(
      "actor type is memberUser in early window",
      actor.actorType,
      memberActorType,
    );
  }

  // Assert that no late member IDs are present in early search
  for (const actor of earlySearchActors) {
    TestValidator.predicate(
      "early window search should not contain late member ids",
      lateIds.has(actor.id) === false,
    );
  }

  const matchedEarlyIds = earlySearchActors
    .map((a) => a.id)
    .filter((id) => earlyIds.has(id));
  TestValidator.predicate(
    "early window search should contain at least one early member",
    matchedEarlyIds.length > 0,
  );

  const earlyPagination = earlySearchPage.pagination;
  TestValidator.predicate(
    "pagination.current is 1 for first page in early window search",
    earlyPagination.current === 1,
  );
  TestValidator.predicate(
    "pagination.limit is respected in early window search",
    earlySearchActors.length <= earlyPagination.limit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEOrderDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEOrderDirection";
import type { IETodoAppActorSearchOrderBy } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorSearchOrderBy";
import type { IETodoAppActorType } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppActorSearch";
import type { ITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSearch";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_actor_search_by_status_and_sorting(
  connection: api.IConnection,
) {
  // 1. Register an admin user who will perform actor searches.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  const targetStatus: string = adminAuthorized.status;

  // 2. Prepare multiple member users with distinct display names.
  const memberCount = 5;
  const memberAuthorizedList: ITodoAppMemberuser.IAuthorized[] = [];

  for (let i = 0; i < memberCount; i++) {
    const memberEmail: string & tags.Format<"email"> = typia.random<
      string & tags.Format<"email">
    >();
    const memberPassword: string & tags.Format<"password"> = typia.random<
      string & tags.Format<"password">
    >();

    const displayNameBase = RandomGenerator.name(1);
    const memberJoinBody = {
      email: memberEmail,
      password: memberPassword,
      display_name: `${displayNameBase}-${i}`,
      ip: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppMemberUserJoin.IRequest;

    const memberAuthorized: ITodoAppMemberuser.IAuthorized =
      await api.functional.auth.memberUser.join(connection, {
        body: memberJoinBody,
      });
    typia.assert(memberAuthorized);
    memberAuthorizedList.push(memberAuthorized);

    TestValidator.equals(
      "joined member status should match its own status field",
      memberAuthorized.status,
      memberAuthorized.status,
    );

    const memberLoginBody = {
      email: memberEmail,
      password: memberPassword,
      ip: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies ITodoAppMemberUserLogin.IRequest;

    const memberLoggedIn: ITodoAppMemberuser.IAuthorized =
      await api.functional.auth.memberUser.login(connection, {
        body: memberLoginBody,
      });
    typia.assert(memberLoggedIn);

    const todoCreateBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
    } satisfies ITodoAppTodo.ICreate;

    const createdTodo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert(createdTodo);

    TestValidator.equals(
      "created todo belongs to logged-in member user",
      createdTodo.memberUser.id,
      memberLoggedIn.id,
    );
  }

  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: null,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoggedIn: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  const anyMemberWithStatus = memberAuthorizedList.find(
    (m) => m.status === targetStatus,
  );
  const effectiveStatus: string =
    anyMemberWithStatus !== undefined
      ? anyMemberWithStatus.status
      : targetStatus;

  const firstSearchBody = {
    actorTypes: ["memberUser" satisfies IETodoAppActorType],
    status: effectiveStatus,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: (memberCount + 5) as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: "createdAt" satisfies IETodoAppActorSearchOrderBy,
    orderDirection: "desc" satisfies IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const firstPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: firstSearchBody,
    });
  typia.assert(firstPage);

  TestValidator.equals(
    "first search pagination current page should be 1",
    firstPage.pagination.current,
    1,
  );

  TestValidator.equals(
    "first search pagination limit should equal requested limit",
    firstPage.pagination.limit,
    firstSearchBody.limit,
  );

  TestValidator.predicate(
    "first search should return at least one actor",
    firstPage.data.length > 0,
  );

  for (const actor of firstPage.data) {
    TestValidator.equals(
      "actorType should be memberUser",
      actor.actorType,
      "memberUser",
    );

    if (actor.status !== undefined) {
      TestValidator.equals(
        "actor status should match filter status when present",
        actor.status,
        effectiveStatus,
      );
    }
  }

  const actorsWithLastLogin = firstPage.data.filter(
    (a) => a.last_login_at !== null && a.last_login_at !== undefined,
  );

  if (actorsWithLastLogin.length >= 2) {
    const sortedByLastLoginDesc = [...actorsWithLastLogin].sort((x, y) => {
      const lx = x.last_login_at!;
      const ly = y.last_login_at!;
      if (lx < ly) return 1;
      if (lx > ly) return -1;
      return 0;
    });

    const observed = actorsWithLastLogin.map((a) => a.id);
    const expected = sortedByLastLoginDesc.map((a) => a.id);

    TestValidator.equals(
      "actors with last_login_at should be ordered by last_login_at desc",
      observed,
      expected,
    );
  }

  const secondSearchBody = {
    actorTypes: ["memberUser" satisfies IETodoAppActorType],
    status: effectiveStatus,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: (memberCount + 5) as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: "displayName" satisfies IETodoAppActorSearchOrderBy,
    orderDirection: "asc" satisfies IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const secondPage: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: secondSearchBody,
    });
  typia.assert(secondPage);

  TestValidator.equals(
    "second search pagination current page should be 1",
    secondPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "second search pagination limit should equal requested limit",
    secondPage.pagination.limit,
    secondSearchBody.limit,
  );

  const displayNameActors = secondPage.data.filter(
    (a) => a.display_name !== undefined,
  );

  if (displayNameActors.length >= 2) {
    const displayNames = displayNameActors.map((a) => a.display_name!);
    const sortedNames = [...displayNames].sort((a, b) => a.localeCompare(b));

    TestValidator.equals(
      "actors should be ordered by display_name in ascending order",
      displayNames,
      sortedNames,
    );
  }

  for (const actor of secondPage.data) {
    TestValidator.equals(
      "actorType in second search should be memberUser",
      actor.actorType,
      "memberUser",
    );

    if (actor.status !== undefined) {
      TestValidator.equals(
        "actor status in second search should match filter status when present",
        actor.status,
        effectiveStatus,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IEOrderDirection } from "@ORGANIZATION/PROJECT-api/lib/structures/IEOrderDirection";
import type { IETodoAppActorSearchOrderBy } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorSearchOrderBy";
import type { IETodoAppActorType } from "@ORGANIZATION/PROJECT-api/lib/structures/IETodoAppActorType";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppActorSearch";
import type { ITodoAppActorSearch } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppActorSearch";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_actor_search_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Admin setup via join
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(2),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Member setup via join
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(2),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorizedFromJoin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorizedFromJoin);

  // 2-1. Create a todo as the member user
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 3. Unauthenticated access attempt: build separate connection without headers
  const unauthConn: api.IConnection = {
    ...connection,
    headers: {},
  };

  const minimalSearchRequestUnauth = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    page: 1,
    limit: 10,
  } satisfies ITodoAppActorSearch.IRequest;

  await TestValidator.error(
    "unauthenticated caller cannot access admin actor search",
    async () => {
      await api.functional.todoApp.adminUser.actors.search.index(unauthConn, {
        body: minimalSearchRequestUnauth,
      });
    },
  );

  // 4. Member-authenticated access attempt (non-admin)
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  const minimalSearchRequestMember = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    page: 1,
    limit: 10,
  } satisfies ITodoAppActorSearch.IRequest;

  await TestValidator.error(
    "memberUser cannot access admin-only actor search",
    async () => {
      await api.functional.todoApp.adminUser.actors.search.index(connection, {
        body: minimalSearchRequestMember,
      });
    },
  );

  // 5. Admin-authenticated happy path via login
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: null,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  const searchRequestAsAdmin = {
    actorTypes: ["memberUser" as IETodoAppActorType],
    email: memberEmail,
    page: 1,
    limit: 10,
    orderBy: "createdAt" as IETodoAppActorSearchOrderBy,
    orderDirection: "desc" as IEOrderDirection,
  } satisfies ITodoAppActorSearch.IRequest;

  const searchResultAsAdmin: IPageITodoAppActorSearch.ISummary =
    await api.functional.todoApp.adminUser.actors.search.index(connection, {
      body: searchRequestAsAdmin,
    });
  typia.assert(searchResultAsAdmin);

  // Basic pagination sanity check
  TestValidator.predicate(
    "admin actor search returns first page",
    () => searchResultAsAdmin.pagination.current === 1,
  );

  TestValidator.predicate(
    "admin actor search limit is positive",
    () => searchResultAsAdmin.pagination.limit > 0,
  );

  // Verify that at least one memberUser actor with the memberEmail exists in results
  const hasMemberActor = searchResultAsAdmin.data.some((actor) => {
    return actor.actorType === "memberUser" && actor.email === memberEmail;
  });

  TestValidator.predicate(
    "admin actor search includes the created member user actor",
    hasMemberActor,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

export async function test_api_admin_user_index_filter_by_status_and_created_range(
  connection: api.IConnection,
) {
  // 1. Register Admin A (operator) via POST /auth/adminUser/join
  const adminAJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminA: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminAJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminA);

  // 2. Register Admin B via POST /auth/adminUser/join
  const adminBJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminB: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminBJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminB);

  // Ensure we have stable created_at from adminB
  const adminBCreatedAt: string & tags.Format<"date-time"> = adminB.created_at;

  // 3. Update Admin B status to a non-active lifecycle value using PUT /todoApp/adminUser/adminUsers/{adminUserId}
  //    We'll use a literal status string distinct from any default like "disabled".
  const disabledStatus = "disabled";

  const updatedAdminB: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: adminB.id,
      body: {
        status: disabledStatus,
      } satisfies ITodoAppAdminUser.IUpdate,
    });
  typia.assert<ITodoAppAdminUser>(updatedAdminB);

  TestValidator.equals(
    "updated admin B status should be disabled",
    updatedAdminB.status,
    disabledStatus,
  );

  // 4. Build created_at range around Admin B's created_at
  const createdAtDate = new Date(adminBCreatedAt);

  const createdFrom = new Date(
    createdAtDate.getTime() - 5 * 60 * 1000,
  ).toISOString();
  const createdTo = new Date(
    createdAtDate.getTime() + 5 * 60 * 1000,
  ).toISOString();

  const requestBody = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    keyword: null,
    status: disabledStatus,
    created_from: createdFrom,
    created_to: createdTo,
    order_by: "created_at",
    order_direction: "desc",
  } satisfies ITodoAppAdminUser.IRequest;

  // 5. Call PATCH /todoApp/adminUser/adminUsers with filters
  const page: IPageITodoAppAdminuser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: requestBody,
    });
  typia.assert<IPageITodoAppAdminuser.ISummary>(page);

  const pagination = page.pagination;
  const data = page.data;

  // 6. Basic pagination invariants
  TestValidator.predicate(
    "pagination current should be within pages",
    () => pagination.current >= 0 && pagination.current < pagination.pages,
  );

  TestValidator.predicate(
    "pagination records equals data length when single-page result",
    () =>
      (pagination.pages === 0 &&
        pagination.records === 0 &&
        data.length === 0) ||
      (pagination.pages >= 1 && pagination.records >= data.length),
  );

  // 7. Verify Admin B is included and matches filters
  const foundAdminB = data.find((summary) => summary.id === updatedAdminB.id);

  TestValidator.predicate(
    "admin B should appear in filtered results",
    () => foundAdminB !== undefined,
  );

  if (foundAdminB !== undefined) {
    TestValidator.equals(
      "admin B status should match disabled filter",
      foundAdminB.status,
      disabledStatus,
    );

    TestValidator.predicate(
      "admin B created_at should be within range",
      () =>
        foundAdminB.created_at >= createdFrom &&
        foundAdminB.created_at <= createdTo,
    );
  }

  // 8. Ensure no result violates the filters
  for (const summary of data) {
    TestValidator.equals(
      "every returned admin should have disabled status",
      summary.status,
      disabledStatus,
    );

    TestValidator.predicate(
      "every returned admin created_at should be within specified range",
      () =>
        summary.created_at >= createdFrom && summary.created_at <= createdTo,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify that only authenticated admin users can list admin user accounts.
 *
 * Scenario:
 *
 * 1. Call the admin listing endpoint without any Authorization header and ensure
 *    it fails.
 * 2. Register a regular member user and, using that member-authenticated
 *    connection, attempt to call the admin listing endpoint and ensure it fails
 *    again.
 * 3. Register an admin user, which issues an admin token into the shared
 *    connection, and then call the admin listing endpoint successfully.
 *
 * The test must only assert that unauthorized/forbidden attempts throw some
 * error (using TestValidator.error), without asserting concrete HTTP status
 * codes or error payloads. For the successful path, the response must be
 * asserted via typia.assert as IPageITodoAppAdminuser.ISummary and basic
 * pagination invariants must be checked via TestValidator (e.g. current page
 * index is non-negative, limit and pages are non-negative, records is
 * non-negative, and that data is an array).
 */
export async function test_api_admin_user_index_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 0. Prepare a minimal request body for admin listing.
  const requestBody = {
    page: 0 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    keyword: null,
    status: null,
    created_from: null,
    created_to: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppAdminUser.IRequest;

  // 1. Unauthenticated call: create a derived connection without headers.
  const unauthenticated: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated access to adminUsers.index must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.index(unauthenticated, {
        body: requestBody,
      });
    },
  );

  // 2. Authenticate as member user and attempt to list admin users.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const member: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(member);

  await TestValidator.error(
    "memberUser access to adminUsers.index must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.index(connection, {
        body: requestBody,
      });
    },
  );

  // 3. Authenticate as admin user and successfully list admin users.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  const page: IPageITodoAppAdminuser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  const pagination = page.pagination;
  TestValidator.predicate(
    "current page index must be non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate("limit must be non-negative", pagination.limit >= 0);
  TestValidator.predicate(
    "records must be non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate("pages must be non-negative", pagination.pages >= 0);

  TestValidator.predicate(
    "data must be an array (already ensured by typia, but check length semantics)",
    Array.isArray(page.data) && page.data.length <= pagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * End-to-end integration test for admin user listing in the presence of
 * existing member todos.
 *
 * Business context:
 *
 * - The system supports two authorization actors: memberUser and adminUser.
 * - Member users own todos (todo_app_todos), while admin users supervise and
 *   manage the system using their own accounts in todo_app_adminusers.
 * - The admin listing endpoint must work correctly regardless of how many member
 *   users or todos exist. Its response must be scoped strictly to admin
 *   accounts and never intermingle todo records.
 *
 * Scenario steps:
 *
 * 1. Register a member user (POST /auth/memberUser/join), which also authenticates
 *    that user and attaches their token to the connection.
 * 2. As the member user, create at least one todo (POST /todoApp/memberUser/todos)
 *    using ITodoAppTodo.ICreate.
 * 3. Register an admin user (POST /auth/adminUser/join); this also authenticates
 *    the admin and sets the admin token into the connection.
 * 4. Call the admin user index endpoint (PATCH /todoApp/adminUser/adminUsers) with
 *    a simple ITodoAppAdminUser.IRequest where page = 0 and limit = 10 and no
 *    additional filters.
 * 5. Validate that a page of admin user summaries is returned, that pagination
 *    metadata is coherent, and that the newly created admin appears in the data
 *    array.
 * 6. Implicitly confirm that the previously created member todos have no impact on
 *    the admin listing response by ensuring all records are
 *    ITodoAppAdminUser.ISummary objects and that no todo-specific fields are
 *    present.
 */
export async function test_api_admin_user_index_integration_with_member_todos_context(
  connection: api.IConnection,
) {
  // 1. Register a member user and obtain authenticated context
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/member/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Create a todo for the member user to ensure there is domain data
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // basic sanity check that the todo belongs to the joined member user
  TestValidator.equals(
    "created todo belongs to member user",
    createdTodo.memberUser.id,
    memberAuthorized.id,
  );

  // 3. Register an admin user and obtain authenticated context
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 4. Call admin user index with simple pagination request
  const requestBody = {
    page: 0,
    limit: 10,
    keyword: null,
    status: null,
    created_from: null,
    created_to: null,
    order_by: null,
    order_direction: null,
  } satisfies ITodoAppAdminUser.IRequest;

  const page: IPageITodoAppAdminuser.ISummary =
    await api.functional.todoApp.adminUser.adminUsers.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  // 5. Validate pagination meta-information
  const pagination: IPage.IPagination = page.pagination;
  typia.assert(pagination);

  TestValidator.equals(
    "admin listing current page should be 0",
    requestBody.page ?? 0,
    pagination.current,
  );

  TestValidator.equals(
    "admin listing limit should match request",
    requestBody.limit ?? 10,
    pagination.limit,
  );

  TestValidator.predicate(
    "admin listing records count is non-negative",
    pagination.records >= 0,
  );

  TestValidator.predicate(
    "admin listing pages count is non-negative",
    pagination.pages >= 0,
  );

  // 6. Validate that at least one admin user is present and that
  // the newly created admin appears in the result set.
  TestValidator.predicate(
    "admin listing contains at least one admin user",
    page.data.length >= 1,
  );

  const matched = page.data.some((summary) => {
    typia.assert(summary);
    return (
      summary.id === adminAuthorized.id ||
      summary.email === adminAuthorized.email
    );
  });

  TestValidator.predicate(
    "admin listing includes the newly created admin user",
    matched,
  );

  // 7. Implicit structural independence check: ensure that returned
  // items look like admin summaries, not todos. Since typia.assert has
  // already validated the type, we only need some light sanity checks
  // on representative fields.
  for (const adminSummary of page.data) {
    typia.assert<ITodoAppAdminUser.ISummary>(adminSummary);

    TestValidator.predicate(
      "admin summary has non-empty email",
      adminSummary.email.length > 0,
    );

    // status is a generic string; just confirm it's present
    TestValidator.predicate(
      "admin summary has status field",
      typeof adminSummary.status === "string",
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

export async function test_api_admin_user_detail_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register Admin A using /auth/adminUser/join to obtain authorized context
  const joinBody = typia.random<ITodoAppAdminUser.IJoin>();

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
