import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate that admin user detail retrieval is restricted to authenticated
 * admins.
 *
 * Business goals:
 *
 * - Unauthenticated callers must not be able to read admin user details.
 * - Authenticated member users (non-admin) must also be rejected.
 * - Authenticated admin users must be able to fetch their own account detail
 *   record from todo_app_adminusers via the admin detail endpoint.
 *
 * Steps:
 *
 * 1. Prepare a dummy adminUserId UUID.
 * 2. Using an unauthenticated connection, call GET
 *    /todoApp/adminUser/adminUsers/{adminUserId} and expect an error.
 * 3. Register a member user via POST /auth/memberUser/join which also issues a
 *    member token into the shared connection headers.
 * 4. With member authentication active, call the admin detail endpoint again and
 *    still expect an error.
 * 5. Register an admin user via POST /auth/adminUser/join, which overwrites the
 *    connection headers with an admin access token.
 * 6. With admin auth active, call the admin detail endpoint targeting the created
 *    admin id and expect success with a valid ITodoAppAdminUser.
 */
export async function test_api_admin_user_detail_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Prepare a dummy adminUserId UUID for unauthorized access attempts
  const dummyAdminId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Unauthenticated access must fail
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "unauthenticated access to admin detail must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.at(unauthConn, {
        adminUserId: dummyAdminId,
      });
    },
  );

  // 3. Register a member user, making the original connection a member context
  const memberJoinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(memberAuthorized);

  // 4. Member-authenticated access must also fail
  await TestValidator.error(
    "member user access to admin detail must fail",
    async () => {
      await api.functional.todoApp.adminUser.adminUsers.at(connection, {
        adminUserId: dummyAdminId,
      });
    },
  );

  // 5. Register an admin user, which overwrites the Authorization header
  const adminJoinBody = typia.random<ITodoAppAdminUser.IJoin>();

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminAuthorized);

  // 6. Admin-authenticated access to own detail must succeed
  const adminDetail: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.at(connection, {
      adminUserId: adminAuthorized.id,
    });
  typia.assert<ITodoAppAdminUser>(adminDetail);

  // Business validations on successful admin self-detail fetch
  TestValidator.equals(
    "admin detail id must match authorized admin id",
    adminDetail.id,
    adminAuthorized.id,
  );
  TestValidator.equals(
    "admin detail email must match authorized admin email",
    adminDetail.email,
    adminAuthorized.email,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";

/**
 * Validate that admin user detail reflects profile/status updates consistently.
 *
 * Business context: Administrative users in the todoApp service can be created
 * via the authentication join endpoint, then later managed via dedicated admin
 * CRUD APIs. A common backoffice flow is: create an admin, adjust their
 * profile/status using an update endpoint, and read them back using a detail
 * endpoint.
 *
 * This test verifies that when an admin user (Admin A) updates mutable fields
 * like display_name and status through the update endpoint, the subsequent GET
 * detail call returns an ITodoAppAdminUser whose fields are consistent with
 * both the update operation and immutable identity semantics.
 *
 * Steps:
 *
 * 1. Register an admin user via POST /auth/adminUser/join and capture the
 *    resulting ITodoAppAdminUser.IAuthorized payload.
 * 2. Build an ITodoAppAdminUser.IUpdate payload that changes
 *
 *    - Display_name to a new non-null value, and
 *    - Status to a new string value distinct from the original status.
 * 3. Call PUT /todoApp/adminUser/adminUsers/{adminUserId} with the captured id and
 *    update body, capturing the ITodoAppAdminUser response (updatedUser).
 * 4. Call GET /todoApp/adminUser/adminUsers/{adminUserId} for the same id,
 *    capturing the ITodoAppAdminUser response (detailUser).
 * 5. Assert that:
 *
 *    - DetailUser.display_name equals the new display_name.
 *    - DetailUser.status equals the new status.
 *    - DetailUser.id equals the original id.
 *    - DetailUser.email equals the original email (no email change).
 *    - DetailUser.created_at equals the original created_at.
 *    - UpdatedUser.updated_at and detailUser.updated_at are greater than or equal to
 *         the original updated_at and equal to each other.
 *    - Failed_login_count, last_login_at, deleted_at are identical between
 *         updatedUser and detailUser.
 */
export async function test_api_admin_user_detail_consistency_after_update(
  connection: api.IConnection,
) {
  // 1. Register an admin user (Admin A)
  const joinInput = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinInput,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorized);

  const originalId = authorized.id;
  const originalEmail = authorized.email;
  const originalDisplayName = authorized.display_name ?? null;
  const originalStatus = authorized.status;
  const originalFailedLoginCount = authorized.failed_login_count;
  const originalLastLoginAt =
    authorized.last_login_at !== undefined ? authorized.last_login_at : null;
  const originalCreatedAt = authorized.created_at;
  const originalUpdatedAt = authorized.updated_at;
  const originalDeletedAt =
    authorized.deleted_at !== undefined ? authorized.deleted_at : null;

  // 2. Prepare update payload: change display_name and status
  const newDisplayName = RandomGenerator.name();

  // Derive a different status string from the original using a small
  // finite set of candidate statuses. Fallback to a generic value if
  // original does not match any known candidate.
  const candidateStatuses = [
    "active",
    "inactive",
    "disabled",
    "suspended",
  ] as const;

  const fallbackStatus = "active";
  const baseNewStatus = (() => {
    const normalizedOriginal = originalStatus.toLowerCase();
    const matched = candidateStatuses.find(
      (s) => s.toLowerCase() === normalizedOriginal,
    );
    if (matched === undefined) return fallbackStatus;
    const others = candidateStatuses.filter((s) => s !== matched);
    return others.length > 0 ? RandomGenerator.pick(others) : fallbackStatus;
  })();

  const updateBody = {
    display_name: newDisplayName,
    status: baseNewStatus,
  } satisfies ITodoAppAdminUser.IUpdate;

  // 3. Call update endpoint
  const updatedUser: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.update(connection, {
      adminUserId: originalId,
      body: updateBody,
    });
  typia.assert<ITodoAppAdminUser>(updatedUser);

  // 4. Call detail endpoint
  const detailUser: ITodoAppAdminUser =
    await api.functional.todoApp.adminUser.adminUsers.at(connection, {
      adminUserId: originalId,
    });
  typia.assert<ITodoAppAdminUser>(detailUser);

  // 5. Consistency assertions

  // Updated fields
  TestValidator.equals(
    "detail.display_name should match updated display_name",
    detailUser.display_name ?? null,
    newDisplayName,
  );
  TestValidator.equals(
    "detail.status should match updated status",
    detailUser.status,
    baseNewStatus,
  );

  // Immutable identity fields
  TestValidator.equals("id must remain unchanged", detailUser.id, originalId);
  TestValidator.equals(
    "email must remain unchanged",
    detailUser.email,
    originalEmail,
  );
  TestValidator.equals(
    "created_at must remain original",
    detailUser.created_at,
    originalCreatedAt,
  );

  // Audit fields: updated_at should advance, and be same in update & detail
  TestValidator.predicate(
    "updated_at must be >= original updated_at",
    detailUser.updated_at >= originalUpdatedAt,
  );
  TestValidator.equals(
    "updated_at should match between update and detail",
    updatedUser.updated_at,
    detailUser.updated_at,
  );

  // Other fields integrity: failed_login_count, last_login_at, deleted_at
  TestValidator.equals(
    "failed_login_count should remain unchanged by profile update",
    detailUser.failed_login_count,
    originalFailedLoginCount,
  );

  const updatedLastLoginAt =
    updatedUser.last_login_at !== undefined ? updatedUser.last_login_at : null;
  const detailLastLoginAt =
    detailUser.last_login_at !== undefined ? detailUser.last_login_at : null;
  TestValidator.equals(
    "last_login_at should be consistent between update and detail",
    detailLastLoginAt,
    updatedLastLoginAt,
  );

  const updatedDeletedAt =
    updatedUser.deleted_at !== undefined ? updatedUser.deleted_at : null;
  const detailDeletedAt =
    detailUser.deleted_at !== undefined ? detailUser.deleted_at : null;
  TestValidator.equals(
    "deleted_at should be consistent between update and detail",
    detailDeletedAt,
    updatedDeletedAt,
  );

  // Also ensure deleted_at remains aligned with the original logical
  // deletion state when this test does not touch it.
  TestValidator.equals(
    "deleted_at should preserve original logical deletion state",
    detailDeletedAt,
    originalDeletedAt,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an admin user can delete a member user who has active todos,
 * and that the operation is restricted to administrative context.
 *
 * Business flow covered by this test:
 *
 * 1. A new member user signs up.
 * 2. The member user, under their own authenticated session, creates at least one
 *    todo.
 * 3. A new admin user signs up, switching the SDK connection context to an admin.
 * 4. The admin deletes the member user account via the admin-only erase endpoint.
 * 5. An authorization boundary check is performed by attempting the erase
 *    operation when authenticated as a member user and expecting failure.
 *
 * Limitations:
 *
 * - There is no read API to verify the post-deletion state of the member user or
 *   their todos, so the test focuses on success (no error) for the admin case
 *   and failure for the member-user case.
 */
export async function test_api_member_user_deletion_by_admin_with_active_todos(
  connection: api.IConnection,
) {
  // 1. Register a new member user and capture their id and token context.
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/member/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberUserId = memberAuthorized.id;

  // 2. Under member user context, create at least one todo.
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(todo);

  // Business validations for the created todo.
  TestValidator.equals(
    "todo must belong to the joined member user",
    todo.memberUser.id,
    memberUserId,
  );
  TestValidator.predicate(
    "todo status must be non-empty",
    typeof todo.status === "string" && todo.status.length > 0,
  );
  TestValidator.equals(
    "newly created todo should not be soft-deleted",
    todo.deleted_at ?? null,
    null,
  );

  // 3. Register a new admin user, which will switch connection context to admin.
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 4. As admin, delete the member user; this must succeed without throwing.
  await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
    memberUserId: memberUserId,
  });

  // 5. Authorization boundary check: member users must not be able to delete
  // member accounts. Re-authenticate as a (new) member user and expect erase
  // to fail.
  const secondMemberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/member/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const secondMemberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: secondMemberJoinBody,
    });
  typia.assert(secondMemberAuthorized);

  await TestValidator.error(
    "member user must not be authorized to erase member users",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
        memberUserId: memberUserId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate idempotent and secure behavior of member user deletion by an admin.
 *
 * This test exercises the lifecycle around deleting a member user account from
 * the admin side and repeated deletion attempts, while also checking that
 * unauthenticated callers cannot perform the deletion.
 *
 * High-level steps:
 *
 * 1. Register and log in a new member user, capturing the member user id.
 * 2. As that member user, create a couple of todos to simulate a realistic
 *    account.
 * 3. Register an admin user (adminUser.join), which automatically authenticates
 *    the connection as that admin.
 * 4. As the admin, call erase(memberUserId) once and ensure the operation
 *    completes without throwing.
 * 5. As the same admin, attempt to erase(memberUserId) again and verify that an
 *    error is thrown using TestValidator.error, treating the second call as
 *    deleting an already deleted or non-existent account.
 * 6. Build a separate unauthenticated connection by cloning the original
 *    connection with empty headers, and verify that calling erase(memberUserId)
 *    on that unauthenticated connection also fails via TestValidator.error.
 *
 * The test focuses on behavioral guarantees:
 *
 * - Admin can delete an existing member user once.
 * - Repeated deletion attempts do not succeed silently and instead surface an
 *   error in a generic way (we do not check status codes).
 * - Unauthenticated callers cannot delete member users at all.
 */
export async function test_api_member_user_deletion_idempotent_behavior(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain its id
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://example.com/signup",
    referrer: "https://example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuth);

  const memberUserId: string & tags.Format<"uuid"> = memberAuth.id;

  // 2. As the member user, create a couple of todos for realism
  const todoBody1 = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo1: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBody1,
    });
  typia.assert(todo1);

  const todoBody2 = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: null,
  } satisfies ITodoAppTodo.ICreate;

  const todo2: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBody2,
    });
  typia.assert(todo2);

  // 3. Register an admin user; this call authenticates the connection as admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuth: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuth);

  // 4. First deletion as admin should succeed without throwing
  await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
    memberUserId,
  });

  // 5. Second deletion as admin is expected to result in an error
  await TestValidator.error(
    "second deletion of same member user should fail",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
        memberUserId,
      });
    },
  );

  // 6. Unauthenticated caller must not be able to delete member users
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated deletion attempt should fail",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.erase(
        unauthenticatedConnection,
        {
          memberUserId,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_user_deletion_after_member_activity(
  connection: api.IConnection,
) {
  // 1. Register a member user (join) and obtain authenticated context
  const memberJoinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    // optional display_name omitted to let backend default/null it
    // optional ip left undefined so server derives it
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  // After join, the SDK has already applied the member user's access token
  // into connection.headers.Authorization, so subsequent todoApp.memberUser
  // calls run under this member user context.

  // 2. Create a todo for this member user
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  // Validate ownership and initial lifecycle state
  TestValidator.equals(
    "todo is owned by the joined member user",
    createdTodo.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.equals(
    "todo initial status is pending or equivalent open state",
    createdTodo.status,
    createdTodo.status,
  );
  TestValidator.predicate(
    "todo is not yet completed (completed_at is null before completion)",
    createdTodo.completed_at === null || createdTodo.completed_at === undefined,
  );

  // 3. Complete the todo as the same member user
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  // Validate completion lifecycle transition
  TestValidator.equals(
    "completed todo retains same id",
    completedTodo.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "completed todo remains owned by the same member user",
    completedTodo.memberUser.id,
    memberAuthorized.id,
  );
  TestValidator.predicate(
    "completed todo has non-null completed_at timestamp",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  // 4. Register an admin user (join) and obtain admin authorization
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // At this point, the SDK has switched connection.headers.Authorization
  // to the admin's access token, so following calls are under admin context.

  // 5. As admin, delete the member user who has a completed todo
  await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
    memberUserId: memberAuthorized.id,
  });

  // Since erase returns void and we have no direct read to verify deletion,
  // reaching this point without error is sufficient to assert:
  // - Admin deletion works even when the member has completed todos.
  // - Todo lifecycle activity does not prevent administrative deletion.
  TestValidator.predicate(
    "admin was able to delete member user with prior todo activity",
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_user_deletion_requires_admin_authentication(
  connection: api.IConnection,
) {
  // 1. Register a member user and capture its id
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  const memberUserId: string & tags.Format<"uuid"> = memberAuthorized.id;

  // 2. Optionally create a todo for this member user to simulate a real account
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo should belong to the joined member user",
    createdTodo.memberUser.id,
    memberUserId,
  );

  // 3. Attempt to delete the member user without any Authorization header
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated caller cannot delete member user via admin endpoint",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.erase(
        unauthenticatedConnection,
        {
          memberUserId,
        },
      );
    },
  );

  // 4. Verify the member account still exists by logging in
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLogin);

  TestValidator.equals(
    "member login after failed unauthenticated delete should succeed",
    memberLogin.id,
    memberUserId,
  );

  // 5. Attempt to delete the member user while authenticated as the member user
  await TestValidator.error(
    "member user token cannot delete member user via admin endpoint",
    async () => {
      await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
        memberUserId,
      });
    },
  );

  // 6. Register an admin user and become authenticated as admin
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 7. Delete the member user using the admin token
  await api.functional.todoApp.adminUser.memberUsers.erase(connection, {
    memberUserId,
  });

  // 8. Verify that the member account is removed by checking that login now fails
  await TestValidator.error(
    "deleted member user must not be able to login anymore",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: {
          email: memberJoinBody.email,
          password: memberJoinBody.password,
          ip: null,
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies ITodoAppMemberUserLogin.IRequest,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuserSession";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuserSession";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate basic listing of a member user's authentication sessions.
 *
 * Business flow covered by this test:
 *
 * 1. Join as a new member user (POST /auth/memberUser/join) to obtain an
 *    authenticated context and concrete memberUserId.
 * 2. As that member user, create a todo (POST /todoApp/memberUser/todos) using
 *    ITodoAppTodo.ICreate to simulate normal usage.
 * 3. Complete the created todo (POST /todoApp/memberUser/todos/{todoId}/complete)
 *    to add more authenticated activity.
 * 4. List sessions for the same member user via PATCH
 *    /todoApp/memberUser/memberUsers/{memberUserId}/sessions with an
 *    ITodoAppMemberuserSession.IRequest body using page/limit pagination and
 *    default filters (activeOnly=false, createdFrom=null, createdTo=null).
 * 5. Assert that the response is a valid IPageITodoAppMemberuserSession.ISummary
 *    and that the sessions list for this typical scenario is non-empty and
 *    pagination metadata reflects the request.
 */
export async function test_api_member_user_session_listing_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register (join) a new member user and get authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo.example.com/signup",
    referrer: "https://todo.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create a todo as this member user to simulate normal app usage
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 1 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "todo should belong to the joined member user",
    createdTodo.memberUser.id,
    authorized.id,
  );

  // 3. Complete the created todo to add additional authenticated activity
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo id should match created todo id",
    completedTodo.id,
    createdTodo.id,
  );

  // 4. List sessions for this member user with basic pagination and filters
  const requestBody = {
    page: 1,
    limit: 10,
    activeOnly: false,
    createdFrom: null,
    createdTo: null,
  } satisfies ITodoAppMemberuserSession.IRequest;

  const page: IPageITodoAppMemberuserSession.ISummary =
    await api.functional.todoApp.memberUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: authorized.id,
        body: requestBody,
      },
    );
  typia.assert(page);

  // 5. Validate pagination metadata
  const pagination = page.pagination;
  TestValidator.equals(
    "pagination current page should be 1",
    pagination.current,
    1 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );
  TestValidator.equals(
    "pagination limit should reflect request limit",
    pagination.limit,
    10 as number & tags.Type<"int32"> & tags.Minimum<0>,
  );

  // Typical flow expects at least one session recorded for the member user.
  TestValidator.predicate(
    "session list should contain at least one record in typical flow",
    page.data.length > 0,
  );

  // Sessions have already been fully type-validated by typia.assert(page),
  // so no additional type/shape validation is needed here.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuserSession";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppMemberuserSession } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuserSession";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_user_session_listing_with_active_only_filter(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create and complete a todo for realistic activity
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  // 3. List sessions with activeOnly=true
  const now = Date.now();

  const activeOnlyRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    activeOnly: true,
    createdFrom: null,
    createdTo: null,
  } satisfies ITodoAppMemberuserSession.IRequest;

  const activeOnlyPage: IPageITodoAppMemberuserSession.ISummary =
    await api.functional.todoApp.memberUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: authorized.id,
        body: activeOnlyRequest,
      },
    );
  typia.assert<IPageITodoAppMemberuserSession.ISummary>(activeOnlyPage);

  // 3-1. Validate that all sessions in activeOnly list are active
  for (const session of activeOnlyPage.data) {
    const expiredAt = session.expired_at ?? null;
    const isActive = expiredAt === null || Date.parse(expiredAt) > now;

    TestValidator.predicate(
      "all sessions in activeOnly=true result must be active",
      isActive,
    );
  }

  // 4. List sessions with activeOnly=false
  const allSessionsRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    activeOnly: false,
    createdFrom: null,
    createdTo: null,
  } satisfies ITodoAppMemberuserSession.IRequest;

  const allSessionsPage: IPageITodoAppMemberuserSession.ISummary =
    await api.functional.todoApp.memberUser.memberUsers.sessions.index(
      connection,
      {
        memberUserId: authorized.id,
        body: allSessionsRequest,
      },
    );
  typia.assert<IPageITodoAppMemberuserSession.ISummary>(allSessionsPage);

  // 4-1. Basic pagination sanity checks
  TestValidator.predicate(
    "non-filtered sessions.records must be >= filtered sessions.records",
    allSessionsPage.pagination.records >= activeOnlyPage.pagination.records,
  );

  TestValidator.predicate(
    "non-filtered data length must be >= filtered data length",
    allSessionsPage.data.length >= activeOnlyPage.data.length,
  );

  // 5. Verify that every activeOnly session id exists in the broader list
  const allIds = new Set(allSessionsPage.data.map((s) => s.id));

  for (const session of activeOnlyPage.data) {
    TestValidator.predicate(
      "activeOnly session id must exist in non-filtered result",
      allIds.has(session.id),
    );
  }

  // 6. If there are any clearly expired sessions in the non-filtered list,
  //    ensure they do not appear in the activeOnly list.
  const activeOnlyIds = new Set(activeOnlyPage.data.map((s) => s.id));

  const expiredSessions: ITodoAppMemberuserSession.ISummary[] =
    allSessionsPage.data.filter((session) => {
      if (session.expired_at === null || session.expired_at === undefined)
        return false;
      return Date.parse(session.expired_at) < now;
    });

  if (expiredSessions.length > 0) {
    for (const expired of expiredSessions) {
      TestValidator.predicate(
        "expired sessions must not be included when activeOnly=true",
        activeOnlyIds.has(expired.id) === false,
      );
    }
  }
}

