  // 4. User B creates its own todos, including ones with the same shared keyword
  const userBKeywordTodos: ITodoAppTodo[] = [];
  const userBOtherTodos: ITodoAppTodo[] = [];

  const userBTodoTitlesWithKeyword: string[] = [
    `${sharedKeyword} task B1`,
    `${sharedKeyword} task B2`,
  ];
  const userBTodoTitlesWithoutKeyword: string[] = [
    "unique B task 1",
    "unique B task 2",
  ];

  for (const title of userBTodoTitlesWithKeyword) {
    const todoCreateBody = {
      title,
      description: RandomGenerator.paragraph({ sentences: 2 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert<ITodoAppTodo>(todo);
    userBKeywordTodos.push(todo);
  }

  for (const title of userBTodoTitlesWithoutKeyword) {
    const todoCreateBody = {
      title,
      description: RandomGenerator.paragraph({ sentences: 2 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert<ITodoAppTodo>(todo);
    userBOtherTodos.push(todo);
  }

  const totalUserBTodos = [...userBKeywordTodos, ...userBOtherTodos];

  // 5. As User B, perform a wide-open search using the shared keyword
  const searchRequestBody = {
    status: null,
    createdFrom: null,
    createdTo: null,
    completed: null,
    search: sharedKeyword,
    page: 1,
    limit: 20,
    orderBy: null,
    orderDirection: null,
  } satisfies ITodoAppTodo.IRequest;

  const searchResult: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.memberUser.todos.index(connection, {
      body: searchRequestBody,
    });
  typia.assert<IPageITodoAppTodo.ISummary>(searchResult);

  const { pagination, data } = searchResult;

  // 6. Assert that all returned todos belong to User B and none to User A
  TestValidator.equals(
    "records should equal data length",
    data.length,
    pagination.records,
  );

  for (const summary of data) {
    // every todo in the result must belong to User B
    TestValidator.equals(
      "each result todo belongs to User B",
      summary.memberUser.id,
      userB.id,
    );

    // ensure no todo from User A is present
    TestValidator.notEquals(
      "no result todo belongs to User A",
      summary.memberUser.id,
      userA.id,
    );
  }

  // 7. Verify that at least all of User B's keyword todos are present in results
  const userBKeywordTodoIds = new Set(userBKeywordTodos.map((todo) => todo.id));

  const resultIds = new Set(data.map((summary) => summary.id));

  for (const id of userBKeywordTodoIds) {
    TestValidator.predicate(
      "all User B keyword todos should appear in search results",
      resultIds.has(id),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify pagination boundary behavior of member user's todo search.
 *
 * Business flow:
 *
 * 1. Join a new member user (POST /auth/memberUser/join), which also authenticates
 *    the connection.
 * 2. Create exactly 15 todos for that member (POST /todoApp/memberUser/todos).
 * 3. Search todos with PATCH /todoApp/memberUser/todos using page/limit only and
 *    validate:
 *
 *    - Page 1 (page=1, limit=10): 10 items, records=15, pages=2
 *    - Page 2 (page=2, limit=10): 5 items, records=15, pages=2
 *    - Page 3 (page=3, limit=10): 0 items, records=15, pages=2, current=3
 * 4. For non-empty pages, all todos must belong to the joined member user.
 */
export async function test_api_member_todo_search_pagination_boundaries(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new member user
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const member: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(member);

  // 2. Create exactly 15 todos for this member user
  const createdTodos: ITodoAppTodo[] = await ArrayUtil.asyncRepeat(
    15,
    async () => {
      const todoBody = {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 6 }),
      } satisfies ITodoAppTodo.ICreate;

      const todo: ITodoAppTodo =
        await api.functional.todoApp.memberUser.todos.create(connection, {
          body: todoBody,
        });
      typia.assert(todo);

      // Ensure ownership matches authenticated member
      TestValidator.equals(
        "created todo must belong to joined member user",
        todo.memberUser.id,
        member.id,
      );

      return todo;
    },
  );

  TestValidator.equals(
    "exactly 15 todos should be created for this test",
    createdTodos.length,
    15,
  );

  // Helper to assert pagination metadata
  const assertPagination = (
    title: string,
    pagination: IPage.IPagination,
    expectedCurrent: number,
    expectedLimit: number,
    expectedRecords: number,
    expectedPages: number,
  ): void => {
    TestValidator.equals(
      `${title} - current page`,
      pagination.current,
      expectedCurrent,
    );
    TestValidator.equals(
      `${title} - page limit`,
      pagination.limit,
      expectedLimit,
    );
    TestValidator.equals(
      `${title} - total records`,
      pagination.records,
      expectedRecords,
    );
    TestValidator.equals(
      `${title} - total pages`,
      pagination.pages,
      expectedPages,
    );
  };

  // Helper to assert that all todos in a page belong to current member
  const assertOwnership = (
    title: string,
    data: IPageITodoAppTodo.ISummary["data"],
    memberId: ITodoAppMemberuser.IAuthorized["id"],
  ): void => {
    for (const summary of data) {
      TestValidator.equals(
        `${title} - todo owner must be joined member user`,
        summary.memberUser.id,
        memberId,
      );
    }
  };

  // 3. Page 1, limit 10
  const page1Body = {
    status: null,
    createdFrom: null,
    createdTo: null,
    completed: null,
    search: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: null,
    orderDirection: null,
  } satisfies ITodoAppTodo.IRequest;

  const page1: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.memberUser.todos.index(connection, {
      body: page1Body,
    });
  typia.assert(page1);

  TestValidator.equals("page 1 should return 10 todos", page1.data.length, 10);
  assertPagination("page 1", page1.pagination, 1, 10, 15, 2);
  assertOwnership("page 1", page1.data, member.id);

  // 4. Page 2, limit 10
  const page2Body = {
    status: null,
    createdFrom: null,
    createdTo: null,
    completed: null,
    search: null,
    page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: null,
    orderDirection: null,
  } satisfies ITodoAppTodo.IRequest;

  const page2: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.memberUser.todos.index(connection, {
      body: page2Body,
    });
  typia.assert(page2);

  TestValidator.equals(
    "page 2 should return remaining 5 todos",
    page2.data.length,
    5,
  );
  assertPagination("page 2", page2.pagination, 2, 10, 15, 2);
  assertOwnership("page 2", page2.data, member.id);

  // 5. Page 3, limit 10 (beyond last page)
  const page3Body = {
    status: null,
    createdFrom: null,
    createdTo: null,
    completed: null,
    search: null,
    page: 3 as number & tags.Type<"int32"> & tags.Minimum<1>,
    limit: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    orderBy: null,
    orderDirection: null,
  } satisfies ITodoAppTodo.IRequest;

  const page3: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.memberUser.todos.index(connection, {
      body: page3Body,
    });
  typia.assert(page3);

  TestValidator.equals(
    "page 3 should return empty data array when beyond last page",
    page3.data.length,
    0,
  );
  assertPagination("page 3", page3.pagination, 3, 10, 15, 2);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_todo_detail_retrieval_own_item(
  connection: api.IConnection,
) {
  // 1. Register a new member user (join) to obtain an authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a todo for this member user with deterministic content
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // Basic invariants on created todo
  TestValidator.equals(
    "created todo title matches request body",
    createdTodo.title,
    todoCreateBody.title,
  );
  TestValidator.equals(
    "created todo description matches request body",
    createdTodo.description ?? null,
    todoCreateBody.description ?? null,
  );

  // The memberUser in the todo should correspond to the authorized member user
  TestValidator.equals(
    "todo memberUser.id matches authorized member id",
    createdTodo.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "todo memberUser.email matches authorized member email",
    createdTodo.memberUser.email,
    authorized.email,
  );

  // 3. Retrieve the same todo by id via GET /todoApp/memberUser/todos/{todoId}
  const fetchedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(fetchedTodo);

  // 4. Validate that fetched todo details match the created todo
  TestValidator.equals(
    "fetched todo id matches created todo id",
    fetchedTodo.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "fetched todo title matches created title",
    fetchedTodo.title,
    createdTodo.title,
  );
  TestValidator.equals(
    "fetched todo description matches created description",
    fetchedTodo.description ?? null,
    createdTodo.description ?? null,
  );
  TestValidator.equals(
    "fetched todo status matches created status",
    fetchedTodo.status,
    createdTodo.status,
  );
  TestValidator.equals(
    "fetched todo created_at matches created created_at",
    fetchedTodo.created_at,
    createdTodo.created_at,
  );
  TestValidator.equals(
    "fetched todo updated_at matches created updated_at",
    fetchedTodo.updated_at,
    createdTodo.updated_at,
  );
  TestValidator.equals(
    "fetched todo completed_at matches created completed_at",
    fetchedTodo.completed_at ?? null,
    createdTodo.completed_at ?? null,
  );
  TestValidator.equals(
    "fetched todo deleted_at matches created deleted_at",
    fetchedTodo.deleted_at ?? null,
    createdTodo.deleted_at ?? null,
  );

  // 5. Validate that memberUser summary in fetched todo matches authorized user
  TestValidator.equals(
    "fetched todo memberUser.id matches authorized id",
    fetchedTodo.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "fetched todo memberUser.email matches authorized email",
    fetchedTodo.memberUser.email,
    authorized.email,
  );

  // 6. Basic temporal invariant: created_at should be <= updated_at
  await TestValidator.predicate(
    "todo updated_at is not earlier than created_at",
    async () =>
      new Date(fetchedTodo.updated_at).getTime() >=
      new Date(fetchedTodo.created_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_todo_detail_after_update(
  connection: api.IConnection,
) {
  // 1. Register a new member user to establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create an initial todo for this member user
  const initialTitle = RandomGenerator.paragraph({ sentences: 3 });
  const initialDescription = RandomGenerator.paragraph({ sentences: 5 });

  const createBody = {
    title: initialTitle,
    description: initialDescription,
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // 3. Update the todo's title and description while keeping lifecycle unchanged
  const updatedTitle = RandomGenerator.paragraph({ sentences: 2 });
  const updatedDescription = RandomGenerator.paragraph({ sentences: 4 });

  const updateBody = {
    title: updatedTitle,
    description: updatedDescription,
  } satisfies ITodoAppTodo.IUpdate;

  const updated: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.update(connection, {
      todoId: created.id,
      body: updateBody,
    });
  typia.assert<ITodoAppTodo>(updated);

  // 4. Fetch the todo detail after the update
  const detail: ITodoAppTodo = await api.functional.todoApp.memberUser.todos.at(
    connection,
    {
      todoId: created.id,
    },
  );
  typia.assert<ITodoAppTodo>(detail);

  // 5. Validate identity and ownership consistency
  TestValidator.equals(
    "todo id should remain the same across create, update, and detail",
    detail.id,
    created.id,
  );
  TestValidator.equals(
    "todo id after update should match detail id",
    detail.id,
    updated.id,
  );

  TestValidator.equals(
    "member user id in todo should match authorized user id",
    detail.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "member user email in todo should match authorized user email",
    detail.memberUser.email,
    authorized.email,
  );

  // 6. Validate title/description changes and that they reflect the latest values
  TestValidator.equals(
    "detail title should match updated title",
    detail.title,
    updatedTitle,
  );
  TestValidator.equals(
    "detail description should match updated description",
    detail.description,
    updatedDescription,
  );

  TestValidator.notEquals(
    "title should have changed from initial value",
    detail.title,
    initialTitle,
  );
  TestValidator.notEquals(
    "description should have changed from initial value",
    detail.description,
    initialDescription,
  );

  // 7. Validate lifecycle fields: status, completed_at, created_at, updated_at
  TestValidator.equals(
    "status should remain consistent between update and detail",
    detail.status,
    updated.status,
  );

  TestValidator.equals(
    "created_at should remain the same between create and detail",
    detail.created_at,
    created.created_at,
  );

  // updated_at from update should be >= created.updated_at and equal to detail.updated_at
  TestValidator.predicate(
    "updated_at should be greater than or equal to created.updated_at",
    new Date(updated.updated_at).getTime() >=
      new Date(created.updated_at).getTime(),
  );
  TestValidator.equals(
    "detail updated_at should match updated.updated_at",
    detail.updated_at,
    updated.updated_at,
  );

  // completed_at should remain unchanged (likely null) if status was not changed
  TestValidator.equals(
    "completed_at should remain unchanged between create and detail when not completed",
    detail.completed_at ?? null,
    created.completed_at ?? null,
  );

  // deleted_at should remain unchanged (likely null) across create, update, and detail
  TestValidator.equals(
    "deleted_at should remain unchanged between create and update",
    updated.deleted_at ?? null,
    created.deleted_at ?? null,
  );
  TestValidator.equals(
    "deleted_at should remain unchanged between create and detail",
    detail.deleted_at ?? null,
    created.deleted_at ?? null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_member_todo_detail_after_completion_and_reopen(
  connection: api.IConnection,
) {
  // 1. Register a new member user and establish authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    // optional display name for readability
    display_name: RandomGenerator.name(1),
    // ip is optional; provide null explicitly to let server infer if desired
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a new todo for this member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // Sanity checks on newly created todo
  TestValidator.equals(
    "created todo owner id should match authorized member user id",
    created.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "created todo owner email should match authorized member user email",
    created.memberUser.email,
    authorized.email,
  );
  TestValidator.equals(
    "new todo should start as pending",
    created.status,
    "pending",
  );
  TestValidator.equals(
    "new todo should have null completed_at",
    created.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "new todo should not be logically deleted",
    created.deleted_at ?? null,
    null,
  );

  // 3. Complete the todo
  const completed: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(completed);

  // 4. Fetch detail after completion
  const afterComplete: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(afterComplete);

  // Invariants after completion
  TestValidator.equals(
    "todo id should remain stable after completion (complete response vs created)",
    completed.id,
    created.id,
  );
  TestValidator.equals(
    "todo id should remain stable in detail after completion",
    afterComplete.id,
    created.id,
  );
  TestValidator.equals(
    "memberUser id should remain stable after completion",
    afterComplete.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "memberUser email should remain stable after completion",
    afterComplete.memberUser.email,
    authorized.email,
  );

  // Status and lifecycle timestamps after completion
  TestValidator.equals(
    "status should be completed after completion transition",
    completed.status,
    "completed",
  );
  TestValidator.equals(
    "status in detail should be completed after completion transition",
    afterComplete.status,
    "completed",
  );

  TestValidator.predicate(
    "completed_at should be non-null after completion",
    afterComplete.completed_at !== null &&
      afterComplete.completed_at !== undefined,
  );
  TestValidator.equals(
    "deleted_at should remain null after completion",
    afterComplete.deleted_at ?? null,
    null,
  );

  TestValidator.predicate(
    "updated_at should be on or after created_at after completion",
    () =>
      new Date(afterComplete.updated_at).getTime() >=
      new Date(created.updated_at).getTime(),
  );

  // 5. Reopen the todo
  const reopened: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(reopened);

  // 6. Fetch detail after reopen
  const afterReopen: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(afterReopen);

  // Invariants after reopen
  TestValidator.equals(
    "todo id should remain stable after reopen",
    afterReopen.id,
    created.id,
  );
  TestValidator.equals(
    "memberUser id should remain stable after reopen",
    afterReopen.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "memberUser email should remain stable after reopen",
    afterReopen.memberUser.email,
    authorized.email,
  );

  // Status and lifecycle timestamps after reopen
  TestValidator.equals(
    "status should revert to pending after reopen (reopen response)",
    reopened.status,
    "pending",
  );
  TestValidator.equals(
    "status in detail should be pending after reopen",
    afterReopen.status,
    "pending",
  );

  TestValidator.equals(
    "completed_at should be cleared (null) after reopen",
    afterReopen.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "deleted_at should still be null after reopen",
    afterReopen.deleted_at ?? null,
    null,
  );

  TestValidator.predicate(
    "updated_at after reopen should be on or after updated_at after completion",
    () =>
      new Date(afterReopen.updated_at).getTime() >=
      new Date(afterComplete.updated_at).getTime(),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure that a member user cannot retrieve another member's todo details.
 *
 * Business goal:
 *
 * - Validate the authorization/ownership boundary on the todo detail endpoint GET
 *   /todoApp/memberUser/todos/{todoId}.
 * - Even if an intruder somehow knows or guesses the UUID of another user's todo,
 *   the API must not return the ITodoAppTodo details to them.
 *
 * Test workflow:
 *
 * 1. Register an Owner member user via POST /auth/memberUser/join using the shared
 *    connection (SDK attaches Owner's access token to the connection).
 * 2. As Owner, create a todo via POST /todoApp/memberUser/todos and capture its
 *    id, verifying that the created todo is owned by the Owner.
 * 3. Register an Intruder member user via another POST /auth/memberUser/join on
 *    the same connection (Authorization header is switched to Intruder's
 *    token).
 * 4. While authenticated as the Intruder, call GET
 *    /todoApp/memberUser/todos/{todoId} using the Owner's todo id.
 * 5. Assert that this cross-user access attempt fails (throws an error) and
 *    therefore does not return an ITodoAppTodo instance to the Intruder.
 */
export async function test_api_member_todo_detail_not_found_for_other_users_item(
  connection: api.IConnection,
) {
  // 1. Register Owner (member user A)
  const ownerJoinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const ownerAuth = await api.functional.auth.memberUser.join(connection, {
    body: ownerJoinBody,
  });
  typia.assert<ITodoAppMemberuser.IAuthorized>(ownerAuth);

  const ownerId = ownerAuth.id;

  // 2. Create todo as Owner
  const createTodoBody = typia.random<ITodoAppTodo.ICreate>();
  const ownerTodo = await api.functional.todoApp.memberUser.todos.create(
    connection,
    {
      body: createTodoBody,
    },
  );
  typia.assert<ITodoAppTodo>(ownerTodo);

  // Sanity check: created todo is owned by Owner
  TestValidator.equals(
    "todo should belong to owner",
    ownerTodo.memberUser.id,
    ownerId,
  );

  const ownerTodoId = ownerTodo.id;

  // 3. Register Intruder (member user B) on the same connection
  const intruderJoinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const intruderAuth = await api.functional.auth.memberUser.join(connection, {
    body: intruderJoinBody,
  });
  typia.assert<ITodoAppMemberuser.IAuthorized>(intruderAuth);

  // 4. As Intruder, attempt to fetch Owner's todo detail
  await TestValidator.error(
    "intruder cannot access foreign member's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.at(connection, {
        todoId: ownerTodoId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Verify todo detail visibility behavior after deletion for a member user.
 *
 * Business context: A member user owns todo items stored in todo_app_todos.
 * When a todo is deleted via the member-facing DELETE endpoint, the system may
 * either logically delete (soft delete) by setting deleted_at or fully hide the
 * record from normal member queries. This test validates how the GET
 * /todoApp/memberUser/todos/{todoId} endpoint behaves after such a deletion
 * from the perspective of the owning member user.
 *
 * Steps:
 *
 * 1. Register a new member user via POST /auth/memberUser/join to obtain an
 *    authenticated context (token is wired into connection by the SDK).
 * 2. Create a new todo for that member via POST /todoApp/memberUser/todos using a
 *    simple, deterministic title/description payload.
 * 3. Delete the todo via DELETE /todoApp/memberUser/todos/{todoId}.
 * 4. Attempt to fetch the todo again via GET /todoApp/memberUser/todos/{todoId}
 *    and observe behavior:
 *
 *    - Either the call fails (any error), which implies deleted todos are hidden
 *         from the owner; or
 *    - The call succeeds and returns ITodoAppTodo with deleted_at non-null,
 *         indicating soft-deleted todos remain visible but marked as deleted.
 * 5. Assert core invariants like id stability, ownership, and type safety using
 *    typia.assert and TestValidator.
 */
export async function test_api_member_todo_detail_after_deletion_behavior(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authenticated context
  const joinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create a todo for this member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(createdTodo);

  // Basic invariants on created todo
  TestValidator.equals(
    "created todo title matches request body",
    createdTodo.title,
    createBody.title,
  );
  TestValidator.equals(
    "created todo owner matches member user id",
    createdTodo.memberUser.id,
    authorized.id,
  );
  TestValidator.predicate(
    "created todo should not be marked as deleted",
    createdTodo.deleted_at === null || createdTodo.deleted_at === undefined,
  );

  // 3. Delete the todo via memberUser delete endpoint
  const deletedView: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.erase(connection, {
      todoId: createdTodo.id,
    });
  typia.assert<ITodoAppTodo>(deletedView);

  // Invariants after deletion
  TestValidator.equals(
    "deleted view id matches original todo id",
    deletedView.id,
    createdTodo.id,
  );
  TestValidator.equals(
    "deleted view owner matches member user id",
    deletedView.memberUser.id,
    authorized.id,
  );
  TestValidator.predicate(
    "deleted view updated_at is not before created_at",
    deletedView.updated_at >= deletedView.created_at,
  );

  // 4. Attempt to fetch the deleted todo again
  let fetchSucceeded = false;
  let fetchedTodo: ITodoAppTodo | null = null;

  try {
    fetchedTodo = await api.functional.todoApp.memberUser.todos.at(connection, {
      todoId: createdTodo.id,
    });
    fetchSucceeded = true;
  } catch (exp) {
    // Any error here is acceptable and means deleted todos are hidden.
    fetchSucceeded = false;
  }

  if (fetchSucceeded && fetchedTodo !== null) {
    // Case: deleted todos remain visible but must be clearly marked as deleted
    typia.assert<ITodoAppTodo>(fetchedTodo);

    TestValidator.equals(
      "fetched-after-delete todo id matches original",
      fetchedTodo.id,
      createdTodo.id,
    );
    TestValidator.equals(
      "fetched-after-delete owner matches member user id",
      fetchedTodo.memberUser.id,
      authorized.id,
    );
    TestValidator.predicate(
      "fetched-after-delete todo should be marked as deleted (deleted_at non-null)",
      fetchedTodo.deleted_at !== null && fetchedTodo.deleted_at !== undefined,
    );
  } else {
    // Case: deleted todos are completely hidden; only assert that fetch failed.
    TestValidator.predicate(
      "fetching deleted todo should not succeed",
      fetchSucceeded === false,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppAdminTodoAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminTodoAction";
import type { ITodoAppAdminTodoAction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminTodoAction";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an admin user can search admin todo actions filtered by admin
 * id and time range, and that pagination metadata and filter semantics are
 * consistent.
 *
 * Business flow (limited by available APIs):
 *
 * 1. Join a new admin user via POST /auth/adminUser/join to obtain an authorized
 *    admin context.
 * 2. Define a time window around the current time (from: now - 1 day, to: now + 1
 *    day).
 * 3. Call PATCH /todoApp/adminUser/adminTodoActions with
 *    ITodoAppAdminTodoAction.IRequest body including:
 *
 *    - Page, pageSize
 *    - AdminUserId = joined admin id
 *    - OccurredFrom/occurredTo = defined time window
 *    - SortBy = "created_at", sortDirection = "desc"
 * 4. Assert that the response matches IPageITodoAppAdminTodoAction.ISummary via
 *    typia.assert.
 * 5. Validate pagination invariants (current, limit, records, pages).
 * 6. For each returned admin todo action, when any exist:
 *
 *    - Confirm adminUser.id equals the filter adminUserId
 *    - Confirm created_at is within [occurredFrom, occurredTo]
 *    - Sanity check that results are sorted by created_at desc when there are 2+
 *         records.
 *
 * Note: Because no API for creating admin todo actions is exposed here, the
 * test must be robust to both empty and non-empty result sets. It focuses on
 * the correctness of filtering, pagination, and response structure rather than
 * enforcing the existence of specific audit records.
 */
export async function test_api_admin_todo_actions_search_by_admin_and_todo_lifecycle(
  connection: api.IConnection,
) {
  // 1. Join a new admin user to get an authorized admin context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const authorizedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppAdminUser.IAuthorized>(authorizedAdmin);

  const adminUserId: string & tags.Format<"uuid"> = authorizedAdmin.id;

  // 2. Define a time window around now: [now - 1 day, now + 1 day].
  const now = new Date();
  const oneDayMs = 24 * 60 * 60 * 1000;
  const fromDate = new Date(now.getTime() - oneDayMs);
  const toDate = new Date(now.getTime() + oneDayMs);
  const occurredFrom = fromDate.toISOString();
  const occurredTo = toDate.toISOString();

  // 3. Call the admin todo actions search endpoint with filters and pagination.
  const requestBody = {
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 10 as number & tags.Type<"int32"> & tags.Minimum<1>,
    adminUserId,
    occurredFrom,
    occurredTo,
    sortBy: "created_at",
    sortDirection: "desc",
  } satisfies ITodoAppAdminTodoAction.IRequest;

  const pageResult: IPageITodoAppAdminTodoAction.ISummary =
    await api.functional.todoApp.adminUser.adminTodoActions.index(connection, {
      body: requestBody,
    });
  typia.assert<IPageITodoAppAdminTodoAction.ISummary>(pageResult);

  const pagination = pageResult.pagination;

  // 4. Validate pagination invariants.
  TestValidator.predicate(
    "pagination.current is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination.limit is non-negative",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination.records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination.pages is non-negative",
    pagination.pages >= 0,
  );

  // If limit > 0, pages must be ceil(records / limit). If limit === 0, pages must be 0.
  if (pagination.limit > 0) {
    const expectedPages = Math.ceil(pagination.records / pagination.limit);
    TestValidator.equals(
      "pagination.pages matches ceil(records / limit)",
      pagination.pages,
      expectedPages,
    );
  } else {
    TestValidator.equals(
      "when limit is 0, pages must be 0",
      pagination.pages,
      0,
    );
  }

  // 5. If there are no records, we are done after validating pagination structure.
  if (pageResult.data.length === 0) {
    TestValidator.equals(
      "no records when data is empty",
      pageResult.data.length,
      0,
    );
    return;
  }

  // 6. For each returned admin todo action, validate filters and time window.
  const fromMs = new Date(occurredFrom).getTime();
  const toMs = new Date(occurredTo).getTime();

  for (const action of pageResult.data) {
    // adminUser filter enforcement
    TestValidator.equals(
      "adminUser.id matches filter adminUserId",
      action.adminUser.id,
      adminUserId,
    );

    // created_at within time window
    const createdMs = new Date(action.created_at).getTime();
    TestValidator.predicate(
      "created_at is within [occurredFrom, occurredTo]",
      createdMs >= fromMs && createdMs <= toMs,
    );
  }

  // 7. Sanity check sort order by created_at in descending order when multiple records.
  if (pageResult.data.length >= 2) {
    for (let i = 1; i < pageResult.data.length; i += 1) {
      const prevCreated = new Date(pageResult.data[i - 1].created_at).getTime();
      const currCreated = new Date(pageResult.data[i].created_at).getTime();
      TestValidator.predicate(
        "results are sorted by created_at in descending order",
        prevCreated >= currCreated,
      );
    }
  }
}

