import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminTodoAction } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminTodoAction";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that admin todo action audit detail is inaccessible to
 * unauthenticated callers and to authenticated non-admin member users.
 *
 * Business context: The GET
 * /todoApp/adminUser/adminTodoActions/{adminTodoActionId} endpoint exposes
 * sensitive administrative audit information about moderation actions taken
 * against member users' todos. Only adminUser actors must be able to read these
 * records. Any request without authentication, or authenticated as a regular
 * memberUser, must not be able to see this data.
 *
 * Test steps:
 *
 * 1. Join as an admin user to obtain an admin Authorization token.
 * 2. As the admin, call the adminTodoActions.at endpoint once to obtain a concrete
 *    ITodoAppAdminTodoAction and its id.
 * 3. Construct an unauthenticated connection (no Authorization header) and attempt
 *    to call adminTodoActions.at with the known id, expecting an authorization
 *    error.
 * 4. Register a member user using /auth/memberUser/join to obtain a
 *    member-authenticated connection.
 * 5. With this member user context, attempt to call adminTodoActions.at using the
 *    same adminTodoActionId, again expecting an authorization error.
 *
 * Validation rules:
 *
 * - All successful responses (admin join, initial admin audit fetch, member join)
 *   must be validated with typia.assert().
 * - Unauthorized scenarios must be wrapped with TestValidator.error() using a
 *   descriptive title, only checking that an error is thrown (no status code or
 *   message assertions).
 * - The original connection.headers must not be mutated directly in the test;
 *   when simulating unauthenticated access, create a shallow-cloned connection
 *   object with headers: {} and do not touch its headers afterwards.
 */
export async function test_api_admin_todo_action_detail_unauthorized_access(
  connection: api.IConnection,
) {
  // 1. Join as an admin user to obtain a valid admin Authorization token.
  const adminJoinBody = typia.random<ITodoAppAdminUser.IJoin>();
  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 2. As the admin, fetch a concrete admin todo action to obtain id.
  const seededAction: ITodoAppAdminTodoAction =
    await api.functional.todoApp.adminUser.adminTodoActions.at(connection, {
      adminTodoActionId: typia.random<string>(),
    });
  typia.assert(seededAction);
  const adminTodoActionId: string = seededAction.id;

  // 3. Try unauthenticated access using a cloned connection with empty headers.
  const unauthConnection: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthenticated access should fail", async () => {
    await api.functional.todoApp.adminUser.adminTodoActions.at(
      unauthConnection,
      {
        adminTodoActionId,
      },
    );
  });

  // 4. Register a member user and obtain member-authenticated connection.
  const memberJoinBody = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 5. With member authentication, attempt to read admin audit detail again.
  await TestValidator.error(
    "member user cannot access admin todo action detail",
    async () => {
      await api.functional.todoApp.adminUser.adminTodoActions.at(connection, {
        adminTodoActionId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate reopening a completed todo by its owning member user.
 *
 * Business goal: Ensure that when a member user completes one of their todos
 * and then calls the reopen operation on the same todo id, the backend
 * correctly transitions the lifecycle of that todo from completed back to an
 * active/open state, preserving ownership and id while updating lifecycle
 * timestamps appropriately.
 *
 * Covered workflow:
 *
 * 1. Register a fresh member user using /auth/memberUser/join.
 * 2. Create a todo for that user using /todoApp/memberUser/todos.
 * 3. Complete that todo using /todoApp/memberUser/todos/{todoId}/complete.
 * 4. Reopen the same todo using /todoApp/memberUser/todos/{todoId}/reopen.
 * 5. Validate lifecycle consistency and ownership across all steps.
 */
export async function test_api_todo_reopen_after_completion_by_owner(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new member user.
  const joinBody = {
    email: `member+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // Newly joined member accounts must not be logically deleted.
  TestValidator.equals(
    "newly joined member should not be deleted",
    authorized.deleted_at ?? null,
    null,
  );

  // 2. Create a new todo for the authenticated member user.
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert<ITodoAppTodo>(created);

  // Validate created todo basics.
  TestValidator.equals(
    "created todo title matches request",
    created.title,
    createBody.title,
  );
  TestValidator.equals(
    "created todo description matches request",
    created.description ?? null,
    createBody.description ?? null,
  );
  TestValidator.equals(
    "created todo should not be completed yet",
    created.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "created todo should not be deleted",
    created.deleted_at ?? null,
    null,
  );

  // Ownership consistency: memberUser.id should match authorized.id.
  TestValidator.equals(
    "todo owner id should equal authorized member id",
    created.memberUser.id,
    authorized.id,
  );

  // 3. Complete the todo.
  const completed: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(completed);

  // Validate completion lifecycle.
  TestValidator.equals(
    "completed todo id should equal created id",
    completed.id,
    created.id,
  );
  TestValidator.equals(
    "completed todo owner id should remain the same",
    completed.memberUser.id,
    created.memberUser.id,
  );
  TestValidator.equals(
    "completed todo should not be deleted",
    completed.deleted_at ?? null,
    null,
  );
  TestValidator.predicate(
    "completed_at should be set after completion",
    completed.completed_at !== null && completed.completed_at !== undefined,
  );

  const completedStatus: string = completed.status;

  // 4. Reopen the todo.
  const reopened: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: created.id,
    });
  typia.assert<ITodoAppTodo>(reopened);

  // 5. Validate reopen lifecycle.
  TestValidator.equals(
    "reopened todo id should equal created id",
    reopened.id,
    created.id,
  );
  TestValidator.equals(
    "reopened todo owner id should remain the same",
    reopened.memberUser.id,
    created.memberUser.id,
  );
  TestValidator.equals(
    "reopened todo should not be deleted",
    reopened.deleted_at ?? null,
    null,
  );
  TestValidator.equals(
    "reopened todo should have completed_at cleared",
    reopened.completed_at ?? null,
    null,
  );

  // Status should reflect a change relative to the completed state, if the
  // backend uses distinct values for completed vs active.
  TestValidator.notEquals(
    "reopened todo status should differ from completed status when lifecycle changes",
    reopened.status,
    completedStatus,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_reopen_idempotent_when_already_open(
  connection: api.IConnection,
) {
  // 1. Register a new member user to obtain an authenticated context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    // Use realistic URIs for href and referrer
    href: "https://todo-app.example.com/signup",
    referrer: "https://todo-app.example.com/landing",
    // Let ip be omitted so that server may infer it
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create a new todo in the default open/pending state
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // Basic invariants on the freshly created todo
  TestValidator.equals(
    "created todo owner matches authorized user",
    created.memberUser.id,
    authorized.id,
  );
  TestValidator.predicate(
    "created_at is non-empty ISO string",
    () => created.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at is non-empty ISO string",
    () => created.updated_at.length > 0,
  );
  TestValidator.equals(
    "completed_at is initially null or undefined",
    created.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "deleted_at is initially null or undefined",
    created.deleted_at ?? null,
    null,
  );

  const originalStatus: string = created.status;
  const originalCreatedAt: string = created.created_at;
  const originalUpdatedAt: string = created.updated_at;

  // 3. First reopen call on an already-open todo
  const reopenedOnce: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: created.id,
    });
  typia.assert(reopenedOnce);

  // 4. Validate idempotent behavior on first reopen
  TestValidator.equals(
    "reopen(1) keeps same todo id",
    reopenedOnce.id,
    created.id,
  );
  TestValidator.equals(
    "reopen(1) keeps same owner id",
    reopenedOnce.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "reopen(1) keeps created_at unchanged",
    reopenedOnce.created_at,
    originalCreatedAt,
  );
  TestValidator.equals(
    "reopen(1) does not alter status when already open",
    reopenedOnce.status,
    originalStatus,
  );
  TestValidator.equals(
    "reopen(1) still has no completed_at",
    reopenedOnce.completed_at ?? null,
    null,
  );
  TestValidator.equals(
    "reopen(1) still has no deleted_at",
    reopenedOnce.deleted_at ?? null,
    null,
  );
  TestValidator.predicate(
    "reopen(1) updated_at is not earlier than original",
    () => reopenedOnce.updated_at >= originalUpdatedAt,
  );

  // 5. Repeat reopen multiple times and ensure state stability and monotonic updated_at
  const reopenCount = 3;
  let previousSnapshot: ITodoAppTodo = reopenedOnce;

  for (let i = 0; i < reopenCount; i++) {
    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: created.id,
      });
    typia.assert(reopened);

    const iterationLabel = `reopen(${i + 2})`; // +2 because first reopen already done

    TestValidator.equals(
      `${iterationLabel} keeps same todo id`,
      reopened.id,
      created.id,
    );
    TestValidator.equals(
      `${iterationLabel} keeps same owner id`,
      reopened.memberUser.id,
      authorized.id,
    );
    TestValidator.equals(
      `${iterationLabel} keeps created_at unchanged`,
      reopened.created_at,
      originalCreatedAt,
    );
    TestValidator.equals(
      `${iterationLabel} keeps status stable`,
      reopened.status,
      originalStatus,
    );
    TestValidator.equals(
      `${iterationLabel} still has no completed_at`,
      reopened.completed_at ?? null,
      null,
    );
    TestValidator.equals(
      `${iterationLabel} still has no deleted_at`,
      reopened.deleted_at ?? null,
      null,
    );
    TestValidator.predicate(
      `${iterationLabel} updated_at is monotonic non-decreasing`,
      () => reopened.updated_at >= previousSnapshot.updated_at,
    );

    previousSnapshot = reopened;
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_todo_reopen_rejected_for_non_owner(
  connection: api.IConnection,
) {
  /**
   * 1. Arrange: register owner user and create + complete a todo under them
   * 2. Act: register a second user and attempt to reopen the owner's completed
   *    todo
   * 3. Assert: the reopen attempt fails, and the todo stays completed for the
   *    owner
   */

  // --- 1. Owner member user joins ---
  const ownerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://landing.example.com/todo",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const ownerAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: ownerJoinBody,
    });
  typia.assert(ownerAuth);

  // After join, connection.headers.Authorization contains owner token.

  // --- 2. Owner creates a todo ---
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo belongs to owner user",
    createdTodo.memberUser.id,
    ownerAuth.id,
  );

  TestValidator.equals(
    "new todo starts as non-completed (completed_at is null)",
    createdTodo.completed_at ?? null,
    null,
  );

  // --- 3. Owner completes the todo ---
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "todo status is completed after completion",
    completedTodo.status,
    "completed",
  );

  TestValidator.predicate(
    "completed_at is set after completion",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  // --- 4. Second member user (non-owner) joins using a separate connection object ---
  const otherConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  const otherJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://ad-network.example.com/campaign/todo",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const otherAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(otherConnection, {
      body: otherJoinBody,
    });
  typia.assert(otherAuth);

  TestValidator.notEquals(
    "owner and other member users must be distinct",
    ownerAuth.id,
    otherAuth.id,
  );

  // At this point, otherConnection carries the other user's Authorization header.

  // --- 5. Act: non-owner attempts to reopen owner's completed todo ---
  await TestValidator.error(
    "non-owner cannot reopen another user's todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.reopen(otherConnection, {
        todoId: createdTodo.id,
      });
    },
  );

  // --- 6. Assert: todo remains completed from owner's perspective ---
  // We call reopen again as owner; the operation is idempotent and should not fail
  // and should keep the todo in a completed or properly lifecycle-consistent state.
  const reopenedAsOwner: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(reopenedAsOwner);

  TestValidator.equals(
    "reopen as owner returns the same todo id",
    reopenedAsOwner.id,
    createdTodo.id,
  );

  // Even if business rules allow reopening to set status back to pending,
  // the critical invariant is that the non-owner attempt did not somehow
  // transfer ownership; the memberUser.id must remain the owner.
  TestValidator.equals(
    "todo ownership remains with the original owner after non-owner attempt",
    reopenedAsOwner.memberUser.id,
    ownerAuth.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure that a logically deleted todo cannot be reopened by its owner.
 *
 * Business flow covered by this test:
 *
 * 1. Register a new member user (POST /auth/memberUser/join) and obtain an
 *    authorized context.
 * 2. Create a new todo for that member (POST /todoApp/memberUser/todos).
 * 3. Complete the todo (POST /todoApp/memberUser/todos/{todoId}/complete).
 * 4. Logically delete the completed todo (DELETE
 *    /todoApp/memberUser/todos/{todoId}).
 * 5. Attempt to reopen the deleted todo (POST
 *    /todoApp/memberUser/todos/{todoId}/reopen).
 *
 * Expected result: the reopen attempt must fail with a domain/business error
 * and must not resurrect the deleted todo into an active state.
 */
export async function test_api_todo_reopen_rejected_for_deleted_todo(
  connection: api.IConnection,
) {
  // 1. Register a new member user and obtain authorized context
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);

  // 2. Create a new todo for that member user
  const createBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo should belong to joined member user",
    createdTodo.memberUser.id,
    authorized.id,
  );
  TestValidator.equals(
    "created todo should not be soft-deleted initially",
    createdTodo.deleted_at,
    null,
  );

  // 3. Complete the todo
  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo id should match original",
    completedTodo.id,
    createdTodo.id,
  );

  TestValidator.predicate(
    "completed_at should be set after completing the todo",
    completedTodo.completed_at !== null &&
      completedTodo.completed_at !== undefined,
  );

  TestValidator.equals(
    "deleted_at should still be null after completion",
    completedTodo.deleted_at,
    null,
  );

  // 4. Logically delete the completed todo
  const deletedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.erase(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(deletedTodo);

  TestValidator.equals(
    "deleted todo id should match original",
    deletedTodo.id,
    createdTodo.id,
  );

  TestValidator.predicate(
    "deleted_at should be set after logical delete",
    deletedTodo.deleted_at !== null && deletedTodo.deleted_at !== undefined,
  );

  // 5. Attempt to reopen the deleted todo and expect a business error
  await TestValidator.error(
    "cannot reopen a logically deleted todo",
    async () => {
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: createdTodo.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Ensure that reopening a todo requires member user authentication and does not
 * succeed when called without a valid Authorization context.
 *
 * Business goal
 *
 * - Verify that the lifecycle transition `completed -> reopened` is protected by
 *   memberUser authentication.
 * - Confirm that an unauthenticated reopen attempt is rejected and does not alter
 *   the todo state.
 *
 * Scenario
 *
 * 1. Join as a new member user using /auth/memberUser/join to obtain an
 *    authenticated context (Authorization header is automatically managed by
 *    the SDK).
 * 2. Create a new todo via /todoApp/memberUser/todos for this member user and
 *    capture its id and initial status.
 * 3. Complete the todo using /todoApp/memberUser/todos/{todoId}/complete and
 *    capture the completed representation.
 * 4. Build a separate unauthenticated connection by shallow cloning the input
 *    `connection` and overriding `headers` with an empty object literal. Never
 *    touch or mutate `headers` on either connection afterwards.
 * 5. Using the unauthenticated connection, attempt to reopen the todo via
 *    /todoApp/memberUser/todos/{todoId}/reopen inside `await
 *    TestValidator.error`, asserting only that some error occurs (do not test
 *    specific HTTP status codes or error payloads).
 * 6. Using the original authenticated connection, successfully call the reopen
 *    endpoint on the same todo and capture the reopened todo.
 * 7. Validate with typia.assert on all non-void responses and use
 *    TestValidator.equals to ensure:
 *
 *    - The todo id is the same across create, complete, and reopen responses.
 *    - The `status` after completion differs from the initial status.
 *    - The `status` after reopening differs from the completed status, proving that
 *         only the authenticated reopen actually changed the lifecycle state.
 */
export async function test_api_todo_reopen_requires_authentication(
  connection: api.IConnection,
) {
  // 1. Register a new member user to obtain an authenticated context.
  const joinRequest = typia.random<ITodoAppMemberUserJoin.IRequest>();

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(authorized);

  // 2. Create a new todo as this authenticated member user.
  const todoCreateBody = typia.random<ITodoAppTodo.ICreate>();

  const created: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(created);

  // 3. Complete the todo so that reopen has lifecycle semantics.
  const completed: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: created.id,
    });
  typia.assert(completed);

  // Basic lifecycle sanity check under authenticated context.
  TestValidator.equals(
    "todo id remains stable between create and complete",
    completed.id,
    created.id,
  );
  TestValidator.notEquals(
    "status changes when todo is completed",
    completed.status,
    created.status,
  );

  // 4. Build an unauthenticated connection by cloning and overriding headers.
  const unauthenticated: api.IConnection = {
    ...connection,
    headers: {},
  };

  // 5. Attempt to reopen the todo without authentication and expect failure.
  await TestValidator.error(
    "reopen without authentication must fail",
    async () => {
      await api.functional.todoApp.memberUser.todos.reopen(unauthenticated, {
        todoId: created.id,
      });
    },
  );

  // 6. Reopen with the original authenticated connection.
  const reopened: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: created.id,
    });
  typia.assert(reopened);

  // 7. Validate lifecycle and identity invariants.
  TestValidator.equals(
    "todo id remains stable across all lifecycle operations",
    reopened.id,
    created.id,
  );
  TestValidator.equals(
    "todo id remains stable between complete and reopen",
    reopened.id,
    completed.id,
  );
  TestValidator.notEquals(
    "status after reopen differs from completed status",
    reopened.status,
    completed.status,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoStatusSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatusSummary";

/**
 * Validate aggregated todo status summary for a member user with mixed pending
 * and completed todos.
 *
 * Business goal: Ensure that GET /todoApp/memberUser/todos/statusSummary
 * correctly reflects the counts of total, pending, completed, and recently
 * completed todos for a single authenticated member user after creating and
 * completing a subset of todos.
 *
 * Scenario steps:
 *
 * 1. Register a new member user via POST /auth/memberUser/join, using
 *    ITodoAppMemberUserJoin.IRequest and letting the SDK attach the access
 *    token to the connection.
 * 2. Create four todos for that member user via POST /todoApp/memberUser/todos
 *    (ITodoAppTodo.ICreate):
 *
 *    - 2 todos that will remain pending.
 *    - 2 todos that will be immediately completed in a later step.
 * 3. Complete the two selected todos using POST
 *    /todoApp/memberUser/todos/{todoId}/complete.
 * 4. Call GET /todoApp/memberUser/todos/statusSummary.
 * 5. Assert business rules on ITodoAppTodoStatusSummary:
 *
 *    - Total_count === 4 (all created are non-deleted).
 *    - Pending_count === 2 (never-completed todos).
 *    - Completed_count === 2 (completed todos).
 *    - Recently_completed_count >= 2 (the two just-completed todos fall within
 *         whatever recent window the implementation uses).
 *
 * Notes and constraints:
 *
 * - No deletion API is provided, so we do not test logical deletion; all created
 *   todos remain visible and should be counted.
 * - All APIs must be invoked with `await`, and every non-void response must be
 *   validated with `typia.assert` to enforce runtime type guarantees.
 * - Request bodies must be constructed using `satisfies` with the precise DTO
 *   type (ITodoAppMemberUserJoin.IRequest, ITodoAppTodo.ICreate).
 * - Business assertions must use TestValidator with descriptive titles and follow
 *   the actual-first, expected-second parameter ordering.
 */
export async function test_api_todo_status_summary_for_mixed_pending_and_completed(
  connection: api.IConnection,
) {
  // 1. Register a new member user so that subsequent todo operations are
  //    performed in an authenticated memberUser context.
  const joinRequest = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    // For href and referrer, use random but valid URIs.
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    // ip is optional and may be null; we can omit it to let the server infer.
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinRequest,
    });
  typia.assert(memberAuthorized);

  // 2. Create four todos for this member user.
  //    Use simple deterministic titles so counts are easy to reason about.
  const todoCreateBodies: ITodoAppTodo.ICreate[] = [
    { title: "pending-1", description: "First pending todo" },
    { title: "pending-2", description: "Second pending todo" },
    { title: "complete-1", description: "First todo to complete" },
    { title: "complete-2", description: "Second todo to complete" },
  ];

  const createdTodos: ITodoAppTodo[] = [];
  for (const body of todoCreateBodies) {
    const created: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: body satisfies ITodoAppTodo.ICreate,
      });
    typia.assert(created);
    createdTodos.push(created);
  }

  TestValidator.equals(
    "exactly four todos must have been created",
    createdTodos.length,
    4,
  );

  // 3. Complete the last two todos (indexes 2 and 3) so we have two pending
  //    and two completed todos for this member user.
  const todosToComplete: ITodoAppTodo[] = createdTodos.slice(2);
  const completedTodos: ITodoAppTodo[] = [];
  for (const todo of todosToComplete) {
    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: todo.id,
      });
    typia.assert(completed);
    completedTodos.push(completed);
  }

  TestValidator.equals(
    "two todos must have been completed",
    completedTodos.length,
    todosToComplete.length,
  );

  // Sanity-check the local status fields on the objects returned from
  // completion; this helps ensure lifecycle correctness in addition to the
  // summary endpoint.
  for (const completed of completedTodos) {
    TestValidator.equals(
      "completed todo status should be 'completed'",
      completed.status,
      "completed",
    );
    await TestValidator.predicate(
      "completed todo must have a non-null completed_at timestamp",
      () =>
        completed.completed_at !== null && completed.completed_at !== undefined,
    );
  }

  // 4. Call the status summary endpoint for this authenticated member user.
  const summary: ITodoAppTodoStatusSummary =
    await api.functional.todoApp.memberUser.todos.statusSummary.at(connection);
  typia.assert(summary);

  // 5. Validate the aggregated counts.
  TestValidator.equals(
    "summary.total_count should equal number of created todos",
    summary.total_count,
    createdTodos.length,
  );

  TestValidator.equals(
    "summary.completed_count should equal number of completed todos",
    summary.completed_count,
    completedTodos.length,
  );

  const expectedPendingCount = createdTodos.length - completedTodos.length;
  TestValidator.equals(
    "summary.pending_count should equal number of never-completed todos",
    summary.pending_count,
    expectedPendingCount,
  );

  // recently_completed_count is implementation-defined over some recent
  // window, but our just-completed todos should fall within that window,
  // so the summary value must be at least the number we just completed.
  await TestValidator.predicate(
    "summary.recently_completed_count should be at least number of just-completed todos",
    () => summary.recently_completed_count >= completedTodos.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoStatusSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoStatusSummary";

export async function test_api_todo_status_summary_excludes_deleted_todos(
  connection: api.IConnection,
) {
  // 1. Register a new member user to obtain an authenticated context.
  const joinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    // display_name is optional, so we can either provide or omit it. Provide for realism.
    display_name: RandomGenerator.name(),
    // ip is optional and nullable; omit it to let server derive it.
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const authorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
  typia.assert(authorized);
  typia.assert<IAuthorizationToken>(authorized.token);

  // 2. Create a set of todos in various lifecycle states.
  // - pendingActive: pending, never completed, never deleted
  // - completedActive: completed, not deleted
  // - pendingDeleted: pending, then deleted
  // - completedThenDeleted: completed, then deleted
  // Only the first two must contribute to counts.

  const pendingActive: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(pendingActive);

  const completedActiveBase: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 4 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(completedActiveBase);

  const pendingDeletedBase: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(pendingDeletedBase);

  const completedThenDeletedBase: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(completedThenDeletedBase);

  // 3. Transition some todos through complete and delete operations.

  // 3-1. Complete the `completedActiveBase` todo but do not delete it.
  const completedActive: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: completedActiveBase.id,
    });
  typia.assert(completedActive);
  TestValidator.equals(
    "completedActive remains non-deleted",
    completedActive.deleted_at,
    null,
  );

  // 3-2. Delete the pendingDeletedBase todo while it is still pending.
  const pendingDeleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.erase(connection, {
      todoId: pendingDeletedBase.id,
    });
  typia.assert(pendingDeleted);
  TestValidator.predicate(
    "pendingDeleted should have deleted_at set",
    pendingDeleted.deleted_at !== null &&
      pendingDeleted.deleted_at !== undefined,
  );

  // 3-3. Complete then delete the completedThenDeletedBase todo.
  const completedThenDeletedCompleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: completedThenDeletedBase.id,
    });
  typia.assert(completedThenDeletedCompleted);

  const completedThenDeleted: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.erase(connection, {
      todoId: completedThenDeletedCompleted.id,
    });
  typia.assert(completedThenDeleted);
  TestValidator.predicate(
    "completedThenDeleted should have deleted_at set",
    completedThenDeleted.deleted_at !== null &&
      completedThenDeleted.deleted_at !== undefined,
  );

  // Sanity checks on status values to keep expectations meaningful.
  TestValidator.equals(
    "pendingActive status should be pending",
    pendingActive.status,
    "pending",
  );
  TestValidator.equals(
    "completedActive status should be completed",
    completedActive.status,
    "completed",
  );

  // 4. Fetch status summary.
  const summary: ITodoAppTodoStatusSummary =
    await api.functional.todoApp.memberUser.todos.statusSummary.at(connection);
  typia.assert(summary);

  // 5. Validate that logically deleted todos are excluded from all counts.
  // Only pendingActive and completedActive should be counted.
  TestValidator.equals(
    "total_count should include only non-deleted todos",
    summary.total_count,
    2,
  );

  TestValidator.equals(
    "pending_count should count only non-deleted pending todos",
    summary.pending_count,
    1,
  );

  TestValidator.equals(
    "completed_count should count only non-deleted completed todos",
    summary.completed_count,
    1,
  );

  // For recently_completed_count we cannot know exact window length,
  // but we can assert that deleted completed todos are not counted by
  // asserting it is at most 1 (the non-deleted completed todo) and at least 0.
  TestValidator.predicate(
    "recently_completed_count should not exceed non-deleted completed todos",
    summary.recently_completed_count === 0 ||
      summary.recently_completed_count === 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
