  typia.assert<ITodoAppMemberuser.IAuthorized>(authorized);

  // 2. Create at least one todo for this member user
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo = await api.functional.todoApp.memberUser.todos.create(
    connection,
    { body: createTodoBody },
  );
  typia.assert<ITodoAppTodo>(createdTodo);

  // 3. Attempt to access statusSummary without authentication
  const unauthConnection: api.IConnection = { ...connection, headers: {} };

  await TestValidator.error(
    "status summary requires authentication",
    async () => {
      await api.functional.todoApp.memberUser.todos.statusSummary.at(
        unauthConnection,
      );
    },
  );

  // 4. Access statusSummary with authenticated connection
  const summary =
    await api.functional.todoApp.memberUser.todos.statusSummary.at(connection);
  typia.assert<ITodoAppTodoStatusSummary>(summary);

  // 5. Basic business validations on the summary
  TestValidator.predicate(
    "total_count is non-negative",
    summary.total_count >= 0,
  );
  TestValidator.predicate(
    "pending_count is non-negative",
    summary.pending_count >= 0,
  );
  TestValidator.predicate(
    "completed_count is non-negative",
    summary.completed_count >= 0,
  );
  TestValidator.predicate(
    "recently_completed_count is non-negative",
    summary.recently_completed_count >= 0,
  );

  TestValidator.predicate(
    "total_count equals pending_count + completed_count",
    summary.total_count === summary.pending_count + summary.completed_count,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppRateLimitEvent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Basic admin rate limit events search flow.
 *
 * This test validates that:
 *
 * 1. A member user can be registered and can generate todo write traffic.
 * 2. An admin user can be registered (and implicitly authenticated).
 * 3. The admin can search rate limit events with a minimal
 *    ITodoAppRateLimitEvent.IRequest.
 * 4. The response matches IPageITodoAppRateLimitEvent.ISummary and contains
 *    consistent pagination metadata and well-typed summary rows.
 *
 * The test does not assume that rate limiting is actually triggered; it only
 * ensures that the search endpoint works and returns a structurally correct
 * paginated response, even when the data array is empty.
 */
export async function test_api_admin_rate_limit_events_search_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register a member user and obtain authorized context
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Generate several todos as the member to produce write traffic
  const todoCount = 5;
  const todos: ITodoAppTodo[] = [];
  for (let i = 0; i < todoCount; i += 1) {
    const createBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: createBody,
      });
    typia.assert(todo);
    todos.push(todo);
  }

  TestValidator.equals(
    "member created expected number of todos",
    todos.length,
    todoCount,
  );

  // 3. Optionally complete and reopen the first todo to add more write activity
  const targetTodo: ITodoAppTodo | undefined = todos[0];
  if (targetTodo) {
    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: targetTodo.id,
      });
    typia.assert(completed);

    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: targetTodo.id,
      });
    typia.assert(reopened);
  }

  // 4. Register an admin user and obtain admin authorization
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 5. As the admin, search rate limit events with minimal filters
  const requestBody = {
    actor_type: undefined,
    ip: undefined,
    limit_key: undefined,
    limit_type: undefined,
    window_start_from: undefined,
    window_start_to: undefined,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: undefined,
    sort_order: undefined,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const page: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: requestBody,
    });
  typia.assert(page);

  // 6. Validate pagination metadata
  const pagination = page.pagination;
  TestValidator.predicate(
    "pagination current page is non-negative",
    pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination limit is non-negative",
    pagination.limit >= 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    pagination.pages >= 0,
  );

  if (page.data.length > 0) {
    // 7. Validate one sample rate limit event summary structurally and logically
    const sample: ITodoAppRateLimitEvent.ISummary = page.data[0];
    typia.assert<ITodoAppRateLimitEvent.ISummary>(sample);

    TestValidator.predicate(
      "sample rate-limit event has non-empty id",
      sample.id.length > 0,
    );
    TestValidator.predicate(
      "sample rate-limit event has non-empty limit_key",
      sample.limit_key.length > 0,
    );
    TestValidator.predicate(
      "sample rate-limit event has non-empty limit_type",
      sample.limit_type.length > 0,
    );
    TestValidator.predicate(
      "sample rate-limit window_start precedes or equals window_end",
      new Date(sample.window_start).getTime() <=
        new Date(sample.window_end).getTime(),
    );

    // Actor type should be plausible for member-generated todo traffic,
    // but we don't strictly assert value set here, only non-empty string.
    TestValidator.predicate(
      "sample rate-limit actor_type is non-empty",
      sample.actor_type.length > 0,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppRateLimitEvent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate admin search of rate limit events with time-window filters and
 * sorting.
 *
 * Business context:
 *
 * - Member users perform todo write operations (create, complete, reopen) that
 *   may be subject to rate limiting rules (e.g., limit_type "todo_write").
 * - Administrators need to inspect rate limit events across a time window,
 *   optionally filtered by logical key/type, and review them in sorted order
 *   with pagination.
 *
 * Test steps:
 *
 * 1. Register and implicitly authenticate a member user using
 *    auth.memberUser.join.
 * 2. Generate a burst of todo traffic as that member:
 *
 *    - Record a timestamp before starting traffic (startBoundary).
 *    - Create multiple todos via todoApp.memberUser.todos.create.
 *    - For at least one todo, call complete and reopen in quick succession.
 *    - Record a timestamp after traffic (endBoundary).
 * 3. Register and implicitly authenticate an admin user using auth.adminUser.join.
 * 4. As the admin, call todoApp.adminUser.rateLimitEvents.index with an
 *    ITodoAppRateLimitEvent.IRequest body that:
 *
 *    - Sets window_start_from to startBoundary and window_start_to to endBoundary.
 *    - Sets page=1 and pageSize to a small positive int (e.g., 20).
 *    - Optionally sets limit_type to "todo_write" to reflect todo write rules.
 * 5. Assert that:
 *
 *    - The response structure matches IPageITodoAppRateLimitEvent.ISummary using
 *         typia.assert.
 *    - Every event’s window_start (if any results) is between the requested from/to
 *         inclusive.
 *    - If limit_type was provided, every event’s limit_type equals that value.
 * 6. Change sort_by and sort_order and re-query:
 *
 *    - Use sort_by = "created_at" (a supported time field) and sort_order = "desc";
 *         assert the results are ordered descending by created_at.
 *    - Use sort_by = "created_at" and sort_order = "asc"; assert the results are
 *         ordered ascending by created_at.
 *    - Comparisons should be done by comparing Date.getTime() values.
 *
 * The test is robust to empty result sets: when no data is returned, it only
 * validates the structural correctness and does not enforce range or ordering
 * checks.
 */
export async function test_api_admin_rate_limit_events_search_with_time_window_and_filters(
  connection: api.IConnection,
) {
  // 1. Register and authenticate member user
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuth);

  // 2. Generate todo traffic as member
  const startBoundary = new Date().toISOString();

  const todos: ITodoAppTodo[] = [];
  for (let i = 0; i < 3; i++) {
    const todoCreateBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert(todo);
    todos.push(todo);
  }

  if (todos.length > 0) {
    const targetTodo: ITodoAppTodo = todos[0];

    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: targetTodo.id,
      });
    typia.assert(completed);

    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: targetTodo.id,
      });
    typia.assert(reopened);
  }

  const endBoundary = new Date().toISOString();

  // 3. Register and authenticate admin user
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuth: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuth);

  // 4. Admin searches rate limit events within time window
  const baseRequestBody = {
    actor_type: null,
    ip: null,
    limit_key: null,
    limit_type: "todo_write",
    window_start_from: startBoundary,
    window_start_to: endBoundary,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: null,
    sort_order: null,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const firstPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: baseRequestBody,
    });
  typia.assert(firstPage);

  // 5. Validate time window and limit_type filters if data exists
  if (firstPage.data.length > 0) {
    const fromMs = Date.parse(baseRequestBody.window_start_from!);
    const toMs = Date.parse(baseRequestBody.window_start_to!);

    for (const event of firstPage.data) {
      const windowStartMs = Date.parse(event.window_start);

      TestValidator.predicate(
        "event window_start must be within requested range",
        () => windowStartMs >= fromMs && windowStartMs <= toMs,
      );

      if (baseRequestBody.limit_type !== null) {
        TestValidator.equals(
          "event limit_type must match requested limit_type when specified",
          event.limit_type,
          baseRequestBody.limit_type,
        );
      }
    }
  }

  // 6. Sorting checks using created_at
  const descRequestBody = {
    ...baseRequestBody,
    sort_by: "created_at",
    sort_order: "desc",
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const descPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: descRequestBody,
    });
  typia.assert(descPage);

  if (descPage.data.length > 1) {
    for (let i = 1; i < descPage.data.length; i++) {
      const prev = descPage.data[i - 1];
      const curr = descPage.data[i];
      const prevTime = Date.parse(prev.created_at);
      const currTime = Date.parse(curr.created_at);

      TestValidator.predicate(
        "events should be ordered by created_at desc",
        () => prevTime >= currTime,
      );
    }
  }

  const ascRequestBody = {
    ...baseRequestBody,
    sort_by: "created_at",
    sort_order: "asc",
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const ascPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: ascRequestBody,
    });
  typia.assert(ascPage);

  if (ascPage.data.length > 1) {
    for (let i = 1; i < ascPage.data.length; i++) {
      const prev = ascPage.data[i - 1];
      const curr = ascPage.data[i];
      const prevTime = Date.parse(prev.created_at);
      const currTime = Date.parse(curr.created_at);

      TestValidator.predicate(
        "events should be ordered by created_at asc",
        () => prevTime <= currTime,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppRateLimitEvent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate pagination edge behaviors for admin rate limit events search.
 *
 * Business goal: Ensure that the administrative endpoint for searching
 * `todo_app_rate_limit_events` supports stable, predictable pagination
 * semantics with small page sizes, independent of the exact rate limiting
 * policies in effect.
 *
 * High‑level flow:
 *
 * 1. Create and authenticate a member user.
 * 2. As that member, perform multiple todo write and lifecycle operations
 *    (create/complete/reopen) to generate realistic traffic that may produce
 *    rate limit events.
 * 3. Create and authenticate an admin user.
 * 4. As admin, call PATCH /todoApp/adminUser/rateLimitEvents with a small pageSize
 *    to fetch page 1, then additional pages.
 * 5. Validate pagination metadata (current, limit, records, pages) and that
 *    data.length never exceeds the requested pageSize.
 * 6. Verify that event ids are not duplicated across pages.
 * 7. Request an out‑of‑range page index and confirm that it returns a well‑formed
 *    page object (with empty or bounded data) rather than an error.
 */
export async function test_api_admin_rate_limit_events_search_pagination_edges(
  connection: api.IConnection,
) {
  // 1. Register a member user (join implicitly authenticates the connection as member).
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/signup",
    referrer: "https://landing.example.com/",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Explicit member login to exercise login flow and ensure session.
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/login",
    referrer: "https://todo-app.example.com/",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLoginAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 3. Generate member todo traffic: create several todos, then complete/reopen some.
  const createdTodos: ITodoAppTodo[] = [];
  const todoCreateCount = 10;

  for (let i = 0; i < todoCreateCount; ++i) {
    const todoBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoBody,
      });
    typia.assert(todo);
    createdTodos.push(todo);
  }

  // For some of the todos, perform complete/reopen cycles to diversify lifecycle events.
  const cycleTargets = createdTodos.slice(0, 5);
  for (const todo of cycleTargets) {
    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: todo.id,
      });
    typia.assert(completed);

    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: todo.id,
      });
    typia.assert(reopened);
  }

  // 4. Register an admin user and authenticate as admin.
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}-admin@example.com`,
    password: RandomGenerator.alphabets(12),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // Explicit admin login to ensure actor switching works and the token is fresh.
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "todo-app-admin-e2e-test",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 5. As admin, search rate limit events with a small page size starting at page 1.
  const pageSize = 2;

  const baseRequest: ITodoAppRateLimitEvent.IRequest = {
    actor_type: null,
    ip: null,
    limit_key: null,
    limit_type: null,
    window_start_from: null,
    window_start_to: null,
    page: 1,
    pageSize,
    sort_by: null,
    sort_order: null,
  };

  const firstPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: baseRequest,
    });
  typia.assert(firstPage);

  const firstPagination = firstPage.pagination;

  // Basic pagination checks for page 1.
  TestValidator.equals(
    "first page current index must be 1",
    firstPagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit must equal requested pageSize",
    firstPagination.limit,
    pageSize,
  );
  TestValidator.predicate(
    "first page data length must be <= pageSize",
    firstPage.data.length <= pageSize,
  );

  // Accumulate ids to ensure no duplication across pages.
  const seenIds = new Set<string>();
  for (const event of firstPage.data) {
    seenIds.add(event.id);
  }

  // 6. Iterate over subsequent pages (if any) and validate pagination semantics.
  const totalPages = firstPagination.pages;
  TestValidator.predicate("total pages must be >= 0", totalPages >= 0);

  const pageVisitCap = Math.max(1, Math.min(totalPages, 5));
  for (let page = 2; page <= pageVisitCap; ++page) {
    const pageRequest: ITodoAppRateLimitEvent.IRequest = {
      ...baseRequest,
      page,
    };

    const pageResult: IPageITodoAppRateLimitEvent.ISummary =
      await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
        body: pageRequest,
      });
    typia.assert(pageResult);

    const pagination = pageResult.pagination;
    TestValidator.equals(
      `page ${page} current index must equal requested page`,
      pagination.current,
      page,
    );
    TestValidator.equals(
      `page ${page} limit must equal requested pageSize`,
      pagination.limit,
      pageSize,
    );
    TestValidator.predicate(
      `page ${page} data length must be <= pageSize`,
      pageResult.data.length <= pageSize,
    );

    // Ensure no duplicate ids across pages we inspected.
    for (const event of pageResult.data) {
      TestValidator.predicate(
        `event id ${event.id} must not be duplicated across pages`,
        seenIds.has(event.id) === false,
      );
      seenIds.add(event.id);
    }
  }

  const observedCount = seenIds.size;
  const finalPagination = firstPage.pagination;

  // 7. Validate that records and pages are consistent with observed data.
  TestValidator.predicate(
    "observed event count must be <= total records",
    observedCount <= finalPagination.records,
  );
  TestValidator.predicate(
    "total records must be >= 0",
    finalPagination.records >= 0,
  );
  TestValidator.predicate(
    "pages must be consistent with records and limit",
    finalPagination.records <= finalPagination.pages * finalPagination.limit,
  );

  // 8. Request an out-of-range page and validate behavior, if there is at least 1 page.
  if (finalPagination.pages >= 1) {
    const outOfRangePageIndex = finalPagination.pages + 1;
    const outOfRangeRequest: ITodoAppRateLimitEvent.IRequest = {
      ...baseRequest,
      page: outOfRangePageIndex,
    };

    const outOfRangePage: IPageITodoAppRateLimitEvent.ISummary =
      await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
        body: outOfRangeRequest,
      });
    typia.assert(outOfRangePage);

    const outPag = outOfRangePage.pagination;
    TestValidator.equals(
      "out-of-range page current index must equal requested page",
      outPag.current,
      outOfRangePageIndex,
    );
    TestValidator.equals(
      "out-of-range page limit must equal requested pageSize",
      outPag.limit,
      pageSize,
    );
    TestValidator.predicate(
      "out-of-range page should return empty or at most pageSize items",
      outOfRangePage.data.length <= pageSize,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppRateLimitEvent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate admin filtering of rate limit events by actor type, IP, and limit
 * key.
 *
 * Business context:
 *
 * - Administrators need to perform forensic searches over the rate limit log to
 *   understand which actors and client IPs are being throttled and under which
 *   logical limit keys (e.g., auth-related or todo-related limits).
 * - The backend exposes PATCH /todoApp/adminUser/rateLimitEvents to search the
 *   `todo_app_rate_limit_events` log with filters such as actor_type, ip,
 *   limit_key, limit_type, and time windows, returning a paginated summary.
 *
 * This test exercises a realistic workflow and then verifies that the admin
 * search endpoint respects actor_type, ip, and limit_key filters semantically
 * over whatever events exist, without assuming any specific rate limit policy
 * or that a particular sequence will definitely trigger limits.
 *
 * Steps:
 *
 * 1. Register a member user with a known IP, href, and referrer via POST
 *    /auth/memberUser/join, receiving an authorized context.
 * 2. Log in as the same member via POST /auth/memberUser/login using the same
 *    IP/href/referrer, verifying that the member id is stable between join and
 *    login.
 * 3. As the authenticated member, create a todo, complete it, and reopen it
 *    through /todoApp/memberUser/todos endpoints to generate normal member
 *    activity tied to this actor and IP.
 * 4. Register an admin user via POST /auth/adminUser/join, then perform an
 *    explicit admin login via POST /auth/adminUser/login, confirming the admin
 *    id is stable between join and login while establishing an admin auth
 *    context for subsequent calls.
 * 5. As the admin, call PATCH /todoApp/adminUser/rateLimitEvents with an
 *    ITodoAppRateLimitEvent.IRequest that filters on actor_type="memberUser"
 *    and the known member IP, while leaving limit_key, limit_type, and time
 *    windows null and using a small page/pageSize.
 *
 *    - Assert the response shape via typia.assert.
 *    - For each returned event, assert that actor_type is "memberUser" and, if ip is
 *         present, it equals the filtered IP.
 * 6. If at least one event is returned, pick a sample event and perform a second
 *    search with the same actor_type/IP filters and limit_key set to the sample
 *    event's limit_key. Assert that all events in this narrowed result share
 *    the same actor_type, that any non-null ip matches the filter ip, and that
 *    limit_key matches the selected key. This validates that the limit_key
 *    filter further narrows results consistently.
 * 7. Finally, call the search again with actor_type="memberUser" and ip=null to
 *    demonstrate an actor-only filter, asserting only that all returned events
 *    have actor_type="memberUser" while relying on typia.assert for structural
 *    validation.
 */
export async function test_api_admin_rate_limit_events_search_actor_ip_and_key_filters(
  connection: api.IConnection,
) {
  // 1. Register a member user with known IP and URLs
  const memberIp = "203.0.113.10";
  const memberJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@example.com`,
    password: "Passw0rd!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(1),
    ip: memberIp,
    href: "https://todo-app.example.com/signup" as string & tags.Format<"uri">,
    referrer: "https://marketing.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Login as the same member user (explicitly exercise login API)
  const memberLoginBody = {
    email: memberAuthorized.email,
    password: memberJoinBody.password,
    ip: memberIp,
    href: "https://todo-app.example.com/login" as string & tags.Format<"uri">,
    referrer: "https://todo-app.example.com/home" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberAuthorizedFromLogin: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberAuthorizedFromLogin);

  TestValidator.equals(
    "member id should be stable between join and login",
    memberAuthorizedFromLogin.id,
    memberAuthorized.id,
  );

  // 3. As member, create a todo then complete and reopen it to generate activity
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  TestValidator.equals(
    "created todo should be pending initially",
    createdTodo.status,
    "pending",
  );

  const completedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.complete(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(completedTodo);

  TestValidator.equals(
    "completed todo should have completed status",
    completedTodo.status,
    "completed",
  );

  const reopenedTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.reopen(connection, {
      todoId: createdTodo.id,
    });
  typia.assert(reopenedTodo);

  TestValidator.equals(
    "reopened todo should return to pending status",
    reopenedTodo.status,
    "pending",
  );

  // 4. Register an admin user (admin join) and rely on token from join
  const adminJoinBody = {
    email: `${RandomGenerator.alphabets(8)}@admin.example.com`,
    password: "Adm1nPass!" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(1),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // Optionally exercise admin login as a separate call (role switching pattern)
  const adminLoginBody = {
    email: adminAuthorized.email,
    password: adminJoinBody.password,
    ip: "198.51.100.5",
    href: "https://todo-app.example.com/admin/login" as string &
      tags.Format<"uri">,
    referrer: "https://todo-app.example.com/admin" as string &
      tags.Format<"uri">,
    user_agent: "e2e-test-agent/1.0",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  TestValidator.equals(
    "admin id should be stable between join and login",
    adminAuthorizedFromLogin.id,
    adminAuthorized.id,
  );

  // 5. As admin, search rate limit events filtered by actor_type and IP
  const baseRequest = {
    actor_type: "memberUser",
    ip: memberIp,
    limit_key: null,
    limit_type: null,
    window_start_from: null,
    window_start_to: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: null,
    sort_order: null,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const firstPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: baseRequest,
    });
  typia.assert(firstPage);

  // Validate that all returned summaries match the actor_type and IP filter semantics
  for (const event of firstPage.data) {
    typia.assert<ITodoAppRateLimitEvent.ISummary>(event);

    TestValidator.equals(
      "rate limit event actor_type should match filter",
      event.actor_type,
      baseRequest.actor_type,
    );

    if (event.ip !== null && event.ip !== undefined) {
      TestValidator.equals(
        "rate limit event IP should match filter when present",
        event.ip,
        memberIp,
      );
    }
  }

  // 6. If we have at least one event, narrow further by that event's limit_key
  const sampleEvent: ITodoAppRateLimitEvent.ISummary | undefined =
    firstPage.data[0];

  if (sampleEvent !== undefined) {
    const limitKeyFilterRequest = {
      actor_type: "memberUser",
      ip: memberIp,
      limit_key: sampleEvent.limit_key,
      limit_type: null,
      window_start_from: null,
      window_start_to: null,
      page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
      sort_by: null,
      sort_order: null,
    } satisfies ITodoAppRateLimitEvent.IRequest;

    const limitKeyPage: IPageITodoAppRateLimitEvent.ISummary =
      await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
        body: limitKeyFilterRequest,
      });
    typia.assert(limitKeyPage);

    for (const event of limitKeyPage.data) {
      typia.assert<ITodoAppRateLimitEvent.ISummary>(event);

      TestValidator.equals(
        "limit-key-filtered event actor_type should remain memberUser",
        event.actor_type,
        "memberUser",
      );

      if (event.ip !== null && event.ip !== undefined) {
        TestValidator.equals(
          "limit-key-filtered event IP should still match member IP",
          event.ip,
          memberIp,
        );
      }

      TestValidator.equals(
        "limit-key-filtered event limit_key should match selected key",
        event.limit_key,
        sampleEvent.limit_key,
      );
    }
  }

  // 7. Optional: actor_type-only filter without IP, just type-check and basic invariants
  const actorOnlyRequest = {
    actor_type: "memberUser",
    ip: null,
    limit_key: null,
    limit_type: null,
    window_start_from: null,
    window_start_to: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: null,
    sort_order: null,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const actorOnlyPage: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: actorOnlyRequest,
    });
  typia.assert(actorOnlyPage);

  for (const event of actorOnlyPage.data) {
    typia.assert<ITodoAppRateLimitEvent.ISummary>(event);

    TestValidator.equals(
      "actor-only filtered events should all be memberUser",
      event.actor_type,
      "memberUser",
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppRateLimitEvent";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an admin user can retrieve a single rate limit event by id
 * after it has been created by member todo activity.
 *
 * Business flow covered by this test:
 *
 * 1. Register a new member user (memberUser actor).
 * 2. As that member, create a todo and perform several complete/reopen lifecycle
 *    transitions to generate realistic write activity that may trigger rate
 *    limiting.
 * 3. Register a new admin user (adminUser actor), which also authenticates the
 *    connection as an admin.
 * 4. As the admin, search the rate limit log via PATCH
 *    /todoApp/adminUser/rateLimitEvents using an
 *    ITodoAppRateLimitEvent.IRequest filter targeting actor_type "memberUser".
 * 5. If at least one rate limit event summary is returned, pick one eventId from
 *    the page and call GET
 *    /todoApp/adminUser/rateLimitEvents/{rateLimitEventId} to fetch the
 *    detailed ITodoAppRateLimitEvent record.
 * 6. Assert that core fields (id, actor_type, limit_key, limit_type, window_start,
 *    window_end, created_at) in the detail record exactly match the values from
 *    the summary, and validate simple non-empty invariants for key string
 *    fields.
 * 7. If the search returns no rate limit events, assert the empty result shape and
 *    finish gracefully without failing due to environment‑specific rate limit
 *    thresholds.
 */
export async function test_api_admin_rate_limit_event_get_by_id_basic_flow(
  connection: api.IConnection,
) {
  // 1. Register a member user and obtain authenticated member context
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const memberPassword = typia.random<string & tags.Format<"password">>();
  const memberHref = typia.random<string & tags.Format<"uri">>();
  const memberReferrer = typia.random<string & tags.Format<"uri">>();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(1),
    ip: null,
    href: memberHref,
    referrer: memberReferrer,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. As the member, create a todo and perform multiple complete/reopen cycles
  const createTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: createTodoBody,
    });
  typia.assert(createdTodo);

  const todoId = createdTodo.id;

  // Perform several complete/reopen transitions to create realistic activity
  const cycles = 5;
  for (let i = 0; i < cycles; i += 1) {
    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId,
      });
    typia.assert(completed);

    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId,
      });
    typia.assert(reopened);
  }

  // 3. Register an admin user and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();
  const adminHref = typia.random<string & tags.Format<"uri">>();
  const adminReferrer = typia.random<string & tags.Format<"uri">>();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(1),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 4. As admin, search for rate limit events for actor_type "memberUser"
  const searchBody = {
    actor_type: "memberUser",
    ip: null,
    limit_key: null,
    limit_type: null,
    window_start_from: null,
    window_start_to: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 20 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: null,
    sort_order: null,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  const page: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: searchBody,
    });
  typia.assert(page);

  // Basic pagination invariants
  TestValidator.equals(
    "pagination current page is 1",
    page.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit matches requested pageSize",
    page.pagination.limit,
    searchBody.pageSize,
  );
  TestValidator.predicate(
    "pagination records is at least data length",
    page.pagination.records >= page.data.length,
  );

  // If no events were found, assert empty result shape and finish gracefully
  if (page.data.length === 0) {
    TestValidator.equals(
      "rate limit event list is empty when no events exist",
      page.data.length,
      0,
    );
    return;
  }

  const summary: ITodoAppRateLimitEvent.ISummary = page.data[0];

  // 5. Fetch detailed rate limit event by id
  const detail: ITodoAppRateLimitEvent =
    await api.functional.todoApp.adminUser.rateLimitEvents.at(connection, {
      rateLimitEventId: summary.id,
    });
  typia.assert(detail);

  // 6. Validate consistency between summary and detail core fields
  TestValidator.equals(
    "rate limit event id matches between summary and detail",
    detail.id,
    summary.id,
  );
  TestValidator.equals(
    "rate limit actor_type matches between summary and detail",
    detail.actor_type,
    summary.actor_type,
  );
  TestValidator.equals(
    "rate limit limit_key matches between summary and detail",
    detail.limit_key,
    summary.limit_key,
  );
  TestValidator.equals(
    "rate limit limit_type matches between summary and detail",
    detail.limit_type,
    summary.limit_type,
  );
  TestValidator.equals(
    "rate limit window_start matches between summary and detail",
    detail.window_start,
    summary.window_start,
  );
  TestValidator.equals(
    "rate limit window_end matches between summary and detail",
    detail.window_end,
    summary.window_end,
  );
  TestValidator.equals(
    "rate limit created_at matches between summary and detail",
    detail.created_at,
    summary.created_at,
  );

  // Additional simple invariants on detailed record
  TestValidator.predicate(
    "detail actor_type is non-empty",
    detail.actor_type.length > 0,
  );
  TestValidator.predicate(
    "detail limit_key is non-empty",
    detail.limit_key.length > 0,
  );
  TestValidator.predicate(
    "detail limit_type is non-empty",
    detail.limit_type.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";

/**
 * Validate behavior when an admin fetches a rate limit event by a non-existent
 * id.
 *
 * Business context
 *
 * - The GET /todoApp/adminUser/rateLimitEvents/{rateLimitEventId} endpoint lets
 *   admins inspect detailed rate limit enforcement events recorded in
 *   todo_app_rate_limit_events.
 * - When the requested UUID does not correspond to any stored event, the backend
 *   should respond with a not-found style error (typically 404), not a
 *   successful payload.
 * - This test ensures the endpoint fails predictably and does not silently
 *   succeed or return a random event for an unknown id.
 *
 * Scenario steps
 *
 * 1. Register an administrative user using POST /auth/adminUser/join so that the
 *    connection holds a valid adminUser token.
 * 2. Generate a random UUID value to use as a fake rateLimitEventId, making it
 *    extremely unlikely to match any real ITodoAppRateLimitEvent.id in the DB.
 * 3. Call GET /todoApp/adminUser/rateLimitEvents/{rateLimitEventId} with that fake
 *    id.
 * 4. Assert that the call results in an HttpError rather than returning an
 *    ITodoAppRateLimitEvent object.
 * 5. Additionally, verify that the HttpError status code is in the 4xx family
 *    (client error), without checking a specific status number to avoid relying
 *    on exact status codes.
 */
export async function test_api_admin_rate_limit_event_get_by_id_not_found(
  connection: api.IConnection,
) {
  // 1. Register an administrative user (auth.adminUser.join)
  const joinBody = typia.random<ITodoAppAdminUser.IJoin>();

  const admin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(admin);

  // 2. Generate a random UUID for a non-existent rate limit event id
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();

  // 3, 4 & 5. Call the by-id endpoint and assert it fails with an HttpError
  // whose status code is a 4xx client error.
  await TestValidator.error(
    "getting non-existent rate limit event should throw 4xx HttpError",
    async () => {
      try {
        await api.functional.todoApp.adminUser.rateLimitEvents.at(connection, {
          rateLimitEventId: nonexistentId,
        });
      } catch (err) {
        // Ensure the error is an HttpError with a 4xx status code.
        if (!(err instanceof api.HttpError)) throw err;
        if (err.status < 400 || err.status >= 500) throw err;
        // Re-throwing is not needed here because TestValidator.error
        // only needs that an error was thrown; since we've reached this
        // point, the classification is acceptable.
        throw err;
      }

      // If we reach here, no error was thrown, which is a test failure.
      throw new Error(
        "Expected HttpError for non-existent rate limit event id, but call succeeded.",
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
