import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppRateLimitEvent } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppRateLimitEvent";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_rate_limit_event_get_by_id_consistency_with_member_and_admin_associations(
  connection: api.IConnection,
) {
  // 1. Create a member user and perform some todo operations to generate realistic member traffic
  const memberJoinBody = {
    email: `member+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "Password!123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://member.example.com/signup" as string & tags.Format<"uri">,
    referrer: "https://member.example.com/landing" as string &
      tags.Format<"uri">,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // Create several todos as the member and toggle their status to simulate traffic
  const todos: ITodoAppTodo[] = [];
  for (let i = 0; i < 3; i += 1) {
    const todoCreateBody = {
      title: RandomGenerator.paragraph({ sentences: 3 }),
      description: RandomGenerator.paragraph({ sentences: 6 }),
    } satisfies ITodoAppTodo.ICreate;

    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body: todoCreateBody,
      });
    typia.assert(todo);
    todos.push(todo);
  }

  // Complete and reopen some todos to add more member activity
  for (const todo of todos) {
    const completed: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.complete(connection, {
        todoId: todo.id,
      });
    typia.assert(completed);

    const reopened: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.reopen(connection, {
        todoId: todo.id,
      });
    typia.assert(reopened);
  }

  // 2. Create an admin user and keep that session for admin operations
  const adminJoinBody = {
    email: `admin+${RandomGenerator.alphaNumeric(8)}@example.com`,
    password: "Password!123" as string & tags.Format<"password">,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 3. As admin, query rate limit events index a few times to both generate and inspect admin traffic
  const indexRequestBody = {
    actor_type: null,
    ip: null,
    limit_key: null,
    limit_type: null,
    window_start_from: null,
    window_start_to: null,
    page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
    pageSize: 50 as number & tags.Type<"int32"> & tags.Minimum<1>,
    sort_by: null,
    sort_order: null,
  } satisfies ITodoAppRateLimitEvent.IRequest;

  // First index call
  const page1: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: indexRequestBody,
    });
  typia.assert(page1);

  // Optional additional admin traffic: call index again with same body
  const page2: IPageITodoAppRateLimitEvent.ISummary =
    await api.functional.todoApp.adminUser.rateLimitEvents.index(connection, {
      body: indexRequestBody,
    });
  typia.assert(page2);

  // Merge data from both pages (they may overlap; that's fine for discovery purposes)
  const allSummaries: ITodoAppRateLimitEvent.ISummary[] = [
    ...page1.data,
    ...page2.data,
  ];

  // If no events exist, assert that data arrays are empty and short-circuit
  if (allSummaries.length === 0) {
    TestValidator.equals(
      "no rate limit events available, index page1 empty",
      page1.data.length,
      0,
    );
    TestValidator.equals(
      "no rate limit events available, index page2 empty",
      page2.data.length,
      0,
    );
    return;
  }

  // Find at most one memberUser event and one adminUser event
  const memberSummary: ITodoAppRateLimitEvent.ISummary | undefined =
    allSummaries.find((ev) => ev.actor_type === "memberUser");
  const adminSummary: ITodoAppRateLimitEvent.ISummary | undefined =
    allSummaries.find((ev) => ev.actor_type === "adminUser");

  // If neither memberUser nor adminUser events exist, fall back to validating
  // scalar consistency for the first available event, regardless of actor_type.
  if (!memberSummary && !adminSummary) {
    const fallback = allSummaries[0];

    const detail: ITodoAppRateLimitEvent =
      await api.functional.todoApp.adminUser.rateLimitEvents.at(connection, {
        rateLimitEventId: fallback.id,
      });
    typia.assert(detail);

    // Scalar field consistency between summary and detail
    TestValidator.equals(
      "fallback event id matches between summary and detail",
      detail.id,
      fallback.id,
    );
    TestValidator.equals(
      "fallback actor_type matches between summary and detail",
      detail.actor_type,
      fallback.actor_type,
    );
    TestValidator.equals(
      "fallback ip matches between summary and detail",
      detail.ip ?? null,
      fallback.ip ?? null,
    );
    TestValidator.equals(
      "fallback limit_key matches between summary and detail",
      detail.limit_key,
      fallback.limit_key,
    );
    TestValidator.equals(
      "fallback limit_type matches between summary and detail",
      detail.limit_type,
      fallback.limit_type,
    );
    TestValidator.equals(
      "fallback window_start matches between summary and detail",
      detail.window_start,
      fallback.window_start,
    );
    TestValidator.equals(
      "fallback window_end matches between summary and detail",
      detail.window_end,
      fallback.window_end,
    );
    TestValidator.equals(
      "fallback created_at matches between summary and detail",
      detail.created_at,
      fallback.created_at,
    );

    // Minimal time sanity: created_at should not be before window_start
    const windowStart = new Date(detail.window_start).getTime();
    const createdAt = new Date(detail.created_at).getTime();
    TestValidator.predicate(
      "fallback detail.created_at is not earlier than window_start",
      createdAt >= windowStart,
    );

    // Associations cannot be asserted for a non-member/admin actor_type,
    // but ensure at least that both association fields are optional and can be null.
    TestValidator.predicate(
      "fallback member_user association may be null or defined",
      true,
    );
    TestValidator.predicate(
      "fallback admin_user association may be null or defined",
      true,
    );

    return;
  }

  // Helper to validate core scalar consistency and basic time sanity
  const assertScalarConsistency = (
    titlePrefix: string,
    summary: ITodoAppRateLimitEvent.ISummary,
    detail: ITodoAppRateLimitEvent,
  ): void => {
    TestValidator.equals(
      `${titlePrefix} id matches between summary and detail`,
      detail.id,
      summary.id,
    );
    TestValidator.equals(
      `${titlePrefix} actor_type matches between summary and detail`,
      detail.actor_type,
      summary.actor_type,
    );
    TestValidator.equals(
      `${titlePrefix} ip matches between summary and detail`,
      detail.ip ?? null,
      summary.ip ?? null,
    );
    TestValidator.equals(
      `${titlePrefix} limit_key matches between summary and detail`,
      detail.limit_key,
      summary.limit_key,
    );
    TestValidator.equals(
      `${titlePrefix} limit_type matches between summary and detail`,
      detail.limit_type,
      summary.limit_type,
    );
    TestValidator.equals(
      `${titlePrefix} window_start matches between summary and detail`,
      detail.window_start,
      summary.window_start,
    );
    TestValidator.equals(
      `${titlePrefix} window_end matches between summary and detail`,
      detail.window_end,
      summary.window_end,
    );
    TestValidator.equals(
      `${titlePrefix} created_at matches between summary and detail`,
      detail.created_at,
      summary.created_at,
    );

    const windowStartMs = new Date(detail.window_start).getTime();
    const createdAtMs = new Date(detail.created_at).getTime();
    TestValidator.predicate(
      `${titlePrefix} detail.created_at is not earlier than window_start`,
      createdAtMs >= windowStartMs,
    );
  };

  // 4. Validate memberUser event details and associations, if available
  if (memberSummary) {
    const memberDetail: ITodoAppRateLimitEvent =
      await api.functional.todoApp.adminUser.rateLimitEvents.at(connection, {
        rateLimitEventId: memberSummary.id,
      });
    typia.assert(memberDetail);

    assertScalarConsistency("memberUser event", memberSummary, memberDetail);

    TestValidator.equals(
      "memberUser event actor_type should be memberUser",
      memberDetail.actor_type,
      "memberUser",
    );

    TestValidator.predicate(
      "memberUser event should have non-null member_user association",
      memberDetail.member_user !== null &&
        memberDetail.member_user !== undefined,
    );
    TestValidator.predicate(
      "memberUser event should have null or undefined admin_user association",
      memberDetail.admin_user === null || memberDetail.admin_user === undefined,
    );
  } else {
    TestValidator.predicate(
      "no memberUser rate limit events available; skipping member association checks",
      true,
    );
  }

  // 5. Validate adminUser event details and associations, if available
  if (adminSummary) {
    const adminDetail: ITodoAppRateLimitEvent =
      await api.functional.todoApp.adminUser.rateLimitEvents.at(connection, {
        rateLimitEventId: adminSummary.id,
      });
    typia.assert(adminDetail);

    assertScalarConsistency("adminUser event", adminSummary, adminDetail);

    TestValidator.equals(
      "adminUser event actor_type should be adminUser",
      adminDetail.actor_type,
      "adminUser",
    );

    TestValidator.predicate(
      "adminUser event should have non-null admin_user association",
      adminDetail.admin_user !== null && adminDetail.admin_user !== undefined,
    );
    TestValidator.predicate(
      "adminUser event should have null or undefined member_user association",
      adminDetail.member_user === null || adminDetail.member_user === undefined,
    );
  } else {
    TestValidator.predicate(
      "no adminUser rate limit events available; skipping admin association checks",
      true,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate admin login-attempt search filtering by member login identifier and
 * time window.
 *
 * Business workflow:
 *
 * 1. Register two distinct member users via /auth/memberUser/join with different
 *    emails.
 * 2. For the first member, perform multiple login attempts (two successful and one
 *    failed) using /auth/memberUser/login.
 * 3. For the second member, perform successful login attempts only.
 * 4. Optionally create todos for both members to exercise authenticated flows.
 * 5. Capture an inclusive time window around the first member’s attempts.
 * 6. Register and authenticate an admin user via /auth/adminUser/join and
 *    /auth/adminUser/login.
 * 7. As admin, call PATCH /todoApp/adminUser/loginAttempts with filters:
 *    login_identifier of first member, created_from/to window, page=1, limit
 *    large enough.
 * 8. Assert that all returned login attempts belong to the first member, have
 *    actor_type indicating memberUser, and created_at within the window; and
 *    that attempts of the second member are excluded.
 * 9. Issue a second search with a narrower window to ensure fewer attempts are
 *    returned but still matching constraints.
 */
export async function test_api_admin_login_attempt_search_with_identifier_and_time_window(
  connection: api.IConnection,
) {
  // Common navigation context for auth flows
  const href: string = typia.random<string & tags.Format<"uri">>();
  const referrer: string = typia.random<string & tags.Format<"uri">>();

  // 1. Register two distinct member users
  const member1Email: string = typia.random<string & tags.Format<"email">>();
  const member2Email: string = typia.random<string & tags.Format<"email">>();

  const member1Password: string = typia.random<
    string & tags.Format<"password">
  >();
  const member2Password: string = typia.random<
    string & tags.Format<"password">
  >();

  const member1JoinBody = {
    email: member1Email,
    password: member1Password,
    display_name: RandomGenerator.name(),
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const member1Auth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: member1JoinBody,
    });
  typia.assert(member1Auth);

  const member2JoinBody = {
    email: member2Email,
    password: member2Password,
    display_name: RandomGenerator.name(),
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const member2Auth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: member2JoinBody,
    });
  typia.assert(member2Auth);

  // 2. First member: successful and failed logins
  // Capture timestamps before and after sequence to define window.
  const windowStart: string = new Date().toISOString();

  // Successful login #1 for member1
  const member1LoginBody1 = {
    email: member1Email,
    password: member1Password,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const member1Login1: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member1LoginBody1,
    });
  typia.assert(member1Login1);

  // Failed login for member1 using wrong password (business-level failure)
  const member1FailedPassword: string = typia.random<
    string & tags.Format<"password">
  >();
  const member1LoginBodyFailed = {
    email: member1Email,
    password: member1FailedPassword,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  await TestValidator.error(
    "member1 failed login attempt recorded",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: member1LoginBodyFailed,
      });
    },
  );

  // Successful login #2 for member1
  const member1LoginBody2 = {
    email: member1Email,
    password: member1Password,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const member1Login2: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member1LoginBody2,
    });
  typia.assert(member1Login2);

  const windowEnd: string = new Date().toISOString();

  // 3. Second member: only successful login attempts
  const member2LoginBody1 = {
    email: member2Email,
    password: member2Password,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const member2Login1: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member2LoginBody1,
    });
  typia.assert(member2Login1);

  const member2LoginBody2 = {
    email: member2Email,
    password: member2Password,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const member2Login2: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member2LoginBody2,
    });
  typia.assert(member2Login2);

  // 4. Optionally create todos for both members
  const todoBody1 = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;
  const todo1: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBody1,
    });
  typia.assert(todo1);

  // Switch to member2 (login again to bump token)
  const member2LoginForTodoBody = {
    email: member2Email,
    password: member2Password,
    ip: null,
    href,
    referrer,
  } satisfies ITodoAppMemberUserLogin.IRequest;
  const member2LoginForTodo: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: member2LoginForTodoBody,
    });
  typia.assert(member2LoginForTodo);

  const todoBody2 = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 4 }),
  } satisfies ITodoAppTodo.ICreate;
  const todo2: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoBody2,
    });
  typia.assert(todo2);

  // 5. Admin registration and login
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoin);

  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href,
    referrer,
    user_agent: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLogin);

  // 6. Admin searches login attempts for member1 within full window
  const searchBodyFullWindow = {
    page: 1,
    limit: 50,
    login_identifier: member1Email,
    actor_type: "memberUser",
    succeeded: undefined,
    ip: undefined,
    failure_reason: undefined,
    created_from: windowStart,
    created_to: windowEnd,
  } satisfies ITodoAppLoginAttempt.IRequest;

  const pageFull: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: searchBodyFullWindow,
    });
  typia.assert(pageFull);

  TestValidator.predicate(
    "full-window search returns at least one attempt for member1",
    pageFull.pagination.records > 0,
  );

  for (const attempt of pageFull.data) {
    typia.assert<ITodoAppLoginAttempt.ISummary>(attempt);

    TestValidator.equals(
      "login_identifier must equal member1 email in full-window search",
      attempt.login_identifier,
      member1Email,
    );

    TestValidator.equals(
      "actor_type must be memberUser in full-window search",
      attempt.actor_type,
      "memberUser",
    );

    TestValidator.predicate(
      "created_at must be within [windowStart, windowEnd]",
      attempt.created_at >= windowStart && attempt.created_at <= windowEnd,
    );

    if (attempt.memberUser !== undefined) {
      TestValidator.equals(
        "memberUser.email in summary must match member1 email",
        attempt.memberUser.email,
        member1Email,
      );
    }

    if (attempt.adminUser !== undefined) {
      TestValidator.equals(
        "adminUser.email, when present, must equal admin email",
        attempt.adminUser.email,
        adminEmail,
      );
    }
  }

  for (const attempt of pageFull.data) {
    TestValidator.notEquals(
      "no login attempt in result should belong to member2 email",
      attempt.login_identifier,
      member2Email,
    );
  }

  // 7. Narrower time window to exclude earliest attempts if possible
  const startDateObj = new Date(windowStart);
  const narrowedStartDate: string = new Date(
    startDateObj.getTime() + 500,
  ).toISOString();

  const searchBodyNarrowWindow = {
    page: 1,
    limit: 50,
    login_identifier: member1Email,
    actor_type: "memberUser",
    succeeded: undefined,
    ip: undefined,
    failure_reason: undefined,
    created_from: narrowedStartDate,
    created_to: windowEnd,
  } satisfies ITodoAppLoginAttempt.IRequest;

  const pageNarrow: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: searchBodyNarrowWindow,
    });
  typia.assert(pageNarrow);

  TestValidator.predicate(
    "narrow-window search returns zero or more attempts for member1",
    pageNarrow.pagination.records >= 0,
  );

  for (const attempt of pageNarrow.data) {
    typia.assert<ITodoAppLoginAttempt.ISummary>(attempt);

    TestValidator.equals(
      "login_identifier must equal member1 email in narrow-window search",
      attempt.login_identifier,
      member1Email,
    );

    TestValidator.predicate(
      "created_at must be within [narrowedStartDate, windowEnd]",
      attempt.created_at >= narrowedStartDate &&
        attempt.created_at <= windowEnd,
    );
  }

  if (pageFull.pagination.records > pageNarrow.pagination.records) {
    TestValidator.predicate(
      "narrow-window search should not expand the number of matched records",
      pageNarrow.pagination.records <= pageFull.pagination.records,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_login_attempt_search_by_ip_and_actor_type(
  connection: api.IConnection,
) {
  // Create distinct, deterministic IPs for two simulated client contexts.
  const ipA = "203.0.113.10";
  const ipB = "198.51.100.20";

  // Common href/referrer values for login/join requests.
  const href = "https://todo-app.example.com/login";
  const referrer = "https://todo-app.example.com/";

  // 1. Register a member user
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: ipA,
    href,
    referrer,
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuth: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuth);

  // 2. Register an admin user
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuth: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuth);

  // Helper to perform a member login with controllable IP
  const performMemberLogin = async (ip: string): Promise<void> => {
    const loginBody = {
      email: memberJoinBody.email,
      password: memberJoinBody.password,
      ip,
      href,
      referrer,
    } satisfies ITodoAppMemberUserLogin.IRequest;

    const auth: ITodoAppMemberuser.IAuthorized =
      await api.functional.auth.memberUser.login(connection, {
        body: loginBody,
      });
    typia.assert(auth);
  };

  // Helper to perform an admin login with controllable IP
  const performAdminLogin = async (ip: string): Promise<void> => {
    const loginBody = {
      email: adminJoinBody.email,
      password: adminJoinBody.password,
      ip,
      href,
      referrer,
      user_agent: "E2E-Test-Agent/1.0",
    } satisfies ITodoAppAdminUser.ILogin;

    const auth: ITodoAppAdminUser.IAuthorized =
      await api.functional.auth.adminUser.login(connection, {
        body: loginBody,
      });
    typia.assert(auth);
  };

  // 3. Generate login attempts from IP_A
  await performMemberLogin(ipA);
  await performMemberLogin(ipA);
  await performAdminLogin(ipA);

  // 4. Generate login attempts from IP_B
  await performMemberLogin(ipB);
  await performAdminLogin(ipB);

  // Ensure we end up authenticated as admin for the search call (IP_A context)
  await performAdminLogin(ipA);

  // 5. Admin searches login attempts filtered by IP_A and actor_type = "memberUser"
  const memberFilterBody = {
    page: 1,
    limit: 50,
    ip: ipA,
    actor_type: "memberUser",
  } satisfies ITodoAppLoginAttempt.IRequest;

  const memberAttemptsPage: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: memberFilterBody,
    });
  typia.assert(memberAttemptsPage);

  // Business assertions for memberUser attempts
  TestValidator.predicate(
    "memberUser loginAttempts search should return at least one record",
    memberAttemptsPage.data.length > 0,
  );

  for (const attempt of memberAttemptsPage.data) {
    typia.assert<ITodoAppLoginAttempt.ISummary>(attempt);
    TestValidator.equals(
      "all returned memberUser attempts should have matching ip",
      attempt.ip,
      ipA,
    );
    TestValidator.equals(
      "all returned attempts should be for actor_type memberUser",
      attempt.actor_type,
      "memberUser",
    );
  }

  // 6. Repeat search with actor_type = "adminUser" for IP_A
  const adminFilterBody = {
    page: 1,
    limit: 50,
    ip: ipA,
    actor_type: "adminUser",
  } satisfies ITodoAppLoginAttempt.IRequest;

  const adminAttemptsPage: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: adminFilterBody,
    });
  typia.assert(adminAttemptsPage);

  TestValidator.predicate(
    "adminUser loginAttempts search should return at least one record",
    adminAttemptsPage.data.length > 0,
  );

  for (const attempt of adminAttemptsPage.data) {
    typia.assert<ITodoAppLoginAttempt.ISummary>(attempt);
    TestValidator.equals(
      "all returned adminUser attempts should have matching ip",
      attempt.ip,
      ipA,
    );
    TestValidator.equals(
      "all returned attempts should be for actor_type adminUser",
      attempt.actor_type,
      "adminUser",
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_login_attempt_search_unauthorized_access_rejected(
  connection: api.IConnection,
) {
  // 1. Register a member user
  const memberJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.local/member/join",
    referrer: "https://todo-app.local/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Perform a member login to generate a login attempt
  const memberLoginBody = {
    email: memberJoinBody.email,
    password: memberJoinBody.password,
    ip: null,
    href: "https://todo-app.local/member/login",
    referrer: "https://todo-app.local/home",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLoginAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginAuthorized);

  // 3. Create a todo as the member to validate normal member flow
  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // Common search request payload (with simple pagination only)
  const requestedPage = 1;
  const requestedLimit = 10;
  const searchRequestBody = {
    page: requestedPage,
    limit: requestedLimit,
  } satisfies ITodoAppLoginAttempt.IRequest;

  // 4-a. Attempt to call admin loginAttempts without any Authorization header
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated caller cannot access admin loginAttempts",
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.index(
        unauthenticatedConnection,
        {
          body: searchRequestBody,
        },
      );
    },
  );

  // 4-b. Attempt to call admin loginAttempts with a memberUser token
  await TestValidator.error(
    "member user cannot access admin loginAttempts",
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
        body: searchRequestBody,
      });
    },
  );

  // 5. Register an admin user
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorized);

  // 6. Perform an explicit admin login to ensure admin token is active
  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://todo-app.local/admin/login",
    referrer: "https://todo-app.local/admin",
    user_agent: "e2e-agent/1.0",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginAuthorized: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginAuthorized);

  // 7. Call admin loginAttempts with valid admin token and assert success
  const adminSearchRequestBody = {
    page: requestedPage,
    limit: requestedLimit,
  } satisfies ITodoAppLoginAttempt.IRequest;

  const page: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: adminSearchRequestBody,
    });
  typia.assert(page);

  // Normalize tagged numeric types to plain numbers for comparison
  const currentPageNumber = page.pagination.current satisfies number as number;
  const currentLimitNumber = page.pagination.limit satisfies number as number;

  TestValidator.equals(
    "pagination current page should equal requested page",
    currentPageNumber,
    requestedPage,
  );
  TestValidator.equals(
    "pagination limit should equal requested limit",
    currentLimitNumber,
    requestedLimit,
  );

  // Validate that all returned records (if any) have consistent structure
  await ArrayUtil.asyncForEach(page.data, async (attempt, index) => {
    typia.assert<ITodoAppLoginAttempt.ISummary>(attempt);

    TestValidator.predicate(
      `actor_type must be a non-empty string at index ${index}`,
      attempt.actor_type.length > 0,
    );

    TestValidator.predicate(
      `created_at must be a non-empty string at index ${index}`,
      attempt.created_at.length > 0,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

/**
 * Validate that an admin user can retrieve detailed information about a
 * specific login attempt by its identifier.
 *
 * Business context:
 *
 * - Todo_app_login_attempts is an immutable audit log capturing both member and
 *   admin authentication attempts.
 * - Admin users must be able to search for login attempts and then drill down
 *   into a specific record to inspect full details (identifier, actor type,
 *   success flag, IP, and linked user summaries).
 *
 * This test performs a realistic, end-to-end lifecycle:
 *
 * 1. Register a member user and perform multiple login attempts to populate login
 *    attempts for a non-admin actor.
 * 2. Create a todo as the member to ensure the member user is a real, active actor
 *    with normal application usage.
 * 3. Register and log in as an admin user so that:
 *
 *    - Admin login attempts themselves are recorded, and
 *    - The connection is authenticated as an admin for secure endpoints.
 * 4. As the admin, call PATCH /todoApp/adminUser/loginAttempts to search for login
 *    attempts, filtering by a known login_identifier or actor_type to ensure at
 *    least one record is returned.
 * 5. Capture one ITodoAppLoginAttempt.ISummary, then invoke GET
 *    /todoApp/adminUser/loginAttempts/{loginAttemptId} using the summary.id.
 * 6. Assert that the detailed ITodoAppLoginAttempt returned by the GET call
 *    matches the summary on core fields (id, login_identifier, actor_type,
 *    succeeded, ip, failure_reason, created_at) and that the
 *    memberUser/adminUser relational summaries are consistent with the
 *    actor_type and any summary-provided relations.
 * 7. Optionally re-fetch the same id to confirm the endpoint is side-effect-free
 *    and returns a stable record.
 */
export async function test_api_admin_login_attempt_detail_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Register a member user
  const memberJoinRequest = typia.random<ITodoAppMemberUserJoin.IRequest>();
  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinRequest,
    });
  typia.assert(memberAuthorized);

  // 2. Perform member login attempts (one success, one failure)
  const memberLoginSuccessRequest: ITodoAppMemberUserLogin.IRequest = {
    email: memberJoinRequest.email,
    password: memberJoinRequest.password,
    href: memberJoinRequest.href,
    referrer: memberJoinRequest.referrer,
    ip: memberJoinRequest.ip ?? null,
  };
  const memberLoginAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginSuccessRequest,
    });
  typia.assert(memberLoginAuthorized);

  const memberLoginFailureRequest: ITodoAppMemberUserLogin.IRequest = {
    email: memberJoinRequest.email,
    password: typia.random<ITodoAppMemberUserLogin.IRequest>().password,
    href: memberJoinRequest.href,
    referrer: memberJoinRequest.referrer,
    ip: memberJoinRequest.ip ?? null,
  };
  await TestValidator.error(
    "member login failure attempt recorded",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: memberLoginFailureRequest,
      });
    },
  );

  // 3. Create a todo as the authenticated member user
  const todoCreateBody = typia.random<ITodoAppTodo.ICreate>();
  const createdTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: todoCreateBody,
    });
  typia.assert(createdTodo);

  // 4. Register an admin user
  const adminJoinBase = typia.random<ITodoAppAdminUser.IJoin>();
  const adminEmail = adminJoinBase.email;
  const adminPassword = adminJoinBase.password;
  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        display_name: adminJoinBase.display_name,
      },
    });
  typia.assert(adminAuthorizedFromJoin);

  // 5. Admin login to create login attempts and ensure admin auth context
  const adminLoginBase = typia.random<ITodoAppAdminUser.ILogin>();
  const adminLoginRequest: ITodoAppAdminUser.ILogin = {
    email: adminEmail,
    password: adminPassword,
    href: adminLoginBase.href,
    referrer: adminLoginBase.referrer,
    ip: adminLoginBase.ip ?? null,
    user_agent: adminLoginBase.user_agent ?? null,
  };
  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginRequest,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 6. Search login attempts as admin
  const primarySearchBody: ITodoAppLoginAttempt.IRequest = {
    page: 1 as number & tags.Type<"int32">,
    limit: 20 as number & tags.Type<"int32">,
    login_identifier: adminEmail,
    actor_type: "adminUser",
    succeeded: undefined,
    ip: undefined,
    failure_reason: undefined,
    created_from: null,
    created_to: null,
  };
  let page: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: primarySearchBody,
    });
  typia.assert(page);

  if (page.data.length === 0) {
    const fallbackSearchBody: ITodoAppLoginAttempt.IRequest = {
      page: 1 as number & tags.Type<"int32">,
      limit: 20 as number & tags.Type<"int32">,
      actor_type: "adminUser",
      login_identifier: undefined,
      succeeded: undefined,
      ip: undefined,
      failure_reason: undefined,
      created_from: null,
      created_to: null,
    };
    page = await api.functional.todoApp.adminUser.loginAttempts.index(
      connection,
      {
        body: fallbackSearchBody,
      },
    );
    typia.assert(page);
  }

  TestValidator.predicate(
    "at least one login attempt should exist for admin search",
    page.data.length > 0,
  );

  const summary: ITodoAppLoginAttempt.ISummary = page.data[0];
  typia.assert(summary);

  // 7. Retrieve detail by loginAttemptId as admin
  const detail: ITodoAppLoginAttempt =
    await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
      loginAttemptId: summary.id,
    });
  typia.assert(detail);

  // 8. Compare core fields between summary and detail
  TestValidator.equals(
    "login attempt id should match between summary and detail",
    detail.id,
    summary.id,
  );
  TestValidator.equals(
    "login_identifier should match between summary and detail",
    detail.login_identifier,
    summary.login_identifier,
  );
  TestValidator.equals(
    "actor_type should match between summary and detail",
    detail.actor_type,
    summary.actor_type,
  );
  TestValidator.equals(
    "succeeded flag should match between summary and detail",
    detail.succeeded,
    summary.succeeded,
  );
  TestValidator.equals(
    "ip should match between summary and detail",
    detail.ip,
    summary.ip,
  );
  TestValidator.equals(
    "failure_reason should match between summary and detail",
    detail.failure_reason ?? null,
    summary.failure_reason ?? null,
  );
  TestValidator.equals(
    "created_at should match between summary and detail",
    detail.created_at,
    summary.created_at,
  );

  // 9. Validate memberUser/adminUser summary consistency
  if (summary.memberUser !== undefined && summary.memberUser !== null) {
    TestValidator.predicate(
      "detail.memberUser should be defined when summary.memberUser exists",
      detail.memberUser !== undefined && detail.memberUser !== null,
    );
    if (detail.memberUser !== undefined && detail.memberUser !== null) {
      TestValidator.equals(
        "memberUser.id should match between summary and detail",
        detail.memberUser.id,
        summary.memberUser.id,
      );
      TestValidator.equals(
        "memberUser.email should match between summary and detail",
        detail.memberUser.email,
        summary.memberUser.email,
      );
    }
  } else {
    TestValidator.predicate(
      "detail.memberUser may be undefined when summary.memberUser is absent",
      detail.memberUser === undefined || detail.memberUser === null,
    );
  }

  if (summary.adminUser !== undefined && summary.adminUser !== null) {
    TestValidator.predicate(
      "detail.adminUser should be defined when summary.adminUser exists",
      detail.adminUser !== undefined && detail.adminUser !== null,
    );
    if (detail.adminUser !== undefined && detail.adminUser !== null) {
      TestValidator.equals(
        "adminUser.id should match between summary and detail",
        detail.adminUser.id,
        summary.adminUser.id,
      );
      TestValidator.equals(
        "adminUser.email should match between summary and detail",
        detail.adminUser.email,
        summary.adminUser.email,
      );
    }
  } else {
    TestValidator.predicate(
      "detail.adminUser may be undefined when summary.adminUser is absent",
      detail.adminUser === undefined || detail.adminUser === null,
    );
  }

  // 10. Re-fetch the same loginAttemptId to confirm idempotent read
  const detailAgain: ITodoAppLoginAttempt =
    await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
      loginAttemptId: summary.id,
    });
  typia.assert(detailAgain);

  TestValidator.equals(
    "detail re-fetch should yield the same record as initial detail",
    detailAgain,
    detail,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Validate not-found behavior for admin login attempt detail endpoint.
 *
 * This E2E test ensures that GET
 * /todoApp/adminUser/loginAttempts/{loginAttemptId} returns an HTTP not-found
 * error (404) when the specified loginAttemptId does not exist, while valid
 * admin authentication is in place and system state remains unaffected.
 */
export async function test_api_admin_login_attempt_detail_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Register an admin user so that we have a legitimate admin actor.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const joinBody = {
    email: adminEmail,
    password: adminPassword,
    // display_name is optional; omit it to keep the payload minimal.
  } satisfies ITodoAppAdminUser.IJoin;

  const joinedAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: joinBody,
    });
  typia.assert(joinedAdmin);

  // 2. Perform a successful admin login to ensure a real login attempt exists
  //    and to simulate realistic authentication flows.
  const loginBody = {
    email: adminEmail,
    password: adminPassword,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    // ip and user_agent are optional; omit for simplicity.
  } satisfies ITodoAppAdminUser.ILogin;

  const loggedInAdmin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: loginBody,
    });
  typia.assert(loggedInAdmin);

  // 3. Generate two random UUIDs that are extremely unlikely to match any
  //    existing login attempt IDs. We do not create attempts with these IDs.
  const unknownLoginAttemptId1: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const unknownLoginAttemptId2: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 4. Assert that fetching details for the first unknown loginAttemptId
  //    results in an HTTP 404 not-found error.
  await TestValidator.httpError(
    "admin login attempt detail returns 404 for first unknown id",
    404,
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
        loginAttemptId: unknownLoginAttemptId1,
      });
    },
  );

  // 5. Assert that a second unknown loginAttemptId also yields 404, verifying
  //    consistent behavior for different non-existent IDs.
  await TestValidator.httpError(
    "admin login attempt detail returns 404 for second unknown id",
    404,
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
        loginAttemptId: unknownLoginAttemptId2,
      });
    },
  );

  // 6. Optional sanity check: ensure that valid IDs still succeed.
  //
  // We cannot directly obtain the ID of the login attempt created by the
  // login call, because the login endpoint returns only the authorized admin
  // context, not the attempt ID. Therefore, we skip a positive-path fetch
  // using a real loginAttemptId here and rely on dedicated tests for
  // /todoApp/adminUser/loginAttempts/:loginAttemptId success behavior.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";

/**
 * Verify access control for login attempt detail retrieval.
 *
 * Business purpose: Ensure that the sensitive audit trail of authentication
 * attempts is only readable by admin users. Unauthenticated callers and regular
 * member users must not be able to retrieve individual login attempt details.
 *
 * Scenario steps:
 *
 * 1. Register a member account and execute a few login attempts so that
 *    todo_app_login_attempts contains at least one record involving this
 *    member.
 * 2. Register an admin account and log in as that admin so that admin-related
 *    login attempts also exist and to obtain a valid Authorization header for
 *    subsequent admin-only calls.
 * 3. As the admin user, search login attempts via PATCH
 *    /todoApp/adminUser/loginAttempts with filters that match at least one
 *    recent record and pick one loginAttemptId from the result.
 * 4. Call GET /todoApp/adminUser/loginAttempts/{loginAttemptId} using a connection
 *    without Authorization headers and ensure it throws an error
 *    (authentication/authorization failure).
 * 5. Log in as the member user, then call the same GET endpoint with the member
 *    token and ensure it also throws an error (member is not allowed to read
 *    login attempts).
 * 6. Log back in as the admin user and call GET
 *    /todoApp/adminUser/loginAttempts/{loginAttemptId} again, asserting that it
 *    succeeds and returns a valid ITodoAppLoginAttempt whose id matches the
 *    selected loginAttemptId.
 */
export async function test_api_admin_login_attempt_detail_access_control(
  connection: api.IConnection,
) {
  // 1. Register a member user.
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/member/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberAuthorized);

  // 2. Perform multiple member login attempts (both success and failure) to
  // ensure login attempts are recorded.
  const memberLoginBase = {
    email: memberEmail,
    ip: null,
    href: "https://todo-app.example.com/member/login",
    referrer: "https://todo-app.example.com/landing",
  } satisfies Omit<ITodoAppMemberUserLogin.IRequest, "password">;

  // 2-1. Failed login attempt: wrong password.
  const wrongPasswordLoginBody = {
    ...memberLoginBase,
    password: typia.random<string & tags.Format<"password">>(),
  } satisfies ITodoAppMemberUserLogin.IRequest;

  await TestValidator.error(
    "member login with wrong password should fail",
    async () => {
      await api.functional.auth.memberUser.login(connection, {
        body: wrongPasswordLoginBody,
      });
    },
  );

  // 2-2. Successful login attempt with correct password.
  const correctPasswordLoginBody = {
    ...memberLoginBase,
    password: memberPassword,
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLoginResult: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: correctPasswordLoginBody,
    });
  typia.assert(memberLoginResult);

  // 3. Register an admin user.
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoinResult: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoinResult);

  // 4. Log in as the admin user to ensure we have a fresh admin session and
  // that admin login attempts are also recorded.
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "e2e-test-agent",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginResult: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginResult);

  // 5. As admin, search login attempts to obtain a valid loginAttemptId.
  // Prefer to search by the member's login_identifier so we know exactly
  // which attempt we are going to inspect.
  const searchBody = {
    page: 1,
    limit: 10,
    login_identifier: memberEmail,
    actor_type: "memberUser",
    succeeded: undefined,
    ip: undefined,
    failure_reason: undefined,
    created_from: null,
    created_to: null,
  } satisfies ITodoAppLoginAttempt.IRequest;

  const pageResult: IPageITodoAppLoginAttempt.ISummary =
    await api.functional.todoApp.adminUser.loginAttempts.index(connection, {
      body: searchBody,
    });
  typia.assert(pageResult);

  // Ensure there's at least one login attempt returned; if not, the test
  // setup would not have created any relevant records.
  TestValidator.predicate(
    "login attempts search should return at least one record for member",
    pageResult.data.length > 0,
  );

  const pickedSummary: ITodoAppLoginAttempt.ISummary = pageResult.data[0];
  const targetLoginAttemptId = pickedSummary.id;

  // 6. Call detail endpoint without any Authorization header and expect an
  // error.
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };

  await TestValidator.error(
    "unauthenticated caller must not access login attempt detail",
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.at(
        unauthenticatedConnection,
        {
          loginAttemptId: targetLoginAttemptId,
        },
      );
    },
  );

  // 7. Log in as the member user and ensure member cannot read login attempt
  // details.
  const memberReLoginBody = {
    ...memberLoginBase,
    password: memberPassword,
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberReLoginResult: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberReLoginBody,
    });
  typia.assert(memberReLoginResult);

  await TestValidator.error(
    "member user must not access login attempt detail",
    async () => {
      await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
        loginAttemptId: targetLoginAttemptId,
      });
    },
  );

  // 8. Log back in as admin to restore admin Authorization.
  const adminReLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "e2e-test-agent",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminReLoginResult: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminReLoginBody,
    });
  typia.assert(adminReLoginResult);

  // 9. As admin, successfully retrieve the login attempt detail and validate
  // its consistency.
  const detail: ITodoAppLoginAttempt =
    await api.functional.todoApp.adminUser.loginAttempts.at(connection, {
      loginAttemptId: targetLoginAttemptId,
    });
  typia.assert(detail);

  TestValidator.equals(
    "loginAttempt detail id should match requested id",
    detail.id,
    targetLoginAttemptId,
  );

  // Basic consistency check: login_identifier and actor_type in the detail
  // should match the summary we picked.
  TestValidator.equals(
    "loginAttempt detail login_identifier should match summary",
    detail.login_identifier,
    pickedSummary.login_identifier,
  );

  TestValidator.equals(
    "loginAttempt detail actor_type should match summary",
    detail.actor_type,
    pickedSummary.actor_type,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

export async function test_api_guest_user_detail_after_guest_join(
  connection: api.IConnection,
) {
  // 1. Join as a guest user from an unauthenticated context
  const joinBody = {
    // Provide a stable display name to assert round-trip consistency
    display_name: RandomGenerator.name(2),
  } satisfies ITodoAppGuestUser.IJoin;

  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: joinBody,
    });
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorized);

  // Capture fields from the authorized payload for later comparison
  const guestId = authorized.id;
  const joinDisplayName = authorized.display_name ?? null;
  const joinCreatedAt = authorized.created_at;
  const joinUpdatedAt = authorized.updated_at;
  const joinDeletedAt = authorized.deleted_at ?? null;

  // Sanity-check invariants on the authorized payload
  TestValidator.predicate("guest id is non-empty uuid", () => {
    return typeof guestId === "string" && guestId.length > 0;
  });
  TestValidator.predicate("guest created_at is non-empty", () => {
    return typeof joinCreatedAt === "string" && joinCreatedAt.length > 0;
  });
  TestValidator.predicate("guest updated_at is non-empty", () => {
    return typeof joinUpdatedAt === "string" && joinUpdatedAt.length > 0;
  });

  // 2. Call the detail endpoint for this guest user
  const detail1: ITodoAppGuestUser =
    await api.functional.todoApp.guestUser.guestUsers.at(connection, {
      guestUserId: guestId,
    });
  typia.assert<ITodoAppGuestUser>(detail1);

  // 3. Validate that detail matches the authorized payload
  TestValidator.equals("detail.id matches authorized.id", detail1.id, guestId);
  TestValidator.equals(
    "detail.created_at matches authorized.created_at",
    detail1.created_at,
    joinCreatedAt,
  );
  TestValidator.equals(
    "detail.updated_at matches authorized.updated_at",
    detail1.updated_at,
    joinUpdatedAt,
  );

  // deleted_at should mirror the join payload (typically null)
  TestValidator.equals(
    "detail.deleted_at matches authorized.deleted_at",
    detail1.deleted_at ?? null,
    joinDeletedAt,
  );

  // display_name round-trip: may be null/undefined or the provided value
  TestValidator.equals(
    "detail.display_name matches authorized.display_name",
    detail1.display_name ?? null,
    joinDisplayName,
  );

  // 4. Call the detail endpoint again to confirm read-only behavior
  const detail2: ITodoAppGuestUser =
    await api.functional.todoApp.guestUser.guestUsers.at(connection, {
      guestUserId: guestId,
    });
  typia.assert<ITodoAppGuestUser>(detail2);

  // 5. Compare first and second detail responses
  TestValidator.equals("second detail id is stable", detail2.id, detail1.id);
  TestValidator.equals(
    "second detail created_at is stable",
    detail2.created_at,
    detail1.created_at,
  );
  TestValidator.equals(
    "second detail deleted_at is stable",
    detail2.deleted_at ?? null,
    detail1.deleted_at ?? null,
  );

  // updated_at should never go backwards; allow equality or forward movement
  TestValidator.predicate("detail.updated_at is monotonic", () => {
    const first = new Date(detail1.updated_at).getTime();
    const second = new Date(detail2.updated_at).getTime();
    return second >= first;
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

/**
 * Validate not-found behavior when requesting guest user details using a
 * non-existent identifier while authenticated as a guestUser.
 *
 * Business objectives
 *
 * - Ensure the detail endpoint does not accidentally return an ITodoAppGuestUser
 *   record when the requested id does not exist.
 * - Confirm that the system returns an HttpError-style failure instead of a
 *   successful 200 response.
 * - Verify that the error payload does not expose internal persistence
 *   implementation details such as Prisma table names or raw SQL fragments.
 * - Exercise the endpoint using a realistic valid guestUser Authorization context
 *   obtained from POST /auth/guestUser/join.
 *
 * Test steps
 *
 * 1. Call api.functional.auth.guestUser.join once with a minimal valid
 *    ITodoAppGuestUser.IJoin body (e.g., omit display_name) to obtain an
 *    ITodoAppGuestUser.IAuthorized payload. This also causes the SDK to set the
 *    Authorization header on the provided connection.
 * 2. Generate a random UUID string (string & tags.Format<"uuid">) that is
 *    extremely unlikely to correspond to an existing todo_app_guestusers.id in
 *    the database.
 * 3. Call api.functional.todoApp.guestUser.guestUsers.at with props.guestUserId
 *    equal to the generated UUID while reusing the same connection instance so
 *    that a valid guestUser token is present.
 * 4. Expect the call to fail with an HttpError, because the referenced guest
 *    record should not exist. Use TestValidator.error to assert that an error
 *    is thrown rather than a successful ITodoAppGuestUser response.
 * 5. Inside the error handling assertion, verify that:
 *
 *    - The thrown error is an instance of api.HttpError.
 *    - Its serialized payload via toJSON() does not contain obviously sensitive
 *         internal details such as the literal substring "todo_app_guestusers"
 *         or "Prisma" or "SELECT" that would indicate raw SQL or ORM internals
 *         being leaked.
 *    - The error message text remains non-empty and human-readable, but do not
 *         assert an exact string value.
 * 6. Do not assert on the exact numeric HTTP status code to avoid coupling this
 *    test to specific status code policy.
 */
export async function test_api_guest_user_detail_not_found_for_unknown_id(
  connection: api.IConnection,
) {
  // 1. Initialize guest user authorization context via join endpoint
  const authorized: ITodoAppGuestUser.IAuthorized =
    await api.functional.auth.guestUser.join(connection, {
      body: {},
    });
  typia.assert(authorized);

  // 2. Generate a random UUID string that is extremely unlikely to exist
  const unknownGuestUserId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();

  // 3-5. Attempt to load the non-existent guest user detail and validate error shape
  await TestValidator.error(
    "guest user detail with unknown id must fail and not leak internals",
    async () => {
      try {
        await api.functional.todoApp.guestUser.guestUsers.at(connection, {
          guestUserId: unknownGuestUserId,
        });
      } catch (exp) {
        // Ensure the error is an HttpError instance
        TestValidator.predicate(
          "error should be instance of HttpError",
          exp instanceof api.HttpError,
        );

        if (exp instanceof api.HttpError) {
          const json = exp.toJSON<unknown>();
          const rawMessage = json.message;

          let messageText: string | null = null;
          if (typeof rawMessage === "string") {
            messageText = rawMessage;
          } else if (rawMessage !== null && rawMessage !== undefined) {
            try {
              messageText = JSON.stringify(rawMessage);
            } catch {
              messageText = "";
            }
          }

          if (messageText !== null) {
            // Message should be non-empty
            TestValidator.predicate(
              "error message should be non-empty",
              messageText.trim().length > 0,
            );

            const lowered = messageText.toLowerCase();

            // Ensure no obvious internal implementation details leak out
            TestValidator.predicate(
              "error message must not expose todo_app_guestusers table name",
              lowered.indexOf("todo_app_guestusers") === -1,
            );
            TestValidator.predicate(
              "error message must not expose Prisma internals",
              lowered.indexOf("prisma") === -1,
            );
            TestValidator.predicate(
              "error message must not expose raw SQL keywords like SELECT",
              lowered.indexOf("select ") === -1,
            );
          }
        }

        // Re-throw so that TestValidator.error can observe the failure
        throw exp;
      }

      // If no error was thrown, explicitly fail the test by throwing
      throw new Error(
        "guest user detail request unexpectedly succeeded for unknown id",
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import type { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";

/**
 * Ensure guest user detail ignores logically deleted or non-existent records.
 *
 * ## Business intent
 *
 * The todoApp service tracks guest identities in the `todo_app_guestusers`
 * table, exposing them via the guestUser detail endpoint: GET
 * /todoApp/guestUser/guestUsers/{guestUserId} which returns an
 * ITodoAppGuestUser snapshot.
 *
 * Logical deletion is modeled by the nullable `deleted_at` column. When
 * `deleted_at` is non-null, the record should be treated as retired and must
 * not be presented as an active guest user detail to callers operating in the
 * guestUser context. Conversely, records whose `deleted_at` is null remain
 * active and should be fully retrievable.
 *
 * Within this E2E test harness we cannot directly toggle `deleted_at` in the
 * database, so we validate the observable behaviors we _can_ drive through the
 * public SDK while honoring type safety and compilation constraints.
 *
 * ## Scenario steps
 *
 * 1. Create two independent guest user identities via POST /auth/guestUser/join
 *    using the SDK function api.functional.auth.guestUser.join.
 *
 *    - Each call accepts ITodoAppGuestUser.IJoin as its body and returns
 *         ITodoAppGuestUser.IAuthorized, which includes the guest id and
 *         token.
 *    - We assert the authorized payload structure with typia.assert and keep the
 *         `id` fields as guestUserIdA and guestUserIdB.
 * 2. For each authorized guest id, call the detail endpoint:
 *    api.functional.todoApp.guestUser.guestUsers.at(connection, { guestUserId
 *    })
 *
 *    - The response type is ITodoAppGuestUser; assert it with typia.assert.
 *    - Validate via TestValidator.equals that `detail.id` matches the authorized
 *         `id` that was used to query it.
 *    - As a sanity check on active status, verify that `detail.deleted_at` is either
 *         null or undefined, since join must not return a guest whose
 *         deleted_at is non-null at issuance time.
 * 3. Simulate a lookup of a non-existent (or logically deleted) guest user id.
 *
 *    - Generate a random UUID-like value that is guaranteed not to equal either
 *         guestUserIdA or guestUserIdB. For example, loop until typia.random
 *         returns an id distinct from both.
 *    - Invoke the detail endpoint with this unknown id, wrapped inside
 *         TestValidator.error with an async callback and awaited, to assert
 *         that the call fails with some HttpError (not-found or
 *         domain-specific).
 *    - We deliberately do not assert a specific HTTP status code; only that an error
 *         is thrown and the endpoint does not succeed for a clearly unknown
 *         id.
 * 4. Confirm isolation of records.
 *
 *    - After the error scenario, re-call the detail endpoint for guestUserIdA (or B)
 *         and confirm it still succeeds and returns a matching id, proving that
 *         an error for one id does not affect other active guest records.
 *
 * ## Implementation notes
 *
 * - Use only the imports provided by the template (api, typia, TestValidator,
 *   RandomGenerator, ArrayUtil, ITodoAppGuestUser, IAuthorizationToken,
 *   ITodoAppGuestUserMetadata).
 * - Do not touch connection.headers directly; the join call already manages
 *   Authorization headers via the SDK.
 * - Never send invalid types or shapes; use ITodoAppGuestUser.IJoin for join
 *   request bodies and rely on typia.assert for all responses.
 * - Do not test specific HTTP status codes in the error case; only that an error
 *   is raised for an obviously unknown guestUserId.
 */
export async function test_api_guest_user_detail_ignores_deleted_records(
  connection: api.IConnection,
) {
  // 1. Create two active guest users via the public join endpoint.
  const authorizedA = await api.functional.auth.guestUser.join(connection, {
    body: typia.random<ITodoAppGuestUser.IJoin>(),
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorizedA);

  const authorizedB = await api.functional.auth.guestUser.join(connection, {
    body: typia.random<ITodoAppGuestUser.IJoin>(),
  });
  typia.assert<ITodoAppGuestUser.IAuthorized>(authorizedB);

  // 2. Fetch detail for each authorized guest id and validate active state.
  const detailA = await api.functional.todoApp.guestUser.guestUsers.at(
    connection,
    { guestUserId: authorizedA.id },
  );
  typia.assert<ITodoAppGuestUser>(detailA);
  TestValidator.equals(
    "detail for guest A should match authorized id",
    detailA.id,
    authorizedA.id,
  );
  TestValidator.predicate(
    "guest A should not be logically deleted (deleted_at null or undefined)",
    detailA.deleted_at === null || detailA.deleted_at === undefined,
  );

  const detailB = await api.functional.todoApp.guestUser.guestUsers.at(
    connection,
    { guestUserId: authorizedB.id },
  );
  typia.assert<ITodoAppGuestUser>(detailB);
  TestValidator.equals(
    "detail for guest B should match authorized id",
    detailB.id,
    authorizedB.id,
  );
  TestValidator.predicate(
    "guest B should not be logically deleted (deleted_at null or undefined)",
    detailB.deleted_at === null || detailB.deleted_at === undefined,
  );

  // 3. Simulate a lookup for a non-existent / logically deleted guest id.
  // Ensure the unknown id does not collide with existing ones.
  const existingIds: string[] = [authorizedA.id, authorizedB.id];
  let unknownId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  while (existingIds.includes(unknownId)) {
    unknownId = typia.random<string & tags.Format<"uuid">>();
  }

  await TestValidator.error(
    "detail endpoint should fail for non-existent or logically deleted guest id",
    async () => {
      await api.functional.todoApp.guestUser.guestUsers.at(connection, {
        guestUserId: unknownId,
      });
    },
  );

  // 4. Re-verify that an existing active guest is still retrievable.
  const detailAAgain = await api.functional.todoApp.guestUser.guestUsers.at(
    connection,
    { guestUserId: authorizedA.id },
  );
  typia.assert<ITodoAppGuestUser>(detailAAgain);
  TestValidator.equals(
    "detail for guest A remains accessible after error scenario",
    detailAAgain.id,
    authorizedA.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_member_user_search_by_email_filter(
  connection: api.IConnection,
) {
  // 1. Prepare an admin user and authenticate
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminAuthorizedFromJoin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminAuthorizedFromJoin);

  // 2. Create two member users with controlled email patterns
  const baseMemberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const atIndex = baseMemberEmail.indexOf("@");
  const filterSubstring: string =
    atIndex > 1 ? baseMemberEmail.substring(0, atIndex) : baseMemberEmail;

  const matchingMemberEmail: string & tags.Format<"email"> = baseMemberEmail;

  const commonMemberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  // 2-1. Join matching member
  const matchingMemberJoinBody = {
    email: matchingMemberEmail,
    password: commonMemberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const matchingMemberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: matchingMemberJoinBody,
    });
  typia.assert(matchingMemberAuthorized);

  // 2-2. Create a todo for matching member to simulate activity
  const matchingTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const matchingTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: matchingTodoBody,
    });
  typia.assert(matchingTodo);

  // 2-3. Join non-matching member with an email that does NOT contain the substring
  let nonMatchingMemberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  // Ensure the non-matching email truly does not contain the filter substring
  while (nonMatchingMemberEmail.includes(filterSubstring)) {
    nonMatchingMemberEmail = typia.random<string & tags.Format<"email">>();
  }

  const nonMatchingMemberJoinBody = {
    email: nonMatchingMemberEmail,
    password: commonMemberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const nonMatchingMemberAuthorized: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: nonMatchingMemberJoinBody,
    });
  typia.assert(nonMatchingMemberAuthorized);

  // 2-4. Create a todo for non-matching member
  const nonMatchingTodoBody = {
    title: RandomGenerator.paragraph({ sentences: 2 }),
    description: RandomGenerator.paragraph({ sentences: 5 }),
  } satisfies ITodoAppTodo.ICreate;

  const nonMatchingTodo: ITodoAppTodo =
    await api.functional.todoApp.memberUser.todos.create(connection, {
      body: nonMatchingTodoBody,
    });
  typia.assert(nonMatchingTodo);

  // 3. Re-authenticate as admin to perform member search
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
    user_agent: null,
  } satisfies ITodoAppAdminUser.ILogin;

  const adminAuthorizedFromLogin: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminAuthorizedFromLogin);

  // 4. Execute the memberUsers.index search with email substring filter
  const searchRequestBody = {
    page: 1,
    limit: 10,
    email: filterSubstring,
  } satisfies ITodoAppMemberuser.IRequest;

  const page: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: searchRequestBody,
    });
  typia.assert(page);

  // 5. Validate pagination metadata
  const pagination = page.pagination;
  TestValidator.predicate(
    "pagination current page should be 1",
    () => pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit should be >= data length",
    () => pagination.limit >= page.data.length,
  );
  TestValidator.predicate(
    "pagination records should equal data length",
    () => pagination.records === page.data.length,
  );
  TestValidator.predicate(
    "pagination pages should be at least 1 when records > 0",
    () =>
      pagination.records === 0 ? pagination.pages === 0 : pagination.pages >= 1,
  );

  // 6. Validate filter correctness: all returned emails contain the substring
  for (const summary of page.data) {
    TestValidator.predicate(
      "returned member email should contain filter substring",
      () => summary.email.includes(filterSubstring),
    );
  }

  // 7. Ensure that the matching member is included and non-matching is excluded
  const hasMatching = page.data.some(
    (summary) => summary.email === matchingMemberEmail,
  );
  const hasNonMatching = page.data.some(
    (summary) => summary.email === nonMatchingMemberEmail,
  );

  TestValidator.predicate(
    "search result must include matching member email",
    hasMatching,
  );
  TestValidator.predicate(
    "search result must not include non-matching member email",
    !hasNonMatching,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_member_user_search_created_at_range(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain admin context
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoin = await api.functional.auth.adminUser.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      display_name: RandomGenerator.name(),
    } satisfies ITodoAppAdminUser.IJoin,
  });
  typia.assert(adminJoin);

  // 2. Explicitly login as admin to simulate typical flow (ensures token header is set)
  const adminLogin = await api.functional.auth.adminUser.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      ip: null,
      href: "https://admin.todo-app.test/login",
      referrer: "https://admin.todo-app.test/",
      user_agent: "e2e-test-agent",
    } satisfies ITodoAppAdminUser.ILogin,
  });
  typia.assert(adminLogin);

  // Helper to create a member user via auth join
  const createMemberUser = async () => {
    const email = typia.random<string & tags.Format<"email">>();
    const password = typia.random<string & tags.Format<"password">>();

    const authorized = await api.functional.auth.memberUser.join(connection, {
      body: {
        email,
        password,
        display_name: RandomGenerator.name(),
        ip: null,
        href: "https://todo-app.test/join",
        referrer: "https://todo-app.test/landing",
      } satisfies ITodoAppMemberUserJoin.IRequest,
    });
    typia.assert(authorized);

    return {
      email,
      password,
      authorized,
    };
  };

  // Helper to login as a member user (switch actor context)
  const loginMemberUser = async (email: string, password: string) => {
    const authorized = await api.functional.auth.memberUser.login(connection, {
      body: {
        email,
        password,
        ip: null,
        href: "https://todo-app.test/login",
        referrer: "https://todo-app.test/",
      } satisfies ITodoAppMemberUserLogin.IRequest,
    });
    typia.assert(authorized);
    return authorized;
  };

  // Helper to create a simple todo as the current member user
  const createTodo = async () => {
    const todo = await api.functional.todoApp.memberUser.todos.create(
      connection,
      {
        body: {
          title: RandomGenerator.paragraph({ sentences: 3 }),
          description: RandomGenerator.paragraph({ sentences: 6 }),
        } satisfies ITodoAppTodo.ICreate,
      },
    );
    typia.assert(todo);
    return todo;
  };

  // 3. Create Group A member users (earlier in time)
  const groupACount = 3;
  const groupA = await ArrayUtil.asyncRepeat(groupACount, async () => {
    const member = await createMemberUser();
    // Switch to member and create a todo for realism
    await loginMemberUser(member.email, member.password);
    await createTodo();
    return member;
  });

  // Capture a boundary time after Group A creation
  const boundaryAfterGroupA: string = new Date().toISOString();

  // 4. Create Group B member users (later in time)
  const groupBCount = 3;
  const groupB = await ArrayUtil.asyncRepeat(groupBCount, async () => {
    const member = await createMemberUser();
    // Switch to member and create a todo as well
    await loginMemberUser(member.email, member.password);
    await createTodo();
    return member;
  });

  // Capture a boundary time after Group B creation
  const boundaryAfterGroupB: string = new Date().toISOString();

  // 5. Switch back to admin context before performing admin search
  const adminAgain = await api.functional.auth.adminUser.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      ip: null,
      href: "https://admin.todo-app.test/login",
      referrer: "https://admin.todo-app.test/",
      user_agent: "e2e-test-agent",
    } satisfies ITodoAppAdminUser.ILogin,
  });
  typia.assert(adminAgain);

  // 6. Search with createdFrom after Group A boundary to favor Group B users
  const searchGroupBPage: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 100,
        createdFrom: boundaryAfterGroupA,
      } satisfies ITodoAppMemberuser.IRequest,
    });
  typia.assert(searchGroupBPage);

  const paginationB = searchGroupBPage.pagination;
  const dataB = searchGroupBPage.data;

  // Basic pagination sanity checks for Group B search
  TestValidator.predicate(
    "pagination limit should be at least number of returned records (Group B search)",
    dataB.length <= paginationB.limit,
  );
  TestValidator.predicate(
    "pagination current page should be 1 for Group B search",
    paginationB.current === 1,
  );

  // Ensure summaries have the expected safe shape
  for (const summary of dataB) {
    typia.assert<ITodoAppMemberuser.ISummary>(summary);
  }

  // At least some of Group B members should be included in result set
  const groupBEmails = groupB.map((m) => m.email);
  const dataBEmails = dataB.map((s) => s.email);
  const hasAnyGroupB = groupBEmails.some((email) =>
    dataBEmails.includes(email),
  );
  TestValidator.predicate(
    "search with createdFrom after Group A should include at least one Group B member",
    hasAnyGroupB,
  );

  // 7. Optional inverse test using createdTo between Group A and Group B boundaries
  const t1Millis = new Date(boundaryAfterGroupA).getTime();
  const t2Millis = new Date(boundaryAfterGroupB).getTime();
  const midMillis = Math.floor((t1Millis + t2Millis) / 2);
  const createdToBetweenGroups: string = new Date(midMillis).toISOString();

  const searchGroupABeforeMid: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: {
        page: 1,
        limit: 100,
        createdTo: createdToBetweenGroups,
      } satisfies ITodoAppMemberuser.IRequest,
    });
  typia.assert(searchGroupABeforeMid);

  const paginationA = searchGroupABeforeMid.pagination;
  const dataA = searchGroupABeforeMid.data;

  TestValidator.predicate(
    "pagination limit should be at least number of returned records (Group A search)",
    dataA.length <= paginationA.limit,
  );
  TestValidator.predicate(
    "pagination current page should be 1 for Group A search",
    paginationA.current === 1,
  );

  const groupAEmails = groupA.map((m) => m.email);
  const dataAEmails = dataA.map((s) => s.email);
  const hasAnyGroupA = groupAEmails.some((email) =>
    dataAEmails.includes(email),
  );
  TestValidator.predicate(
    "search with createdTo between groups should include at least one Group A member",
    hasAnyGroupA,
  );

  // 8. Confirm that summary DTO does not expose sensitive fields by checking structure
  for (const summary of dataA) {
    typia.assert<ITodoAppMemberuser.ISummary>(summary);
    const keys = Object.keys(summary as Record<string, unknown>);
    TestValidator.predicate(
      "member summary object must not contain password_hash field",
      !keys.includes("password_hash"),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_member_user_search_sorting_and_direction(
  connection: api.IConnection,
) {
  // 1. Register an admin user and obtain an authenticated admin session
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword: string = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoin = await api.functional.auth.adminUser.join(connection, {
    body: adminJoinBody,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminJoin);

  // 2. Create multiple member users with deterministic, sortable emails
  const baseLocal = RandomGenerator.alphabets(8);
  const domain = "example.com";

  const memberCount = 4;
  const memberEmails: string[] = [];
  const memberPasswords: string[] = [];

  for (let i = 0; i < memberCount; i++) {
    const email = `${baseLocal}+${String.fromCharCode(97 + i)}@${domain}`;
    const password: string = typia.random<string & tags.Format<"password">>();

    memberEmails.push(email);
    memberPasswords.push(password);

    const joinBody = {
      email,
      password,
      display_name: RandomGenerator.name(),
      ip: null,
      href: "https://todo-app.test/join",
      referrer: "https://todo-app.test/landing",
    } satisfies ITodoAppMemberUserJoin.IRequest;

    const memberJoin = await api.functional.auth.memberUser.join(connection, {
      body: joinBody,
    });
    typia.assert<ITodoAppMemberuser.IAuthorized>(memberJoin);
  }

  // 3. Exercise some member activity and then ensure we are back as admin
  const firstMemberLoginBody = {
    email: memberEmails[0],
    password: memberPasswords[0],
    ip: null,
    href: "https://todo-app.test/login",
    referrer: "https://todo-app.test",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLogin = await api.functional.auth.memberUser.login(connection, {
    body: firstMemberLoginBody,
  });
  typia.assert<ITodoAppMemberuser.IAuthorized>(memberLogin);

  const todoCreateBody = {
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.paragraph({ sentences: 6 }),
  } satisfies ITodoAppTodo.ICreate;

  const todo = await api.functional.todoApp.memberUser.todos.create(
    connection,
    {
      body: todoCreateBody,
    },
  );
  typia.assert<ITodoAppTodo>(todo);

  // Switch back to admin session to perform memberUsers search
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.test/admin/login",
    referrer: "https://todo-app.test/admin",
    user_agent: "e2e-test-agent",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLogin = await api.functional.auth.adminUser.login(connection, {
    body: adminLoginBody,
  });
  typia.assert<ITodoAppAdminUser.IAuthorized>(adminLogin);

  // 4. Call memberUsers.index with ascending order by email
  const ascRequestBody = {
    page: 1,
    limit: 50,
    orderBy: "email",
    orderDirection: "asc",
  } satisfies ITodoAppMemberuser.IRequest;

  const ascPage = await api.functional.todoApp.adminUser.memberUsers.index(
    connection,
    {
      body: ascRequestBody,
    },
  );
  typia.assert<IPageITodoAppMemberuser.ISummary>(ascPage);

  // Basic pagination sanity checks using predicates to avoid tag-generic issues
  TestValidator.predicate(
    "pagination current page should be 1",
    ascPage.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit should be >= number of records",
    ascPage.pagination.limit >= ascPage.pagination.records,
  );

  // Extract subset of summaries corresponding to our created member emails
  const ascSubset: ITodoAppMemberuser.ISummary[] = ascPage.data.filter(
    (summary) => memberEmails.includes(summary.email),
  );

  TestValidator.equals(
    "all created member users must appear in asc results",
    ascSubset.length,
    memberEmails.length,
  );

  // Verify the subset is sorted ascending by email
  const ascSorted = ascSubset
    .slice()
    .sort((a, b) => a.email.localeCompare(b.email));

  TestValidator.equals(
    "ascending subset should already be sorted by email",
    ascSubset,
    ascSorted,
  );

  // 5. Call memberUsers.index with descending order by email
  const descRequestBody = {
    page: 1,
    limit: 50,
    orderBy: "email",
    orderDirection: "desc",
  } satisfies ITodoAppMemberuser.IRequest;

  const descPage = await api.functional.todoApp.adminUser.memberUsers.index(
    connection,
    {
      body: descRequestBody,
    },
  );
  typia.assert<IPageITodoAppMemberuser.ISummary>(descPage);

  // Pagination sanity checks for desc as well
  TestValidator.predicate(
    "desc pagination current page should be 1",
    descPage.pagination.current === 1,
  );

  // Extract subset for our members in descending results
  const descSubset: ITodoAppMemberuser.ISummary[] = descPage.data.filter(
    (summary) => memberEmails.includes(summary.email),
  );

  TestValidator.equals(
    "desc subset must contain all created member users",
    descSubset.length,
    memberEmails.length,
  );

  // 6. Verify descending subset is the reverse order of ascending subset
  const ascEmails = ascSubset.map((s) => s.email);
  const descEmails = descSubset.map((s) => s.email);

  const reversedAscEmails = ascEmails.slice().reverse();

  TestValidator.equals(
    "descending emails should equal reversed ascending emails",
    descEmails,
    reversedAscEmails,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppMemberuser";
import type { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import type { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import type { ITodoAppMemberUserLogin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogin";
import type { ITodoAppMemberUserLogout } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogout";
import type { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import type { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";

export async function test_api_admin_member_user_search_after_member_logout_flows(
  connection: api.IConnection,
) {
  // 1. Register an admin user
  const adminEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const adminPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    display_name: RandomGenerator.name(),
  } satisfies ITodoAppAdminUser.IJoin;

  const adminJoinOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(adminJoinOutput);

  // 2. Register a member user
  const memberEmail: string & tags.Format<"email"> = typia.random<
    string & tags.Format<"email">
  >();
  const memberPassword: string & tags.Format<"password"> = typia.random<
    string & tags.Format<"password">
  >();

  const memberJoinBody = {
    email: memberEmail,
    password: memberPassword,
    display_name: RandomGenerator.name(),
    ip: null,
    href: "https://todo-app.example.com/join",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserJoin.IRequest;

  const memberJoinOutput: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.join(connection, {
      body: memberJoinBody,
    });
  typia.assert(memberJoinOutput);

  // 3. Create multiple todos as the member user
  const todoBodies: ITodoAppTodo.ICreate[] = ArrayUtil.repeat(3, (index) => {
    const baseTitle = `member todo ${index + 1}`;
    return {
      title: baseTitle,
      description: RandomGenerator.paragraph({ sentences: 4 }),
    } satisfies ITodoAppTodo.ICreate;
  });

  const todos: ITodoAppTodo[] = [];
  for (const body of todoBodies) {
    const todo: ITodoAppTodo =
      await api.functional.todoApp.memberUser.todos.create(connection, {
        body,
      });
    typia.assert(todo);
    todos.push(todo);

    TestValidator.equals(
      "todo owner id should match member user id",
      todo.memberUser.id,
      memberJoinOutput.id,
    );
    TestValidator.equals(
      "todo owner email should match member email",
      todo.memberUser.email,
      memberJoinOutput.email,
    );
  }

  TestValidator.equals(
    "should have created 3 todos for the member user",
    todos.length,
    3,
  );

  // 4. Logout current member session
  const logoutResponse: ITodoAppMemberUserLogout.IResponse =
    await api.functional.auth.memberUser.logout(connection);
  typia.assert(logoutResponse);
  TestValidator.predicate(
    "single-session logout success flag should be true",
    logoutResponse.success === true,
  );

  // 5. Re-login and then logoutAll for the same member
  const memberLoginBody = {
    email: memberEmail,
    password: memberPassword,
    ip: null,
    href: "https://todo-app.example.com/login",
    referrer: "https://todo-app.example.com/landing",
  } satisfies ITodoAppMemberUserLogin.IRequest;

  const memberLoginOutput: ITodoAppMemberuser.IAuthorized =
    await api.functional.auth.memberUser.login(connection, {
      body: memberLoginBody,
    });
  typia.assert(memberLoginOutput);

  const logoutAllResponse: ITodoAppMemberUserLogoutAll.IResponse =
    await api.functional.auth.memberUser.logoutAll(connection);
  typia.assert(logoutAllResponse);
  TestValidator.predicate(
    "logoutAll success flag should be true",
    logoutAllResponse.success === true,
  );

  // 6. Switch back to admin user via login (re-authenticate as admin)
  const adminLoginBody = {
    email: adminEmail,
    password: adminPassword,
    ip: null,
    href: "https://todo-app.example.com/admin/login",
    referrer: "https://todo-app.example.com/admin",
    user_agent: "e2e-suite/1.0",
  } satisfies ITodoAppAdminUser.ILogin;

  const adminLoginOutput: ITodoAppAdminUser.IAuthorized =
    await api.functional.auth.adminUser.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoginOutput);

  // 7. Admin searches for member user by email using PATCH /todoApp/adminUser/memberUsers
  const searchRequestBody = {
    page: 1 as number & tags.Type<"int32">,
    limit: 10 as number & tags.Type<"int32">,
    email: memberEmail,
    status: undefined,
    createdFrom: undefined,
    createdTo: undefined,
    deleted: undefined,
    orderBy: "created_at",
    orderDirection: "desc",
  } satisfies ITodoAppMemberuser.IRequest;

  const searchResult: IPageITodoAppMemberuser.ISummary =
    await api.functional.todoApp.adminUser.memberUsers.index(connection, {
      body: searchRequestBody,
    });
  typia.assert(searchResult);

  TestValidator.predicate(
    "search result should contain at least one member user",
    searchResult.pagination.records >= 1,
  );

  const matchedMember: ITodoAppMemberuser.ISummary | undefined =
    searchResult.data.find((summary) => summary.email === memberEmail);

  TestValidator.predicate(
    "admin search should find the member user by email even after logout flows",
    matchedMember !== undefined,
  );

  if (matchedMember !== undefined) {
    TestValidator.equals(
      "matched summary id should equal created member id",
      matchedMember.id,
      memberJoinOutput.id,
    );

    TestValidator.equals(
      "matched summary email should equal created member email",
      matchedMember.email,
      memberJoinOutput.email,
    );

    TestValidator.equals(
      "matched summary status should equal latest member status",
      matchedMember.status,
      memberLoginOutput.status,
    );
  }
}

