import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IPageITodoAppAdminuser } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppAdminuser";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchTodoAppAdminUserAdminUsers(props: {
  adminUser: AdminuserPayload;
  body: ITodoAppAdminUser.IRequest;
}): Promise<IPageITodoAppAdminuser.ISummary> {
  const body = props.body;

  const rawPage = body.page !== undefined && body.page !== null ? body.page : 0;
  const rawLimit =
    body.limit !== undefined && body.limit !== null ? body.limit : 20;

  const maxLimit = 100;
  const page = rawPage < 0 ? 0 : rawPage;
  const limit = rawLimit <= 0 ? 20 : rawLimit > maxLimit ? maxLimit : rawLimit;

  const skip = page * limit;

  const whereConditions: Prisma.todo_app_adminusersWhereInput = {
    deleted_at: null,
  };

  if (body.status !== undefined && body.status !== null) {
    whereConditions.status = body.status;
  }

  if (
    body.keyword !== undefined &&
    body.keyword !== null &&
    body.keyword !== ""
  ) {
    whereConditions.OR = [
      {
        email: {
          contains: body.keyword,
          mode: "insensitive",
        },
      },
      {
        display_name: {
          contains: body.keyword,
          mode: "insensitive",
        },
      },
    ];
  }

  const hasCreatedFrom =
    body.created_from !== undefined && body.created_from !== null;
  const hasCreatedTo =
    body.created_to !== undefined && body.created_to !== null;

  if (hasCreatedFrom || hasCreatedTo) {
    whereConditions.created_at = {};
    if (hasCreatedFrom) {
      whereConditions.created_at.gte =
        body.created_from! satisfies string as string;
    }
    if (hasCreatedTo) {
      whereConditions.created_at.lte =
        body.created_to! satisfies string as string;
    }
  }

  const orderByFieldRaw =
    body.order_by !== undefined && body.order_by !== null
      ? body.order_by
      : "created_at";

  const orderByField =
    orderByFieldRaw === "email" ||
    orderByFieldRaw === "status" ||
    orderByFieldRaw === "created_at"
      ? orderByFieldRaw
      : "created_at";

  const directionRaw =
    body.order_direction !== undefined && body.order_direction !== null
      ? body.order_direction.toLowerCase()
      : "desc";

  const direction: Prisma.SortOrder = directionRaw === "asc" ? "asc" : "desc";

  let orderBy: Prisma.todo_app_adminusersOrderByWithRelationInput;
  if (orderByField === "email") {
    orderBy = { email: direction };
  } else if (orderByField === "status") {
    orderBy = { status: direction };
  } else {
    orderBy = { created_at: direction };
  }

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_adminusers.findMany({
      where: whereConditions,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.todo_app_adminusers.count({
      where: whereConditions,
    }),
  ]);

  const data: ITodoAppAdminUser.ISummary[] = rows.map((row) => {
    const summary: ITodoAppAdminUser.ISummary = {
      id: row.id,
      email: row.email,
      status: row.status,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    };

    if (row.display_name !== null) {
      summary.display_name = row.display_name;
    } else {
      summary.display_name = null;
    }

    if (row.last_login_at !== null) {
      summary.last_login_at = toISOStringSafe(row.last_login_at);
    } else {
      summary.last_login_at = null;
    }

    return summary;
  });

  const pages = limit > 0 ? Math.ceil(total / limit) : 0;

  const pagination: IPage.IPagination = {
    current: page satisfies number as number,
    limit: limit satisfies number as number,
    records: total,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppLoginAttempt";
import { IPageITodoAppLoginAttempt } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppLoginAttempt";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { AdminuserPayload } from "../decorators/payload/AdminuserPayload";

export async function patchTodoAppAdminUserLoginAttempts(props: {
  adminUser: AdminuserPayload;
  body: ITodoAppLoginAttempt.IRequest;
}): Promise<IPageITodoAppLoginAttempt.ISummary> {
  const page: number = props.body.page !== undefined ? props.body.page : 1;
  const limit: number = props.body.limit !== undefined ? props.body.limit : 100;

  const skip: number = (page - 1) * limit;

  const hasCreatedFrom: boolean =
    props.body.created_from !== undefined && props.body.created_from !== null;
  const hasCreatedTo: boolean =
    props.body.created_to !== undefined && props.body.created_to !== null;

  const where = {
    ...(props.body.login_identifier !== undefined && {
      login_identifier: props.body.login_identifier,
    }),
    ...(props.body.actor_type !== undefined && {
      actor_type: props.body.actor_type,
    }),
    ...(props.body.succeeded !== undefined && {
      succeeded: props.body.succeeded,
    }),
    ...(props.body.ip !== undefined && {
      ip: props.body.ip,
    }),
    ...(props.body.failure_reason !== undefined && {
      failure_reason: props.body.failure_reason,
    }),
    ...(() => {
      if (!hasCreatedFrom && !hasCreatedTo) return {};

      return {
        created_at: {
          ...(hasCreatedFrom && props.body.created_from !== null
            ? { gte: props.body.created_from }
            : {}),
          ...(hasCreatedTo && props.body.created_to !== null
            ? { lte: props.body.created_to }
            : {}),
        },
      };
    })(),
  };

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_login_attempts.findMany({
      where,
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      include: {
        memberUser: {
          select: {
            id: true,
            email: true,
            display_name: true,
            status: true,
            last_login_at: true,
          },
        },
        adminUser: {
          select: {
            id: true,
            email: true,
            display_name: true,
            status: true,
            last_login_at: true,
            created_at: true,
            updated_at: true,
          },
        },
      },
    }),
    MyGlobal.prisma.todo_app_login_attempts.count({ where }),
  ]);

  const data: ITodoAppLoginAttempt.ISummary[] = rows.map((row) => {
    const memberSummary: ITodoAppMemberuser.ISummary | undefined =
      row.memberUser === null
        ? undefined
        : {
            id: row.memberUser.id,
            email: row.memberUser.email,
            display_name: row.memberUser.display_name ?? null,
            status: row.memberUser.status,
            last_login_at:
              row.memberUser.last_login_at !== null
                ? toISOStringSafe(row.memberUser.last_login_at)
                : null,
          };

    const adminSummary: ITodoAppAdminUser.ISummary | undefined =
      row.adminUser === null
        ? undefined
        : {
            id: row.adminUser.id,
            email: row.adminUser.email,
            display_name: row.adminUser.display_name ?? null,
            status: row.adminUser.status,
            last_login_at:
              row.adminUser.last_login_at !== null
                ? toISOStringSafe(row.adminUser.last_login_at)
                : null,
            created_at: toISOStringSafe(row.adminUser.created_at),
            updated_at: toISOStringSafe(row.adminUser.updated_at),
          };

    return {
      id: row.id,
      login_identifier: row.login_identifier,
      actor_type: row.actor_type,
      succeeded: row.succeeded,
      ip: row.ip,
      failure_reason: row.failure_reason ?? null,
      created_at: toISOStringSafe(row.created_at),
      ...(memberSummary !== undefined && { memberUser: memberSummary }),
      ...(adminSummary !== undefined && { adminUser: adminSummary }),
    };
  });

  const pages: number = limit === 0 ? 0 : Math.ceil(total / limit);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function patchTodoAppMemberUserTodos(props: {
  memberUser: MemberuserPayload;
  body: ITodoAppTodo.IRequest;
}): Promise<IPageITodoAppTodo.ISummary> {
  const body = props.body;

  // Normalize createdFrom/createdTo into Prisma-compatible string filters
  const createdFrom: string | undefined =
    body.createdFrom !== undefined && body.createdFrom !== null
      ? (body.createdFrom satisfies string as string)
      : undefined;
  const createdTo: string | undefined =
    body.createdTo !== undefined && body.createdTo !== null
      ? (body.createdTo satisfies string as string)
      : undefined;

  const createdAtFilter:
    | {
        gte?: string;
        lte?: string;
      }
    | undefined = (() => {
    const hasFrom = createdFrom !== undefined;
    const hasTo = createdTo !== undefined;
    if (!hasFrom && !hasTo) return undefined;
    const filter: { gte?: string; lte?: string } = {};
    if (hasFrom) filter.gte = createdFrom as string;
    if (hasTo) filter.lte = createdTo as string;
    return filter;
  })();

  // Base where condition: only non-deleted todos of the authenticated member user
  const where: Prisma.todo_app_todosWhereInput = {
    todo_app_memberuser_id: props.memberUser.id satisfies string as string,
    deleted_at: null,
    // Status filter
    ...(body.status !== undefined && body.status !== null
      ? { status: body.status }
      : {}),
    // Created_at range filters
    ...(createdAtFilter !== undefined
      ? {
          created_at: createdAtFilter,
        }
      : {}),
    // Completed state filter
    ...(() => {
      if (body.completed === undefined || body.completed === null) return {};
      return body.completed === true
        ? { completed_at: { not: null } }
        : { completed_at: null };
    })(),
    // Text search across title and description
    ...(() => {
      if (
        body.search === undefined ||
        body.search === null ||
        body.search === ""
      )
        return {};
      const search: string = body.search satisfies string as string;
      return {
        OR: [
          { title: { contains: search } },
          { description: { contains: search } },
        ],
      };
    })(),
  };

  const page = body.page;
  const limit = body.limit;
  const skip = (page - 1) * limit;

  // Determine orderBy mapping from API field to DB column
  const orderByField = (() => {
    if (body.orderBy === undefined || body.orderBy === null)
      return "created_at" as const;
    if (body.orderBy === "createdAt") return "created_at" as const;
    if (body.orderBy === "updatedAt") return "updated_at" as const;
    if (body.orderBy === "completedAt") return "completed_at" as const;
    return "created_at" as const;
  })();

  const orderDirection: "asc" | "desc" = (() => {
    if (body.orderDirection === "asc" || body.orderDirection === "desc")
      return body.orderDirection;
    return "desc";
  })();

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.todo_app_todos.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [orderByField]: orderDirection },
      include: {
        memberUser: true,
      },
    }),
    MyGlobal.prisma.todo_app_todos.count({
      where,
    }),
  ]);

  const data: ITodoAppTodo.ISummary[] = rows.map((row) => {
    const member = (row as any).memberUser;

    const memberLastLoginAt =
      member.last_login_at === null
        ? null
        : toISOStringSafe(member.last_login_at as any);

    const completedAt =
      row.completed_at === null
        ? null
        : toISOStringSafe(row.completed_at as any);

    const summaryMemberUser: ITodoAppMemberuser.ISummary = {
      id: member.id,
      email: member.email,
      display_name: member.display_name === null ? null : member.display_name,
      status: member.status,
      last_login_at: memberLastLoginAt,
    };

    const summaryTodo: ITodoAppTodo.ISummary = {
      id: row.id,
      title: row.title,
      status: row.status,
      created_at: toISOStringSafe(row.created_at as any),
      updated_at: toISOStringSafe(row.updated_at as any),
      completed_at: completedAt,
      memberUser: summaryMemberUser,
    };

    return summaryTodo;
  });

  const pages = total === 0 ? 0 : Math.ceil(total / limit);

  const pagination: IPage.IPagination = {
    current: page,
    limit,
    records: total,
    pages,
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminUserLogin(props: {
  body: ITodoAppAdminUser.ILogin;
}): Promise<ITodoAppAdminUser.IAuthorized> {
  const nowIso = toISOStringSafe(new Date());

  const normalizeEmail = (email: string): string => {
    // Basic normalization: trim and lowercase. Authentication requirements
    // mention normalization but do not specify further rules.
    return email.trim().toLowerCase();
  };

  const loginEmail = normalizeEmail(props.body.email);

  // Threshold for locking accounts based on consecutive failed login attempts.
  const MAX_FAILED_ATTEMPTS = 5;

  const admin = await MyGlobal.prisma.todo_app_adminusers.findFirst({
    where: {
      email: loginEmail,
    },
  });

  if (!admin) {
    await MyGlobal.prisma.todo_app_login_attempts.create({
      data: {
        id: v4(),
        login_identifier: loginEmail,
        actor_type: "adminUser",
        succeeded: false,
        ip:
          props.body.ip === null || props.body.ip === undefined
            ? ""
            : props.body.ip,
        user_agent:
          props.body.user_agent === null || props.body.user_agent === undefined
            ? null
            : props.body.user_agent,
        failure_reason: "invalid_credentials",
        created_at: nowIso,
        todo_app_memberuser_id: null,
        todo_app_adminuser_id: null,
      },
    });
    throw new HttpException("Invalid credentials", 401);
  }

  // From here, `admin` is guaranteed to be non-null
  const nonNullAdmin = admin;

  const ipValue =
    props.body.ip === null || props.body.ip === undefined ? "" : props.body.ip;

  const userAgentValue =
    props.body.user_agent === null || props.body.user_agent === undefined
      ? null
      : props.body.user_agent;

  const createLoginAttempt = async (params: {
    adminId: string | null;
    succeeded: boolean;
    failureReason: string | null;
  }): Promise<void> => {
    await MyGlobal.prisma.todo_app_login_attempts.create({
      data: {
        id: v4(),
        login_identifier: loginEmail,
        actor_type: "adminUser",
        succeeded: params.succeeded,
        ip: ipValue,
        user_agent: userAgentValue,
        failure_reason: params.failureReason,
        created_at: nowIso,
        todo_app_memberuser_id: null,
        todo_app_adminuser_id: params.adminId,
      },
    });
  };

  const throwInvalidCredentials = async (
    adminId: string | null,
    failureReason: string | null,
  ): Promise<never> => {
    await createLoginAttempt({
      adminId,
      succeeded: false,
      failureReason,
    });
    throw new HttpException("Invalid credentials", 401);
  };

  if (nonNullAdmin.deleted_at !== null) {
    await throwInvalidCredentials(nonNullAdmin.id, "account_locked");
  }

  if (nonNullAdmin.status !== "active") {
    await throwInvalidCredentials(nonNullAdmin.id, "account_locked");
  }

  if (nonNullAdmin.failed_login_count >= MAX_FAILED_ATTEMPTS) {
    await throwInvalidCredentials(nonNullAdmin.id, "account_locked");
  }

  const passwordValid = await PasswordUtil.verify(
    props.body.password,
    nonNullAdmin.password_hash,
  );

  if (!passwordValid) {
    await MyGlobal.prisma.todo_app_adminusers.update({
      where: { id: nonNullAdmin.id },
      data: {
        failed_login_count: nonNullAdmin.failed_login_count + 1,
        updated_at: nowIso,
      },
    });

    await throwInvalidCredentials(nonNullAdmin.id, "invalid_credentials");
  }

  const accessExpiresAt = Date.now() + 60 * 60 * 1000;
  const refreshExpiresAt = Date.now() + 7 * 24 * 60 * 60 * 1000;

  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresAt));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresAt));

  const updatedAdmin = await MyGlobal.prisma.todo_app_adminusers.update({
    where: { id: nonNullAdmin.id },
    data: {
      failed_login_count: 0,
      last_login_at: nowIso,
      updated_at: nowIso,
    },
  });

  const sessionId = v4();

  await MyGlobal.prisma.todo_app_adminuser_sessions.create({
    data: {
      id: sessionId,
      todo_app_adminuser_id: updatedAdmin.id,
      ip: ipValue,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: nowIso,
      expired_at: accessExpiresIso,
    },
  });

  await createLoginAttempt({
    adminId: updatedAdmin.id,
    succeeded: true,
    failureReason: null,
  });

  const accessToken = jwt.sign(
    {
      type: "admin",
      id: updatedAdmin.id,
      session_id: sessionId,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "admin",
      id: updatedAdmin.id,
      session_id: sessionId,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  const authorized: ITodoAppAdminUser.IAuthorized = {
    id: updatedAdmin.id,
    email: updatedAdmin.email,
    display_name:
      updatedAdmin.display_name === null ? null : updatedAdmin.display_name,
    status: updatedAdmin.status,
    failed_login_count: updatedAdmin.failed_login_count,
    last_login_at:
      updatedAdmin.last_login_at === null
        ? null
        : toISOStringSafe(updatedAdmin.last_login_at),
    created_at: toISOStringSafe(updatedAdmin.created_at),
    updated_at: toISOStringSafe(updatedAdmin.updated_at),
    deleted_at:
      updatedAdmin.deleted_at === null
        ? null
        : toISOStringSafe(updatedAdmin.deleted_at),
    token,
  };

  return authorized;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postTodoAppMemberUserTodosTodoIdComplete(props: {
  memberUser: MemberuserPayload;
  todoId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTodo> {
  // Fetch the todo with its owning member user for ownership check and DTO mapping
  const existing = await MyGlobal.prisma.todo_app_todos.findUnique({
    where: { id: props.todoId },
    include: {
      memberUser: true,
    },
  });

  if (existing === null) {
    throw new HttpException("Todo not found", 404);
  }

  // Soft-deleted todos cannot be completed
  if (existing.deleted_at !== null) {
    throw new HttpException(
      "Todo has been deleted and cannot be completed",
      400,
    );
  }

  // Enforce ownership: only the owning member user can complete their todo
  if (existing.todo_app_memberuser_id !== props.memberUser.id) {
    throw new HttpException("Forbidden", 403);
  }

  // Determine if the todo is already completed (idempotent behavior)
  const isAlreadyCompleted: boolean = existing.status === "completed";

  // Perform state transition only when not already completed
  const target = isAlreadyCompleted
    ? existing
    : await MyGlobal.prisma.todo_app_todos.update({
        where: { id: props.todoId },
        data: {
          status: "completed",
          // We intentionally do not manipulate timestamp fields here. It is
          // assumed that either the database manages these columns (e.g., via
          // triggers/defaults) or they remain consistent with existing values.
        },
        include: {
          memberUser: true,
        },
      });

  const toOptionalNullableDateTime = (
    value:
      | string
      | null
      | undefined
      | (object & { constructor: { name: string } }),
  ): (string & tags.Format<"date-time">) | null | undefined => {
    if (value === null || value === undefined) return value as null | undefined;

    // When Prisma returns Date objects, convert them to ISO string using
    // pre-provided helper. We avoid using Date type directly in signatures.
    const raw: string =
      typeof value === "object" && (value as any).constructor?.name === "Date"
        ? toISOStringSafe(value as any)
        : (value as string);

    return raw as string & tags.Format<"date-time">;
  };

  const toRequiredDateTime = (
    value: string | (object & { constructor: { name: string } }),
  ): string & tags.Format<"date-time"> => {
    const raw: string =
      typeof value === "object" && (value as any).constructor?.name === "Date"
        ? toISOStringSafe(value as any)
        : (value as string);

    return raw as string & tags.Format<"date-time">;
  };

  // Build ITodoAppTodo DTO from Prisma record
  const dto: ITodoAppTodo = {
    id: target.id as string & tags.Format<"uuid">,
    memberUser: {
      id: target.memberUser.id as string & tags.Format<"uuid">,
      email: target.memberUser.email as string & tags.Format<"email">,
      display_name:
        target.memberUser.display_name === null
          ? null
          : target.memberUser.display_name,
      status: target.memberUser.status,
      last_login_at: toOptionalNullableDateTime(
        target.memberUser.last_login_at as any,
      ),
    },
    title: target.title,
    description:
      target.description === null || target.description === undefined
        ? null
        : target.description,
    status: target.status,
    created_at: toRequiredDateTime(target.created_at as any),
    updated_at: toRequiredDateTime(target.updated_at as any),
    completed_at: toOptionalNullableDateTime(target.completed_at as any),
    deleted_at: toOptionalNullableDateTime(target.deleted_at as any),
  };

  return dto;
}

