import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthGuestUserJoin(props: {
  body: ITodoAppGuestUser.IJoin;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  const nowDate = new Date();
  const nowIso = toISOStringSafe(nowDate);

  const accessExpiresDate = new Date(nowDate.getTime() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(
    nowDate.getTime() + 7 * 24 * 60 * 60 * 1000,
  );
  const accessExpiresIso = toISOStringSafe(accessExpiresDate);
  const refreshExpiresIso = toISOStringSafe(refreshExpiresDate);

  try {
    const createdGuest = await MyGlobal.prisma.todo_app_guestusers.create({
      data: {
        id: v4(),
        display_name: props.body.display_name ?? null,
        created_at: nowDate,
        updated_at: nowDate,
        deleted_at: null,
      },
    });

    const sessionId = v4();

    const accessToken = jwt.sign(
      {
        type: "guestUser",
        id: createdGuest.id,
        session_id: sessionId,
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: "guestUser",
        id: createdGuest.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: nowIso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    const authorized: ITodoAppGuestUser.IAuthorized = {
      id: createdGuest.id,
      display_name: createdGuest.display_name,
      created_at: toISOStringSafe(createdGuest.created_at),
      updated_at: toISOStringSafe(createdGuest.updated_at),
      deleted_at: createdGuest.deleted_at
        ? toISOStringSafe(createdGuest.deleted_at)
        : null,
      token: {
        access: accessToken,
        refresh: refreshToken,
        expired_at: accessExpiresIso,
        refreshable_until: refreshExpiresIso,
      },
    };

    return authorized;
  } catch (error) {
    if (error instanceof Prisma.PrismaClientKnownRequestError) {
      throw new HttpException("Failed to create guest user", 500);
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppGuestUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUser";
import { ITodoAppGuestUserMetadata } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppGuestUserMetadata";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { GuestuserPayload } from "../decorators/payload/GuestuserPayload";

export async function postAuthGuestUserRefresh(props: {
  guestUser: GuestuserPayload;
  body: ITodoAppGuestUser.IRefresh;
}): Promise<ITodoAppGuestUser.IAuthorized> {
  // Step 1: verify the refresh token from request body
  let decodedRaw: unknown;

  try {
    decodedRaw = jwt.verify(
      props.body.refresh_token,
      MyGlobal.env.JWT_SECRET_KEY,
      {
        issuer: "autobe",
      },
    );
  } catch (_error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  // Narrow the decoded payload shape without relying on `as any`.
  const decodedObject = typeof decodedRaw === "string" ? undefined : decodedRaw;

  if (
    !decodedObject ||
    typeof (decodedObject as jwt.JwtPayload).id !== "string" ||
    typeof (decodedObject as jwt.JwtPayload).session_id !== "string" ||
    (decodedObject as jwt.JwtPayload).type !== "guestUser"
  ) {
    throw new HttpException("Invalid refresh token payload for guestUser", 401);
  }

  const decoded = decodedObject as jwt.JwtPayload;

  const decodedId = decoded.id as string;
  const decodedSessionId = decoded.session_id as string;

  // Step 2: validate that the token type and identity align with the injected guestUser payload
  if (decoded.type !== "guestUser") {
    throw new HttpException("Invalid token type for guestUser refresh", 403);
  }

  if (
    decodedId !== props.guestUser.id ||
    decodedSessionId !== props.guestUser.session_id
  ) {
    throw new HttpException(
      "Token subject does not match authenticated guest user",
      403,
    );
  }

  // Step 3: ensure the underlying guest actor still exists and is not soft-deleted
  const guest = await MyGlobal.prisma.todo_app_guestusers.findFirst({
    where: {
      id: props.guestUser.id,
      deleted_at: null,
    },
  });

  if (guest === null) {
    throw new HttpException(
      "Guest user has been deleted or does not exist",
      403,
    );
  }

  // Step 4: compute new token expiration instants
  const now = new Date();
  const accessExpires = new Date(now.getTime() + 60 * 60 * 1000); // 1 hour
  const refreshExpires = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  // Step 5: issue new JWT access and refresh tokens preserving the same session_id
  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decodedId,
      session_id: decodedSessionId,
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decodedId,
      session_id: decodedSessionId,
      tokenType: "refresh",
      created_at: now.toISOString(),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  // Step 6: construct the authorized guest user payload.
  const createdAt = toISOStringSafe(guest.created_at);
  const updatedAt = toISOStringSafe(guest.updated_at);

  const deletedAt = guest.deleted_at ? toISOStringSafe(guest.deleted_at) : null;

  return {
    id: guest.id,
    display_name: guest.display_name === null ? null : guest.display_name,
    created_at: createdAt,
    updated_at: updatedAt,
    deleted_at: deletedAt,
    metadata: undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserJoin } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserJoin";
import { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthMemberUserJoin(props: {
  body: ITodoAppMemberUserJoin.IRequest;
}): Promise<ITodoAppMemberuser.IAuthorized> {
  // Check for duplicate email without exposing database internals
  const existing = await MyGlobal.prisma.todo_app_memberusers.findFirst({
    where: {
      email: props.body.email,
    },
  });

  if (existing !== null) {
    throw new HttpException("Member user with this email already exists.", 409);
  }

  // Hash the incoming password
  const passwordHash: string = await PasswordUtil.hash(props.body.password);

  // Compute current and expiry timestamps as ISO strings
  const nowDate = new Date();
  const now = toISOStringSafe(nowDate);

  const accessExpiryDate = new Date(nowDate.getTime() + 60 * 60 * 1000);
  const accessExpiresAt = toISOStringSafe(accessExpiryDate);

  const refreshExpiryDate = new Date(
    nowDate.getTime() + 7 * 24 * 60 * 60 * 1000,
  );
  const refreshExpiresAt = toISOStringSafe(refreshExpiryDate);

  // Generate UUIDs for member user and session
  const memberId = v4();
  const sessionId = v4();

  try {
    // Create member user and session within a single transaction
    const [member, session] = await MyGlobal.prisma.$transaction([
      MyGlobal.prisma.todo_app_memberusers.create({
        data: {
          id: memberId,
          email: props.body.email,
          password_hash: passwordHash,
          display_name: props.body.display_name ?? null,
          status: "active",
          failed_login_count: 0,
          last_login_at: null,
          created_at: now,
          updated_at: now,
          deleted_at: null,
        },
      }),
      MyGlobal.prisma.todo_app_memberuser_sessions.create({
        data: {
          id: sessionId,
          todo_app_memberuser_id: memberId,
          ip:
            props.body.ip !== undefined && props.body.ip !== null
              ? props.body.ip
              : "0.0.0.0",
          href: props.body.href,
          referrer: props.body.referrer,
          created_at: now,
          expired_at: accessExpiresAt,
        },
      }),
    ]);

    // Generate JWT access and refresh tokens
    const accessToken = jwt.sign(
      {
        type: "memberuser",
        id: member.id,
        session_id: session.id,
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    );

    const refreshToken = jwt.sign(
      {
        type: "memberuser",
        id: member.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: now,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    );

    const token: IAuthorizationToken = {
      access: accessToken,
      refresh: refreshToken,
      expired_at: accessExpiresAt,
      refreshable_until: refreshExpiresAt,
    };

    return {
      id: member.id,
      email: member.email,
      display_name:
        member.display_name === null ? undefined : member.display_name,
      status: member.status,
      failed_login_count: member.failed_login_count,
      last_login_at:
        member.last_login_at === null
          ? null
          : toISOStringSafe(member.last_login_at),
      created_at: toISOStringSafe(member.created_at),
      updated_at: toISOStringSafe(member.updated_at),
      deleted_at:
        member.deleted_at === null ? null : toISOStringSafe(member.deleted_at),
      token,
    };
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      // Unique constraint violation (likely email)
      throw new HttpException(
        "Member user with this email already exists.",
        409,
      );
    }

    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserRefresh } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserRefresh";
import { ITodoAppMemberuser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberuser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postAuthMemberUserRefresh(props: {
  memberUser: MemberuserPayload;
  body: ITodoAppMemberUserRefresh.IRequest;
}): Promise<ITodoAppMemberuser.IAuthorized> {
  // 1. Verify and decode the refresh token
  let decoded: any;

  try {
    decoded = jwt.verify(props.body.refreshToken, MyGlobal.env.JWT_SECRET_KEY, {
      issuer: "autobe",
    });
  } catch (_error) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (!decoded || typeof decoded !== "object") {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  if (decoded.type !== "memberuser") {
    throw new HttpException("Invalid token type", 403);
  }

  if (decoded.tokenType !== "refresh") {
    // Enforce that only refresh tokens can be used here
    throw new HttpException("Invalid token kind for refresh operation", 403);
  }

  // 2. Validate that the session exists and is active
  const session = await MyGlobal.prisma.todo_app_memberuser_sessions.findFirst({
    where: {
      id: decoded.session_id,
      todo_app_memberuser_id: decoded.id,
    },
  });

  if (session === null) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.expired_at !== null) {
    // Session already marked as expired, do not allow refresh
    throw new HttpException("Session expired or revoked", 401);
  }

  // 3. Load the corresponding member user account
  const member = await MyGlobal.prisma.todo_app_memberusers.findUnique({
    where: {
      id: decoded.id,
    },
  });

  if (member === null) {
    // Avoid leaking account existence vs token validity differences
    throw new HttpException("Session expired or revoked", 401);
  }

  // Business rule: disabled or logically deleted accounts cannot refresh tokens
  if (member.deleted_at !== null || member.status !== "active") {
    throw new HttpException("Account has been disabled or deleted", 403);
  }

  // 4. Generate new tokens (reuse same session_id)
  const nowMs = Date.now();
  const nowIso = toISOStringSafe(new Date(nowMs));

  const accessExpiresMs = nowMs + 60 * 60 * 1000; // 1 hour
  const refreshExpiresMs = nowMs + 7 * 24 * 60 * 60 * 1000; // 7 days

  const accessExpiresIso = toISOStringSafe(new Date(accessExpiresMs));
  const refreshExpiresIso = toISOStringSafe(new Date(refreshExpiresMs));

  const accessToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  // 5. Update session expiration to align with new refresh token
  await MyGlobal.prisma.todo_app_memberuser_sessions.update({
    where: {
      id: decoded.session_id,
    },
    data: {
      expired_at: new Date(refreshExpiresMs),
    },
  });

  // Optionally, track last authenticated activity by updating member user timestamps
  const updatedMember = await MyGlobal.prisma.todo_app_memberusers.update({
    where: {
      id: member.id,
    },
    data: {
      last_login_at: new Date(nowMs),
      updated_at: new Date(nowMs),
    },
  });

  // 6. Map DB record to ITodoAppMemberuser.IAuthorized
  const displayName =
    updatedMember.display_name === null ? null : updatedMember.display_name;
  const lastLoginAtIso =
    updatedMember.last_login_at === null
      ? null
      : toISOStringSafe(updatedMember.last_login_at);
  const createdAtIso = toISOStringSafe(updatedMember.created_at);
  const updatedAtIso = toISOStringSafe(updatedMember.updated_at);
  const deletedAtIso =
    updatedMember.deleted_at === null
      ? null
      : toISOStringSafe(updatedMember.deleted_at);

  const result: ITodoAppMemberuser.IAuthorized = {
    id: updatedMember.id,
    email: updatedMember.email,
    display_name: displayName,
    status: updatedMember.status,
    failed_login_count: updatedMember.failed_login_count,
    last_login_at: lastLoginAtIso,
    created_at: createdAtIso,
    updated_at: updatedAtIso,
    deleted_at: deletedAtIso,
    token,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserLogoutAll } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserLogoutAll";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function postAuthMemberUserLogoutAll(props: {
  memberUser: MemberuserPayload;
}): Promise<ITodoAppMemberUserLogoutAll.IResponse> {
  // Identify the authenticated member user whose sessions must be terminated
  const memberUserId = props.memberUser.id;

  // Perform a bulk update to expire all active sessions for this member user.
  // We consider a session active when `expired_at` is null.
  const result = await MyGlobal.prisma.todo_app_memberuser_sessions.updateMany({
    where: {
      todo_app_memberuser_id: memberUserId,
      expired_at: null,
    },
    data: {
      // Prisma expects a Date for datetime fields; conversion to API string
      // happens only when returning values in DTOs, which we do not here.
      expired_at: new Date(),
    },
  });

  const affectedCount: number = result.count;

  // Build a human-readable message only when at least one session was affected.
  const message: string | null | undefined =
    affectedCount > 0
      ? `Successfully logged out from ${affectedCount} active session${
          affectedCount === 1 ? "" : "s"
        }.`
      : "No active sessions were found for this account.";

  const response: ITodoAppMemberUserLogoutAll.IResponse = {
    success: true,
    affectedSessionCount: affectedCount,
    // DTO allows message to be string | null | undefined; we always provide a string
    // for clearer UX.
    message,
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppMemberUserChangePassword } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMemberUserChangePassword";
import { MemberuserPayload } from "../decorators/payload/MemberuserPayload";

export async function putAuthMemberUserPassword(props: {
  memberUser: MemberuserPayload;
  body: ITodoAppMemberUserChangePassword.IRequest;
}): Promise<ITodoAppMemberUserChangePassword.IResponse> {
  const { memberUser, body } = props;

  // Step 1: Load current member user
  const existingUser = await MyGlobal.prisma.todo_app_memberusers.findUnique({
    where: { id: memberUser.id },
  });

  if (existingUser === null) {
    throw new HttpException("Member user not found", 404);
  }

  // Step 2: Verify current password
  const isCurrentPasswordValid = await PasswordUtil.verify(
    body.currentPassword,
    existingUser.password_hash,
  );

  if (!isCurrentPasswordValid) {
    // Increment failed_login_count on incorrect current password
    await MyGlobal.prisma.todo_app_memberusers.update({
      where: { id: memberUser.id },
      data: {
        failed_login_count: existingUser.failed_login_count + 1,
      },
    });

    throw new HttpException("Current password is incorrect", 400);
  }

  // Step 3: Enforce password complexity rules.
  // Business rule: at least 8 characters, includes letters and digits.
  const newPassword = body.newPassword;

  const hasMinimumLength = newPassword.length >= 8;
  const hasLetter = /[A-Za-z]/.test(newPassword);
  const hasDigit = /[0-9]/.test(newPassword);

  if (!hasMinimumLength || !hasLetter || !hasDigit) {
    throw new HttpException(
      "New password does not meet complexity requirements.",
      400,
    );
  }

  // Step 4: Hash the new password
  const newPasswordHash = await PasswordUtil.hash(newPassword);

  // Step 5: Compute current timestamp string for auditing/session expiry.
  const now = toISOStringSafe(new Date());

  // Step 6: Transactionally update user credentials and expire sessions
  await MyGlobal.prisma.$transaction([
    // Update member user record
    MyGlobal.prisma.todo_app_memberusers.update({
      where: { id: memberUser.id },
      data: {
        password_hash: newPasswordHash,
        failed_login_count: 0,
        updated_at: now,
        last_login_at: now,
      },
    }),

    // Expire all active sessions for this member user, including current one
    MyGlobal.prisma.todo_app_memberuser_sessions.updateMany({
      where: {
        todo_app_memberuser_id: memberUser.id,
        expired_at: null,
      },
      data: {
        expired_at: now,
      },
    }),
  ]);

  const response: ITodoAppMemberUserChangePassword.IResponse = {
    success: true,
    message:
      "Password has been updated successfully. All active sessions have been expired.",
  };

  return response;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { ITodoAppAdminUser } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppAdminUser";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminUserJoin(props: {
  body: ITodoAppAdminUser.IJoin;
}): Promise<ITodoAppAdminUser.IAuthorized> {
  // Check for existing admin with same email
  const existing = await MyGlobal.prisma.todo_app_adminusers.findFirst({
    where: { email: props.body.email },
  });

  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  // Hash password
  const hashedPassword = await PasswordUtil.hash(props.body.password);

  const nowDate = new Date();
  const nowIso = toISOStringSafe(nowDate);

  const adminId = v4() as string & tags.Format<"uuid">;

  // Create admin user
  let admin: Prisma.todo_app_adminusersUncheckedCreateInput & {
    id: string & tags.Format<"uuid">;
    last_login_at: Date | null;
    created_at: Date;
    updated_at: Date;
    deleted_at: Date | null;
  };

  try {
    admin = (await MyGlobal.prisma.todo_app_adminusers.create({
      data: {
        id: adminId,
        email: props.body.email,
        password_hash: hashedPassword,
        display_name: props.body.display_name ?? null,
        status: "active",
        failed_login_count: 0,
        last_login_at: null,
        created_at: nowDate,
        updated_at: nowDate,
        deleted_at: null,
      },
    })) as typeof admin;
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2002"
    ) {
      // Unique constraint violation on email
      throw new HttpException("Email already registered", 409);
    }
    throw error;
  }

  // Create session for admin user
  const sessionId = v4() as string & tags.Format<"uuid">;

  const accessExpiresDate = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpiresDate = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const accessExpiresIso = toISOStringSafe(accessExpiresDate);
  const refreshExpiresIso = toISOStringSafe(refreshExpiresDate);

  const session = await MyGlobal.prisma.todo_app_adminuser_sessions.create({
    data: {
      id: sessionId,
      todo_app_adminuser_id: admin.id,
      // No IP/href/referrer come from props for this operation; use empty string defaults.
      ip: "",
      href: "",
      referrer: "",
      created_at: nowDate,
      expired_at: accessExpiresDate,
    },
  });

  const accessToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: nowIso,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  const token: IAuthorizationToken = {
    access: accessToken,
    refresh: refreshToken,
    expired_at: accessExpiresIso,
    refreshable_until: refreshExpiresIso,
  };

  return {
    id: admin.id,
    email: admin.email as string & tags.Format<"email">,
    display_name: admin.display_name === null ? undefined : admin.display_name,
    status: admin.status,
    failed_login_count: admin.failed_login_count,
    last_login_at:
      admin.last_login_at === null
