      ? { ip: requestBody.ip }
      : {}),
    ...(requestBody.limit_key !== undefined && requestBody.limit_key !== null
      ? { limit_key: requestBody.limit_key }
      : {}),
    ...(requestBody.limit_type !== undefined && requestBody.limit_type !== null
      ? { limit_type: requestBody.limit_type }
      : {}),
