@Controller("/auth/memberUser/password")
export class AuthMemberuserPasswordController {
  /**
   * Allow an authenticated member user to change their password by updating
   * password_hash in the todo_app_memberusers table and expiring their sessions
   * in todo_app_memberuser_sessions.
   *
   * This operation allows an authenticated member user to change their password
   * by updating the `password_hash` column in the `todo_app_memberusers` table.
   * The request contains both the current password and the desired new
   * password, encapsulated in the `ITodoAppMemberUserChangePassword.IRequest`
   * schema. The backend first looks up the current member user row using the
   * authenticated identity and verifies that the provided current password
   * matches the stored `password_hash` using the configured hashing algorithm.
   * If the verification fails, the endpoint returns a business error and may
   * increment `failed_login_count` to reflect a failed security-sensitive
   * operation, following the guidelines defined in the authentication
   * requirements.
   *
   * Before updating the password, the endpoint validates the new password
   * according to the complexity rules described in the authentication
   * requirements document. These rules might include minimum length, presence
   * of multiple character classes, or other constraints, but the actual values
   * are enforced at the service layer and not encoded in the Prisma schema
   * itself. If the new password does not satisfy these rules, the operation
   * rejects the change with a clear, user-facing message while leaving the
   * existing `password_hash` intact and preserving the member user’s current
   * login state.
   *
   * On successful validation, the service computes a new `password_hash` from
   * the new password and writes it into the `todo_app_memberusers` row for the
   * authenticated user. It also resets `failed_login_count` to zero, reflecting
   * that the account’s security has been refreshed, and updates the
   * `updated_at` timestamp to record the change. Depending on implementation
   * choices, it may also adjust `last_login_at` if password change events are
   * considered an authenticated action worth tracking as recent activity, but
   * the account’s `status` and `deleted_at` fields remain unchanged unless
   * external business processes alter them.
   *
   * For security reasons, a password change must cause all existing sessions to
   * be invalidated. To achieve this, the endpoint queries
   * `todo_app_memberuser_sessions` for all sessions associated with the user’s
   * `todo_app_memberuser_id` and sets `expired_at` on each active session. This
   * ensures that any tokens issued under the previous password, on any device,
   * are no longer accepted. The token subsystem must also revoke or blacklist
   * corresponding refresh tokens so that clients are forced to re-authenticate
   * with the new password on their next interaction.
   *
   * In a typical workflow, the member user invokes this endpoint from a
   * settings or security page while already logged in as `memberUser`. After
   * the operation succeeds, the response, encoded as
   * `ITodoAppMemberUserChangePassword.IResponse`, indicates that the password
   * was updated and that active sessions have been terminated. The current
   * session may either remain valid or be terminated as well depending on
   * business policy; in either case, the behavior must be consistent with the
   * overall authentication and session requirements, and the database schema
   * fields `password_hash`, `failed_login_count`, `updated_at`, and session
   * `expired_at` collectively reflect the completed password change.
   *
   * @param connection
   * @param body Current and new password information for a member user
   *   requesting a password change.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put()
  public async changePassword(
    @MemberuserAuth()
    memberUser: MemberuserPayload,
    @TypedBody()
    body: ITodoAppMemberUserChangePassword.IRequest,
  ): Promise<ITodoAppMemberUserChangePassword.IResponse> {
    try {
      return await putAuthMemberUserPassword({
        memberUser,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

